/// Maximum length for user guidance text (characters).
/// Prevents oversized payloads from being injected into LLM goal context.
const MAX_GUIDANCE_LENGTH: usize = 500;

/// Maximum number of times a paused execution can be continued via escalation
/// ("Keep Trying") before the user must resolve the issue manually.
const MAX_CONTINUATION_COUNT: usize = 5;
const RESOLVED_ELSEWHERE_INPUT_TYPE: &str = "resolved_elsewhere";
const CONTINUE_INPUT_TYPE: &str = "continue";

async fn enrich_episode_from_execution(
    episode: &mut V3EpisodeRecord,
    orchestrator: &MagicianV2Orchestrator,
    execution_id: &str,
    execution_record: Option<&TaskExecutionRecord>,
) {
    use magician::magician_v2::agents::memory_tiers::ActionSummary;

    let _ = (orchestrator, execution_id);
    let Some(record) = execution_record else {
        return;
    };
    if record.step_statuses.is_empty() {
        return;
    }

    for step in &record.step_statuses {
        let succeeded = step.status == "completed";
        episode.actions_taken.push(ActionSummary {
            action_type: "taskplan_step".to_string(),
            description: step.name.clone(),
            tool: String::new(),
            succeeded,
            duration_ms: None,
            metadata: {
                let mut meta = HashMap::new();
                meta.insert("task_number".to_string(), serde_json::json!(step.number));
                meta.insert("progress".to_string(), serde_json::json!(step.progress));
                if let Some(step_id) = step.step_id.clone() {
                    meta.insert("step_id".to_string(), serde_json::json!(step_id));
                }
                meta
            },
        });
    }
}

