/// Authoritative operator-control capabilities for one execution.
///
/// Task projections intentionally collapse several runtime states (for example,
/// both HITL waits and manual pauses appear as `paused`) and may retain a latest
/// historical execution id. UI surfaces must use this response rather than
/// inferring action availability from task status alone.
#[derive(Debug, Clone, Serialize, PartialEq, Eq)]
pub struct ExecutionControlStateResponse {
    pub execution_id: String,
    pub waiting_state: String,
    #[serde(skip_serializing_if = "Option::is_none")]
    pub paused_from_state: Option<String>,
    #[serde(skip_serializing_if = "Option::is_none")]
    pub pause_kind: Option<String>,
    pub active: bool,
    pub can_pause: bool,
    pub can_resume: bool,
    pub can_steer: bool,
    pub can_cancel: bool,
}

/// Request for continuing agentic execution after max iterations (no user input needed)
#[derive(Debug, Serialize, Deserialize)]
pub struct AgenticContinueRequest {
    /// Exact pause storage key for deterministic lookup.
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub pause_state_id: Option<String>,
    /// The plan ID where execution is paused (optional — if missing, scans store by execution_id)
    #[serde(default)]
    pub plan_id: Option<String>,
    /// The step ID where execution is paused (optional — if missing, scans store by execution_id)
    #[serde(default)]
    pub step_id: Option<String>,
    /// Agent ID for agent-scoped pause lookup (TRUE_AGENTS Phase 0).
    /// When set alongside goal_id and cycle_id, uses agent-keyed store lookup.
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub agent_id: Option<String>,
    /// Goal ID for agent-scoped pause lookup.
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub goal_id: Option<String>,
    /// Cycle ID for agent-scoped pause lookup.
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub cycle_id: Option<String>,
    /// Optional user guidance to inject into the continuation context.
    /// When provided (e.g., from an escalation "Keep Trying" with guidance text),
    /// this is appended to the enhanced goal so the LLM can incorporate the user's hint.
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub guidance: Option<String>,
}

