/// Request for creating a new execution
#[derive(Debug, Serialize, Deserialize)]
pub struct CreateExecutionRequest {
    /// Optional request-supplied workspace. The active API path requires
    /// explicit scope via request headers and validates this against them.
    pub workspace: Option<String>,
    #[serde(default = "magician::magician_v2::storage::task_models::default_ui_thread_id")]
    pub ui_thread_id: String,
    /// Optional execution title
    pub title: Option<String>,
    /// Optional initial message to post after execution creation (enables serial
    /// create+post in one call)
    pub initial_message: Option<String>,
    /// Skip planning phase and go directly to agentic execution
    /// When true, initial_message is used as the goal for agentic execution
    #[serde(default)]
    pub skip_planning: bool,
    /// Maximum number of agentic iterations (backend default: 4000 when omitted)
    #[serde(default)]
    pub max_iterations: Option<usize>,
    /// Optional per-run LLM routing overrides for direct agentic execution.
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub llm_routing_overrides: Option<OperationRoutingOverrides>,
    /// v0.6.655 — flag the run as a debug/internal execution. When
    /// true, the created V3 task is marked NOT user-visible (hidden
    /// from the `/tasks` page by default; routed to `internal_tasks/`
    /// via the `Internal` lifecycle). Set by the debug page
    /// for SOTA tests, skill action runs, agentic experiments — they're
    /// test scaffolding, not work the user wants tracked.
    #[serde(default)]
    pub debug: bool,
    /// Mark the run's V3 task `Internal` (routed to `internal_tasks/`,
    /// hidden from `/tasks`) WITHOUT the debug / `__system__` semantics.
    /// Used by contextual/extension automation such as iOS webpage assistance:
    /// user-initiated, but the resulting task is execution machinery rather
    /// than a commitment the user should manage. `created_by` stays as supplied.
    #[serde(default)]
    pub internal: bool,
    /// Optional capability "env" to scope a direct agentic execution to a
    /// single tool/pack (e.g. `"browser"` for SOTA browser tests). Sent by the
    /// debug page's env-mode selector. When set, the execution runs that tool
    /// directly (no delegation). `None` = full agent tool set.
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub env_mode: Option<String>,
    /// The engagement this run belongs to, named by the **owner's request**.
    ///
    /// This is the one place a ROOT execution can acquire authority: a child
    /// inherits its parent's carrier verbatim and can never supply its own
    /// (§4.2c row 5), so without this every execution in the system started
    /// unbound and the whole engagement stack — outward capability ceiling,
    /// envelope scope, retrieval containment, act maturity — had nothing to
    /// resolve against.
    ///
    /// It is a **name, not a grant**. The server resolves it against the live
    /// engagement roster and reads the authority revision from there; a blank
    /// id, a separator-carrying id, and an unknown, revoked or expired
    /// engagement all refuse the whole creation rather than quietly producing
    /// an unconfined run.
    ///
    /// Owner-supplied on this route: the scope comes from request headers and
    /// an agent creating work goes through the task tools, not through here.
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub engagement_id: Option<String>,
}

/// The routing overrides a client may hand a direct run: its endpoints only.
/// The flow's parent engine is named by the runtime from the run's own
/// engine, never by the request, so a `parent_engine` on the wire is dropped
/// before the overrides are durably accepted and sealed.
fn client_llm_routing_overrides(
    overrides: Option<&OperationRoutingOverrides>,
) -> Option<OperationRoutingOverrides> {
    overrides
        .cloned()
        .map(OperationRoutingOverrides::without_parent_engine)
}

fn build_direct_context_overrides(
    task_execution: Option<(&str, &str)>,
    llm_routing_overrides: Option<OperationRoutingOverrides>,
    env_mode: Option<String>,
) -> Option<magician::magician_v2::execution::AgenticContextOverrides> {
    let mut overrides = magician::magician_v2::execution::AgenticContextOverrides::default();

    if let Some((task_id, execution_id)) = task_execution {
        overrides.task_id = Some(task_id.to_string());
        overrides.execution_id = Some(execution_id.to_string());
    }

    overrides.llm_routing_overrides = llm_routing_overrides.and_then(|value| value.normalized());
    overrides.env_mode = env_mode
        .map(|mode| mode.trim().to_string())
        .filter(|mode| !mode.is_empty());

    if overrides.task_id.is_some()
        || overrides.execution_id.is_some()
        || overrides.llm_routing_overrides.is_some()
        || overrides.env_mode.is_some()
    {
        Some(overrides)
    } else {
        None
    }
}

