pub(crate) fn resolve_required_scope_from_request(
    req: &HttpRequest,
) -> Result<(String, String), HttpResponse> {
    resolve_required_scope(req.headers(), None).map_err(|_| {
        api_error_response(
            StatusCode::BAD_REQUEST,
            "missing_scope",
            "A bearer with embedded principal/workspace scope is required.",
            None,
        )
    })
}

fn agent_scope_error_response(agent_id: &str, error: impl Into<String>) -> HttpResponse {
    api_error_response(
        StatusCode::UNPROCESSABLE_ENTITY,
        "agent_scope_missing",
        error.into(),
        Some(serde_json::json!({
            "agent_id": agent_id,
        })),
    )
}

const STARTUP_HYDRATION_RETRY_BACKOFF: StdDuration = StdDuration::from_secs(5);
const AGENT_EPISODES_LIMIT_DEFAULT: usize = 100;
const AGENT_EPISODES_LIMIT_MAX: usize = 500;
// 5s is safe now: scope enumeration is cache-cheap (see AgentDefinitionStore's
// runtime definition cache) and the tick is dispatch-bounded (see
// SCHEDULER_DISPATCH_BUDGET_PER_TICK) so a thundering herd of due agents can't
// monopolize the loop. Overflow is requeued, never dropped, so the tighter cadence
// keeps cron/interval detection latency low without stalling the request handler.
const AGENT_SCHEDULER_TICK_INTERVAL: StdDuration = StdDuration::from_secs(5);
/// Scopes scanned per tick. usize::MAX = scan-all (detection <= one tick).
/// Lower it only if scanning all scopes ever becomes measurable; batching stays
/// loss-free because an unscanned scope is never collected (uncollected = unconsumed).
const SCHEDULER_SCOPES_PER_TICK: usize = usize::MAX;
/// Max agent runs *dispatched* per tick. Overflow is requeued to the next tick.
const SCHEDULER_DISPATCH_BUDGET_PER_TICK: usize = 8;
const APPROVAL_EXPIRY_SWEEP_INTERVAL: StdDuration = StdDuration::from_secs(30);
const MEMORY_CONSOLIDATION_SWEEP_INTERVAL: StdDuration = StdDuration::from_secs(300);
const TASK_SCHEDULER_TICK_INTERVAL: StdDuration = StdDuration::from_secs(60);
/// Phase 4.2 — cadence of the scheduled harness steward / growth-eval drain.
/// Every 6h, per active scope, drains the skill/capability backlog into deduped
/// DRAFT proposals + runs a growth evaluation (final apply stays owner-gated).
const HARNESS_STEWARD_TICK_INTERVAL: StdDuration = StdDuration::from_secs(6 * 60 * 60);
/// Max deduped proposals the steward drain drafts per scope per tick (decision #7).
const HARNESS_STEWARD_TICK_MAX_PROPOSALS: usize = 3;
const MULTI_VALIDATION_ERROR_PREFIX: &str = "multiple validation errors";
const CANCEL_ACTIVE_CYCLE_MAX_ATTEMPTS: usize = 4;
const CANCEL_ACTIVE_CYCLE_RETRY_DELAY: StdDuration = StdDuration::from_millis(25);

#[derive(Debug, Serialize, Deserialize)]
pub(crate) struct ApiErrorEnvelope {
    pub(crate) code: String,
    pub(crate) error: String,
    #[serde(skip_serializing_if = "Option::is_none")]
    pub(crate) details: Option<serde_json::Value>,
}

pub(crate) fn api_error_response(
    status: StatusCode,
    code: &str,
    error: impl Into<String>,
    details: Option<serde_json::Value>,
) -> HttpResponse {
    HttpResponse::build(status).json(ApiErrorEnvelope {
        code: code.to_string(),
        error: error.into(),
        details,
    })
}

fn v2_invalid_request(
    error: impl Into<String>,
    details: Option<serde_json::Value>,
) -> HttpResponse {
    api_error_response(StatusCode::BAD_REQUEST, "invalid_request", error, details)
}

fn v2_not_found(error: impl Into<String>, details: Option<serde_json::Value>) -> HttpResponse {
    api_error_response(StatusCode::NOT_FOUND, "resource_not_found", error, details)
}

fn v2_conflict(error: impl Into<String>, details: Option<serde_json::Value>) -> HttpResponse {
    api_error_response(StatusCode::CONFLICT, "resource_conflict", error, details)
}

fn v2_internal_error(error: impl Into<String>, details: Option<serde_json::Value>) -> HttpResponse {
    api_error_response(
        StatusCode::INTERNAL_SERVER_ERROR,
        "internal_error",
        error,
        details,
    )
}

fn v2_execution_prepare_error(error: String, fallback_message: &'static str) -> HttpResponse {
    if error.starts_with("stateless_scope_not_activated:") {
        return api_error_response(
            StatusCode::SERVICE_UNAVAILABLE,
            "stateless_scope_not_activated",
            "Stateless execution is unavailable until this scope's legacy-writer cutover is sealed",
            Some(serde_json::json!({ "error": error })),
        );
    }
    v2_internal_error(
        fallback_message,
        Some(serde_json::json!({ "error": error })),
    )
}

fn v2_execution_load_error(execution_id: &str, err: &str) -> HttpResponse {
    if err.to_ascii_lowercase().contains("not found") {
        v2_not_found(
            "Execution not found",
            Some(serde_json::json!({
                "execution_id": execution_id,
            })),
        )
    } else {
        v2_internal_error(
            "Failed to load execution",
            Some(serde_json::json!({
                "execution_id": execution_id,
            })),
        )
    }
}

#[cfg(test)]
fn default_v3_root_for(base_path: &Path) -> PathBuf {
    ArtifactV2Workspace::resolve_scoped_root(base_path)
}

fn approval_service_error_response(
    err: ApprovalServiceError,
    approval_id: Option<&str>,
) -> HttpResponse {
    match err {
        ApprovalServiceError::NotFound(id) => api_error_response(
            StatusCode::NOT_FOUND,
            "approval_not_found",
            "Approval not found",
            Some(serde_json::json!({
                "approval_id": if id.is_empty() { approval_id.unwrap_or_default() } else { &id },
            })),
        ),
        ApprovalServiceError::Expired(id) => api_error_response(
            StatusCode::GONE,
            "approval_expired",
            "Approval is expired",
            Some(serde_json::json!({
                "approval_id": if id.is_empty() { approval_id.unwrap_or_default() } else { &id },
            })),
        ),
        ApprovalServiceError::PlanDrift {
            approval_id,
            expected_hash,
            actual_hash,
        } => api_error_response(
            StatusCode::CONFLICT,
            "approval_plan_drift",
            "Approval invalidated because execution plan changed; re-approval required",
            Some(serde_json::json!({
                "approval_id": approval_id,
                "expected_hash": expected_hash,
                "actual_hash": actual_hash,
            })),
        ),
        ApprovalServiceError::InvalidRequest(message) => api_error_response(
            StatusCode::BAD_REQUEST,
            "invalid_approval_request",
            message,
            None,
        ),
        ApprovalServiceError::Storage(details) => api_error_response(
            StatusCode::INTERNAL_SERVER_ERROR,
            "approval_storage_error",
            "Approval persistence failed",
            Some(serde_json::json!({
                "details": details,
            })),
        ),
        ApprovalServiceError::StateMachine(details) => api_error_response(
            StatusCode::INTERNAL_SERVER_ERROR,
            "approval_state_machine_error",
            "Approval transition evaluation failed",
            Some(serde_json::json!({
                "details": details,
            })),
        ),
    }
}

fn proposal_store_error_response(
    err: ProposalStoreError,
    proposal_id: Option<&str>,
) -> HttpResponse {
    match err {
        ProposalStoreError::InvalidProposalId(id) => api_error_response(
            StatusCode::BAD_REQUEST,
            "invalid_proposal_id",
            "Proposal id is invalid",
            Some(serde_json::json!({
                "proposal_id": if id.is_empty() { proposal_id.unwrap_or_default() } else { &id },
            })),
        ),
        ProposalStoreError::NotFound(id) => api_error_response(
            StatusCode::NOT_FOUND,
            "proposal_not_found",
            "Proposal not found",
            Some(serde_json::json!({
                "proposal_id": if id.is_empty() { proposal_id.unwrap_or_default() } else { &id },
            })),
        ),
        ProposalStoreError::StaleTransition {
            proposal_id,
            current_status,
            attempted_status,
        } => api_error_response(
            StatusCode::CONFLICT,
            "proposal_stale_transition",
            "Proposal transition is stale",
            Some(serde_json::json!({
                "proposal_id": proposal_id,
                "current_status": serde_json::to_value(&current_status).unwrap_or_default(),
                "attempted_status": serde_json::to_value(&attempted_status).unwrap_or_default(),
            })),
        ),
        ProposalStoreError::InvalidRequest(details) => api_error_response(
            StatusCode::BAD_REQUEST,
            "invalid_proposal_request",
            details,
            None,
        ),
        ProposalStoreError::Storage { details, .. } => api_error_response(
            StatusCode::INTERNAL_SERVER_ERROR,
            "proposal_storage_error",
            "Proposal persistence failed",
            Some(serde_json::json!({
                "details": details,
            })),
        ),
    }
}

fn parse_proposal_status_filter(raw: Option<&str>) -> Result<Option<ProposalStatus>, HttpResponse> {
    let Some(raw) = raw.map(str::trim).filter(|value| !value.is_empty()) else {
        return Ok(None);
    };
    let status = match raw.to_ascii_lowercase().as_str() {
        "pending" => ProposalStatus::Pending,
        "approved" => ProposalStatus::Approved,
        "rejected" => ProposalStatus::Rejected,
        "deferred" => ProposalStatus::Deferred,
        _ => {
            return Err(api_error_response(
                StatusCode::BAD_REQUEST,
                "invalid_proposal_filter",
                "status must be one of: pending, approved, rejected, deferred",
                Some(serde_json::json!({
                    "status": raw,
                })),
            ));
        },
    };
    Ok(Some(status))
}

fn approval_matches_status_filter(request: &ApprovalRequest, status: Option<&str>) -> bool {
    let Some(status) = status.map(str::trim).filter(|value| !value.is_empty()) else {
        return true;
    };
    let status = status.to_ascii_lowercase();
    matches!(
        (status.as_str(), &request.status),
        ("pending", ApprovalStatus::Pending)
            | ("validating", ApprovalStatus::Validating)
            | ("approved", ApprovalStatus::Approved)
            | ("rejected", ApprovalStatus::Rejected)
            | ("expired", ApprovalStatus::Expired)
    )
}

fn current_plan_hash_for_approval(
    full_pause_store: &Arc<FullPauseStore>,
    request: &ApprovalRequest,
) -> Option<String> {
    full_pause_store
        .confirmation_action_json_for_agent_ids(
            &request.agent_id,
            &request.goal_id,
            &request.cycle_id,
        )
        .map(|action_json| ApprovalService::hash_plan_payload(&action_json))
}

fn approval_decision_from_resume_value(value: &UserInputValue) -> Option<ApprovalDecision> {
    match value {
        UserInputValue::Confirmation { confirmed: true } => Some(ApprovalDecision::Approve),
        UserInputValue::Confirmation { confirmed: false } | UserInputValue::Aborted { .. } => {
            Some(ApprovalDecision::Reject)
        },
        _ => None,
    }
}

async fn reject_confirmation_approval_for_pause(
    approval_service: &Arc<ApprovalService>,
    v2_orchestrator: &Arc<MagicianV2Orchestrator>,
    pause_data: &FullPauseData,
    resolved_by: &str,
    event_source: &str,
) -> Result<(), HttpResponse> {
    if !matches!(pause_data.input_type, UserInputType::Confirmation { .. }) {
        return Ok(());
    }

    let Some(action_json) = pause_data.confirmation_action_json.as_deref() else {
        return Ok(());
    };

    let (Some(agent_id), Some(goal_id), Some(cycle_id)) = (
        pause_data.pause_state.agent_id.as_deref(),
        pause_data.pause_state.goal_id.as_deref(),
        pause_data.pause_state.cycle_id.as_deref(),
    ) else {
        return Ok(());
    };

    let plan_hash = ApprovalService::hash_plan_payload(action_json);
    let request = match approval_service
        .find_latest_request_for_cycle_plan(agent_id, goal_id, cycle_id, &plan_hash)
        .await
    {
        Ok(Some(request)) => request,
        Ok(None) => return Ok(()),
        Err(err) => return Err(approval_service_error_response(err, None)),
    };

    let approval_id = request.approval_id.clone();
    let outcome = approval_service
        .resolve_with_outcome(&approval_id, ApprovalDecision::Reject, resolved_by, None)
        .await
        .map_err(|err| approval_service_error_response(err, Some(&approval_id)))?;

    match outcome {
        ApprovalResolveOutcome::Resolved => {
            emit_approval_resolved_event(
                v2_orchestrator,
                pause_data.pause_state.principal.as_deref(),
                pause_data.pause_state.workspace.as_deref(),
                &request,
                &ApprovalDecision::Reject,
                resolved_by,
                event_source,
            );
        },
        ApprovalResolveOutcome::Expired { transitioned } => {
            if transitioned {
                match approval_service.get_request(&approval_id).await {
                    Ok(Some(expired_request)) => {
                        emit_approval_expired_event(
                            v2_orchestrator,
                            pause_data.pause_state.principal.as_deref(),
                            pause_data.pause_state.workspace.as_deref(),
                            &expired_request,
                            event_source,
                        );
                    },
                    Ok(None) => {},
                    Err(err) => {
                        warn!(
                            approval_id = %approval_id,
                            agent_id = %agent_id,
                            goal_id = %goal_id,
                            cycle_id = %cycle_id,
                            error = %err,
                            "Failed to load expired approval after rejection reconciliation"
                        );
                    },
                }
            }
        },
        ApprovalResolveOutcome::Noop => {},
    }

    Ok(())
}

async fn reconcile_confirmation_approval_on_resume(
    approval_service: &Arc<ApprovalService>,
    v2_orchestrator: &Arc<MagicianV2Orchestrator>,
    pause_data: &FullPauseData,
    user_value: &UserInputValue,
) -> Result<(), HttpResponse> {
    if !matches!(pause_data.input_type, UserInputType::Confirmation { .. }) {
        return Ok(());
    }

    let Some(decision) = approval_decision_from_resume_value(user_value) else {
        return Ok(());
    };

    match decision {
        ApprovalDecision::Reject => {
            reject_confirmation_approval_for_pause(
                approval_service,
                v2_orchestrator,
                pause_data,
                "in_app",
                "resume_confirmation",
            )
            .await
        },
        ApprovalDecision::Approve => {
            let Some(action_json) = pause_data.confirmation_action_json.as_deref() else {
                return Ok(());
            };

            let (Some(agent_id), Some(goal_id), Some(cycle_id)) = (
                pause_data.pause_state.agent_id.as_deref(),
                pause_data.pause_state.goal_id.as_deref(),
                pause_data.pause_state.cycle_id.as_deref(),
            ) else {
                return Ok(());
            };

            let plan_hash = ApprovalService::hash_plan_payload(action_json);
            let request = match approval_service
                .find_latest_request_for_cycle_plan(agent_id, goal_id, cycle_id, &plan_hash)
                .await
            {
                Ok(Some(request)) => request,
                Ok(None) => return Ok(()),
                Err(err) => return Err(approval_service_error_response(err, None)),
            };

            let approval_id = request.approval_id.clone();
            let outcome = approval_service
                .resolve_with_outcome(
                    &approval_id,
                    ApprovalDecision::Approve,
                    "in_app",
                    Some(plan_hash.as_str()),
                )
                .await
                .map_err(|err| approval_service_error_response(err, Some(&approval_id)))?;

            match outcome {
                ApprovalResolveOutcome::Resolved => {
                    emit_approval_resolved_event(
                        v2_orchestrator,
                        pause_data.pause_state.principal.as_deref(),
                        pause_data.pause_state.workspace.as_deref(),
                        &request,
                        &ApprovalDecision::Approve,
                        "in_app",
                        "resume_confirmation",
                    );
                    return Ok(());
                },
                ApprovalResolveOutcome::Expired { transitioned } => {
                    if transitioned {
                        match approval_service.get_request(&approval_id).await {
                            Ok(Some(expired_request)) => {
                                emit_approval_expired_event(
                                    v2_orchestrator,
                                    pause_data.pause_state.principal.as_deref(),
                                    pause_data.pause_state.workspace.as_deref(),
                                    &expired_request,
                                    "resume_confirmation",
                                );
                            },
                            Ok(None) => {},
                            Err(err) => {
                                warn!(
                                    approval_id = %approval_id,
                                    agent_id = %agent_id,
                                    goal_id = %goal_id,
                                    cycle_id = %cycle_id,
                                    error = %err,
                                    "Failed to load expired approval after approval reconciliation"
                                );
                            },
                        }
                    }
                    return Err(api_error_response(
                        StatusCode::GONE,
                        "approval_expired",
                        "Approval is expired",
                        Some(serde_json::json!({ "approval_id": approval_id })),
                    ));
                },
                ApprovalResolveOutcome::Noop => {},
            }

            let (latest, expired_on_read) = approval_service
                .get_request_with_transition(&approval_id)
                .await
                .map_err(|err| approval_service_error_response(err, Some(&approval_id)))?;
            let latest = latest.ok_or_else(|| {
                api_error_response(
                    StatusCode::NOT_FOUND,
                    "approval_not_found",
                    "Approval not found",
                    Some(serde_json::json!({ "approval_id": approval_id })),
                )
            })?;

            if expired_on_read {
                emit_approval_expired_event(
                    v2_orchestrator,
                    pause_data.pause_state.principal.as_deref(),
                    pause_data.pause_state.workspace.as_deref(),
                    &latest,
                    "resume_confirmation",
                );
            }

            match latest.status {
                ApprovalStatus::Approved => Ok(()),
                ApprovalStatus::Expired => Err(api_error_response(
                    StatusCode::GONE,
                    "approval_expired",
                    "Approval is expired",
                    Some(serde_json::json!({ "approval_id": latest.approval_id })),
                )),
                ApprovalStatus::Rejected => Err(api_error_response(
                    StatusCode::CONFLICT,
                    "approval_rejected",
                    "Approval was rejected and cannot be resumed",
                    Some(serde_json::json!({ "approval_id": latest.approval_id })),
                )),
                ApprovalStatus::Pending | ApprovalStatus::Validating => Err(api_error_response(
                    StatusCode::CONFLICT,
                    "approval_not_resolved",
                    "Approval is not in approved state",
                    Some(serde_json::json!({
                        "approval_id": latest.approval_id,
                        "status": format!("{:?}", latest.status),
                    })),
                )),
            }
        },
    }
}

fn should_auto_resume_on_approval_resolution(decision: &ApprovalDecision, resolved: bool) -> bool {
    resolved && matches!(decision, ApprovalDecision::Approve)
}

fn execution_hint_for_approval(
    full_pause_store: &Arc<FullPauseStore>,
    request: &ApprovalRequest,
    principal: &str,
    workspace: &str,
) -> Option<String> {
    let mut matching_execution_ids = full_pause_store
        .get_pending_for_agent(&request.agent_id)
        .into_iter()
        .filter(|pause| {
            pause.goal_id.as_deref() == Some(request.goal_id.as_str())
                && pause.cycle_id.as_deref() == Some(request.cycle_id.as_str())
                && !pause.execution_id.trim().is_empty()
                && pause.principal.as_deref() == Some(principal)
                && pause.workspace.as_deref() == Some(workspace)
        })
        .map(|pause| pause.execution_id)
        .collect::<Vec<_>>();
    matching_execution_ids.sort();
    matching_execution_ids.dedup();

    if let Some(persisted_execution_id) = request
        .execution_id
        .as_deref()
        .map(str::trim)
        .filter(|execution_id| !execution_id.is_empty())
    {
        return matching_execution_ids
            .iter()
            .any(|execution_id| execution_id == persisted_execution_id)
            .then(|| persisted_execution_id.to_string());
    }

    (matching_execution_ids.len() == 1).then(|| matching_execution_ids.remove(0))
}

fn build_auto_resume_request_for_approval(request: &ApprovalRequest) -> AgenticResumeRequest {
    AgenticResumeRequest {
        pause_state_id: None,
        plan_id: None,
        step_id: None,
        input_type: "confirmation".to_string(),
        value: AgenticResumeValue::Confirmation { confirmed: true },
        agent_id: Some(request.agent_id.clone()),
        goal_id: Some(request.goal_id.clone()),
        cycle_id: Some(request.cycle_id.clone()),
    }
}

fn has_partial_plan_step_selector(plan_id: Option<&str>, step_id: Option<&str>) -> bool {
    plan_id.is_some() ^ step_id.is_some()
}

fn pause_storage_key_for_agent_ids(agent_id: &str, goal_id: &str, cycle_id: &str) -> String {
    format!("{}{}:{}:{}", AGENT_KEY_PREFIX, agent_id, goal_id, cycle_id)
}

fn pause_execution_id(
    pause_state: &magician::magician_v2::execution::agentic::AgenticPauseState,
) -> Option<&str> {
    pause_state.execution_id.as_deref()
}

fn full_pause_data_from_serializable(
    serializable: magician::magician_v2::execution::agentic::SerializablePauseData,
    executors: magician::magician_v2::execution::agentic::ActionExecutors,
) -> FullPauseData {
    executors.run_identity.update(|identity| {
        identity.principal = serializable.principal.clone();
        identity.workspace = serializable.workspace.clone();
    });
    let sanitized_previous_answer = sanitize_retry_previous_answer(
        &serializable.input_type,
        serializable.asking_for_parameter.as_deref(),
        &serializable.pending_inputs,
        serializable.question.as_deref(),
        serializable.hint.as_deref(),
        serializable.pause_state.pending_sensitive.as_ref(),
        serializable.previous_answer.as_deref(),
    );
    FullPauseData {
        pause_state: serializable.pause_state,
        input_type: serializable.input_type,
        executors,
        question: serializable.question,
        hint: serializable.hint,
        confirmation_action_json: serializable.confirmation_action_json,
        secret_approval_challenge_id: serializable.secret_approval_challenge_id,
        secret_approval_request: serializable.secret_approval_request,
        pending_inputs: serializable.pending_inputs,
        resolved_inputs: serializable.resolved_inputs,
        asking_for_parameter: serializable.asking_for_parameter,
        retry_count: serializable.retry_count,
        previous_answer: sanitized_previous_answer,
        retry_reason: serializable.retry_reason,
        escalation_trigger: serializable.escalation_trigger,
        confirmation_action_summary: serializable.confirmation_action_summary,
        confirmation_reason: serializable.confirmation_reason,
        confirmation_action_type: serializable.confirmation_action_type,
        pause_kind: serializable.pause_kind,
        harness_pause: serializable.harness_pause,
    }
}

fn pause_matches_lookup_constraints(
    pause_data: &FullPauseData,
    execution_id: &str,
    pause_state_id: Option<&str>,
    plan_id: Option<&str>,
    step_id: Option<&str>,
    agent_id: Option<&str>,
    goal_id: Option<&str>,
    cycle_id: Option<&str>,
) -> bool {
    let pause_execution_id = pause_execution_id(&pause_data.pause_state);

    if let Some(expected_key) = pause_state_id {
        if pause_data.pause_state.storage_key() != expected_key {
            return false;
        }
    }

    if let Some(pause_execution_id) = pause_execution_id {
        if pause_execution_id != execution_id {
            return false;
        }
    }

    if let (Some(aid), Some(gid), Some(cid)) = (agent_id, goal_id, cycle_id) {
        if pause_data.pause_state.agent_id.as_deref() != Some(aid)
            || pause_data.pause_state.goal_id.as_deref() != Some(gid)
            || pause_data.pause_state.cycle_id.as_deref() != Some(cid)
        {
            return false;
        }
    } else if pause_execution_id != Some(execution_id) {
        // Runtime endpoint lookups without explicit agent routing must resolve to the path execution.
        return false;
    }

    if has_partial_plan_step_selector(plan_id, step_id) {
        return false;
    }

    if let (Some(expected_plan), Some(expected_step)) = (plan_id, step_id) {
        if pause_data.pause_state.plan_id.as_deref() != Some(expected_plan)
            || pause_data.pause_state.step_id.as_deref() != Some(expected_step)
        {
            return false;
        }
    }

    true
}

fn plan_step_from_pause_selector(
    execution_id: &str,
    pause_state_id: Option<&str>,
    plan_id: Option<&str>,
    step_id: Option<&str>,
) -> (String, String) {
    if let (Some(plan_id), Some(step_id)) = (plan_id, step_id) {
        return (plan_id.to_string(), step_id.to_string());
    }

    let Some(pause_state_id) = pause_state_id else {
        return (String::new(), String::new());
    };
    // A caller may hand this the canonical correlation id rather than the bare
    // storage key; the ask suffix is not part of the step id.
    let pause_state_id =
        magician::magician_v2::execution::agentic::split_hitl_correlation_id(pause_state_id).0;
    let mut parts = pause_state_id.splitn(3, ':');
    match (parts.next(), parts.next(), parts.next()) {
        (Some(key_execution_id), Some(plan_id), Some(step_id))
            if key_execution_id == execution_id =>
        {
            (plan_id.to_string(), step_id.to_string())
        },
        _ => (String::new(), String::new()),
    }
}

/// Phase H2 — emit canonical `HitlResolved` alongside `AgenticResumed`.
/// `correlation_id` is the same `pause_state_id` the canonical
/// `HitlRequested` carried, so frontend `pendingHitlStore` can dedupe
/// pending entries off whichever event arrives.
fn emit_hitl_resolved_for_agentic_pause(
    orchestrator: &Arc<MagicianV2Orchestrator>,
    pause_state_id: Option<&str>,
    execution_id: &str,
    task_id: Option<String>,
    principal: Option<String>,
    workspace: Option<String>,
    agent_id: Option<String>,
    decision: Option<String>,
    outcome: &str,
) {
    let Some(broadcaster) = orchestrator.event_broadcaster() else {
        return;
    };
    let Some(correlation_id) = pause_state_id else {
        // Without a stable correlation id we can't dedupe against the
        // pending entry, so skip the canonical emit. The legacy
        // `AgenticResumed` event still fires.
        return;
    };
    // Persist canonical resolution. Attention reconstructs pending HITL from
    // event-log backfill, so a transport-only resolution makes an answered
    // pause reappear after refresh or restart.
    broadcaster.emit(
        magician::magician_v2::realtime_events::RuntimeTransportEvent::HitlResolved {
            correlation_id: correlation_id.to_string(),
            source: "agentic".to_string(),
            outcome: outcome.to_string(),
            decision,
            task_id,
            execution_id: Some(execution_id.to_string()),
            agent_id,
            principal,
            workspace,
            timestamp: chrono::Utc::now().timestamp_millis(),
        },
    );
}

/// Resolve the storage key that a resolve/resume request targets, using the
/// same precedence as [`select_pause_storage_key_for_request`] but as a free
/// function over the already-fetched pending set. Returns `None` when no
/// selector was supplied (whole-execution scan) so the caller can fall back to
/// the emptiness check for that degenerate case.
fn target_pause_storage_key_for_selector(
    pending: &[magician::magician_v2::execution::agentic::PendingPauseInfo],
    execution_id: &str,
    pause_state_id: Option<&str>,
    plan_id: Option<&str>,
    step_id: Option<&str>,
    agent_id: Option<&str>,
    goal_id: Option<&str>,
    cycle_id: Option<&str>,
) -> Option<String> {
    if let Some(key) = pause_state_id {
        return Some(key.to_string());
    }
    if let (Some(aid), Some(gid), Some(cid)) = (agent_id, goal_id, cycle_id) {
        return Some(pause_storage_key_for_agent_ids(aid, gid, cid));
    }
    if let (Some(pid), Some(sid)) = (plan_id, step_id) {
        // Prefer the matched pending key so the persisted `HitlResolved`
        // carries the id the card's `HitlRequested` used; fall back to the
        // deterministic composite key.
        return pending
            .iter()
            .find(|p| p.plan_id.as_deref() == Some(pid) && p.step_id.as_deref() == Some(sid))
            .map(|p| p.key.clone())
            .or_else(|| Some(format!("{}:{}:{}", execution_id, pid, sid)));
    }
    None
}

/// A resolve/resume that missed a live pause counts as "resolved elsewhere"
/// only when *this* request's specific pause is no longer pending. A sibling
/// pause on the same execution (the common multi-agent / company-loop fan-out
/// case) must NOT suppress the canonical `HitlResolved` for the correlation the
/// operator just answered.
fn should_suppress_resolved_elsewhere(
    pending: &[magician::magician_v2::execution::agentic::PendingPauseInfo],
    execution_id: &str,
    pause_state_id: Option<&str>,
    plan_id: Option<&str>,
    step_id: Option<&str>,
    agent_id: Option<&str>,
    goal_id: Option<&str>,
    cycle_id: Option<&str>,
) -> bool {
    match target_pause_storage_key_for_selector(
        pending,
        execution_id,
        pause_state_id,
        plan_id,
        step_id,
        agent_id,
        goal_id,
        cycle_id,
    ) {
        // A concrete correlation was requested — suppress only when that exact
        // pause is still live.
        Some(target_key) => pending.iter().any(|p| p.key == target_key),
        // No selector at all: fall back to the whole-execution emptiness check
        // (a bare execution-scoped resolve genuinely cannot target a sibling).
        None => !pending.is_empty(),
    }
}

fn emit_resolved_elsewhere_notice_for_missing_pause(
    orchestrator: &Arc<MagicianV2Orchestrator>,
    full_pause_store: &Arc<FullPauseStore>,
    execution_id: &str,
    req: &AgenticResumeRequest,
    // The id the client actually named — the canonical `<key>~<ask>` when it
    // had one. The notice exists to retire that request on every surface, and
    // a surface keys its pending entry on the id it was told; resolving the
    // bare key would leave the card's badge behind.
    canonical_correlation_id: Option<&str>,
) {
    let pending = full_pause_store.get_pending_for_execution(execution_id);
    if should_suppress_resolved_elsewhere(
        &pending,
        execution_id,
        req.pause_state_id.as_deref(),
        req.plan_id.as_deref(),
        req.step_id.as_deref(),
        req.agent_id.as_deref(),
        req.goal_id.as_deref(),
        req.cycle_id.as_deref(),
    ) {
        return;
    }

    let Some(broadcaster) = orchestrator.event_broadcaster() else {
        return;
    };
    let (plan_id, step_id) = plan_step_from_pause_selector(
        execution_id,
        req.pause_state_id.as_deref(),
        req.plan_id.as_deref(),
        req.step_id.as_deref(),
    );
    // When no explicit pause_state_id was supplied, derive the correlation id
    // from the selector so the canonical `HitlResolved` carries the same id the
    // card's `HitlRequested` used (dedupe hinges on that correlation).
    // The canonical id the client named wins: it is the one every surface
    // keyed its pending entry on. Only a caller that named no ask falls back
    // to the selector's own key.
    let correlation_id = canonical_correlation_id
        .map(ToOwned::to_owned)
        .or_else(|| req.pause_state_id.clone())
        .or_else(|| {
            target_pause_storage_key_for_selector(
                &pending,
                execution_id,
                req.pause_state_id.as_deref(),
                req.plan_id.as_deref(),
                req.step_id.as_deref(),
                req.agent_id.as_deref(),
                req.goal_id.as_deref(),
                req.cycle_id.as_deref(),
            )
        });

    broadcaster.emit_transport_only(
        magician::magician_v2::realtime_events::RuntimeTransportEvent::AgenticResumed {
            execution_id: execution_id.to_string(),
            principal: None,
            workspace: None,
            // The id the client named, so this notice and its `HitlResolved`
            // retire the same card the surfaces are holding.
            pause_state_id: correlation_id.clone(),
            plan_id,
            step_id,
            resumed_from_iteration: 0,
            input_type: RESOLVED_ELSEWHERE_INPUT_TYPE.to_string(),
            user_responded: true,
            agent_id: req.agent_id.clone(),
            goal_id: req.goal_id.clone(),
            cycle_id: req.cycle_id.clone(),
            timestamp: chrono::Utc::now().timestamp_millis(),
        },
    );
    // Phase H2 — canonical dual-emit. "Already resolved elsewhere" still
    // counts as `responded` from the operator's perspective; the request
    // is no longer pending.
    emit_hitl_resolved_for_agentic_pause(
        orchestrator,
        correlation_id.as_deref(),
        execution_id,
        None,
        None,
        None,
        req.agent_id.clone(),
        None,
        "responded",
    );
}

fn emit_resolved_elsewhere_notice_for_missing_continue_pause(
    orchestrator: &Arc<MagicianV2Orchestrator>,
    full_pause_store: &Arc<FullPauseStore>,
    execution_id: &str,
    req: &AgenticContinueRequest,
    // See `emit_resolved_elsewhere_notice_for_missing_pause`.
    canonical_correlation_id: Option<&str>,
) {
    let pending = full_pause_store.get_pending_for_execution(execution_id);
    if should_suppress_resolved_elsewhere(
        &pending,
        execution_id,
        req.pause_state_id.as_deref(),
        req.plan_id.as_deref(),
        req.step_id.as_deref(),
        req.agent_id.as_deref(),
        req.goal_id.as_deref(),
        req.cycle_id.as_deref(),
    ) {
        return;
    }

    let Some(broadcaster) = orchestrator.event_broadcaster() else {
        return;
    };
    let (plan_id, step_id) = plan_step_from_pause_selector(
        execution_id,
        req.pause_state_id.as_deref(),
        req.plan_id.as_deref(),
        req.step_id.as_deref(),
    );

    // When no explicit pause_state_id was supplied, derive the correlation id
    // from the selector so the canonical `HitlResolved` carries the same id the
    // card's `HitlRequested` used (dedupe hinges on that correlation).
    // The canonical id the client named wins: it is the one every surface
    // keyed its pending entry on. Only a caller that named no ask falls back
    // to the selector's own key.
    let correlation_id = canonical_correlation_id
        .map(ToOwned::to_owned)
        .or_else(|| req.pause_state_id.clone())
        .or_else(|| {
            target_pause_storage_key_for_selector(
                &pending,
                execution_id,
                req.pause_state_id.as_deref(),
                req.plan_id.as_deref(),
                req.step_id.as_deref(),
                req.agent_id.as_deref(),
                req.goal_id.as_deref(),
                req.cycle_id.as_deref(),
            )
        });

    broadcaster.emit_transport_only(
        magician::magician_v2::realtime_events::RuntimeTransportEvent::AgenticResumed {
            execution_id: execution_id.to_string(),
            principal: None,
            workspace: None,
            // The id the client named, so this notice and its `HitlResolved`
            // retire the same card the surfaces are holding.
            pause_state_id: correlation_id.clone(),
            plan_id,
            step_id,
            resumed_from_iteration: 0,
            input_type: RESOLVED_ELSEWHERE_INPUT_TYPE.to_string(),
            user_responded: true,
            agent_id: req.agent_id.clone(),
            goal_id: req.goal_id.clone(),
            cycle_id: req.cycle_id.clone(),
            timestamp: chrono::Utc::now().timestamp_millis(),
        },
    );
    // Phase H2 — canonical dual-emit (continue path).
    emit_hitl_resolved_for_agentic_pause(
        orchestrator,
        correlation_id.as_deref(),
        execution_id,
        None,
        None,
        None,
        req.agent_id.clone(),
        None,
        "responded",
    );
}

/// Re-request a pause the handler put back after it had already announced
/// the answer as the pause's resolution — a validation re-ask, or a loop that
/// failed before it could run on the answer. Persisted canonically like the
/// loop's own `HitlRequested`, so the card returns to the feed; the resolution
/// announced earlier settles only the request that preceded it.
fn emit_hitl_requested_for_restored_pause(
    orchestrator: &Arc<MagicianV2Orchestrator>,
    execution_id: &str,
    pause_data: &FullPauseData,
) {
    let Some(broadcaster) = orchestrator.event_broadcaster() else {
        return;
    };
    let protected_app = pause_data.pause_state.app_disclosure_checkpoint.is_some();
    let input_type = magician::magician_v2::execution::agentic::format_input_type_for_event(
        &pause_data.input_type,
    );
    broadcaster.emit(
        magician::magician_v2::realtime_events::RuntimeTransportEvent::HitlRequested {
            correlation_id: pause_data.pause_state.storage_key(),
            source: "agentic".to_string(),
            input_type: input_type.clone(),
            prompt: if protected_app {
                "Protected app workflow requires user input".to_owned()
            } else {
                pause_data.question.clone().unwrap_or_default()
            },
            hint: if protected_app {
                None
            } else {
                pause_data.hint.clone()
            },
            input_schema: if protected_app {
                Some(serde_json::json!({
                    "protected": true,
                    "input_type": input_type,
                }))
            } else {
                pause_data.input_type.schema_json_value()
            },
            task_id: pause_data.pause_state.task_id.clone(),
            execution_id: Some(execution_id.to_string()),
            agent_id: pause_data.pause_state.agent_id.clone(),
            principal: pause_data.pause_state.principal.clone(),
            workspace: pause_data.pause_state.workspace.clone(),
            timestamp: chrono::Utc::now().timestamp_millis(),
        },
    );
}

fn emit_agentic_resumed_notice_for_answered_pause(
    orchestrator: &Arc<MagicianV2Orchestrator>,
    execution_id: &str,
    pause_data: &FullPauseData,
    req: &AgenticResumeRequest,
    input_type: &str,
    user_responded: bool,
) {
    let Some(broadcaster) = orchestrator.event_broadcaster() else {
        return;
    };
    let plan_id = pause_data
        .pause_state
        .plan_id
        .clone()
        .or_else(|| req.plan_id.clone())
        .unwrap_or_default();
    let step_id = pause_data
        .pause_state
        .step_id
        .clone()
        .or_else(|| req.step_id.clone())
        .unwrap_or_default();
    // The pause's canonical id, not the selector the client happened to use:
    // this notice and the `HitlResolved` beside it must name the same ask the
    // request was published under, because that is the id every surface
    // indexed its open card by (a chat escalation card matched only by an
    // execution-wide fallback otherwise, which picks the newest card when a
    // run has asked twice).
    let pause_state_id = Some(pause_data.pause_state.hitl_correlation_id());

    broadcaster.emit_transport_only(
        magician::magician_v2::realtime_events::RuntimeTransportEvent::AgenticResumed {
            execution_id: execution_id.to_string(),
            principal: pause_data.pause_state.principal.clone(),
            workspace: pause_data.pause_state.workspace.clone(),
            pause_state_id: pause_state_id.clone(),
            plan_id,
            step_id,
            resumed_from_iteration: pause_data.pause_state.iteration,
            input_type: input_type.to_string(),
            user_responded,
            agent_id: pause_data.pause_state.agent_id.clone(),
            goal_id: pause_data.pause_state.goal_id.clone(),
            cycle_id: pause_data.pause_state.cycle_id.clone(),
            timestamp: chrono::Utc::now().timestamp_millis(),
        },
    );
    // Phase H2 — canonical dual-emit. The primary "user responded"
    // resume path; outcome is `responded` on success. The resolution names
    // the pause's own canonical id — the one its `HitlRequested` carried —
    // whatever selector the client used to find it.
    emit_hitl_resolved_for_agentic_pause(
        orchestrator,
        Some(&pause_data.pause_state.hitl_correlation_id()),
        execution_id,
        pause_data.pause_state.task_id.clone(),
        pause_data.pause_state.principal.clone(),
        pause_data.pause_state.workspace.clone(),
        pause_data.pause_state.agent_id.clone(),
        Some(input_type.to_string()),
        if user_responded {
            "responded"
        } else {
            "cancelled"
        },
    );
}

fn emit_agentic_resumed_notice_for_continued_pause(
    orchestrator: &Arc<MagicianV2Orchestrator>,
    execution_id: &str,
    pause_data: &FullPauseData,
    req: &AgenticContinueRequest,
) {
    let Some(broadcaster) = orchestrator.event_broadcaster() else {
        return;
    };
    let plan_id = pause_data
        .pause_state
        .plan_id
        .clone()
        .or_else(|| req.plan_id.clone())
        .unwrap_or_default();
    let step_id = pause_data
        .pause_state
        .step_id
        .clone()
        .or_else(|| req.step_id.clone())
        .unwrap_or_default();
    // The pause's canonical id, not the selector the client happened to use:
    // this notice and the `HitlResolved` beside it must name the same ask the
    // request was published under, because that is the id every surface
    // indexed its open card by (a chat escalation card matched only by an
    // execution-wide fallback otherwise, which picks the newest card when a
    // run has asked twice).
    let pause_state_id = Some(pause_data.pause_state.hitl_correlation_id());

    broadcaster.emit_transport_only(
        magician::magician_v2::realtime_events::RuntimeTransportEvent::AgenticResumed {
            execution_id: execution_id.to_string(),
            principal: pause_data.pause_state.principal.clone(),
            workspace: pause_data.pause_state.workspace.clone(),
            pause_state_id: pause_state_id.clone(),
            plan_id,
            step_id,
            resumed_from_iteration: pause_data.pause_state.iteration,
            input_type: CONTINUE_INPUT_TYPE.to_string(),
            user_responded: true,
            agent_id: pause_data.pause_state.agent_id.clone(),
            goal_id: pause_data.pause_state.goal_id.clone(),
            cycle_id: pause_data.pause_state.cycle_id.clone(),
            timestamp: chrono::Utc::now().timestamp_millis(),
        },
    );
    // Phase H2 — canonical dual-emit. The "continue" decision counts as
    // the operator's response to a max-iterations pause.
    emit_hitl_resolved_for_agentic_pause(
        orchestrator,
        Some(&pause_data.pause_state.hitl_correlation_id()),
        execution_id,
        pause_data.pause_state.task_id.clone(),
        pause_data.pause_state.principal.clone(),
        pause_data.pause_state.workspace.clone(),
        pause_data.pause_state.agent_id.clone(),
        Some("continue".to_string()),
        "responded",
    );
}

fn is_max_iterations_continue_pause(pause_data: &FullPauseData) -> bool {
    // A budget pause is resumed identically to a max-iterations pause (fresh
    // budget via the "Continue execution?" agentic-continue flow); classify it
    // here so the resume path fires the same continue re-emission and reset.
    if matches!(
        pause_data.pause_kind,
        Some(ExecutionPauseKind::MaxIterations) | Some(ExecutionPauseKind::Budget)
    ) {
        return true;
    }
    // Classify max-iterations continue pauses by explicit confirmation labels and
    // absence of approval-action payload. This keeps replay/continue robust even
    // when legacy persisted payloads omit or alter the question text.
    matches!(
        &pause_data.input_type,
        UserInputType::Confirmation {
            confirm_label,
            deny_label,
            destructive: false,
        } if confirm_label.as_deref() == Some("Resume")
            && deny_label.as_deref() == Some("Cancel")
            && pause_data.confirmation_action_json.is_none()
    )
}

fn direct_execution_block_reason(waiting_state: &WaitingState) -> Option<&'static str> {
    match waiting_state {
        WaitingState::Planning | WaitingState::PlanningComplete => None,
        WaitingState::Runnable => Some(
            "Runnable execution requires server-owned typed recovery authority",
        ),
        WaitingState::Completed | WaitingState::Cancelled | WaitingState::Failed => {
            Some("Terminal executions require a new execution id for rerun")
        },
        WaitingState::Executing => Some("Execution is already running"),
        WaitingState::Sleeping => Some(
            "Execution is deferred on its execution-bound retry timer; direct execution cannot replace it",
        ),
        WaitingState::WaitingUser => Some(
            "Execution is waiting for user input; resume or cancel the paused execution instead",
        ),
        WaitingState::WaitingChildren => Some(
            "Execution is waiting on delegated child work; direct execution cannot bypass WaitingChildren",
        ),
        WaitingState::Paused => Some(
            "Execution is paused; resume or cancel the paused execution instead",
        ),
    }
}

/// Check whether a pause is eligible for the agentic-continue flow.
///
/// Returns true for max-iterations pauses (existing behavior) and for
/// escalation pauses (on_failure: ask_user). The "Keep Trying" button on
/// the frontend sends an agentic-continue request for escalation pauses.
fn is_continuable_pause(pause_data: &FullPauseData) -> bool {
    matches!(
        pause_data.pause_kind,
        Some(ExecutionPauseKind::MaxIterations)
            | Some(ExecutionPauseKind::Budget)
            | Some(ExecutionPauseKind::Escalation)
            | Some(ExecutionPauseKind::Manual)
    ) || is_max_iterations_continue_pause(pause_data)
        || pause_data.escalation_trigger.is_some()
}

fn is_manual_exact_pause(pause_data: &FullPauseData) -> bool {
    pause_data.pause_kind == Some(ExecutionPauseKind::Manual)
}

/// Truncate a string to at most `max_bytes` bytes, ensuring the cut
/// falls on a valid UTF-8 char boundary (never panics on multi-byte chars).
fn truncate_to_char_boundary(s: &str, max_bytes: usize) -> &str {
    if s.len() <= max_bytes {
        return s;
    }
    let mut end = max_bytes;
    while end > 0 && !s.is_char_boundary(end) {
        end -= 1;
    }
    &s[..end]
}

/// Truncate user guidance text within `UserInputValue` variants to prevent
/// oversized payloads from being injected into the LLM goal context.
fn truncate_user_input_guidance(value: UserInputValue) -> UserInputValue {
    match value {
        UserInputValue::ExternalActionCompleted { guidance } => {
            UserInputValue::ExternalActionCompleted {
                guidance: guidance
                    .map(|g| truncate_to_char_boundary(&g, MAX_GUIDANCE_LENGTH).to_string()),
            }
        },
        UserInputValue::Guidance { advice } => UserInputValue::Guidance {
            advice: truncate_to_char_boundary(&advice, MAX_GUIDANCE_LENGTH).to_string(),
        },
        other => other,
    }
}

async fn restore_pause_after_continue_error(
    full_pause_store: &Arc<FullPauseStore>,
    pause_data: FullPauseData,
) -> Option<(String, FullPauseData)> {
    let key = pause_data.pause_state.storage_key();
    restore_taken_pause_exact(full_pause_store, pause_data.clone()).then_some((key, pause_data))
}

/// Build a pause prompt event to rehydrate connected clients when continue fails
/// after we already acknowledged the optimistic continue request.
fn build_continue_failure_pause_reemit_event(
    requested_execution_id: &str,
    restored_pause_state_id: &str,
    restored_pause_data: &FullPauseData,
) -> magician::magician_v2::realtime_events::RuntimeTransportEvent {
    let effective_execution_id = if requested_execution_id.is_empty() {
        restored_pause_data
            .pause_state
            .execution_id
            .as_deref()
            .unwrap_or_default()
    } else {
        requested_execution_id
    };
    let plan_id = restored_pause_data
        .pause_state
        .plan_id
        .clone()
        .unwrap_or_default();
    let step_id = restored_pause_data
        .pause_state
        .step_id
        .clone()
        .unwrap_or_default();
    let timestamp = chrono::Utc::now().timestamp_millis();

    if is_max_iterations_continue_pause(restored_pause_data) {
        magician::magician_v2::realtime_events::RuntimeTransportEvent::AgenticMaxIterationsReached {
            execution_id: effective_execution_id.to_string(),
            principal: restored_pause_data.pause_state.principal.clone(),
            workspace: restored_pause_data.pause_state.workspace.clone(),
            plan_id,
            step_id,
            iterations_used: restored_pause_data.pause_state.iteration,
            pause_state_id: Some(restored_pause_state_id.to_string()),
            agent_id: restored_pause_data.pause_state.agent_id.clone(),
            goal_id: restored_pause_data.pause_state.goal_id.clone(),
            cycle_id: restored_pause_data.pause_state.cycle_id.clone(),
            timestamp,
        }
    } else if restored_pause_data.confirmation_action_summary.is_some() {
        magician::magician_v2::realtime_events::RuntimeTransportEvent::AgenticWaitingForConfirmation {
            execution_id: effective_execution_id.to_string(),
            principal: restored_pause_data.pause_state.principal.clone(),
            workspace: restored_pause_data.pause_state.workspace.clone(),
            plan_id,
            step_id,
            iteration: restored_pause_data.pause_state.iteration,
            pause_state_id: Some(restored_pause_state_id.to_string()),
            agent_id: restored_pause_data.pause_state.agent_id.clone(),
            goal_id: restored_pause_data.pause_state.goal_id.clone(),
            cycle_id: restored_pause_data.pause_state.cycle_id.clone(),
            timestamp,
        }
    } else {
        magician::magician_v2::realtime_events::RuntimeTransportEvent::AgenticWaitingForUser {
            execution_id: effective_execution_id.to_string(),
            principal: restored_pause_data.pause_state.principal.clone(),
            workspace: restored_pause_data.pause_state.workspace.clone(),
            plan_id,
            step_id,
            iteration: restored_pause_data.pause_state.iteration,
            pause_state_id: Some(restored_pause_state_id.to_string()),
            correlation_id: None,
            is_retry: restored_pause_data.is_retry().then_some(true),
            retry_count: (restored_pause_data.retry_count > 0)
                .then_some(restored_pause_data.retry_count),
            agent_id: restored_pause_data.pause_state.agent_id.clone(),
            goal_id: restored_pause_data.pause_state.goal_id.clone(),
            cycle_id: restored_pause_data.pause_state.cycle_id.clone(),
            escalation_trigger: restored_pause_data.escalation_trigger.clone(),
            timestamp,
        }
    }
}

fn is_benign_auto_resume_race(status: StatusCode) -> bool {
    matches!(status, StatusCode::NOT_FOUND | StatusCode::CONFLICT)
}

fn parse_validation_issues(details: &str) -> Vec<String> {
    let trimmed = details.trim();
    if trimmed.is_empty() {
        return Vec::new();
    }
    if !trimmed.starts_with(MULTI_VALIDATION_ERROR_PREFIX) {
        return vec![trimmed.to_string()];
    }

    let mut issues = Vec::new();
    for line in trimmed.lines().skip(1) {
        let candidate = line.trim_start();
        if let Some(issue) = candidate.strip_prefix("- ").map(str::trim) {
            if !issue.is_empty() {
                issues.push(issue.to_string());
            }
        }
    }
    if issues.is_empty() {
        vec![trimmed.to_string()]
    } else {
        issues
    }
}

