#[cfg(test)]
fn scoped_agent_storage_root(base_root: &Path, principal: &str, workspace: &str) -> PathBuf {
    magician::magician_v2::artifact_v2::workspace::ArtifactV2Workspace::new(
        derive_agent_storage_base_root(base_root),
    )
    .scope_root(principal, workspace)
    .join(AGENT_SCOPE_ROOT_DIR)
}

fn ensure_system_trust_policy_templates_sync(workspace: &ArtifactV2Workspace) {
    // A read-only seed (container/deployment) ships the trust policy templates;
    // never write into it.
    if workspace.templates_are_read_only() {
        return;
    }
    let template_root = workspace.system_trust_policy_template_root();
    std::fs::create_dir_all(&template_root).expect("should create trust policy template root");

    let template_path = workspace.system_trust_policy_template_path();
    if !template_path.exists() {
        std::fs::write(
            &template_path,
            magician::magician_v2::agents::TrustPolicyFile::recommended_template_yaml(),
        )
        .expect("should write trust policy template");
    }

    let default_path = workspace.system_trust_policy_default_path();
    if !default_path.exists() {
        std::fs::write(
            &default_path,
            magician::magician_v2::agents::TrustPolicyFile::recommended_defaults_yaml(),
        )
        .expect("should write default trust policy template");
    }
}

const PAUSED_AGENTS_STATE_FILE: &str = "paused_agents.json";

#[derive(Debug, Clone, Serialize, Deserialize, Default)]
struct PausedAgentsState {
    #[serde(default)]
    paused_agent_ids: Vec<String>,
}

fn build_agent_api_services_with_workspace(
    workspace_layout: ArtifactV2Workspace,
    llm_router: Option<
        Arc<magician::magician_v2::query_analysis::operation_llm_router::OperationLlmRouter>,
    >,
    v2_orchestrator: Arc<MagicianV2Orchestrator>,
) -> AgentApiServices {
    let definition_store = Arc::new(AgentDefinitionStore::with_workspace_layout(
        workspace_layout.clone(),
    ));
    ensure_system_trust_policy_templates_sync(&workspace_layout);
    let memory_resolver = AgentMemoryResolver::with_workspace_layout(workspace_layout.clone());

    tracing::info!(
        agent_runtime_scope_root = %workspace_layout.base_root().display(),
        "AgentRuntime scoped goal state root (goal_cycles.json and scheduler state resolved per scope)"
    );
    // WakeUpQueue: powers SleepUntil and task-schedule wake-ups.
    // Persisted to wake_up_queue.json so scheduled wakes survive restarts.
    let wake_up_queue = WakeUpQueue::new();
    wake_up_queue.set_persist_path(workspace_layout.base_root().join("wake_up_queue.json"));
    // Clone orchestrator Arc before it moves into AgentRuntime so we can wire
    // the delegation dispatcher back after runtime construction.
    let orchestrator_for_delegation = v2_orchestrator.clone();
    let runtime = Arc::new(
        AgentRuntime::new()
            .with_v2_orchestrator(v2_orchestrator.clone())
            .with_workspace_layout(workspace_layout.clone())
            .with_wake_up_queue(wake_up_queue.clone())
            .with_memory_resolver(memory_resolver.clone()),
    );
    if let Some(service) = v2_orchestrator.artifact_v2_service() {
        runtime.set_artifact_v2_service(service);
    }
    orchestrator_for_delegation.set_wake_up_queue(wake_up_queue.clone());
    // Wire cross-agent delegation: RuntimeDelegationDispatcher bridges executor
    // trait to execution-backed V2 runtime. Set on orchestrator so every
    // ActionExecutors instance built from now on carries a live dispatcher.
    orchestrator_for_delegation.set_delegation_dispatcher(Arc::new(
        magician::magician_v2::agents::RuntimeDelegationDispatcher::new(runtime.clone()),
    ));

    // NOTE: Do NOT set_task_store here. The main orchestrator's task store
    // is wired in magician.rs AFTER this function returns.
    // Since orchestrator_for_delegation is the same Arc as the main orchestrator,
    // calling set_task_store here would overwrite it. All tasks (including delegation-
    // created ones) live in the central store; agent_id on each task tracks ownership.
    //
    // Trusted-store authority: create the single per-boot map here and ALSO install
    // it as the process-global handle so the executor-side stage site (compiled
    // handlers, which only carry `AgentResources`) records into the SAME instance
    // the decision site (`respond_hitl_handler`) consults. `install_process_authority`
    // is install-or-get and returns the canonical global instance; the struct field
    // is set from that RETURN value, so `field == global` for EVERY construction (not
    // just the first) — the stage site (global) and decision site (field) can never
    // diverge and silently fail-close.
    let trust_authority =
        magician::magician_v2::execution::trusted_store::install_process_authority(
            std::sync::Arc::new(
                magician::magician_v2::execution::trusted_store::TrustAuthority::new(),
            ),
        );
    AgentApiServices {
        definition_store,
        memory_resolver,
        v2_memory_llm_router: llm_router,
        v2_prompt_manager: v2_orchestrator.prompt_manager(),
        prompt_pipeline_interpreter: PromptPipelineInterpreter,
        runtime,
        scoped_schedulers: Arc::new(RwLock::new(HashMap::new())),
        scoped_approval_services: Arc::new(RwLock::new(HashMap::new())),
        scoped_proposal_stores: Arc::new(RwLock::new(HashMap::new())),
        scoped_paused_agents: Arc::new(RwLock::new(HashMap::new())),
        pending_cycle_dispatches: Arc::new(RwLock::new(HashMap::new())),
        control_gate: Arc::new(Mutex::new(())),
        startup_hydrated: Arc::new(RwLock::new(false)),
        startup_hydration_gate: Arc::new(Mutex::new(())),
        startup_hydration_retry_after: Arc::new(RwLock::new(None)),
        startup_hydration_in_progress: Arc::new(RwLock::new(false)),
        list_cache: Arc::new(RwLock::new(None)),
        crew_health: Arc::new(CrewHealthService::new(workspace_layout.clone())),
        durable_artifact_workspace: workspace_layout,
        feedback_transformer_registry:
            magician::magician_v2::agents::feedback::FeedbackTransformerRegistry::with_builtins(),
        boot_key: magician::magician_v2::execution::trusted_store::BootKey::generate(),
        trust_authority,
    }
}

fn paused_agents_state_path(storage: &magician::magician_v2::agents::AgentStorage) -> PathBuf {
    storage.agents_root().join(PAUSED_AGENTS_STATE_FILE)
}

async fn persist_paused_agents_state(
    agent_api: &AgentApiServices,
    principal: &str,
    workspace: &str,
) -> Result<(), AgentStorageError> {
    let storage = agent_api
        .resolve_definition_store(principal, workspace)
        .storage()
        .clone();
    let paused_handle = agent_api.resolve_paused_agents(principal, workspace).await;
    let mut paused_agent_ids = {
        let paused_agents = paused_handle.read().await;
        paused_agents.iter().cloned().collect::<Vec<_>>()
    };
    paused_agent_ids.sort();
    paused_agent_ids.dedup();

    let state = PausedAgentsState { paused_agent_ids };
    storage.ensure_base_layout().await?;
    storage
        .write_json_atomic(paused_agents_state_path(&storage), &state)
        .await
}

#[cfg(test)]
async fn load_paused_agents_state(
    agent_api: &AgentApiServices,
) -> Result<usize, AgentStorageError> {
    let mut total_loaded = 0usize;
    let scopes = agent_api
        .definition_store
        .list_all_definitions_across_scopes()
        .await
        .map_err(|err| AgentStorageError::Io(std::io::Error::other(err.to_string())))?
        .into_iter()
        .filter_map(|record| Some((record.definition.principal?, record.definition.workspace?)))
        .collect::<HashSet<_>>();

    for (principal, workspace) in scopes {
        total_loaded +=
            load_paused_agents_state_for_scope(agent_api, &principal, &workspace).await?;
    }

    Ok(total_loaded)
}

async fn load_paused_agents_state_for_scope(
    agent_api: &AgentApiServices,
    principal: &str,
    workspace: &str,
) -> Result<usize, AgentStorageError> {
    let storage = agent_api
        .resolve_definition_store(principal, workspace)
        .storage()
        .clone();
    let path = paused_agents_state_path(&storage);
    if !tokio::fs::try_exists(&path)
        .await
        .map_err(AgentStorageError::from)?
    {
        return Ok(0);
    }

    let state: PausedAgentsState = storage.read_json(&path).await?;
    let paused_handle = agent_api.resolve_paused_agents(principal, workspace).await;
    let mut paused_agents = paused_handle.write().await;
    paused_agents.clear();
    for agent_id in state.paused_agent_ids {
        let normalized = agent_id.trim();
        if normalized.is_empty() {
            continue;
        }
        paused_agents.insert(normalized.to_string());
    }
    Ok(paused_agents.len())
}

fn pause_scope_from_pause_data(pause_data: &FullPauseData) -> Option<(String, String)> {
    // The executors are authoritative when they know; the pause record is the
    // fallback. Both halves read from one identity snapshot, so this can no
    // longer take the principal from the live executors and the workspace from
    // the record — a mismatch that would name a scope neither side ever held.
    let identity = pause_data.executors.run_identity.get();
    let principal = identity
        .principal
        .clone()
        .or_else(|| pause_data.pause_state.principal.clone())?;
    let workspace = identity
        .workspace
        .clone()
        .or_else(|| pause_data.pause_state.workspace.clone())?;
    Some((principal, workspace))
}

async fn persist_generated_pause(
    store: &FullPauseStore,
    pause_data: FullPauseData,
    require_durable: bool,
) -> bool {
    magician::magician_v2::execution::agentic::persist_pause_with_workflow_authority(
        store,
        pause_data,
        require_durable,
    )
    .await
    .is_ok()
}

/// Put back an already-admitted pause after a retryable HTTP-path failure
/// without minting a new app-continuation authority. Protected pauses retain
/// their exact checkpoint and must still match the exact canonical body before
/// the store will republish the scoped HMAC envelope. Ordinary pauses preserve
/// the historical in-memory behavior.
fn restore_taken_pause_exact(store: &FullPauseStore, pause_data: FullPauseData) -> bool {
    let protected = pause_data.pause_state.app_disclosure_checkpoint.is_some();
    let key = pause_data.pause_state.storage_key();
    let restored = if protected {
        store.restore_exact_protected_pause(pause_data).map(|_| ())
    } else {
        store.store(pause_data);
        Ok(())
    };
    if restored.is_err() {
        warn!(
            key = %key,
            protected,
            "Failed to restore the exact taken pause after a retryable request failure"
        );
        return false;
    }
    true
}

fn restore_taken_pause_or_503(
    store: &FullPauseStore,
    pause_data: FullPauseData,
) -> std::result::Result<(), HttpResponse> {
    let execution_id = pause_data
        .pause_state
        .execution_id
        .clone()
        .unwrap_or_default();
    if restore_taken_pause_exact(store, pause_data) {
        return Ok(());
    }
    Err(api_error_response(
        StatusCode::SERVICE_UNAVAILABLE,
        "pause_restore_failed",
        "The protected pause could not be restored durably; retry after storage recovers",
        Some(serde_json::json!({ "execution_id": execution_id })),
    ))
}

async fn validate_taken_app_pause_or_response(
    store: &FullPauseStore,
    pause_data: &FullPauseData,
    execution_id: &str,
) -> std::result::Result<(), HttpResponse> {
    use magician::magician_v2::execution::agentic::AppPauseContinuationValidationError;

    match magician::magician_v2::execution::agentic::validate_app_pause_continuation_classified(
        pause_data,
    )
    .await
    {
        Ok(()) => Ok(()),
        Err(AppPauseContinuationValidationError::DefinitiveDenial) => Err(api_error_response(
            StatusCode::CONFLICT,
            "app_continuation_not_authorized",
            "The protected app continuation is no longer authorized",
            Some(serde_json::json!({
                "execution_id": execution_id,
                "category": "definitive_authority_denial",
            })),
        )),
        Err(AppPauseContinuationValidationError::TemporarilyUnavailable) => {
            restore_taken_pause_or_503(store, pause_data.clone())?;
            Err(api_error_response(
                StatusCode::SERVICE_UNAVAILABLE,
                "app_continuation_authority_unavailable",
                "The protected app continuation could not be revalidated; retry later",
                Some(serde_json::json!({
                    "execution_id": execution_id,
                    "category": "current_authority_temporarily_unavailable",
                })),
            ))
        },
    }
}

/// TRUSTED-STORE INTEGRITY (pause-state decide site).
///
/// For an ELEVATION-bearing pause (`is_elevation()` — carries approval_rules or an
/// owner authority chain), prove the authorization about to be restored by
/// `restore_context_from_pause` is the one magician itself staged this boot. The
/// stage site (`FullPauseStore::store`) recorded an authority entry keyed by the
/// SAME `{ PauseState, pause.principal, pause.workspace, pause.storage_key() }`
/// tuple and hashed over the SAME security-bearing field subset. Two failures
/// fail closed:
///   - authority MISS: the pause was never staged this boot — forged on disk, or a
///     pre-restart leftover (the authority is empty after a restart by design).
///   - hash MISMATCH: the on-disk authorization fields were tampered after staging.
///
/// Returns `Ok(())` when the pause is benign (non-elevation — no check) or the
/// elevation is authority-verified. Returns `Err(reason)` on fail-closed; the
/// caller surfaces the reason to the operator and does NOT re-store the pause (a
/// re-store would re-mint the entry via `FullPauseStore::store` and let a retry
/// auto-heal), so the forged/stale pause is dropped and the operator must
/// re-approve to mint a fresh entry. On success the caller does NOT forget here —
/// `forget` happens once the pause is definitively consumed by the resume.
fn elevation_pause_authority_key(
    pause_data: &FullPauseData,
) -> magician::magician_v2::execution::trusted_store::TrustedRecordKey {
    magician::magician_v2::execution::trusted_store::TrustedRecordKey {
        kind: magician::magician_v2::execution::trusted_store::StoreKind::PauseState,
        principal: pause_data.pause_state.principal.clone().unwrap_or_default(),
        workspace: pause_data.pause_state.workspace.clone().unwrap_or_default(),
        id: pause_data.pause_state.storage_key(),
    }
}

fn verify_elevation_pause_authority(pause_data: &FullPauseData) -> std::result::Result<(), String> {
    if !pause_data.pause_state.is_elevation() {
        // Protected app pauses are restart-authorized by the scoped durable
        // HMAC verified while loading their exact envelope/body pair, then by
        // fresh app authority in `validate_app_pause_continuation`. Requiring
        // this boot-local elevation entry as well would reject every valid
        // app continuation after restart. Elevation-bearing pauses remain
        // boot-local and still require explicit re-approval.
        return Ok(());
    }
    let key = elevation_pause_authority_key(pause_data);
    let expected_hash = magician::magician_v2::execution::agentic::pause_authority_hash(pause_data)
        .map_err(|_| "protected pause authority could not be derived".to_owned())?;
    let ok = magician::magician_v2::execution::trusted_store::process_authority()
        .and_then(|authority| authority.get(&key))
        .map(|entry| entry.content_hash == expected_hash)
        .unwrap_or(false);
    if ok {
        Ok(())
    } else {
        Err(
            "pause_authorization_not_in_authority: this elevated pause was not staged by magician this boot (forged, or predates a restart), or its on-disk authorization fields were tampered — re-approve to obtain a fresh grant".to_string(),
        )
    }
}

/// Drop the authority entry for an elevation pause once the resume has definitively
/// consumed it (terminal). No-op for benign pauses. Mirrors the txn/proposal
/// `forget()` on terminal so a replayed resume of the same id fail-closes.
fn forget_elevation_pause_authority(
    pause_store: &FullPauseStore,
    pause_data: &FullPauseData,
    consume_protected: bool,
) -> std::result::Result<(), String> {
    if !pause_data.pause_state.is_elevation()
        && pause_data.pause_state.app_disclosure_checkpoint.is_none()
    {
        return Ok(());
    }
    if pause_data.pause_state.app_disclosure_checkpoint.is_some() && consume_protected {
        pause_store
            .consume_protected_pause_claim(pause_data)
            .map_err(|_| "protected app pause consumption failed closed".to_owned())?;
    }
    if let Some(authority) = magician::magician_v2::execution::trusted_store::process_authority() {
        authority.forget(&elevation_pause_authority_key(pause_data));
    }
    Ok(())
}

async fn resolve_approval_service_for_pause_data(
    agent_api: &AgentApiServices,
    pause_data: &FullPauseData,
) -> Result<Arc<ApprovalService>, HttpResponse> {
    let Some((principal, workspace)) = pause_scope_from_pause_data(pause_data) else {
        return Err(api_error_response(
            StatusCode::UNPROCESSABLE_ENTITY,
            "approval_scope_missing",
            "Paused execution is missing principal/workspace scope for approval persistence",
            None,
        ));
    };
    agent_api
        .resolve_approval_service(&principal, &workspace)
        .await
        .map_err(|err| approval_service_error_response(err, None))
}

fn pause_states_path_for_store_or_orchestrator(
    v2_orchestrator: &Arc<MagicianV2Orchestrator>,
    full_pause_store: Option<&Arc<FullPauseStore>>,
) -> PathBuf {
    full_pause_store
        .and_then(|store| store.persistence_dir().map(Path::to_path_buf))
        .unwrap_or_else(|| v2_orchestrator.pause_states_storage_path())
}

fn log_pause_store_recovery(full_pause_store: &Arc<FullPauseStore>, pause_states_path: &Path) {
    match full_pause_store.load_pending_index_from_disk() {
        Ok(loaded) => {
            if !loaded.is_empty() {
                info!(
                    count = loaded.len(),
                    path = %pause_states_path.display(),
                    "[API] Loaded {} paused executions from disk for crash recovery",
                    loaded.len()
                );
                // Note: These will be restored with executors when the user reconnects
                // and we re-emit the WaitingForUser events. For now, we just log them.
                for pause_data in &loaded {
                    info!(
                        execution_id = %pause_data.execution_id,
                        plan_id = ?pause_data.plan_id,
                        step_id = ?pause_data.step_id,
                        "[API] Found paused execution awaiting user input"
                    );
                }
            }
        },
        Err(e) => {
            warn!(
                error = %e,
                path = %pause_states_path.display(),
                "[API] Failed to load paused executions from disk"
            );
        },
    }
    let _ = full_pause_store.schedule_legacy_pending_index_background_repair();
}

fn warn_if_agent_storage_root_mismatch(agent_api: &AgentApiServices, pause_states_path: &Path) {
    let expected_root =
        ArtifactV2Workspace::new(pause_states_path.to_path_buf()).system_agent_template_root();
    let actual_root = agent_api.definition_store.storage().root().to_path_buf();
    let normalized_expected = normalize_path_for_diagnostic_comparison(&expected_root);
    let normalized_actual = normalize_path_for_diagnostic_comparison(&actual_root);
    if normalized_actual != normalized_expected {
        info!(
            expected_root = %expected_root.display(),
            actual_root = %actual_root.display(),
            normalized_expected_root = %normalized_expected.display(),
            normalized_actual_root = %normalized_actual.display(),
            pause_states_path = %pause_states_path.display(),
            "Agent API storage root differs from pause-store-derived root"
        );
    }
}

fn normalize_path_for_diagnostic_comparison(path: &Path) -> PathBuf {
    let absolute = if path.is_absolute() {
        path.to_path_buf()
    } else {
        std::env::current_dir()
            .unwrap_or_else(|_| PathBuf::from("."))
            .join(path)
    };
    std::fs::canonicalize(&absolute).unwrap_or(absolute)
}

fn startup_hydration_pending_response(retry_after: Option<Instant>) -> HttpResponse {
    let retry_after_ms = retry_after.map(|deadline| {
        u64::try_from(
            deadline
                .saturating_duration_since(Instant::now())
                .as_millis(),
        )
        .unwrap_or(u64::MAX)
    });
    api_error_response(
        StatusCode::SERVICE_UNAVAILABLE,
        "agent_startup_hydration_pending",
        "Agent startup hydration in progress",
        Some(serde_json::json!({
            "retry_after_ms": retry_after_ms,
        })),
    )
}

async fn schedule_startup_hydration_retry(agent_api: &AgentApiServices) -> Instant {
    let next_retry = Instant::now() + STARTUP_HYDRATION_RETRY_BACKOFF;
    *agent_api.startup_hydrated.write().await = false;
    *agent_api.startup_hydration_retry_after.write().await = Some(next_retry);
    next_retry
}

type StartupHydrationResult = Result<(), Option<Instant>>;

async fn run_agent_startup_hydration(agent_api: &AgentApiServices) -> StartupHydrationResult {
    let records = match agent_api
        .definition_store
        .list_all_definitions_across_scopes()
        .await
    {
        Ok(records) => records,
        Err(err) => {
            warn!(
                error = %err,
                "Failed to hydrate agent runtime from persisted definitions"
            );
            let next_retry = schedule_startup_hydration_retry(agent_api).await;
            return Err(Some(next_retry));
        },
    };

    let definitions: Vec<AgentDefinition> = records
        .into_iter()
        .map(|record| record.definition)
        .collect();
    let mut definitions_by_scope: HashMap<(String, String), Vec<AgentDefinition>> = HashMap::new();
    for definition in &definitions {
        let Some(principal) = definition.principal.as_ref() else {
            continue;
        };
        let Some(workspace) = definition.workspace.as_ref() else {
            continue;
        };
        definitions_by_scope
            .entry((principal.clone(), workspace.clone()))
            .or_default()
            .push(definition.clone());
    }

    let mut hydrated_count = 0usize;
    let mut stale_scheduler_agent_count = 0usize;
    for ((principal, workspace), scoped_definitions) in definitions_by_scope {
        if let Err(err) =
            load_paused_agents_state_for_scope(agent_api, &principal, &workspace).await
        {
            warn!(
                principal = %principal,
                workspace = %workspace,
                error = %err,
                "Failed to hydrate paused agent state from persisted scoped store"
            );
            let next_retry = schedule_startup_hydration_retry(agent_api).await;
            return Err(Some(next_retry));
        }

        // Trusted-Store Integrity Phase 5 (restart re-record): the in-process
        // `TrustAuthority` is empty after a restart by design, so an operator who
        // re-approves a still-pending file-write approval would hit the decide
        // site's authority MISS and fail closed. Re-anchor every pending
        // transaction + pending code-change proposal in THIS scope into the
        // authority so those approvals survive the restart. This ONLY re-records
        // authority entries — it auto-applies nothing and re-emits no HITL events
        // (proposals already re-surface via listing; transactions via their
        // existing mechanism). Elevation pauses are deliberately NOT re-recorded
        // (privilege grants stay strict — a fresh confirmation is required after a
        // restart).
        //
        // The key + entry are byte-for-byte the stage sites' derivations so the
        // decide-site lookup hits and the un-tampered content_hash compares equal:
        //   - key `(kind, principal, workspace, id)` — `id` is the record id
        //     string; `(principal, workspace)` are this loop's scope, which is the
        //     SAME pair `respond_hitl_handler` derives its store root from.
        //   - `content_hash` is `record.content_hash()` (the SAME method the stage
        //     and decide sites use), so a record tampered AFTER this re-anchor
        //     still fails closed.
        //   - proposal: `apply_root`/`target_paths` = `apply_root`/`touched_files`
        //     (matches `stage_patch_with_apply_root`).
        //   - transaction: `apply_root` = `txn.apply_root` (the field the stage
        //     site copies from `scoped.apply_root` after staging);
        //     `target_paths` = the edits' target paths (matches `stage_edits`).
        //
        // Best-effort: store scans tolerate a missing/unreadable dir or a
        // malformed/legacy record by skipping it, and an absent artifact service
        // is skipped — none of this aborts or retries hydration.
        if let Some(authority) =
            magician::magician_v2::execution::trusted_store::process_authority()
        {
            if let Some(artifact_service) = agent_api.runtime.artifact_v2_service() {
                use magician::magician_v2::execution::trusted_store::{
                    AuthorityEntry, StoreKind, TrustedRecordKey,
                };
                let scope_root = artifact_service
                    .workspace()
                    .scope_root(&principal, &workspace);

                let txn_store =
                    magician::magician_v2::execution::file_edit::transaction::TransactionStore::new(
                        &scope_root,
                    );
                let pending_txns = txn_store.list_pending();
                for txn in &pending_txns {
                    let target_paths: Vec<std::path::PathBuf> = txn
                        .edits
                        .iter()
                        .map(|edit| edit.path().to_path_buf())
                        .collect();
                    let key = TrustedRecordKey {
                        kind: StoreKind::Transaction,
                        principal: principal.clone(),
                        workspace: workspace.clone(),
                        id: txn.id.as_str().to_string(),
                    };
                    let _ = authority.record_authenticated_file_edit_stage(
                        key,
                        AuthorityEntry {
                            content_hash: txn.content_hash(),
                            apply_root: txn.apply_root.clone(),
                            target_paths,
                        },
                        txn.task_id.clone(),
                        txn.execution_id.clone(),
                        txn.content_hash(),
                    );
                }

                let proposal_store =
                    magician::magician_v2::execution::file_edit::proposal::CodeChangeProposalStore::new(
                        &scope_root,
                    );
                let pending_proposals = proposal_store.list_pending();
                for proposal in &pending_proposals {
                    let key = TrustedRecordKey {
                        kind: StoreKind::CodeChangeProposal,
                        principal: principal.clone(),
                        workspace: workspace.clone(),
                        id: proposal.id.as_str().to_string(),
                    };
                    let _ = authority.record_authenticated_file_edit_stage(
                        key,
                        AuthorityEntry {
                            content_hash: proposal.content_hash(),
                            apply_root: proposal.apply_root.clone(),
                            target_paths: proposal.touched_files.clone(),
                        },
                        proposal.task_id.clone(),
                        proposal.execution_id.clone(),
                        proposal.content_hash(),
                    );
                }

                let reanchored = pending_txns.len() + pending_proposals.len();
                if reanchored > 0 {
                    info!(
                        principal = %principal,
                        workspace = %workspace,
                        pending_transactions = pending_txns.len(),
                        pending_proposals = pending_proposals.len(),
                        "Re-anchored pending file-write approvals into the trust authority (restart re-approval)"
                    );
                }
            }
        }

        // One-time reconciler (RC #3): when MAGICIAN_RECONCILE_ORPHANED_TASKS_ON_BOOT
        // is armed, drain approved/ready/unscheduled agent-created tasks that predate
        // the dispatch-at-creation fix — dedup clones, dispatch same-scope leaves
        // (bounded), leave plan-pending for review. Idempotent + opt-in; a no-op
        // otherwise. Best-effort: never blocks or fails hydration.
        if magician::magician_v2::execution::task_reconcile::reconcile_on_boot_enabled() {
            if let Some(artifact_service) = agent_api.runtime.artifact_v2_service() {
                let outcome =
                    magician::magician_v2::execution::task_reconcile::reconcile_orphaned_ready_tasks(
                        artifact_service,
                        magician::magician_v2::artifact_v2::service::ScopeRef::system_internal_unauthenticated(&principal.clone(), &workspace.clone()),
                        magician::magician_v2::execution::task_reconcile::DEFAULT_RECONCILE_BATCH_CAP,
                    )
                    .await;
                if outcome.scanned > 0 {
                    info!(
                        principal = %principal,
                        workspace = %workspace,
                        scanned = outcome.scanned,
                        dispatched = outcome.dispatched,
                        dedup_planned = outcome.dedup_planned,
                        deduped = outcome.deduped,
                        dedup_errors = outcome.dedup_errors,
                        skipped_planned = outcome.skipped_planned,
                        skipped_capped = outcome.skipped_capped,
                        skipped_depth_capped = outcome.skipped_depth_capped,
                        skipped_dedup_error = outcome.skipped_dedup_error,
                        dispatch_errors = outcome.dispatch_errors,
                        "One-time orphaned-task reconcile (RC #3) drained this scope"
                    );
                }
            }
        }

        let scheduler = match agent_api.resolve_scheduler(&principal, &workspace).await {
            Ok(scheduler) => scheduler,
            Err(err) => {
                warn!(
                    principal = %principal,
                    workspace = %workspace,
                    error = %err,
                    "Failed to resolve scoped scheduler during startup hydration"
                );
                let next_retry = schedule_startup_hydration_retry(agent_api).await;
                return Err(Some(next_retry));
            },
        };
        let disabled_agent_ids = disabled_agent_hierarchy(scoped_definitions.iter());
        let enabled_definitions = scoped_definitions
            .into_iter()
            .filter(|definition| !disabled_agent_ids.contains(&definition.agent_id))
            .collect::<Vec<_>>();

        match scheduler
            .rebuild_from_definitions(&enabled_definitions)
            .await
        {
            Ok((hydrated, stale)) => {
                hydrated_count += hydrated;
                stale_scheduler_agent_count += stale;
            },
            Err(err) => {
                warn!(
                    principal = %principal,
                    workspace = %workspace,
                    error = %err,
                    "Failed to rebuild scoped scheduler state during startup hydration"
                );
                let next_retry = schedule_startup_hydration_retry(agent_api).await;
                return Err(Some(next_retry));
            },
        }
    }

    // Restore persisted wakes before any reconcile path re-arms scoped goals so
    // non-harness wakes (task retries, child completions) are merged into the
    // live queue instead of being overwritten by the first fresh persist.
    if let Some(queue) = agent_api.runtime.wake_up_queue() {
        queue.restore_from_disk().await;
    }

    for definition in &definitions {
        agent_api
            .runtime
            .upsert_definition(definition.clone())
            .await;
        if let Err(err) = reconcile_autonomous_scheduler_entries(agent_api, definition).await {
            warn!(
                agent_id = %definition.agent_id,
                principal = ?definition.principal,
                workspace = ?definition.workspace,
                error = %err,
                "Failed to reconcile autonomous scheduler entries during startup hydration"
            );
            let next_retry = schedule_startup_hydration_retry(agent_api).await;
            return Err(Some(next_retry));
        }
    }

    if hydrated_count > 0 || stale_scheduler_agent_count > 0 {
        info!(
            hydrated_count = hydrated_count,
            stale_scheduler_agent_count = stale_scheduler_agent_count,
            "Hydrated agent runtime/scheduler state from definition store"
        );
    }

    *agent_api.startup_hydration_retry_after.write().await = None;
    *agent_api.startup_hydrated.write().await = true;
    Ok(())
}

/// Returns a boxed future on purpose.
///
/// 41 handlers await this, and an `async fn` stores its callee's state machine
/// inline, so an unboxed version puts this guard *and* the whole
/// `run_agent_startup_hydration` subtree into all 41 of their futures. Measured
/// at the point of a stack overflow in the P3-14 integration test, that subtree
/// was ~420 KiB of a 1.29 MiB stack. Boxing here moves it to the heap once, for
/// every caller, and costs one allocation on a path that is guarded to run at
/// most once per process.
fn ensure_agent_startup_hydrated(
    agent_api: &AgentApiServices,
) -> Pin<Box<dyn Future<Output = Result<(), HttpResponse>> + Send + '_>> {
    Box::pin(ensure_agent_startup_hydrated_inner(agent_api))
}

async fn ensure_agent_startup_hydrated_inner(
    agent_api: &AgentApiServices,
) -> Result<(), HttpResponse> {
    if *agent_api.startup_hydrated.read().await {
        return Ok(());
    }
    if *agent_api.startup_hydration_in_progress.read().await {
        let retry_after = *agent_api.startup_hydration_retry_after.read().await;
        return Err(startup_hydration_pending_response(retry_after.or_else(
            || Some(Instant::now() + STARTUP_HYDRATION_RETRY_BACKOFF),
        )));
    }
    let retry_after = *agent_api.startup_hydration_retry_after.read().await;
    if retry_after.is_some_and(|deadline| Instant::now() < deadline) {
        return Err(startup_hydration_pending_response(retry_after));
    }

    let _hydrate_guard = agent_api.startup_hydration_gate.lock().await;
    if *agent_api.startup_hydrated.read().await {
        return Ok(());
    }
    let retry_after = *agent_api.startup_hydration_retry_after.read().await;
    if retry_after.is_some_and(|deadline| Instant::now() < deadline) {
        return Err(startup_hydration_pending_response(retry_after));
    }
    if *agent_api.startup_hydration_in_progress.read().await {
        return Err(startup_hydration_pending_response(retry_after.or_else(
            || Some(Instant::now() + STARTUP_HYDRATION_RETRY_BACKOFF),
        )));
    }

    *agent_api.startup_hydration_in_progress.write().await = true;
    // Boxed for the same reason as the guard above: this is the largest single
    // frame on that path (~284 KiB measured).
    let result = Box::pin(run_agent_startup_hydration(agent_api)).await;
    *agent_api.startup_hydration_in_progress.write().await = false;
    result.map_err(startup_hydration_pending_response)
}

/// Eagerly hydrate agent runtime/scheduler state during server startup.
///
/// Returns `true` when hydration succeeded immediately. When hydration is backing
/// off (for example due to transient storage errors), returns `false` and leaves
/// retry responsibility to supervisor loops/API calls.
pub async fn hydrate_agent_services_on_startup(agent_api: &AgentApiServices) -> bool {
    match ensure_agent_startup_hydrated(agent_api).await {
        Ok(()) => {
            info!("Agent startup hydration completed");
            true
        },
        Err(response) => {
            warn!(
                status = %response.status().as_u16(),
                "Agent startup hydration deferred; background loops will retry"
            );
            false
        },
    }
}

/// Start agent runtime/scheduler hydration without blocking the HTTP bind path.
///
/// Agent endpoints return `agent_startup_hydration_pending` while this task owns
/// the hydration gate; the normal request-time fallback remains available after a
/// transient failure/backoff expires.
pub async fn spawn_agent_services_startup_hydration(agent_api: AgentApiServices) {
    if *agent_api.startup_hydrated.read().await {
        return;
    }
    *agent_api.startup_hydration_in_progress.write().await = true;
    *agent_api.startup_hydration_retry_after.write().await =
        Some(Instant::now() + STARTUP_HYDRATION_RETRY_BACKOFF);
    tokio::spawn(async move {
        if !magician::magician_v2::runtime::startup::wait_for_http().await {
            *agent_api.startup_hydration_in_progress.write().await = false;
            return;
        }

        let _hydrate_guard = agent_api.startup_hydration_gate.lock().await;
        *agent_api.startup_hydration_retry_after.write().await = None;
        let result = if *agent_api.startup_hydrated.read().await {
            Ok(())
        } else {
            run_agent_startup_hydration(&agent_api).await
        };
        *agent_api.startup_hydration_in_progress.write().await = false;
        match result {
            Ok(()) => info!("Agent startup hydration completed"),
            Err(retry_after) => warn!(
                retry_after_ms = retry_after.map(|deadline| {
                    u64::try_from(
                        deadline
                            .saturating_duration_since(Instant::now())
                            .as_millis(),
                    )
                    .unwrap_or(u64::MAX)
                }),
                "Agent startup hydration deferred; background loops will retry"
            ),
        }
    });
}

/// Build a scoped learning-event store for recording harness cycle dispatch
/// outcomes (observability for the self-improvement loop). Cheap — wraps the
/// workspace handle; see `harness::cycle_outcome`.
fn harness_cycle_outcome_store(
    agent_api: &AgentApiServices,
) -> magician::magician_v2::learning::LearningStore {
    magician::magician_v2::learning::LearningStore::new(
        agent_api.durable_artifact_workspace.clone(),
    )
}

async fn prepare_scheduled_trigger_dispatch(
    agent_api: &AgentApiServices,
    scheduled: &ScheduledTrigger,
) -> Result<Option<ManualTriggerDispatch>, String> {
    let principal = scheduled.principal.clone();
    let workspace = scheduled.workspace.clone();
    let agent_id = scheduled.agent_id.as_str();
    let goal_id = scheduled.goal_id.clone();
    let definition_store = agent_api.resolve_definition_store(&principal, &workspace);

    let definition = match definition_store.get_definition(agent_id).await {
        Ok(Some(record)) => record.definition,
        Ok(None) => {
            warn!(
                principal = %principal,
                workspace = %workspace,
                agent_id = %agent_id,
                goal_id = %goal_id,
                trigger_seq = scheduled.trigger_seq,
                "Skipping scheduled trigger because definition was not found in scheduled scope"
            );
            return Ok(None);
        },
        Err(error) => {
            warn!(
                principal = %principal,
                workspace = %workspace,
                agent_id = %agent_id,
                goal_id = %goal_id,
                trigger_seq = scheduled.trigger_seq,
                error = %error,
                "Skipping scheduled trigger because scoped definition load failed"
            );
            return Err("definition load failed".to_string());
        },
    };

    let disabled_agent_ids = definition_store
        .disabled_hierarchy_agent_ids()
        .await
        .map_err(|error| {
            warn!(
                principal = %principal,
                workspace = %workspace,
                agent_id = %agent_id,
                goal_id = %goal_id,
                trigger_seq = scheduled.trigger_seq,
                error = %error,
                "Skipping scheduled trigger because disabled hierarchy resolution failed"
            );
            "disabled hierarchy resolution failed".to_string()
        })?;
    if disabled_agent_ids.contains(agent_id) {
        debug!(
            agent_id = %agent_id,
            goal_id = %goal_id,
            trigger_seq = scheduled.trigger_seq,
            "Skipping scheduled trigger because agent is disabled"
        );
        magician::magician_v2::harness::record_harness_cycle_outcome(
            &harness_cycle_outcome_store(agent_api),
            &principal,
            &workspace,
            agent_id,
            &goal_id,
            None,
            Some(scheduled.trigger_seq),
            magician::magician_v2::harness::HarnessCycleDispatchOutcome::DroppedDisabled,
            serde_json::json!({ "reason": "agent_disabled" }),
        );
        if let Ok(scheduler) = agent_api.resolve_scheduler(&principal, &workspace).await {
            if let Err(error) = scheduler.unregister_agent(agent_id).await {
                warn!(
                    agent_id = %agent_id,
                    error = %error,
                    "Failed to unregister disabled scheduled agent"
                );
            }
        }
        if let Some(queue) = agent_api.runtime.wake_up_queue() {
            queue
                .cancel_scoped(&principal, &workspace, agent_id, &goal_id)
                .await;
        }
        return Ok(None);
    }

    if agent_api
        .is_agent_paused(&principal, &workspace, agent_id)
        .await
    {
        debug!(
            agent_id = %agent_id,
            goal_id = %goal_id,
            trigger_seq = scheduled.trigger_seq,
            "Skipping scheduled trigger because agent is paused"
        );
        magician::magician_v2::harness::record_harness_cycle_outcome(
            &harness_cycle_outcome_store(agent_api),
            &principal,
            &workspace,
            agent_id,
            &goal_id,
            None,
            Some(scheduled.trigger_seq),
            magician::magician_v2::harness::HarnessCycleDispatchOutcome::DroppedPaused,
            serde_json::json!({ "reason": "agent_paused" }),
        );
        return Ok(None);
    }

    // NOTE: goals/triggers validation removed — these are now managed by
    // the scheduler via Task definitions, not by AgentDefinition fields.

    let trust_policy_storage = scoped_trust_policy_storage(agent_api, &principal, &workspace);
    let enforcer = match load_trust_policy_enforcer(&trust_policy_storage).await {
        Ok(enforcer) => Arc::new(enforcer),
        Err(response) => {
            warn!(
                agent_id = %agent_id,
                goal_id = %goal_id,
                trigger_seq = scheduled.trigger_seq,
                status = %response.status().as_u16(),
                "Skipping scheduled trigger because trust policy is unavailable"
            );
            return Err("trust policy unavailable".to_string());
        },
    };
    let trust_level = normalized_trust_level(&definition);
    if !enforcer.has_level_exact(&trust_level.0) {
        warn!(
            agent_id = %agent_id,
            goal_id = %goal_id,
            trigger_seq = scheduled.trigger_seq,
            trust_level = %trust_level.0,
            "Skipping scheduled trigger because trust_level is not defined"
        );
        return Ok(None);
    }

    let cycle_id = AgentRuntime::cycle_id_for_scope(
        Some(&principal),
        Some(&workspace),
        agent_id,
        &goal_id,
        scheduled.trigger_seq,
    );
    let goal_description = resolve_cycle_goal_description(&definition, &goal_id);
    let strategy_summary =
        resolve_manual_trigger_strategy_summary(agent_api, &definition, agent_id, &goal_id).await;
    let llm_routing_overrides = llm_routing_overrides(&definition);

    let dispatch = ManualTriggerDispatch {
        agent_id: agent_id.to_string(),
        principal,
        workspace,
        goal_id,
        trigger: "cron".to_string(),
        trigger_seq: scheduled.trigger_seq,
        cycle_id,
        task_id: None,
        execution_id: None,
        runtime_execution_id: None,
        definition_version: definition.version,
        goal_description,
        max_iterations: usize::try_from(definition.constraints.max_iterations).ok(),
        trust_level: trust_level.0,
        trust_policies_path: trust_policy_storage.trust_policies_path(),
        preloaded_trust_enforcer: enforcer,
        approval_rules: magician::magician_v2::agents::approval::harness_merged_approval_rules(
            &definition,
        ),
        strategy_summary,
        strategy_hint_enabled: definition.strategy.is_some(),
        llm_routing_overrides,
        workflow_inputs: HashMap::new(),
        definition,
    };
    Ok(Some(dispatch))
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
enum ScheduledDispatchAdmission {
    StartNow,
    Queued,
    Drop,
}

type HarnessRootPermit = magician::magician_v2::local_resource_governor::HarnessRootPermit;

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
enum RootDispatchClass {
    Harness,
    Standard,
}

fn classify_root_dispatch(goal_id: &str) -> RootDispatchClass {
    if magician::magician_v2::harness::cycle_outcome::is_harness_goal(goal_id) {
        RootDispatchClass::Harness
    } else {
        RootDispatchClass::Standard
    }
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
struct HarnessRootCapacityExhausted;

const HARNESS_ROOT_TERMINAL_POLL_INTERVAL: StdDuration = StdDuration::from_millis(250);

/// Hard ceiling on how long a harness-root permit may be retained by the
/// defensive `retain_harness_root_permit_until_terminal` fallback. Beyond this
/// the permit is force-released with a warning so a stuck/undeleted execution
/// can never permanently starve the harness-root pool (which would otherwise
/// require a restart the operator cannot perform).
const HARNESS_ROOT_PERMIT_MAX_RETENTION: StdDuration = StdDuration::from_secs(2 * 60 * 60 + 5 * 60);

fn try_admit_harness_root(
    goal_id: &str,
    inherited_permit: Option<HarnessRootPermit>,
) -> Result<Option<HarnessRootPermit>, HarnessRootCapacityExhausted> {
    if classify_root_dispatch(goal_id) == RootDispatchClass::Standard {
        return Ok(None);
    }
    if let Some(permit) = inherited_permit {
        return Ok(Some(permit));
    }
    magician::magician_v2::local_resource_governor::try_acquire_harness_root()
        .map(Some)
        .ok_or(HarnessRootCapacityExhausted)
}

fn record_harness_root_capacity_drop(
    agent_api: &AgentApiServices,
    dispatch: &ManualTriggerDispatch,
) {
    magician::magician_v2::harness::record_harness_cycle_outcome(
        &harness_cycle_outcome_store(agent_api),
        &dispatch.principal,
        &dispatch.workspace,
        &dispatch.agent_id,
        &dispatch.goal_id,
        Some(dispatch.cycle_id.as_str()),
        Some(dispatch.trigger_seq),
        magician::magician_v2::harness::HarnessCycleDispatchOutcome::DroppedProvisionFailed,
        serde_json::json!({ "reason": "harness_root_capacity_exhausted" }),
    );
}

fn harness_root_permit_requires_terminal_retention(outcome: &AgenticOutcome) -> bool {
    matches!(outcome, AgenticOutcome::WaitingForChildren { .. })
}

fn harness_root_permit_can_release(waiting_state: WaitingState) -> bool {
    waiting_state.is_terminal()
}

/// True when the orchestrator's error string indicates the execution no longer
/// exists (deleted/unreadable), as opposed to a transient lookup failure. A
/// missing execution can never reach a terminal state, so continuing to retain
/// its permit would leak it forever.
fn execution_lookup_error_is_missing(error: &str) -> bool {
    let lowered = error.to_ascii_lowercase();
    lowered.contains("not found") || lowered.contains("does not exist")
}

/// Bounded fallback that retains a harness-root permit until the execution
/// reaches a terminal state. Preserved as a safety net for any future path that
/// still wants terminal-scoped retention; the live WaitingForChildren dispatch
/// now releases the permit immediately (see the P1.5-permit fix at the manual
/// dispatch call site), so this is currently unused in production. It is hard-
/// bounded on both a missing/deleted execution (b) and a max-retention cap (c)
/// so it can never leak a permit.
#[allow(dead_code)]
fn retain_harness_root_permit_until_terminal(
    v2_orchestrator: Arc<MagicianV2Orchestrator>,
    execution_id: String,
    harness_root_permit: HarnessRootPermit,
) {
    tokio::spawn(async move {
        let harness_root_permit = harness_root_permit;
        let started_at = std::time::Instant::now();
        loop {
            match v2_orchestrator.get_execution(&execution_id).await {
                Ok(execution) => {
                    if harness_root_permit_can_release(execution.waiting_state) {
                        return;
                    }
                },
                Err(error) if execution_lookup_error_is_missing(&error) => {
                    // (b) The execution was deleted/unreadable — it can never
                    // reach a terminal state, so release the permit now rather
                    // than looping forever and starving the harness-root pool.
                    warn!(
                        execution_id = %execution_id,
                        error = %error,
                        "Releasing harness root permit because execution is missing/deleted"
                    );
                    drop(harness_root_permit);
                    return;
                },
                Err(error) => {
                    // A transient lookup failure cannot prove that a waiting root terminated.
                    // Retain the permit until the orchestrator reports a terminal state
                    // (bounded by the hard max-retention cap below).
                    warn!(
                        execution_id = %execution_id,
                        error = %error,
                        "Retaining harness root permit because execution state could not be read"
                    );
                },
            }
            // (c) Hard ceiling: never pin a permit past the max-retention window,
            // even if the execution never reports terminal (e.g. a stuck root).
            if started_at.elapsed() >= HARNESS_ROOT_PERMIT_MAX_RETENTION {
                warn!(
                    execution_id = %execution_id,
                    max_retention_secs = HARNESS_ROOT_PERMIT_MAX_RETENTION.as_secs(),
                    "Force-releasing harness root permit after exceeding max retention window"
                );
                drop(harness_root_permit);
                return;
            }
            time::sleep(HARNESS_ROOT_TERMINAL_POLL_INTERVAL).await;
        }
    });
}

async fn scheduled_dispatch_definition_is_current(
    agent_api: &AgentApiServices,
    dispatch: &ManualTriggerDispatch,
) -> bool {
    let Some(current) = agent_api
        .runtime
        .get_definition_in_scope(&dispatch.principal, &dispatch.workspace, &dispatch.agent_id)
        .await
    else {
        debug!(
            agent_id = %dispatch.agent_id,
            goal_id = %dispatch.goal_id,
            cycle_id = %dispatch.cycle_id,
            "Skipping scheduled trigger because runtime definition is missing"
        );
        return false;
    };
    if current.version != dispatch.definition_version {
        debug!(
            agent_id = %dispatch.agent_id,
            goal_id = %dispatch.goal_id,
            cycle_id = %dispatch.cycle_id,
            current_version = current.version,
            prepared_version = dispatch.definition_version,
            "Skipping scheduled trigger because definition version changed before admission"
        );
        return false;
    }
    // NOTE: goals/triggers validation removed — these are now managed by
    // the scheduler via Task definitions, not by AgentDefinition fields.
    true
}

/// Branch B dispatch-time guard: the definition *version* is validated once at
/// admission (`scheduled_dispatch_definition_is_current`); by launch we only
/// require that the definition still EXISTS in scope. A benign cache refresh /
/// hot-reload that bumps the version between admission and launch must not drop
/// an otherwise-unchanged definition — only an outright disappearance does.
async fn scheduled_dispatch_definition_still_exists(
    agent_api: &AgentApiServices,
    dispatch: &ManualTriggerDispatch,
) -> bool {
    if agent_api
        .runtime
        .get_definition_in_scope(&dispatch.principal, &dispatch.workspace, &dispatch.agent_id)
        .await
        .is_some()
    {
        return true;
    }
    debug!(
        agent_id = %dispatch.agent_id,
        goal_id = %dispatch.goal_id,
        cycle_id = %dispatch.cycle_id,
        "Skipping scheduled trigger because runtime definition disappeared before dispatch"
    );
    false
}

/// Parse `MAGICIAN_HARNESS_PAUSED` into an explicit override, mirroring
/// `autofix_env_override`: `Some(true)` for `1/true/yes/on`, `Some(false)` for
/// `0/false/no/off`, `None` when unset or unrecognized (fall back to config).
fn parse_harness_pause_override(value: &str) -> Option<bool> {
    match value.trim().to_ascii_lowercase().as_str() {
        "1" | "true" | "yes" | "on" => Some(true),
        "0" | "false" | "no" | "off" => Some(false),
        _ => None,
    }
}

fn harness_pause_env_override() -> Option<bool> {
    std::env::var("MAGICIAN_HARNESS_PAUSED")
        .ok()
        .as_deref()
        .and_then(parse_harness_pause_override)
}

fn load_harness_runtime_status() -> HarnessRuntimeStatusResponse {
    let env_override = harness_pause_env_override();
    let config_path = magician::config::magician_config_path();
    let (configured_paused, config_error) =
        match magician::config::load_magician_config_from_path(&config_path) {
            Ok(config) => (Some(config.harness.paused), None),
            Err(error) => (None, Some(error.to_string())),
        };
    let (paused, effective_source) = if let Some(overridden) = env_override {
        (overridden, "environment")
    } else if let Some(configured) = configured_paused {
        (configured, "config")
    } else {
        // A malformed/missing runtime config must not silently start autonomous
        // work. The status response carries the parse error for the operator.
        (true, "config_error")
    };
    HarnessRuntimeStatusResponse {
        enabled: !paused,
        paused,
        configured_paused,
        env_override,
        effective_source: effective_source.to_string(),
        config_error,
    }
}

fn render_harness_config_block(config: &magician::config::HarnessConfig) -> String {
    [
        "harness:".to_string(),
        "  # Autonomous company-loop runtime controls. API/UI writes preserve".to_string(),
        "  # these values in the live runtime config; credentials remain in env.".to_string(),
        format!("  autofix_enabled: {}", config.autofix_enabled),
        format!("  autofix_agent: {}", yaml_string(&config.autofix_agent)),
        "  # true blocks scheduled/manual starts plus steward/autofix dispatches;".to_string(),
        "  # the control API clears queues and requests active-cycle cancellation.".to_string(),
        "  # MAGICIAN_HARNESS_PAUSED remains an emergency override; a UI mutation".to_string(),
        "  # clears it from runtime env files so config becomes authoritative.".to_string(),
        format!("  paused: {}", config.paused),
    ]
    .join("\n")
}

fn persist_harness_runtime_enabled(
    enabled: bool,
) -> Result<(bool, bool, magician::config::MagicianConfig), String> {
    let paths = runtime_settings_paths();
    let mut config = magician::config::load_magician_config_from_path(&paths.config_path)
        .map_err(|error| format!("failed to load {}: {error}", paths.config_path.display()))?;
    let configured_paused = !enabled;
    let config_changed = config.harness.paused != configured_paused;
    config.harness.paused = configured_paused;
    write_top_level_yaml_block(
        &paths.config_path,
        "harness",
        &render_harness_config_block(&config.harness),
    )
    .map_err(|error| format!("failed to update {}: {error}", paths.config_path.display()))?;

    let env_key = "MAGICIAN_HARNESS_PAUSED";
    let process_override_present = std::env::var_os(env_key).is_some();
    let mut file_override_present = false;
    for env_path in [&paths.env_development_path, &paths.env_path] {
        if !env_path.exists() {
            continue;
        }
        file_override_present |= read_env_file_values(env_path).contains_key(env_key);
        update_env_file(env_path, &[(env_key, None)]).map_err(|error| {
            format!(
                "failed to clear {env_key} from {}: {error}",
                env_path.display()
            )
        })?;
    }
    std::env::remove_var(env_key);
    let env_override_cleared = process_override_present || file_override_present;
    Ok((
        config_changed || env_override_cleared,
        env_override_cleared,
        config,
    ))
}

/// Global harness pause kill-switch. Config is reloaded per admission so API/UI
/// changes are live without restart. Environment remains an emergency override.
/// Config read failures fail closed to avoid unexpected autonomous work.
fn harness_globally_paused() -> bool {
    load_harness_runtime_status().paused
}

#[cfg(test)]
mod harness_pause_gate_tests {
    use super::{parse_harness_pause_override, render_harness_config_block};

    #[test]
    fn env_override_parses_pause_resume_or_none() {
        assert_eq!(parse_harness_pause_override("on"), Some(true));
        assert_eq!(parse_harness_pause_override("0"), Some(false));
        assert_eq!(parse_harness_pause_override("banana"), None);
    }

    #[test]
    fn rendered_harness_block_preserves_runtime_fields() {
        let mut config = magician::config::HarnessConfig::default();
        config.paused = true;
        let block = render_harness_config_block(&config);

        assert!(block.starts_with("harness:\n"));
        assert!(block.contains("  autofix_enabled: true"));
        assert!(block.contains("  autofix_agent: senior-software-developer"));
        assert!(block.contains("  paused: true"));
    }
}

#[cfg(test)]
mod harness_root_admission_tests {
    use super::{
        classify_root_dispatch, harness_root_permit_can_release,
        harness_root_permit_requires_terminal_retention, try_admit_harness_root, AgenticOutcome,
        EnvironmentState, RootDispatchClass, WaitingState,
    };

    #[test]
    fn classifies_only_the_canonical_harness_goal_lane_as_harness_roots() {
        assert_eq!(
            classify_root_dispatch("harness:cto:daily-review"),
            RootDispatchClass::Harness
        );
        assert_eq!(
            classify_root_dispatch("harness:owner:manual-review"),
            RootDispatchClass::Harness
        );
        assert_eq!(
            classify_root_dispatch("autonomous:cto:daily-review"),
            RootDispatchClass::Standard
        );
        assert_eq!(
            classify_root_dispatch("default"),
            RootDispatchClass::Standard
        );
    }

    #[test]
    fn standard_roots_bypass_harness_admission() {
        assert!(matches!(
            try_admit_harness_root("worker:daily-review", None),
            Ok(None)
        ));
    }

    #[test]
    fn waiting_for_children_retains_harness_root_permit_until_terminal_state() {
        let waiting = AgenticOutcome::WaitingForChildren {
            child_execution_ids: vec!["child-1".to_string()],
            last_state: EnvironmentState::Uninitialized,
            iterations_used: 1,
            pause_state: Some(Box::new(
                magician::magician_v2::execution::agentic::AgenticPauseState::new(
                    1,
                    "test",
                    "test",
                    EnvironmentState::Browser(Default::default()),
                    "",
                    2,
                    2,
                ),
            )),
        };
        let failed = AgenticOutcome::Failed {
            reason: "failed".to_string(),
            last_state: EnvironmentState::Browser(Default::default()),
            iterations_used: 1,
        };

        assert!(harness_root_permit_requires_terminal_retention(&waiting));
        assert!(!harness_root_permit_requires_terminal_retention(&failed));
        assert!(!harness_root_permit_can_release(
            WaitingState::WaitingChildren
        ));
        assert!(!harness_root_permit_can_release(WaitingState::Executing));
        assert!(!harness_root_permit_can_release(WaitingState::WaitingUser));
        assert!(harness_root_permit_can_release(WaitingState::Completed));
        assert!(harness_root_permit_can_release(WaitingState::Failed));
        assert!(harness_root_permit_can_release(WaitingState::Cancelled));
    }

    #[test]
    fn execution_lookup_error_missing_detection() {
        // The orchestrator wraps a missing execution as
        // "Failed to get execution: Execution not found: <id>".
        assert!(super::execution_lookup_error_is_missing(
            "Failed to get execution: Execution not found: exec-123"
        ));
        assert!(super::execution_lookup_error_is_missing(
            "record does not exist"
        ));
        // A transient failure must NOT be treated as missing (permit is retained).
        assert!(!super::execution_lookup_error_is_missing(
            "Failed to get execution: connection reset by peer"
        ));
    }
}

async fn admit_prepared_scheduled_dispatch(
    agent_api: &AgentApiServices,
    dispatch: &ManualTriggerDispatch,
) -> ScheduledDispatchAdmission {
    // The global company-loop switch must not suppress unrelated scheduled
    // agents. Harness roots use the canonical harness goal namespace.
    if classify_root_dispatch(&dispatch.goal_id) == RootDispatchClass::Harness
        && harness_globally_paused()
    {
        debug!(
            agent_id = %dispatch.agent_id,
            goal_id = %dispatch.goal_id,
            trigger_seq = dispatch.trigger_seq,
            "Skipping scheduled trigger: harness globally paused (harness.paused / MAGICIAN_HARNESS_PAUSED)"
        );
        return ScheduledDispatchAdmission::Drop;
    }
    if agent_api
        .is_agent_paused(&dispatch.principal, &dispatch.workspace, &dispatch.agent_id)
        .await
    {
        debug!(
            agent_id = %dispatch.agent_id,
            goal_id = %dispatch.goal_id,
            trigger_seq = dispatch.trigger_seq,
            "Skipping scheduled trigger because agent is paused before admission"
        );
        return ScheduledDispatchAdmission::Drop;
    }
    if !scheduled_dispatch_definition_is_current(agent_api, dispatch).await {
        return ScheduledDispatchAdmission::Drop;
    }
    if agent_api
        .runtime
        .is_goal_running_in_scope(
            Some(&dispatch.principal),
            Some(&dispatch.workspace),
            &dispatch.agent_id,
            &dispatch.goal_id,
        )
        .await
        || agent_api
            .runtime
            .pending_trigger_count_in_scope(
                Some(&dispatch.principal),
                Some(&dispatch.workspace),
                &dispatch.agent_id,
                &dispatch.goal_id,
            )
            .await
            > 0
    {
        info!(
            agent_id = %dispatch.agent_id,
            goal_id = %dispatch.goal_id,
            trigger_seq = dispatch.trigger_seq,
            "Coalescing scheduled trigger because this agent/goal already has active or queued work"
        );
        return ScheduledDispatchAdmission::Drop;
    }

    // Stage payload before runtime admission so queue promotion can always
    // fetch dispatch metadata.
    let staged_pending_payload = {
        let mut pending = agent_api.pending_cycle_dispatches.write().await;
        if pending.contains_key(&dispatch.cycle_id) {
            false
        } else {
            pending.insert(dispatch.cycle_id.clone(), dispatch.clone());
            true
        }
    };

    match agent_api
        .runtime
        .admit_trigger_in_scope(
            Some(&dispatch.principal),
            Some(&dispatch.workspace),
            &dispatch.agent_id,
            &dispatch.goal_id,
            &dispatch.trigger,
            dispatch.trigger_seq,
        )
        .await
    {
        TriggerAdmission::StartNow { .. } => {
            agent_api
                .pending_cycle_dispatches
                .write()
                .await
                .remove(&dispatch.cycle_id);
            ScheduledDispatchAdmission::StartNow
        },
        TriggerAdmission::Queued { queue_position, .. } => {
            debug!(
                agent_id = %dispatch.agent_id,
                goal_id = %dispatch.goal_id,
                trigger_seq = dispatch.trigger_seq,
                queue_position = queue_position,
                "Queued scheduled trigger for serialized execution"
            );
            ScheduledDispatchAdmission::Queued
        },
        TriggerAdmission::Duplicate { cycle_id } => {
            if staged_pending_payload {
                agent_api
                    .pending_cycle_dispatches
                    .write()
                    .await
                    .remove(&dispatch.cycle_id);
            }
            debug!(
                agent_id = %dispatch.agent_id,
                goal_id = %dispatch.goal_id,
                trigger_seq = dispatch.trigger_seq,
                cycle_id = %cycle_id,
                "Skipping scheduled trigger because tuple is already active/queued/completed"
            );
            ScheduledDispatchAdmission::Drop
        },
        TriggerAdmission::QueueFull { capacity, .. } => {
            if staged_pending_payload {
                agent_api
                    .pending_cycle_dispatches
                    .write()
                    .await
                    .remove(&dispatch.cycle_id);
            }
            warn!(
                agent_id = %dispatch.agent_id,
                goal_id = %dispatch.goal_id,
                trigger_seq = dispatch.trigger_seq,
                capacity = capacity,
                "Dropping scheduled trigger because runtime queue is full"
            );
            ScheduledDispatchAdmission::Drop
        },
    }
}

async fn requeue_scheduled_trigger_for_retry(
    agent_api: &AgentApiServices,
    scheduled: &ScheduledTrigger,
    reason: &str,
) {
    let scheduler = match agent_api
        .resolve_scheduler(&scheduled.principal, &scheduled.workspace)
        .await
    {
        Ok(scheduler) => scheduler,
        Err(_) => return,
    };
    match scheduler
        .requeue_due_cron_trigger(scheduled, Utc::now())
        .await
    {
        Ok(true) => warn!(
            agent_id = %scheduled.agent_id,
            goal_id = %scheduled.goal_id,
            trigger_seq = scheduled.trigger_seq,
            reason = %reason,
            "Re-queued scheduled trigger after retryable dispatch failure"
        ),
        Ok(false) => debug!(
            agent_id = %scheduled.agent_id,
            goal_id = %scheduled.goal_id,
            trigger_seq = scheduled.trigger_seq,
            reason = %reason,
            "Skipped scheduled-trigger requeue because tuple already moved forward"
        ),
        Err(err) => warn!(
            agent_id = %scheduled.agent_id,
            goal_id = %scheduled.goal_id,
            trigger_seq = scheduled.trigger_seq,
            reason = %reason,
            error = %err,
            "Failed to re-queue scheduled trigger after retryable dispatch failure"
        ),
    }
}

async fn dispatch_scheduled_trigger(
    agent_api: &AgentApiServices,
    v2_orchestrator: &Arc<MagicianV2Orchestrator>,
    scheduled: ScheduledTrigger,
) {
    let mut prepared = match prepare_scheduled_trigger_dispatch(agent_api, &scheduled).await {
        Ok(Some(prepared)) => prepared,
        Ok(None) => return,
        Err(err) => {
            warn!(
                agent_id = %scheduled.agent_id,
                goal_id = %scheduled.goal_id,
                trigger_seq = scheduled.trigger_seq,
                error = %err,
                "Failed to prepare scheduled trigger dispatch"
            );
            requeue_scheduled_trigger_for_retry(agent_api, &scheduled, "prepare_failed").await;
            return;
        },
    };

    let admission = {
        let _control_guard = agent_api.control_gate.lock().await;
        admit_prepared_scheduled_dispatch(agent_api, &prepared).await
    };

    if !matches!(admission, ScheduledDispatchAdmission::StartNow) {
        return;
    }

    let _agent_lifecycle_exclusion = match acquire_agent_dispatch_lifecycle_exclusion(
        v2_orchestrator,
        &prepared.principal,
        &prepared.workspace,
        &prepared.agent_id,
    )
    .await
    {
        Ok(exclusion) => exclusion,
        Err(_) => {
            requeue_scheduled_trigger_for_retry(
                agent_api,
                &scheduled,
                "agent_lifecycle_admission_unavailable",
            )
            .await;
            let _ = abandon_cycle_and_take_next_dispatch_controlled(
                agent_api,
                &prepared.principal,
                &prepared.workspace,
                &prepared.agent_id,
                &prepared.goal_id,
                &prepared.cycle_id,
                false,
            )
            .await;
            return;
        },
    };

    let harness_root_permit = match try_admit_harness_root(&prepared.goal_id, None) {
        Ok(permit) => permit,
        Err(HarnessRootCapacityExhausted) => {
            info!(
                agent_id = %prepared.agent_id,
                goal_id = %prepared.goal_id,
                cycle_id = %prepared.cycle_id,
                "Dropping scheduled harness trigger because root capacity is exhausted"
            );
            record_harness_root_capacity_drop(agent_api, &prepared);
            let next_dispatch = abandon_cycle_and_take_next_dispatch_controlled(
                agent_api,
                &prepared.principal,
                &prepared.workspace,
                &prepared.agent_id,
                &prepared.goal_id,
                &prepared.cycle_id,
                true,
            )
            .await;
            drop(_agent_lifecycle_exclusion);
            if let Some(next_dispatch) = next_dispatch {
                launch_manual_trigger_dispatch(agent_api, v2_orchestrator, next_dispatch, None)
                    .await;
            }
            return;
        },
    };

    let execution_goal = match execution_goal_for_manual_dispatch(agent_api, &prepared).await {
        Ok(goal) => goal,
        Err(err) => {
            warn!(
                agent_id = %prepared.agent_id,
                goal_id = %prepared.goal_id,
                cycle_id = %prepared.cycle_id,
                error = %err,
                "Prompt pipeline assembly failed for scheduled trigger"
            );
            requeue_scheduled_trigger_for_retry(agent_api, &scheduled, "prompt_assembly_failed")
                .await;
            let next_dispatch = abandon_cycle_and_take_next_dispatch_controlled(
                agent_api,
                &prepared.principal,
                &prepared.workspace,
                &prepared.agent_id,
                &prepared.goal_id,
                &prepared.cycle_id,
                true,
            )
            .await;
            drop(_agent_lifecycle_exclusion);
            if let Some(next_dispatch) = next_dispatch {
                launch_manual_trigger_dispatch(
                    agent_api,
                    v2_orchestrator,
                    next_dispatch,
                    harness_root_permit,
                )
                .await;
            }
            return;
        },
    };

    let next_dispatch = {
        let _control_guard = agent_api.control_gate.lock().await;
        if agent_api
            .is_agent_paused(&prepared.principal, &prepared.workspace, &prepared.agent_id)
            .await
        {
            let _ = abandon_cycle_and_take_next_dispatch(
                agent_api,
                &prepared.principal,
                &prepared.workspace,
                &prepared.agent_id,
                &prepared.goal_id,
                &prepared.cycle_id,
                false,
            )
            .await;
            debug!(
                agent_id = %prepared.agent_id,
                goal_id = %prepared.goal_id,
                cycle_id = %prepared.cycle_id,
                "Skipping scheduled trigger dispatch because agent was paused before launch"
            );
            None
        } else if !scheduled_dispatch_definition_still_exists(agent_api, &prepared).await {
            magician::magician_v2::harness::record_harness_cycle_outcome(
                &harness_cycle_outcome_store(agent_api),
                &prepared.principal,
                &prepared.workspace,
                &prepared.agent_id,
                &prepared.goal_id,
                Some(prepared.cycle_id.as_str()),
                None,
                magician::magician_v2::harness::HarnessCycleDispatchOutcome::DroppedDefinitionStale,
                serde_json::json!({ "reason": "definition_missing_before_dispatch" }),
            );
            abandon_cycle_and_take_next_dispatch(
                agent_api,
                &prepared.principal,
                &prepared.workspace,
                &prepared.agent_id,
                &prepared.goal_id,
                &prepared.cycle_id,
                true,
            )
            .await
        } else {
            // Branch A: admission already keeps a single active reservation per
            // (scope, agent, goal). Here we refuse to launch only when the live
            // reservation belongs to a *genuinely different* trigger. If it is
            // the SAME trigger identity (goal + trigger + trigger_seq) but a
            // refreshed/promoted cycle_id, adopt that cycle_id and proceed rather
            // than dropping an otherwise-valid cycle. We never loosen to "any
            // active reservation counts".
            let active_reservation = agent_api
                .runtime
                .active_cycle_in_scope(
                    Some(&prepared.principal),
                    Some(&prepared.workspace),
                    &prepared.agent_id,
                    &prepared.goal_id,
                )
                .await;
            let active_matches = match active_reservation.as_ref() {
                Some(active) if active.cycle_id == prepared.cycle_id => true,
                Some(active)
                    if active.goal_id == prepared.goal_id
                        && active.trigger == prepared.trigger
                        && active.trigger_seq == prepared.trigger_seq =>
                {
                    prepared.cycle_id = active.cycle_id.clone();
                    true
                },
                _ => false,
            };
            if !active_matches {
                debug!(
                    agent_id = %prepared.agent_id,
                    goal_id = %prepared.goal_id,
                    cycle_id = %prepared.cycle_id,
                    "Skipping scheduled trigger launch because active reservation changed before dispatch"
                );
                magician::magician_v2::harness::record_harness_cycle_outcome(
                    &harness_cycle_outcome_store(agent_api),
                    &prepared.principal,
                    &prepared.workspace,
                    &prepared.agent_id,
                    &prepared.goal_id,
                    Some(prepared.cycle_id.as_str()),
                    None,
                    magician::magician_v2::harness::HarnessCycleDispatchOutcome::DroppedReservationChanged,
                    serde_json::json!({ "reason": "active_reservation_changed_before_dispatch" }),
                );
                return;
            }
            if let Err(error) = ensure_dispatch_task_backed_root(
                agent_api,
                v2_orchestrator,
                &mut prepared,
                &execution_goal,
            )
            .await
            {
                warn!(
                    agent_id = %prepared.agent_id,
                    goal_id = %prepared.goal_id,
                    cycle_id = %prepared.cycle_id,
                    error = %error,
                    "Failed to provision exact execution for scheduled trigger"
                );
                magician::magician_v2::harness::record_harness_cycle_outcome(
                    &harness_cycle_outcome_store(agent_api),
                    &prepared.principal,
                    &prepared.workspace,
                    &prepared.agent_id,
                    &prepared.goal_id,
                    Some(prepared.cycle_id.as_str()),
                    None,
                    magician::magician_v2::harness::HarnessCycleDispatchOutcome::DroppedProvisionFailed,
                    serde_json::json!({ "reason": "thread_provision_failed", "error": error.to_string() }),
                );
                requeue_scheduled_trigger_for_retry(
                    agent_api,
                    &scheduled,
                    "thread_provision_failed",
                )
                .await;
                if let Some(next_dispatch) = abandon_cycle_and_take_next_dispatch(
                    agent_api,
                    &prepared.principal,
                    &prepared.workspace,
                    &prepared.agent_id,
                    &prepared.goal_id,
                    &prepared.cycle_id,
                    true,
                )
                .await
                {
                    // The promoted dispatch acquires its own agent fence and
                    // then the control gate. Release both current authorities
                    // before re-entering admission, including the same-agent
                    // case and process-lock stripe collisions.
                    drop(_control_guard);
                    drop(_agent_lifecycle_exclusion);
                    launch_manual_trigger_dispatch(
                        agent_api,
                        v2_orchestrator,
                        next_dispatch,
                        harness_root_permit,
                    )
                    .await;
                }
                return;
            }

            magician::magician_v2::harness::record_harness_cycle_outcome(
                &harness_cycle_outcome_store(agent_api),
                &prepared.principal,
                &prepared.workspace,
                &prepared.agent_id,
                &prepared.goal_id,
                Some(prepared.cycle_id.as_str()),
                None,
                magician::magician_v2::harness::HarnessCycleDispatchOutcome::Dispatched,
                serde_json::json!({ "reason": "launched" }),
            );
            dispatch_manual_trigger_cycle(
                agent_api,
                v2_orchestrator,
                prepared,
                execution_goal,
                harness_root_permit,
            );
            return;
        }
    };

    drop(_agent_lifecycle_exclusion);
    if let Some(next_dispatch) = next_dispatch {
        launch_manual_trigger_dispatch(
            agent_api,
            v2_orchestrator,
            next_dispatch,
            harness_root_permit,
        )
        .await;
    }
}

async fn resolve_scheduled_wake_target(
    agent_api: &AgentApiServices,
    task_id: &str,
) -> Option<(String, String, String, String)> {
    if let Some(target) =
        magician::magician_v2::agents::wake_up_queue::parse_scoped_automation_task_id(task_id)
    {
        return Some(target);
    }

    let schedulers = agent_api
        .scoped_schedulers
        .read()
        .await
        .iter()
        .map(|(scope, scheduler)| (scope.clone(), Arc::clone(scheduler)))
        .collect::<Vec<_>>();
    for ((principal, workspace), scheduler) in schedulers {
        if let Some(entry) = scheduler.entry_for_task_id(task_id).await {
            return Some((principal, workspace, entry.agent_id, entry.goal_id));
        }
    }
    None
}

async fn dispatch_harness_scheduled_wake(
    agent_api: &AgentApiServices,
    v2_orchestrator: &Arc<MagicianV2Orchestrator>,
    task_id: &str,
) -> bool {
    let Some((principal, workspace, agent_id, goal_id)) =
        resolve_scheduled_wake_target(agent_api, task_id).await
    else {
        return false;
    };
    if classify_root_dispatch(&goal_id) == RootDispatchClass::Standard {
        return false;
    }

    let scheduler = match agent_api.resolve_scheduler(&principal, &workspace).await {
        Ok(scheduler) => scheduler,
        Err(error) => {
            warn!(
                principal = %principal,
                workspace = %workspace,
                agent_id = %agent_id,
                goal_id = %goal_id,
                error = %error,
                "Failed to resolve scheduler for harness cron wake"
            );
            return true;
        },
    };
    let Some(entry) = scheduler.entry_for_agent_goal(&agent_id, &goal_id).await else {
        warn!(
            principal = %principal,
            workspace = %workspace,
            agent_id = %agent_id,
            goal_id = %goal_id,
            "Harness cron wake no longer has a scheduler entry"
        );
        return true;
    };
    if !matches!(
        entry.registration,
        SchedulerTriggerRegistration::Cron { .. }
    ) {
        warn!(
            principal = %principal,
            workspace = %workspace,
            agent_id = %agent_id,
            goal_id = %goal_id,
            "Suppressing non-cron harness scheduled wake because it bypasses root admission"
        );
        return true;
    }

    let due = match scheduler.collect_due_cron_triggers(Utc::now()).await {
        Ok(due) => due,
        Err(error) => {
            warn!(
                principal = %principal,
                workspace = %workspace,
                agent_id = %agent_id,
                goal_id = %goal_id,
                error = %error,
                "Failed to collect catch-up cron triggers for harness wake"
            );
            return true;
        },
    };
    for scheduled in due {
        dispatch_scheduled_trigger(agent_api, v2_orchestrator, scheduled).await;
    }
    // Do not resume SchedulerAgent here: it can provision the harness root
    // outside the dispatcher that owns the root-capacity permit.
    true
}

/// Persistent round-robin cursor across scheduler ticks. Only advances (never
/// resets mid-cycle) so no scope starves when SCHEDULER_SCOPES_PER_TICK batches.
static SCHEDULER_SCOPE_CURSOR: AtomicUsize = AtomicUsize::new(0);

/// Take at most `k` scopes starting at `cursor`, wrapping. Returns (batch, next_cursor).
/// The cursor only advances (never resets mid-cycle) so no scope starves.
fn select_scope_batch(
    scopes: &[(String, String)],
    cursor: usize,
    k: usize,
) -> (Vec<(String, String)>, usize) {
    if scopes.is_empty() {
        return (Vec::new(), 0);
    }
    let start = cursor % scopes.len();
    let take = k.min(scopes.len());
    let batch = (0..take)
        .map(|i| scopes[(start + i) % scopes.len()].clone())
        .collect();
    (batch, (start + take) % scopes.len())
}

async fn run_scheduler_tick(
    agent_api: &AgentApiServices,
    v2_orchestrator: &Arc<MagicianV2Orchestrator>,
) {
    if ensure_agent_startup_hydrated(agent_api).await.is_err() {
        return;
    }

    // Scope keys only. This used to clone every definition in every scope out of
    // the store's cache purely to read two `Option<String>` fields off each one
    // and drop the rest — every 5 seconds, forever. `list_definition_scope_keys`
    // derives the same deduplicated, sorted tuple set by borrowing the cached
    // lists, so the tick allocates one small tuple per scope instead of a deep
    // copy of the whole definition corpus.
    let scopes = match agent_api
        .definition_store
        .list_definition_scope_keys()
        .await
    {
        Ok(scopes) => scopes,
        Err(err) => {
            warn!(error = %err, "Failed to enumerate scopes for scheduler tick");
            return;
        },
    };

    let cursor = SCHEDULER_SCOPE_CURSOR.load(Ordering::Relaxed);
    let (batch, next_cursor) = select_scope_batch(&scopes, cursor, SCHEDULER_SCOPES_PER_TICK);
    SCHEDULER_SCOPE_CURSOR.store(next_cursor, Ordering::Relaxed);

    let mut dispatched = 0usize;
    let mut requeued = 0usize;

    for (principal, workspace) in batch {
        let scheduler = match agent_api.resolve_scheduler(&principal, &workspace).await {
            Ok(scheduler) => scheduler,
            Err(err) => {
                warn!(
                    principal = %principal,
                    workspace = %workspace,
                    error = %err,
                    "Failed to resolve scoped scheduler during tick"
                );
                continue;
            },
        };

        let due = match scheduler.collect_due_cron_triggers(Utc::now()).await {
            Ok(due) => due,
            Err(err) => {
                warn!(
                    principal = %principal,
                    workspace = %workspace,
                    error = %err,
                    "Failed to collect due cron triggers"
                );
                continue;
            },
        };

        // collect_due_cron_triggers CONSUMES each fire (bumps trigger_seq, advances
        // next_run_at). Any collected trigger we do not dispatch MUST be requeued or
        // the fire is silently lost. Never drop a collected trigger.
        for scheduled in due {
            if dispatched < SCHEDULER_DISPATCH_BUDGET_PER_TICK {
                dispatch_scheduled_trigger(agent_api, v2_orchestrator, scheduled).await;
                dispatched += 1;
            } else {
                requeue_scheduled_trigger_for_retry(
                    agent_api,
                    &scheduled,
                    "scheduler_dispatch_budget_spent",
                )
                .await;
                requeued += 1;
            }
        }
    }

    if requeued > 0 {
        warn!(
            dispatched,
            requeued,
            "scheduler dispatch budget spent this tick; deferred triggers requeued for next tick"
        );
    }
}

async fn run_approval_expiry_sweep(
    agent_api: &AgentApiServices,
    v2_orchestrator: &Arc<MagicianV2Orchestrator>,
) {
    if ensure_agent_startup_hydrated(agent_api).await.is_err() {
        return;
    }

    let scopes = match agent_api
        .definition_store
        .list_all_definitions_across_scopes()
        .await
    {
        Ok(records) => records
            .into_iter()
            .filter_map(|record| Some((record.definition.principal?, record.definition.workspace?)))
            .collect::<HashSet<_>>(),
        Err(err) => {
            warn!(error = %err, "Failed to enumerate scopes for approval expiry sweep");
            return;
        },
    };

    for (principal, workspace) in scopes {
        let approval_service = match agent_api
            .resolve_approval_service(&principal, &workspace)
            .await
        {
            Ok(service) => service,
            Err(err) => {
                warn!(
                    principal = %principal,
                    workspace = %workspace,
                    error = %err,
                    "Failed to resolve scoped approval service during sweep"
                );
                continue;
            },
        };
        match approval_service.expire_pending_requests(Utc::now()).await {
            Ok(expired_requests) => {
                let expired = expired_requests.len();
                if expired > 0 {
                    info!(
                        principal = %principal,
                        workspace = %workspace,
                        expired = expired,
                        "Expired pending approvals during sweep"
                    );
                    for request in expired_requests {
                        emit_approval_expired_event(
                            v2_orchestrator,
                            Some(principal.as_str()),
                            Some(workspace.as_str()),
                            &request,
                            "sweep",
                        );
                    }
                }
            },
            Err(err) => {
                warn!(
                    principal = %principal,
                    workspace = %workspace,
                    error = %err,
                    "Approval expiry sweep failed"
                );
            },
        }
    }
}

/// Disabled-agent consolidation drain-then-stop policy: once a sweep on a
/// disabled agent produces no updates, skip its subsequent sweeps for this
/// long before re-checking. Lets a stray late-arriving episode eventually
/// get consolidated without burning a sweep on a steady-state-empty agent
/// every 5 minutes.
const DISABLED_DRAINED_REVISIT: chrono::Duration = chrono::Duration::hours(1);

async fn run_memory_consolidation_sweep(
    agent_api: &AgentApiServices,
    v2_orchestrator: &Arc<MagicianV2Orchestrator>,
    drained_disabled: &Arc<StdMutex<HashMap<String, DateTime<Utc>>>>,
) {
    if ensure_agent_startup_hydrated(agent_api).await.is_err() {
        return;
    }

    let definitions = agent_api.runtime.list_definitions().await;
    if definitions.is_empty() {
        return;
    }

    // 2026-05-23 — Resolve the set of disabled-by-hierarchy agent IDs from
    // the current definition snapshot. Reuses `disabled_agent_hierarchy`
    // (the same helper the scheduled-trigger path at line ~2003 uses to
    // skip disabled work), so the policy is consistent across triggers.
    let disabled_agent_ids: HashSet<String> = disabled_agent_hierarchy(definitions.iter())
        .into_iter()
        .collect();
    // Drop any drained entries for agents that are now enabled — they
    // should resume normal sweeps immediately.
    {
        let mut drained = drained_disabled.lock().unwrap();
        drained.retain(|agent_id, _| disabled_agent_ids.contains(agent_id));
    }

    let now = Utc::now();
    // The Semaphore::new(4) that capped concurrent consolidation sweeps was
    // removed: the LLM dispatch queue now owns provider back-pressure (its
    // Background lane + per-provider concurrency caps), so this redundant
    // outer cap on the sweep is gone.
    let mut handles = Vec::new();
    let mut skipped_drained = 0usize;

    for definition in definitions {
        let agent_id = definition.agent_id.clone();
        let is_disabled = disabled_agent_ids.contains(&agent_id);
        // For a disabled agent that has been drained recently, skip both
        // the batch and retention sweeps until the revisit window
        // elapses. Retention is intentionally skipped too: a disabled
        // agent isn't accumulating new episodes, so its retention
        // backlog is bounded by what was already there at disable time.
        if is_disabled {
            let drained = drained_disabled.lock().unwrap();
            if let Some(drained_at) = drained.get(&agent_id) {
                if now.signed_duration_since(*drained_at) < DISABLED_DRAINED_REVISIT {
                    skipped_drained += 1;
                    continue;
                }
            }
        }
        let agent_api = agent_api.clone();
        let v2_orchestrator = Arc::clone(v2_orchestrator);
        let drained_disabled = Arc::clone(drained_disabled);

        let handle = tokio::spawn(async move {
            let scoped_memory_consolidator = match agent_api
                .resolve_cycle_memory_consolidator(&definition, &agent_id)
                .await
            {
                Ok(consolidator) => consolidator,
                Err(error) => {
                    warn!(
                        agent_id = %agent_id,
                        error = %error,
                        "Skipping memory consolidation sweep because the agent definition is missing explicit scope"
                    );
                    return;
                },
            };
            // OS1 — replay any memory-clarification answers whose
            // original `ask().await` coroutine died with a previous
            // process (operator answered via /attention but the
            // inline consolidator path never recorded the learning
            // event / created the candidate). Idempotent: dedups
            // against existing `learning_memory_clarification_*`
            // events keyed by `memory_question_key`. Per-agent scope
            // — recovery only touches THIS agent's orphans.
            scoped_memory_consolidator
                .recover_orphan_clarification_answers(&agent_id)
                .await;
            match scoped_memory_consolidator
                .run_batch_sweep_for_agent(&definition, &agent_id, now)
                .await
            {
                Ok(batch_outcome) => {
                    // Drain-then-stop bookkeeping: a disabled agent
                    // whose sweep produced no `updated_targets` and no
                    // `reports` has nothing pending → mark drained so
                    // we skip subsequent ticks until the revisit
                    // window elapses. Any non-empty outcome clears
                    // the drained mark (an episode just got
                    // consolidated; there may be more behind it).
                    if is_disabled {
                        let did_work = !batch_outcome.updated_targets.is_empty()
                            || !batch_outcome.reports.is_empty();
                        let mut drained = drained_disabled.lock().unwrap();
                        if did_work {
                            drained.remove(&agent_id);
                        } else {
                            drained.insert(agent_id.clone(), now);
                            debug!(
                                agent_id = %agent_id,
                                revisit_minutes = DISABLED_DRAINED_REVISIT.num_minutes(),
                                "Disabled agent has no pending consolidation; skipping subsequent sweeps until revisit window elapses"
                            );
                        }
                    }
                    emit_consolidation_reports(
                        &agent_api,
                        &definition,
                        &v2_orchestrator,
                        &agent_id,
                        "",
                        "batch_sweep",
                        &batch_outcome.reports,
                    )
                    .await;
                },
                Err(err) if is_memory_file_lock_timeout(&err) => {
                    debug!(
                        agent_id = %agent_id,
                        error = %err,
                        "Memory batch consolidation sweep skipped because a shared memory file lock is busy"
                    );
                },
                Err(err) => {
                    warn!(
                        agent_id = %agent_id,
                        error = %err,
                        "Memory batch consolidation sweep failed"
                    );
                },
            }

            match scoped_memory_consolidator
                .run_retention_sweep_for_agent(&definition, &agent_id, now)
                .await
            {
                Ok(retention_outcome) => {
                    if retention_outcome.deleted_count > 0 {
                        info!(
                            agent_id = %agent_id,
                            deleted = retention_outcome.deleted_count,
                            "Retention sweep deleted expired episodes"
                        );
                    }
                    emit_consolidation_reports(
                        &agent_api,
                        &definition,
                        &v2_orchestrator,
                        &agent_id,
                        "",
                        "retention_sweep",
                        &retention_outcome.consolidation.reports,
                    )
                    .await;
                },
                Err(err) if is_memory_file_lock_timeout(&err) => {
                    debug!(
                        agent_id = %agent_id,
                        error = %err,
                        "Memory retention sweep skipped because a shared memory file lock is busy"
                    );
                },
                Err(err) => {
                    warn!(
                        agent_id = %agent_id,
                        error = %err,
                        "Memory retention sweep failed"
                    );
                },
            }
        });

        handles.push(handle);
    }

    for handle in handles {
        if let Err(err) = handle.await {
            warn!(error = %err, "Memory consolidation task panicked");
        }
    }

    if skipped_drained > 0 {
        debug!(
            skipped = skipped_drained,
            "Memory consolidation sweep skipped drained disabled agents"
        );
    }
}

/// Phase 4.2 kill-switch for the scheduled harness steward / growth-eval drain.
/// Default ON (in dev and prod); force-OFF with
/// `MAGICIAN_HARNESS_STEWARD_TICK=0` (also accepts `false`/`no`/`off`/`disabled`).
fn harness_steward_tick_enabled() -> bool {
    !matches!(
        std::env::var("MAGICIAN_HARNESS_STEWARD_TICK")
            .ok()
            .as_deref()
            .map(str::trim),
        Some("0") | Some("false") | Some("no") | Some("off") | Some("disabled")
    )
}

/// Phase 4.2 — one low-frequency steward/growth-eval drain pass over every
/// active scope. Reuses the scheduler's scope enumeration
/// (`list_all_definitions_across_scopes`), drafts at most
/// `HARNESS_STEWARD_TICK_MAX_PROPOSALS` deduped proposals per scope, and records
/// a durable `harness_steward_tick` learning event with the counts. Drafting
/// only — never auto-applies (validation/implementation budgets pinned to zero
/// inside `run_harness_steward_tick_for_scope`).
async fn run_harness_steward_tick(agent_api: &AgentApiServices) {
    if harness_globally_paused() || !harness_steward_tick_enabled() {
        return;
    }
    if ensure_agent_startup_hydrated(agent_api).await.is_err() {
        return;
    }

    let scopes = match agent_api
        .definition_store
        .list_all_definitions_across_scopes()
        .await
    {
        Ok(records) => records
            .into_iter()
            .filter_map(|record| Some((record.definition.principal?, record.definition.workspace?)))
            .collect::<HashSet<_>>(),
        Err(err) => {
            warn!(error = %err, "Failed to enumerate scopes for harness steward tick");
            return;
        },
    };

    let repo_root = magician::magician_v2::execution::coding_engine::live_repo_source_fence()
        .map(|(root, _)| root)
        .unwrap_or_else(|| std::env::current_dir().unwrap_or_else(|_| PathBuf::from(".")));
    let learning_api = crate::learning_api::LearningApi::new(
        agent_api.durable_artifact_workspace.clone(),
        repo_root,
    );

    for (principal, workspace) in scopes {
        let scope = magician::magician_v2::learning::LearningScope::new(
            principal.clone(),
            workspace.clone(),
        );
        let outcome = learning_api
            .run_harness_steward_tick_for_scope(scope.clone(), HARNESS_STEWARD_TICK_MAX_PROPOSALS)
            .await;

        if outcome.proposals_drafted > 0 || !outcome.errors.is_empty() {
            info!(
                principal = %principal,
                workspace = %workspace,
                proposals_drafted = outcome.proposals_drafted,
                growth_eval_status = ?outcome.growth_eval_status,
                error_count = outcome.errors.len(),
                "Harness steward tick drained backlog"
            );
        }

        if let Err(error) = harness_cycle_outcome_store(agent_api).append_event(
            scope,
            magician::magician_v2::learning::CreateLearningEventRequest {
                principal: None,
                workspace: None,
                event_type: "harness_steward_tick".to_string(),
                agent_id: None,
                task_id: None,
                execution_id: None,
                chat_session_id: None,
                summary: format!(
                    "Harness steward tick drafted {} proposal(s); growth-eval {}.",
                    outcome.proposals_drafted,
                    outcome.growth_eval_status.as_deref().unwrap_or("skipped")
                ),
                evidence_refs: Vec::new(),
                payload: serde_json::json!({
                    "proposals_drafted": outcome.proposals_drafted,
                    "max_proposals": HARNESS_STEWARD_TICK_MAX_PROPOSALS,
                    "steward_status": outcome.steward_status,
                    "steward_run_id": outcome.steward_run_id,
                    "steward_attention_required": outcome.steward_attention_required,
                    "growth_eval_status": outcome.growth_eval_status,
                    "growth_eval_run_id": outcome.growth_eval_run_id,
                    "errors": outcome.errors,
                }),
            },
        ) {
            warn!(
                principal = %principal,
                workspace = %workspace,
                error = %error,
                "Failed to record harness_steward_tick event"
            );
        }
    }
}

/// Autofix sweep — one pass over every active scope's anomaly queue.
///
/// **Default ON (opt-out)**: gated by the typed config field
/// `harness.autofix_enabled` (default true). The env var
/// `MAGICIAN_HARNESS_AUTOFIX` overrides the config (`0/off` → disable,
/// `1/on` → enable). When enabled, for the top open + uncooled anomaly per
/// scope (rate-limited to `AUTOFIX_MAX_PER_SWEEP`, per-anomaly `autofix_cooldown`
/// of 6h), it creates and starts a coding task assigned to a coding-capable
/// engineer (`harness.autofix_agent`, default `cto`, override via
/// `MAGICIAN_HARNESS_AUTOFIX_AGENT`). The task asks for a MINIMAL fix drafted as
/// a review proposal — NOT applied — and the anomaly is marked
/// `FixDispatched` only after the task starts.
async fn reconcile_harness_autofix_dispatches(
    artifact_service: &Arc<ArtifactV2Service>,
    store: &magician::magician_v2::harness::AnomalyStore,
    principal: &str,
    workspace: &str,
    anomalies: &[magician::magician_v2::harness::HarnessAnomaly],
) {
    let scope =
        ScopeRef::system_internal_unauthenticated(&principal.to_string(), &workspace.to_string());
    for anomaly in anomalies.iter().filter(|anomaly| {
        anomaly.status == magician::magician_v2::harness::AnomalyStatus::FixDispatched
    }) {
        let Some(task_id) = anomaly.fix_task_id.as_deref() else {
            if let Err(error) = store.mark(
                &anomaly.principal,
                &anomaly.workspace,
                &anomaly.signature,
                magician::magician_v2::harness::AnomalyStatus::Open,
                None,
            ) {
                warn!(
                    principal = %principal,
                    workspace = %workspace,
                    signature = %anomaly.signature,
                    error = %error,
                    "Harness autofix sweep failed to reopen dispatched anomaly without a task id"
                );
            }
            continue;
        };

        let task = match artifact_service.get_task(&scope, task_id).await {
            Ok(task) => task,
            Err(error) => {
                warn!(
                    principal = %principal,
                    workspace = %workspace,
                    signature = %anomaly.signature,
                    task_id = %task_id,
                    error = %error,
                    "Harness autofix sweep reopening anomaly whose dispatched fix task is missing/unreadable"
                );
                if let Err(mark_error) = store.mark(
                    &anomaly.principal,
                    &anomaly.workspace,
                    &anomaly.signature,
                    magician::magician_v2::harness::AnomalyStatus::Open,
                    None,
                ) {
                    warn!(
                        principal = %principal,
                        workspace = %workspace,
                        signature = %anomaly.signature,
                        error = %mark_error,
                        "Harness autofix sweep failed to reopen anomaly after missing fix task"
                    );
                }
                continue;
            },
        };

        match task.state.status.as_str() {
            "pending" | "ready" | "paused" | "deferred" => {
                match Arc::clone(artifact_service)
                    .start_execution(scope.clone(), task_id.to_string(), None, false)
                    .await
                {
                    Ok((_task, execution)) => {
                        info!(
                            principal = %principal,
                            workspace = %workspace,
                            signature = %anomaly.signature,
                            task_id = %task_id,
                            execution_id = %execution.state.execution_id,
                            "Harness autofix sweep started previously dispatched fix task"
                        );
                    },
                    Err(error) => {
                        let error_text = error.to_string();
                        if error_text.contains("task_execution_in_progress") {
                            continue;
                        }
                        warn!(
                            principal = %principal,
                            workspace = %workspace,
                            signature = %anomaly.signature,
                            task_id = %task_id,
                            error = %error_text,
                            "Harness autofix sweep could not start previously dispatched fix task; reopening anomaly"
                        );
                        if let Err(status_error) = artifact_service
                            .update_task_status(&scope, task_id, "failed")
                            .await
                        {
                            warn!(
                                principal = %principal,
                                workspace = %workspace,
                                task_id = %task_id,
                                error = %status_error,
                                "Harness autofix sweep failed to mark unstartable fix task failed"
                            );
                        }
                        if let Err(mark_error) = store.mark(
                            &anomaly.principal,
                            &anomaly.workspace,
                            &anomaly.signature,
                            magician::magician_v2::harness::AnomalyStatus::Open,
                            None,
                        ) {
                            warn!(
                                principal = %principal,
                                workspace = %workspace,
                                signature = %anomaly.signature,
                                error = %mark_error,
                                "Harness autofix sweep failed to reopen anomaly after unstartable fix task"
                            );
                        }
                    },
                }
            },
            "completed" => {
                // #27: a completed fix task clears the anomaly. Previously this
                // fell through to `_ => {}`, leaving the anomaly FixDispatched
                // forever so the reliability queue only ever grew.
                if let Err(error) = store.mark(
                    &anomaly.principal,
                    &anomaly.workspace,
                    &anomaly.signature,
                    magician::magician_v2::harness::AnomalyStatus::Resolved,
                    None,
                ) {
                    warn!(
                        principal = %principal,
                        workspace = %workspace,
                        signature = %anomaly.signature,
                        task_id = %task_id,
                        error = %error,
                        "Harness autofix sweep failed to resolve anomaly after completed fix task"
                    );
                } else {
                    info!(
                        principal = %principal,
                        workspace = %workspace,
                        signature = %anomaly.signature,
                        task_id = %task_id,
                        "Harness autofix sweep resolved anomaly after completed fix task"
                    );
                }
            },
            "failed" | "cancelled" | "canceled" => {
                if let Err(error) = store.mark(
                    &anomaly.principal,
                    &anomaly.workspace,
                    &anomaly.signature,
                    magician::magician_v2::harness::AnomalyStatus::Open,
                    None,
                ) {
                    warn!(
                        principal = %principal,
                        workspace = %workspace,
                        signature = %anomaly.signature,
                        task_id = %task_id,
                        error = %error,
                        "Harness autofix sweep failed to reopen anomaly after terminal failed fix task"
                    );
                }
            },
            _ => {},
        }
    }
}

async fn run_harness_autofix_tick(agent_api: &AgentApiServices) {
    if harness_globally_paused() {
        return;
    }
    let config =
        magician::config::load_magician_config_from_path(&magician::config::magician_config_path())
            .ok();
    // Default ON if the config fails to load; the env var overrides the config value.
    let config_enabled = config
        .as_ref()
        .map(|c| c.harness.autofix_enabled)
        .unwrap_or(true);
    let enabled =
        magician::magician_v2::harness::autofix::autofix_env_override().unwrap_or(config_enabled);
    if !enabled {
        return;
    }
    if ensure_agent_startup_hydrated(agent_api).await.is_err() {
        return;
    }

    let artifact_service = match agent_api.runtime.artifact_v2_service() {
        Some(service) => service,
        None => {
            warn!("Harness autofix sweep skipped: artifact_v2_service not wired");
            return;
        },
    };

    let scopes = match agent_api
        .definition_store
        .list_all_definitions_across_scopes()
        .await
    {
        Ok(records) => records
            .into_iter()
            .filter_map(|record| Some((record.definition.principal?, record.definition.workspace?)))
            .collect::<HashSet<_>>(),
        Err(err) => {
            warn!(error = %err, "Failed to enumerate scopes for harness autofix sweep");
            return;
        },
    };

    // Engineer target: env override wins, then the typed config field, then "cto".
    let engineer = std::env::var("MAGICIAN_HARNESS_AUTOFIX_AGENT")
        .ok()
        .or_else(|| config.as_ref().map(|c| c.harness.autofix_agent.clone()))
        .unwrap_or_else(|| "cto".to_string());

    for (principal, workspace) in scopes {
        let store = magician::magician_v2::harness::AnomalyStore::new(
            agent_api.durable_artifact_workspace.clone(),
        );
        let anoms = match store.list(&principal, &workspace) {
            Ok(anoms) => anoms,
            Err(error) => {
                warn!(
                    principal = %principal,
                    workspace = %workspace,
                    error = %error,
                    "Harness autofix sweep: failed to list anomalies for scope"
                );
                continue;
            },
        };
        reconcile_harness_autofix_dispatches(
            &artifact_service,
            &store,
            &principal,
            &workspace,
            &anoms,
        )
        .await;
        let anoms = match store.list(&principal, &workspace) {
            Ok(anoms) => anoms,
            Err(error) => {
                warn!(
                    principal = %principal,
                    workspace = %workspace,
                    error = %error,
                    "Harness autofix sweep: failed to reload anomalies after repair pass"
                );
                continue;
            },
        };
        let targets = magician::magician_v2::harness::select_autofix_targets(
            &anoms,
            Utc::now(),
            magician::magician_v2::harness::autofix::autofix_cooldown(),
            magician::magician_v2::harness::autofix::AUTOFIX_MAX_PER_SWEEP,
        );

        for anomaly in targets {
            let description = format!(
                "An autonomous harness cycle hit this anomaly. Investigate and draft a \
                 MINIMAL fix as a diff proposal — do NOT apply it; leave it as a review \
                 proposal.\n\nKind: {:?}\nSummary: {}\nAgent/goal: {} / {}\nDetail:\n{}",
                anomaly.kind, anomaly.summary, anomaly.agent_id, anomaly.goal_id, anomaly.detail,
            );
            let input = CreateTaskInput {
                principal: anomaly.principal.clone(),
                workspace: anomaly.workspace.clone(),
                title: format!("[autofix] {}", anomaly.summary),
                description,
                agent_id: engineer.clone(),
                goal_id: Some(anomaly.goal_id.clone()),
                ui_thread_id: magician::magician_v2::artifact_v2::models::default_ui_thread_id(),
                priority: None,
                due_date: None,
                tags: Vec::new(),
                created_by: "system:harness:autofix".to_string(),
                depends_on: Vec::new(),
                approved: true,
                schedule: None,
                output_mode: magician::magician_v2::artifact_v2::models::TaskOutputMode::Accumulate,
                chat_session_id: None,
                lifecycle: magician::magician_v2::artifact_v2::models::TaskLifecycle::Internal,
                sync_mode: magician::magician_v2::artifact_v2::models::TaskSyncMode::default(),
            };
            match artifact_service.create_task(input).await {
                Ok(task) => {
                    let task_id = task.manifest.task_id.clone();
                    let scope = ScopeRef::system_internal_unauthenticated(
                        &anomaly.principal.clone(),
                        &anomaly.workspace.clone(),
                    );
                    match Arc::clone(&artifact_service)
                        .start_execution(scope.clone(), task_id.clone(), None, false)
                        .await
                    {
                        Ok((_started_task, execution)) => {
                            info!(
                                principal = %principal,
                                workspace = %workspace,
                                signature = %anomaly.signature,
                                agent_id = %engineer,
                                task_id = %task_id,
                                execution_id = %execution.state.execution_id,
                                "Harness autofix sweep dispatched and started a fix task"
                            );
                            if let Err(error) = store.mark(
                                &anomaly.principal,
                                &anomaly.workspace,
                                &anomaly.signature,
                                magician::magician_v2::harness::AnomalyStatus::FixDispatched,
                                Some(task_id),
                            ) {
                                warn!(
                                    principal = %principal,
                                    workspace = %workspace,
                                    signature = %anomaly.signature,
                                    error = %error,
                                    "Harness autofix sweep started a task but failed to mark the anomaly FixDispatched"
                                );
                            }
                        },
                        Err(error) => {
                            if let Err(status_error) = artifact_service
                                .update_task_status(&scope, &task_id, "failed")
                                .await
                            {
                                warn!(
                                    principal = %principal,
                                    workspace = %workspace,
                                    task_id = %task_id,
                                    error = %status_error,
                                    "Harness autofix sweep failed to mark unstarted fix task failed"
                                );
                            }
                            warn!(
                                principal = %principal,
                                workspace = %workspace,
                                signature = %anomaly.signature,
                                agent_id = %engineer,
                                task_id = %task_id,
                                error = %error,
                                "Harness autofix sweep created a fix task but failed to start it; anomaly remains open"
                            );
                        },
                    }
                },
                Err(error) => {
                    warn!(
                        principal = %principal,
                        workspace = %workspace,
                        signature = %anomaly.signature,
                        error = %error,
                        "Harness autofix sweep failed to create a fix task"
                    );
                },
            }
        }
    }
}

/// Build the dedicated background runtime that owns the agent sweep loops, so
/// they never run on the HTTP request runtime's worker threads.
fn build_agent_supervisor_runtime(
    worker_threads: usize,
) -> std::io::Result<tokio::runtime::Runtime> {
    tokio::runtime::Builder::new_multi_thread()
        // This runtime hosts the supervisor sweep loops AND the memory-index
        // maintainer. Width comes from the pre-bootstrap plan (`current` = 4).
        .worker_threads(worker_threads.max(1))
        .thread_name("magician-bg")
        .enable_all()
        .build()
}

/// Spawn startup-owned background loops for scheduler dispatch and approval expiry.
///
/// The loops run on a dedicated multi-thread tokio runtime (its own OS threads,
/// named `magician-bg`) rather than the HTTP request runtime, so a sweep can
/// never occupy request-handling threads. `background_worker_threads` comes
/// from the pre-bootstrap plan (`current` is 4).
///
/// The caller MUST keep the returned `Runtime` alive for the process lifetime,
/// cancel `shutdown`, await the returned task handles at shutdown, and then call
/// `shutdown_background()` on the returned `Runtime` (dropping a `Runtime` in an
/// async context panics, so it must not be dropped implicitly).
pub fn spawn_agent_supervisor_tasks(
    agent_api: AgentApiServices,
    v2_orchestrator: Arc<MagicianV2Orchestrator>,
    shutdown: CancellationToken,
    background_worker_threads: usize,
) -> (tokio::runtime::Runtime, Vec<(&'static str, JoinHandle<()>)>) {
    let runtime = build_agent_supervisor_runtime(background_worker_threads)
        .expect("failed to build agent supervisor runtime");

    let scheduler_agent_api = agent_api.clone();
    let scheduler_orchestrator = Arc::clone(&v2_orchestrator);
    let scheduler_shutdown = shutdown.child_token();
    let scheduler_loop = runtime.handle().spawn(async move {
        if !magician::magician_v2::runtime::startup::wait_for_http_or_cancel(&scheduler_shutdown).await { return; }
        let mut ticker = time::interval(AGENT_SCHEDULER_TICK_INTERVAL);
        ticker.set_missed_tick_behavior(MissedTickBehavior::Skip);
        loop {
            tokio::select! {
                _ = scheduler_shutdown.cancelled() => break,
                _ = ticker.tick() => run_scheduler_tick(&scheduler_agent_api, &scheduler_orchestrator).await,
            }
        }
        info!("Agent scheduler loop stopped");
    });

    let expiry_agent_api = agent_api.clone();
    let expiry_orchestrator = Arc::clone(&v2_orchestrator);
    let expiry_shutdown = shutdown.child_token();
    let approval_expiry_loop = runtime.handle().spawn(async move {
        if !magician::magician_v2::runtime::startup::wait_for_http_or_cancel(&expiry_shutdown).await { return; }
        let mut ticker = time::interval(APPROVAL_EXPIRY_SWEEP_INTERVAL);
        ticker.set_missed_tick_behavior(MissedTickBehavior::Skip);
        loop {
            tokio::select! {
                _ = expiry_shutdown.cancelled() => break,
                _ = ticker.tick() => run_approval_expiry_sweep(&expiry_agent_api, &expiry_orchestrator).await,
            }
        }
        info!("Approval expiry sweep loop stopped");
    });

    let consolidation_agent_api = agent_api;
    let wakeup_agent_api = consolidation_agent_api.clone();
    let task_sched_agent_api = wakeup_agent_api.clone();
    let steward_agent_api = wakeup_agent_api.clone();
    let autofix_agent_api = wakeup_agent_api.clone();
    let consolidation_orchestrator = Arc::clone(&v2_orchestrator);
    let consolidation_shutdown = shutdown.child_token();
    // 2026-05-23 — Drained-disabled tracker. Keyed by `agent_id`, value
    // is the UTC timestamp at which we observed the disabled agent's
    // last consolidation sweep produce zero updates. While the entry
    // is younger than DRAINED_REVISIT_INTERVAL we skip both batch
    // consolidation AND retention for that agent on subsequent ticks;
    // once it ages past that window the next tick re-evaluates (so a
    // late-arriving episode is eventually picked up). Cleared on the
    // tick where the agent shows as enabled again. In-memory only —
    // a process restart re-evaluates everyone from scratch on the
    // first sweep, which is desirable.
    let drained_disabled_agents: Arc<StdMutex<HashMap<String, DateTime<Utc>>>> =
        Arc::new(StdMutex::new(HashMap::new()));
    let drained_for_loop = Arc::clone(&drained_disabled_agents);
    let memory_consolidation_loop = runtime.handle().spawn(async move {
        if !magician::magician_v2::runtime::startup::wait_for_http_or_cancel(
            &consolidation_shutdown,
        )
        .await
        {
            return;
        }
        let mut ticker = time::interval(MEMORY_CONSOLIDATION_SWEEP_INTERVAL);
        ticker.set_missed_tick_behavior(MissedTickBehavior::Skip);
        loop {
            tokio::select! {
                _ = consolidation_shutdown.cancelled() => break,
                _ = ticker.tick() => run_memory_consolidation_sweep(
                    &consolidation_agent_api,
                    &consolidation_orchestrator,
                    &drained_for_loop,
                ).await,
            }
        }
        info!("Memory consolidation sweep loop stopped");
    });

    // WakeUpQueue watcher: drains due entries and re-triggers each agent goal via
    // resume_scheduler_agent.  Mirrors the logic in AgentRuntime::start_wake_up_watcher
    // but works with the AgentApiServices clone pattern used by all other loops here.
    let wakeup_orchestrator = Arc::clone(&v2_orchestrator);
    let wakeup_shutdown = shutdown.child_token();
    let wakeup_loop = runtime.handle().spawn(async move {
        if !magician::magician_v2::runtime::startup::wait_for_http_or_cancel(&wakeup_shutdown).await { return; }
        // Claimed wake handlers are children of this retained supervisor, not
        // detached background work. Shutdown must stop draining new rows and
        // join every in-flight child before the parent reports joined;
        // execution jobs launched by a child have their own process-wide
        // runtime-boundary registry.
        let mut wake_handlers = tokio::task::JoinSet::new();
        'wakeup: loop {
            // Compute how long to sleep until the next due entry (or 30s if queue empty).
            let wait_queue = wakeup_agent_api.runtime.wake_up_queue().cloned();
            let sleep_dur = match wait_queue.as_ref() {
                None => std::time::Duration::from_secs(30),
                Some(queue) => match queue.next_wake_at().await {
                    Some(wake_at) => {
                        let now = chrono::Utc::now();
                        if wake_at <= now {
                            std::time::Duration::ZERO
                        } else {
                            (wake_at - now)
                                .to_std()
                                .unwrap_or(std::time::Duration::from_secs(1))
                                // Notifications do not cross process boundaries.
                                // A rolling peer may publish an earlier durable
                                // row while this owner is sleeping on a cached
                                // far-future deadline, so reload at least every
                                // 30 seconds just like AgentRuntime's watcher.
                                .min(std::time::Duration::from_secs(30))
                        }
                    },
                    None => std::time::Duration::from_secs(30),
                },
            };
            tokio::select! {
                _ = wakeup_shutdown.cancelled() => break 'wakeup,
                _ = tokio::time::sleep(sleep_dur) => {},
                _ = async {
                    match wait_queue.as_ref() {
                        Some(queue) => queue.wait_for_change().await,
                        None => std::future::pending::<()>().await,
                    }
                } => continue,
                joined = wake_handlers.join_next(), if !wake_handlers.is_empty() => {
                    if let Some(Err(error)) = joined {
                        tracing::warn!(
                            %error,
                            "web_api wakeup loop: claimed wake handler exited with a join error"
                        );
                    }
                    continue;
                },
            }
            let Some(queue) = wakeup_agent_api.runtime.wake_up_queue() else {
                continue;
            };
            // Wait for one handler slot before leasing any row. Shutdown can
            // still stop the watcher while all slots are busy; no durable claim
            // has been issued at that point.
            let first_dispatch_permit = tokio::select! {
                _ = wakeup_shutdown.cancelled() => break 'wakeup,
                permit = queue.acquire_dispatch_permit() => permit,
            };
            let mut dispatch_permits = vec![first_dispatch_permit];
            dispatch_permits.extend(queue.reserve_dispatch_page_permits());
            let due = queue
                .drain_due_for_limit(
                    magician::magician_v2::agents::wake_up_queue::WakeConsumer::ProductionWeb,
                    dispatch_permits.len(),
                )
                .await;
            for (entry, dispatch_permit) in due.into_iter().zip(dispatch_permits) {
                let rt_clone = wakeup_agent_api.clone();
                let wakeup_orchestrator = Arc::clone(&wakeup_orchestrator);
                let wake_queue = Arc::clone(queue);
                let kind = entry.kind.clone();
                // The queue reserved this handler slot before durably leasing
                // the row, so a saturated earlier page cannot consume this
                // entry's claim lifetime before its handler is installed.

                // TaskRetry retains the legacy retry semantics. TaskSchedule
                // wakes are recovery hints only; new scheduled fires are
                // accepted durably and launched directly by the scheduler loop.
                if kind == WakeKind::TaskSchedule || kind == WakeKind::TaskRetry {
                    let task_id = entry.task_id.clone();
                    let claimed_until = entry.wake_at;
                    let claim_generation = entry.child_completed_generation.clone();
                    wake_handlers.spawn(async move {
                        let _dispatch_permit = dispatch_permit;
                        let launch_kind = kind.clone();
                        // Validate and extend the exact delivery before polling
                        // any handler work. Rescheduling retains a still-live
                        // immutable generation beside its successor; renewal
                        // can fail here only after cancellation, expiry, or
                        // authoritative loss of this exact lease.
                        let mut owned_until = match wake_queue
                            .renew_task_addressed_wake(
                                kind.clone(),
                                &task_id,
                                claimed_until,
                                claim_generation.as_deref(),
                            )
                            .await
                        {
                            Ok(Some(renewed_until)) => renewed_until,
                            Ok(None) => {
                                tracing::warn!(
                                    task_id = %task_id,
                                    "web_api wakeup loop: V3 task wake was superseded before dispatch"
                                );
                                return;
                            },
                            Err(error) => {
                                tracing::warn!(
                                    task_id = %task_id,
                                    %error,
                                    "web_api wakeup loop: V3 task wake pre-dispatch renewal failed closed"
                                );
                                return;
                            },
                        };
                        let launch = async {
                            if launch_kind == WakeKind::TaskRetry {
                                launch_v3_task_retry_wake(&rt_clone.runtime, &task_id).await
                            } else {
                                recover_v3_task_schedule_wake(&rt_clone.runtime, &task_id).await
                            }
                        };
                        tokio::pin!(launch);
                        let mut renewal = tokio::time::interval_at(
                            tokio::time::Instant::now() + std::time::Duration::from_secs(10),
                            std::time::Duration::from_secs(10),
                        );
                        let result = loop {
                            tokio::select! {
                                result = &mut launch => break result,
                                _ = renewal.tick() => {
                                    match wake_queue
                                        .renew_task_addressed_wake(
                                            kind.clone(),
                                            &task_id,
                                            owned_until,
                                            claim_generation.as_deref(),
                                        )
                                        .await
                                    {
                                        Ok(Some(renewed_until)) => owned_until = renewed_until,
                                        Ok(None) => {
                                            tracing::warn!(
                                                task_id = %task_id,
                                                "web_api wakeup loop: V3 task wake ownership changed; cancelling stale handler"
                                            );
                                            return;
                                        },
                                        Err(error) => {
                                            tracing::warn!(
                                                task_id = %task_id,
                                                %error,
                                                "web_api wakeup loop: V3 task wake renewal failed; cancelling handler fail-closed"
                                            );
                                            return;
                                        },
                                    }
                                },
                            }
                        };
                        match result {
                            Ok(()) => {
                                if let Err(error) = wake_queue
                                    .acknowledge_task_wake(
                                        kind,
                                        &task_id,
                                        owned_until,
                                        claim_generation.as_deref(),
                                    )
                                    .await
                                {
                                    tracing::warn!(
                                        task_id = %task_id,
                                        %error,
                                        "web_api wakeup loop: V3 task wake completed but durable acknowledgement failed"
                                    );
                                }
                            },
                            Err(error) => tracing::error!(
                                task_id = %task_id,
                                error = %error,
                                "web_api wakeup loop: V3 task wake launch failed; durable claim retained"
                            ),
                        }
                    });
                    continue;
                }

                // Spawn a separate task per entry so a slow agent does not block others.
                let task_id = entry.task_id.clone();
                let principal = entry.principal.clone();
                let workspace = entry.workspace.clone();
                let execution_id = entry.execution_id.clone();
                let stateless_source_segment = entry.stateless_source_segment.clone();
                let execution_retry_due_at = entry.execution_retry_due_at.clone();
                let child_completed_generation = entry.child_completed_generation.clone();
                let claimed_until = entry.wake_at;
                let execution_retry_started = entry.execution_retry_started;
                let projection_grace_elapsed = entry.execution_retry_claim_attempt > 1;
                wake_handlers.spawn(async move {
                    let _dispatch_permit = dispatch_permit;
                    match kind {
                        // Harness scheduled wakes re-enter the admitted web dispatcher;
                        // standard scheduled wakes retain the SchedulerAgent path.
                        WakeKind::Scheduled => {
                            // Revalidate the immutable delivery generation
                            // immediately before the scheduler future can run.
                            // A later reschedule preserves this in-flight
                            // generation and publishes its successor beside it.
                            let mut owned_until = match wake_queue
                                .renew_task_addressed_wake(
                                    WakeKind::Scheduled,
                                    &task_id,
                                    claimed_until,
                                    child_completed_generation.as_deref(),
                                )
                                .await
                            {
                                Ok(Some(renewed_until)) => renewed_until,
                                Ok(None) => {
                                    tracing::warn!(
                                        task_id = %task_id,
                                        "web_api wakeup loop: scheduled wake was superseded before dispatch"
                                    );
                                    return;
                                },
                                Err(error) => {
                                    tracing::warn!(
                                        task_id = %task_id,
                                        %error,
                                        "web_api wakeup loop: scheduled wake pre-dispatch renewal failed closed"
                                    );
                                    return;
                                },
                            };
                            let dispatch = async {
                                let handled_by_harness = dispatch_harness_scheduled_wake(
                                    &rt_clone,
                                    &wakeup_orchestrator,
                                    &task_id,
                                )
                                .await;
                                if !handled_by_harness {
                                    rt_clone.runtime.resume_scheduler_entry(&task_id).await;
                                }
                            };
                            tokio::pin!(dispatch);
                            let mut renewal = tokio::time::interval_at(
                                tokio::time::Instant::now() + std::time::Duration::from_secs(10),
                                std::time::Duration::from_secs(10),
                            );
                            loop {
                                tokio::select! {
                                    _ = &mut dispatch => break,
                                    _ = renewal.tick() => {
                                        match wake_queue
                                            .renew_task_addressed_wake(
                                                WakeKind::Scheduled,
                                                &task_id,
                                                owned_until,
                                                child_completed_generation.as_deref(),
                                            )
                                            .await
                                        {
                                            Ok(Some(renewed_until)) => owned_until = renewed_until,
                                            Ok(None) => {
                                                tracing::warn!(
                                                    task_id = %task_id,
                                                    "web_api wakeup loop: scheduled wake ownership changed; cancelling stale handler"
                                                );
                                                return;
                                            },
                                            Err(error) => {
                                                tracing::warn!(
                                                    task_id = %task_id,
                                                    %error,
                                                    "web_api wakeup loop: scheduled wake renewal failed; cancelling handler fail-closed"
                                                );
                                                return;
                                            },
                                        }
                                    },
                                }
                            }
                            if let Err(error) = wake_queue
                                .acknowledge_scheduled_wake(
                                    &task_id,
                                    owned_until,
                                    child_completed_generation.as_deref(),
                                )
                                .await
                            {
                                tracing::warn!(
                                    task_id = %task_id,
                                    %error,
                                    "web_api wakeup loop: scheduled wake completed but durable acknowledgement failed"
                                );
                            }
                        },
                        WakeKind::ExecutionRetry => {
                            let Some(execution_id) = execution_id else {
                                tracing::error!(
                                    task_id = %task_id,
                                    "web_api wakeup loop: ExecutionRetry wake missing execution_id; durable claim retained"
                                );
                                return;
                            };
                            if task_id.trim().is_empty() {
                                tracing::error!(
                                    execution_id = %execution_id,
                                    "web_api wakeup loop: ExecutionRetry wake missing task_id; durable claim retained"
                                );
                                return;
                            }
                            let (Some(principal), Some(workspace)) = (principal, workspace) else {
                                tracing::error!(
                                    task_id = %task_id,
                                    execution_id = %execution_id,
                                    "web_api wakeup loop: legacy ExecutionRetry lacks canonical scope; durable claim retained fail-closed"
                                );
                                return;
                            };
                            let _claim_guard = match wake_queue
                                .lock_execution_retry_claim(
                                    &principal,
                                    &workspace,
                                    &task_id,
                                    &execution_id,
                                )
                                .await
                            {
                                Ok(guard) => guard,
                                Err(error) => {
                                    tracing::warn!(
                                        task_id = %task_id,
                                        execution_id = %execution_id,
                                        %error,
                                        "web_api wakeup loop: exact retry claim lock unavailable; durable claim retained"
                                    );
                                    return;
                                },
                            };
                            if !wake_queue
                                .execution_retry_claim_is_current(
                                    &principal,
                                    &workspace,
                                    &task_id,
                                    &execution_id,
                                    claimed_until,
                                    execution_retry_due_at.clone(),
                                    stateless_source_segment.as_deref(),
                                )
                                .await
                            {
                                // Another delivery renewed the lease, or the
                                // resumed execution published a later Sleeping
                                // generation. This stale handler owns neither.
                                return;
                            }
                            // The Artifact retry owner later takes this same
                            // non-reentrant generation lock around its exact
                            // Sleeping -> Executing CAS and revalidates the
                            // queue row there. Retaining the dispatcher's
                            // preliminary guard across that call would make
                            // every exact retry wait on itself forever.
                            drop(_claim_guard);
                            let Some(service) = rt_clone.runtime.artifact_v2_service() else {
                                tracing::warn!(
                                    task_id = %task_id,
                                    execution_id = %execution_id,
                                    "web_api wakeup loop: Artifact V2 service unavailable; durable ExecutionRetry claim retained"
                                );
                                return;
                            };
                            match service
                                .retry_exact_sleeping_execution(
                                    &principal,
                                    &workspace,
                                    &task_id,
                                    &execution_id,
                                    stateless_source_segment.as_deref(),
                                    execution_retry_due_at.clone(),
                                    claimed_until,
                                    execution_retry_started,
                                    projection_grace_elapsed,
                                )
                                .await
                            {
                                Ok(magician::magician_v2::artifact_v2::ExecutionRetryDisposition::Settled) => {
                                    if let Err(error) = wake_queue
                                        .acknowledge_execution_retry_wake(
                                            &principal,
                                            &workspace,
                                            &task_id,
                                            &execution_id,
                                            claimed_until,
                                            execution_retry_due_at,
                                            stateless_source_segment.as_deref(),
                                        )
                                        .await
                                    {
                                        tracing::warn!(
                                            task_id = %task_id,
                                            execution_id = %execution_id,
                                            %error,
                                            "web_api wakeup loop: exact retry ran but durable wake acknowledgement failed"
                                        );
                                    }
                                },
                                Ok(magician::magician_v2::artifact_v2::ExecutionRetryDisposition::Running) => {
                                    // The started queue row is the durable
                                    // cross-process admission record. Retain it
                                    // until terminal settlement or an exact-
                                    // generation replacement; a merely-running
                                    // owner is not a safe acknowledgement point.
                                },
                                Ok(magician::magician_v2::artifact_v2::ExecutionRetryDisposition::Started) => {
                                    match wake_queue
                                        .mark_execution_retry_started(
                                            &principal,
                                            &workspace,
                                            &task_id,
                                            &execution_id,
                                            claimed_until,
                                            execution_retry_due_at.clone(),
                                            stateless_source_segment.as_deref(),
                                        )
                                        .await
                                    {
                                        Ok(true) => {},
                                        Ok(false) => {
                                            if let Err(error) = wake_queue
                                                .mark_current_execution_retry_started(
                                                    &principal,
                                                    &workspace,
                                                    &task_id,
                                                    &execution_id,
                                                    execution_retry_due_at,
                                                    stateless_source_segment.as_deref(),
                                                )
                                                .await
                                            {
                                                tracing::warn!(
                                                    task_id = %task_id,
                                                    execution_id = %execution_id,
                                                    %error,
                                                    "web_api wakeup loop: failed to transfer exact-retry adoption to renewed claim"
                                                );
                                            }
                                        },
                                        Err(error) => tracing::warn!(
                                            task_id = %task_id,
                                            execution_id = %execution_id,
                                            %error,
                                            "web_api wakeup loop: exact retry started but durable adoption marker failed"
                                        ),
                                    }
                                },
                                Ok(magician::magician_v2::artifact_v2::ExecutionRetryDisposition::PendingProjection) => {
                                    // The leased row remains durable. A later
                                    // delivery acknowledges only after runtime
                                    // ownership or settlement is observable.
                                },
                                Err(error) => tracing::warn!(
                                    task_id = %task_id,
                                    execution_id = %execution_id,
                                    %error,
                                    "web_api wakeup loop: exact retry deferred; durable claim retained"
                                ),
                            }
                        },
                        WakeKind::ChildCompleted => {
                            let Some(execution_id) = execution_id else {
                                tracing::warn!(
                                    "web_api wakeup loop: ChildCompleted wake missing execution_id"
                                );
                                return;
                            };
                            match wakeup_orchestrator
                                .reconcile_waiting_children_and_continue(&execution_id)
                                .await
                            {
                                Ok(_) => {
                                    if let Err(error) = wake_queue
                                        .acknowledge_child_completed_wake(
                                            &execution_id,
                                            claimed_until,
                                            child_completed_generation.as_deref(),
                                        )
                                        .await
                                    {
                                        tracing::warn!(
                                            execution_id = %execution_id,
                                            %error,
                                            "web_api wakeup loop: child reconciliation completed but durable acknowledgement failed"
                                        );
                                    }
                                },
                                Err(error) => tracing::warn!(
                                    execution_id = %execution_id,
                                    error = %error,
                                    "web_api wakeup loop: failed to reconcile waiting children; durable ChildCompleted claim retained"
                                ),
                            }
                        },
                        WakeKind::TaskSchedule | WakeKind::TaskRetry => {
                            // Already handled above; unreachable due to the `continue`.
                            unreachable!("TaskSchedule/TaskRetry dispatched above");
                        },
                    }
                });
            }
        }
        while let Some(joined) = wake_handlers.join_next().await {
            if let Err(error) = joined {
                if !error.is_cancelled() {
                    tracing::warn!(
                        %error,
                        "web_api wakeup loop: claimed wake handler failed during shutdown drain"
                    );
                }
            }
        }
        info!("WakeUpQueue watcher loop stopped");
    });

    // Task-level cron/one-time scheduler: ticks TaskSchedulerService and
    // enqueues due tasks onto the WakeUpQueue so the wakeup_loop above
    // dispatches them.
    let task_sched_shutdown = shutdown.child_token();
    let task_scheduler_loop = runtime.handle().spawn(async move {
        if !magician::magician_v2::runtime::startup::wait_for_http_or_cancel(&task_sched_shutdown).await { return; }
        use magician::magician_v2::storage::task_scheduler::TaskSchedulerService;

        let artifact_v2_service = {
            let mut warned_waiting = false;
            loop {
                if let Some(service) = task_sched_agent_api.runtime.artifact_v2_service() {
                    break service;
                }

                if !warned_waiting {
                    info!("Task scheduler: waiting for artifact_v2_service startup wiring");
                    warned_waiting = true;
                }

                tokio::select! {
                    _ = task_sched_shutdown.cancelled() => {
                        info!("Task scheduler loop stopped before artifact_v2_service wiring");
                        return;
                    }
                    _ = tokio::time::sleep(std::time::Duration::from_secs(1)) => {}
                }
            }
        };

        let svc = TaskSchedulerService::new();
        let mut known_task_ids = HashSet::<String>::new();

        // Initial hydration: load all scheduled tasks from the V3 task store.
        match sync_v3_task_scheduler_registrations(&svc, &mut known_task_ids, &artifact_v2_service)
            .await
        {
            Ok(count) => {
                info!(count, "Task scheduler: initial V3 hydration complete");
            },
            Err(error) => {
                warn!(error = %error, "Task scheduler: failed initial V3 hydration");
            },
        }

        let mut ticker = time::interval(TASK_SCHEDULER_TICK_INTERVAL);
        ticker.set_missed_tick_behavior(MissedTickBehavior::Skip);
        loop {
            tokio::select! {
                _ = task_sched_shutdown.cancelled() => break,
                _ = ticker.tick() => {
                    // Reconcile every tick. Unchanged registrations retain their
                    // current occurrence, while new reminders are discovered
                    // within one bounded scheduler interval.
                    if let Err(error) = sync_v3_task_scheduler_registrations(
                        &svc,
                        &mut known_task_ids,
                        &artifact_v2_service,
                    )
                    .await
                    {
                        warn!(error = %error, "Task scheduler: V3 re-hydration failed");
                    }

                    let now = chrono::Utc::now();
                    let due_fires = svc.tick(now);
                    if due_fires.is_empty() {
                        continue;
                    }

                    for fire in due_fires {
                            let task_id = fire.task_id.as_str();
                            match load_v3_scheduled_task(artifact_v2_service.as_ref(), task_id).await {
                                Ok(Some((scope, task))) => {
                                    // TaskSchedule only executes Ready tasks.
                                    // Paused/deferred are retry states and retain
                                    // their separate TaskRetry behavior.
                                    if !v3_task_schedule_status_can_execute(&task.state.status) {
                                        continue;
                                    }
                                    let max_runs = magician::magician_v2::artifact_v2::service::task_schedule_max_runs(
                                        task.manifest.schedule.as_ref(),
                                    );
                                    if let Some(max) = max_runs {
                                        if task.state.schedule_fire_count >= max {
                                            svc.unregister_task(task_id);
                                            known_task_ids.remove(task_id);
                                            continue;
                                        }
                                    }
                                    match v3_task_dependencies_blocked(
                                        artifact_v2_service.as_ref(),
                                        &scope,
                                        &task,
                                    )
                                    .await
                                    {
                                        Ok(true) => continue,
                                        Ok(false) => {},
                                        Err(error) => {
                                            warn!(
                                                task_id = %task_id,
                                                error = %error,
                                                "Task scheduler: failed to evaluate V3 task dependencies; skipping"
                                            );
                                            continue;
                                        },
                                    }
                                    let acceptance = match artifact_v2_service
                                        .accept_scheduled_execution(&scope, task_id, fire.scheduled_at)
                                        .await
                                    {
                                        Ok(Some(acceptance)) => acceptance,
                                        Ok(None) => continue,
                                        Err(error) => {
                                            warn!(
                                                task_id = %task_id,
                                                error = %error,
                                                "Task scheduler: durable fire acceptance failed"
                                            );
                                            continue;
                                        },
                                    };
                                    svc.acknowledge_fire(task_id, fire.scheduled_at, now);
                                    if let Some(max) = max_runs {
                                        if acceptance.fire_count >= max {
                                            svc.unregister_task(task_id);
                                            known_task_ids.remove(task_id);
                                        }
                                    }
                                    if let Err(error) = artifact_v2_service
                                        .launch_accepted_scheduled_execution(
                                            &scope,
                                            task_id,
                                            &acceptance.execution_id,
                                        )
                                        .await
                                    {
                                        warn!(
                                            task_id = %task_id,
                                            execution_id = %acceptance.execution_id,
                                            error = %error,
                                            "Task scheduler: accepted launch failed; reconciliation will retry"
                                        );
                                    }
                                    debug!(
                                        task_id = %task_id,
                                        principal = %scope.principal(),
                                        workspace = %scope.workspace(),
                                        execution_id = %acceptance.execution_id,
                                        fire_count = acceptance.fire_count,
                                        max_runs = ?max_runs,
                                        "Task scheduler: durably accepted due V3 task"
                                    );
                                },
                                Ok(None) => {},
                                Err(error) => {
                                    warn!(
                                        task_id = %task_id,
                                        error = %error,
                                        "Task scheduler: failed to load due V3 task; skipping"
                                    );
                                },
                            }
                    }
                }
            }
        }
        info!("Task scheduler loop stopped");
    });

    // Phase 4.2 — low-frequency harness steward / growth-eval drain. Drafts (never
    // applies) skill/capability proposals + runs growth-eval per scope every 6h.
    // Gated by `MAGICIAN_HARNESS_STEWARD_TICK` (default ON).
    let steward_shutdown = shutdown.child_token();
    let harness_steward_loop = runtime.handle().spawn(async move {
        if !magician::magician_v2::runtime::startup::wait_for_http_or_cancel(&steward_shutdown)
            .await
        {
            return;
        }
        let mut ticker = time::interval(HARNESS_STEWARD_TICK_INTERVAL);
        ticker.set_missed_tick_behavior(MissedTickBehavior::Skip);
        // The first immediate tick fires at startup; skip it so the drain runs on
        // the cadence rather than racing process boot / scope hydration.
        ticker.tick().await;
        loop {
            tokio::select! {
                _ = steward_shutdown.cancelled() => break,
                _ = ticker.tick() => run_harness_steward_tick(&steward_agent_api).await,
            }
        }
        info!("Harness steward tick loop stopped");
    });

    // CTO detect-and-fix loop — autofix sweep. Reads the anomaly queue and
    // dispatches a MINIMAL-fix coding task (drafted as a review proposal, never
    // applied) for the top open + uncooled anomaly per scope, rate-limited to one
    // per sweep with a per-anomaly cooldown. Default ON (opt-out): gated by the
    // typed config field `harness.autofix_enabled`, with `MAGICIAN_HARNESS_AUTOFIX`
    // as an env override (both checked inside `run_harness_autofix_tick`).
    let autofix_shutdown = shutdown.child_token();
    let harness_autofix_loop = runtime.handle().spawn(async move {
        if !magician::magician_v2::runtime::startup::wait_for_http_or_cancel(&autofix_shutdown)
            .await
        {
            return;
        }
        let mut ticker = time::interval(StdDuration::from_secs(
            magician::magician_v2::harness::autofix::AUTOFIX_TICK_INTERVAL_SECS,
        ));
        ticker.set_missed_tick_behavior(MissedTickBehavior::Skip);
        // The first immediate tick fires at startup; skip it so the sweep runs on
        // the cadence rather than racing process boot / scope hydration.
        ticker.tick().await;
        loop {
            tokio::select! {
                _ = autofix_shutdown.cancelled() => break,
                _ = ticker.tick() => run_harness_autofix_tick(&autofix_agent_api).await,
            }
        }
        info!("Harness autofix sweep loop stopped");
    });

    let tasks = vec![
        ("agent_scheduler_loop", scheduler_loop),
        ("approval_expiry_loop", approval_expiry_loop),
        ("memory_consolidation_loop", memory_consolidation_loop),
        ("wakeup_queue_loop", wakeup_loop),
        ("task_scheduler_loop", task_scheduler_loop),
        ("harness_steward_loop", harness_steward_loop),
        ("harness_autofix_loop", harness_autofix_loop),
    ];

    (runtime, tasks)
}

async fn invalidate_agent_list_cache(agent_api: &AgentApiServices) {
    *agent_api.list_cache.write().await = None;
}

fn normalized_agent_list_pagination(
    query: Option<&ListAgentDefinitionsQuery>,
) -> Result<(usize, Option<usize>), HttpResponse> {
    // Crew surface seam (plan 3.5): the policy lives in
    // `crew_surface::projection::validate_agent_list_pagination`; this wrapper
    // keeps only the HTTP 400 envelope mapping.
    validate_agent_list_pagination(query).map_err(|invalid| {
        api_error_response(
            StatusCode::BAD_REQUEST,
            "invalid_pagination_limit",
            "Invalid pagination limit",
            Some(serde_json::json!({
                "max_limit": invalid.max_limit,
            })),
        )
    })
}

fn normalized_episode_pagination(
    query: &AgentEpisodesQuery,
) -> Result<(usize, usize), HttpResponse> {
    let offset = query.offset.unwrap_or(0);
    let limit = query.limit.unwrap_or(AGENT_EPISODES_LIMIT_DEFAULT);
    if limit == 0 || limit > AGENT_EPISODES_LIMIT_MAX {
        return Err(api_error_response(
            StatusCode::BAD_REQUEST,
            "invalid_pagination_limit",
            "Invalid pagination limit",
            Some(serde_json::json!({
                "max_limit": AGENT_EPISODES_LIMIT_MAX,
                "default_limit": AGENT_EPISODES_LIMIT_DEFAULT,
            })),
        ));
    }
    Ok((offset, limit))
}

async fn clear_local_agent_runtime_state(
    agent_api: &AgentApiServices,
    principal: &str,
    workspace: &str,
    agent_id: &str,
) -> Result<(), SchedulerError> {
    let _ = clear_pending_dispatches_for_agent(agent_api, principal, workspace, agent_id).await;
    agent_api
        .runtime
        .remove_definition_in_scope(principal, workspace, agent_id)
        .await;
    let paused_agents = agent_api.resolve_paused_agents(principal, workspace).await;
    let was_paused = paused_agents.write().await.remove(agent_id);
    if was_paused {
        persist_paused_agents_state(agent_api, principal, workspace)
            .await
            .map_err(|err| SchedulerError::Storage {
                operation: "persist_paused_agents_state",
                details: err.to_string(),
            })?;
    }
    Ok(())
}

async fn clear_local_agent_state(
    agent_api: &AgentApiServices,
    principal: &str,
    workspace: &str,
    agent_id: &str,
) -> Result<(), SchedulerError> {
    agent_api
        .resolve_scheduler(principal, workspace)
        .await?
        .unregister_agent(agent_id)
        .await?;
    clear_local_agent_runtime_state(agent_api, principal, workspace, agent_id).await
}

fn emit_agent_event(
    v2_orchestrator: &Arc<MagicianV2Orchestrator>,
    principal: Option<&str>,
    workspace: Option<&str>,
    event_type: &str,
    agent_id: &str,
    payload: serde_json::Value,
) {
    let Some(broadcaster) = v2_orchestrator.event_broadcaster() else {
        return;
    };
    let event = match (principal, workspace) {
        (Some(principal), Some(workspace)) => {
            magician::magician_v2::realtime_events::AgentEventEnvelope::new_scoped(
                event_type, agent_id, principal, workspace, payload,
            )
        },
        _ => magician::magician_v2::realtime_events::AgentEventEnvelope::new(
            event_type, agent_id, payload,
        ),
    };
    broadcaster.emit_agent_transport_event(event);
}

fn emit_agent_definition_changed(
    v2_orchestrator: &Arc<MagicianV2Orchestrator>,
    principal: &str,
    workspace: &str,
    agent_id: &str,
) {
    let Some(broadcaster) = v2_orchestrator.event_broadcaster() else {
        return;
    };
    broadcaster.emit_transport_only(
        magician::magician_v2::realtime_events::RuntimeTransportEvent::AgentDefinitionChanged {
            principal: principal.to_string(),
            workspace: workspace.to_string(),
            agent_id: agent_id.to_string(),
            timestamp: Utc::now().timestamp_millis(),
        },
    );
}

fn bounded_approval_action_descriptions<'a>(
    descriptions: impl IntoIterator<Item = &'a str>,
) -> Vec<String> {
    descriptions
        .into_iter()
        .map(|description| description.chars().take(300).collect::<String>())
        .filter(|description| !description.trim().is_empty())
        .take(5)
        .collect()
}

// `approval_decision_event_value` removed in H6.4 along with the legacy
// `emit_agent_event("approval.resolved", ...)` call that consumed it.
// The canonical `HitlResolved.decision` field uses lowercase verbs
// (`"approve"` / `"reject"`) and that mapping lives inline in
// `emit_approval_resolved_event` below.

fn emit_approval_requested_event(
    v2_orchestrator: &Arc<MagicianV2Orchestrator>,
    principal: Option<&str>,
    workspace: Option<&str>,
    request: &ApprovalRequest,
    source: &str,
) {
    // Phase H6.4 — legacy `emit_agent_event("approval.requested", ...)`
    // path retired. The canonical `RuntimeTransportEvent::HitlRequested`
    // emit below covers every downstream consumer:
    //   - `feed/materializer.rs` reads canonical (H5.1)
    //   - `approvalStore.handleCanonicalHitlApprovalEvent` (H5.3)
    //   - `publish_agent_update` is an independent emit (H5.2 audit)
    //
    // Known impact: the progress-channels chat surface
    // (`progress_channels/channels/chat.rs`) used to render an
    // "Approval requested before the agent can continue." line
    // inline in chat when the legacy event_type passed through
    // `normalize.rs`. Operators still see the AttentionBar badge
    // climb and the `/approvals` page is fully functional. The
    // inline-chat approval notification is a known regression of
    // this drop; H6.4 follow-up can route chat-surface approval
    // notifications off the canonical envelope if it turns out to be
    // user-visibly missed.
    let _ = source; // kept to avoid signature churn — used by callers' tracing
                    // Parallel emission for the operator feed. Tool/action are not available
                    // at this call site (the legacy payload carries only approval metadata);
                    // emit pending_action_count so the card still has something to show.
    if let Some(broadcaster) = v2_orchestrator.event_broadcaster() {
        let action_descriptions = bounded_approval_action_descriptions(
            request
                .pending_actions
                .iter()
                .map(|action| action.action_description.as_str()),
        );
        let approval_summary = format!(
            "Approval required for {} pending action{}",
            request.pending_actions.len(),
            if request.pending_actions.len() == 1 {
                ""
            } else {
                "s"
            }
        );
        let approval_prompt = if action_descriptions.is_empty() {
            approval_summary
        } else {
            format!(
                "{approval_summary}\n\nPending actions:\n- {}",
                action_descriptions.join("\n- ")
            )
        };
        let mut update = magician::magician_v2::agents::agent_update::AgentUpdate::new(
            workspace.unwrap_or_default().to_string(),
            request.agent_id.clone(),
            magician::magician_v2::agents::agent_update::AgentUpdateKind::ApprovalRequested {
                approval_id: request.approval_id.clone(),
                tool: None,
                action: None,
                params: None,
                pending_action_count: Some(request.pending_actions.len() as u32),
            },
        );
        if !request.cycle_id.is_empty() {
            update = update.with_cycle(request.cycle_id.clone());
        }
        magician::magician_v2::agents::agent_update_emitter::publish_agent_update(
            &broadcaster,
            principal,
            workspace,
            update,
        );
        // Phase H4.6 — canonical HITL dual-emit. Approvals carry their
        // own correlation_id (`approval_id`); the canonical respond
        // endpoint dispatches `source: "approval"` to
        // `MagicianV2Api::resolve_approval()` which the existing
        // `/api/v2/approvals/{id}/resolve` endpoint also calls.
        //
        // Phase H5.3 — `input_schema` now carries the approval-specific
        // ride-along fields (`goal_id`, `cycle_id`, `trigger_seq`,
        // `pending_action_count`, `expires_at`, `source`) that the
        // frontend `approvalStore` needs to render its rows. Before
        // this extension, those fields lived only on the legacy
        // `approval.requested` AgentEvent payload, forcing the store to
        // dual-read. With the extension the canonical envelope is
        // sufficient and H6.4 can drop the legacy emit cleanly.
        broadcaster.emit_transport_only(
            magician::magician_v2::realtime_events::RuntimeTransportEvent::HitlRequested {
                correlation_id: request.approval_id.clone(),
                source: "approval".to_string(),
                input_type: "confirmation".to_string(),
                prompt: approval_prompt,
                hint: None,
                input_schema: Some(serde_json::json!({
                    "approval_id": request.approval_id,
                    "confirm_label": "Approve",
                    "deny_label": "Reject",
                    "goal_id": request.goal_id,
                    "cycle_id": request.cycle_id,
                    "trigger_seq": request.trigger_seq,
                    "pending_action_count": request.pending_actions.len(),
                    "pending_action_descriptions": action_descriptions,
                    "expires_at": request.expires_at.to_rfc3339(),
                    "source": source,
                })),
                task_id: None,
                execution_id: request.execution_id.clone(),
                agent_id: Some(request.agent_id.clone()),
                principal: principal.map(|s| s.to_string()),
                workspace: workspace.map(|s| s.to_string()),
                timestamp: chrono::Utc::now().timestamp_millis(),
            },
        );
    }
}

fn emit_approval_resolved_event(
    v2_orchestrator: &Arc<MagicianV2Orchestrator>,
    principal: Option<&str>,
    workspace: Option<&str>,
    request: &ApprovalRequest,
    decision: &ApprovalDecision,
    resolved_by: &str,
    source: &str,
) {
    // Phase H6.4 — legacy `emit_agent_event("approval.resolved", ...)`
    // path retired. Canonical `HitlResolved` emit below covers
    // approval-store + feed-materializer + agent-update-journal.
    let _ = source;
    if let Some(broadcaster) = v2_orchestrator.event_broadcaster() {
        // Announce the resolution to the approval's ORIGINATING scope (the
        // execution's principal/workspace captured at create time), falling back
        // to the resolver's scope only for legacy approvals that predate the
        // stored scope. This keeps a cross-surface resolve visible to whichever
        // surface received the original `HitlRequested` (e.g. the anonymous/default
        // desktop overlay), so its card clears and the tray badge decrements even
        // when the resolve arrives from a different (e.g. logged-in web) scope.
        let event_principal = request.principal.as_deref().or(principal);
        let event_workspace = request.workspace.as_deref().or(workspace);
        let mut update = magician::magician_v2::agents::agent_update::AgentUpdate::new(
            event_workspace.unwrap_or_default().to_string(),
            request.agent_id.clone(),
            magician::magician_v2::agents::agent_update::AgentUpdateKind::ApprovalResolved {
                approval_id: request.approval_id.clone(),
                decision: decision.clone(),
                resolver: resolved_by.to_string(),
            },
        );
        if !request.cycle_id.is_empty() {
            update = update.with_cycle(request.cycle_id.clone());
        }
        magician::magician_v2::agents::agent_update_emitter::publish_agent_update(
            &broadcaster,
            event_principal,
            event_workspace,
            update,
        );
        // Phase H4.6 — canonical HITL dual-emit (resolution).
        let decision_label = match decision {
            magician::magician_v2::agents::approval_service::ApprovalDecision::Approve => "approve",
            magician::magician_v2::agents::approval_service::ApprovalDecision::Reject => "reject",
        };
        broadcaster.emit_transport_only(
            magician::magician_v2::realtime_events::RuntimeTransportEvent::HitlResolved {
                correlation_id: request.approval_id.clone(),
                source: "approval".to_string(),
                outcome: "responded".to_string(),
                decision: Some(decision_label.to_string()),
                task_id: None,
                execution_id: request.execution_id.clone(),
                agent_id: Some(request.agent_id.clone()),
                principal: event_principal.map(|s| s.to_string()),
                workspace: event_workspace.map(|s| s.to_string()),
                timestamp: chrono::Utc::now().timestamp_millis(),
            },
        );
    }
}

/// Acknowledge a synthetic debug/test HITL resolution.
///
/// Debug events minted by `POST /v3/events/debug-emit` carry a `debug-`
/// correlation id (see [`crate::events_api::is_debug_hitl_correlation`])
/// and have NO backing pause or approval record, so the normal resolve arms
/// would 404 and leave the card stuck. Instead we resolve them as a pure
/// acknowledgement: broadcast a canonical `HitlResolved` (keyed on the same
/// correlation id) so every connected surface — the web attention feed and the
/// desktop overlay — drops the card in sync, then return 200. No store is
/// touched and no execution is resumed. Scoped strictly to the `debug-` prefix,
/// so a real approval/pause that is genuinely missing still returns its 404 (we
/// don't mask scope-drift or lost-record bugs).
fn ack_debug_hitl_resolution(
    v2_orchestrator: &Arc<MagicianV2Orchestrator>,
    request: &HttpRequest,
    correlation_id: &str,
    body: &RespondHitlRequest,
) -> HttpResponse {
    // Scope the HitlResolved to the resolve request's middleware-verified identity so it
    // reaches the same overlay subscribers that see the debug card. Resolve
    // requests always carry a workspace-bound bearer, so the `Err` arm is a
    // defensive fallback only: an unscoped clear reaches just `system/system`
    // subscribers (fail-closed), never a real overlay — but that path isn't
    // taken in practice.
    let (principal, workspace) = match resolve_required_scope_from_request(request) {
        Ok((p, w)) => (Some(p), Some(w)),
        Err(_) => (None, None),
    };
    let source = {
        let trimmed = body.source.trim();
        if trimmed.is_empty() {
            "approval".to_string()
        } else {
            trimmed.to_string()
        }
    };
    if let Some(broadcaster) = v2_orchestrator.event_broadcaster() {
        broadcaster.emit_transport_only(
            magician::magician_v2::realtime_events::RuntimeTransportEvent::HitlResolved {
                correlation_id: correlation_id.to_string(),
                source,
                outcome: "responded".to_string(),
                decision: Some(agentic_value_decision_label(&body.value)),
                task_id: None,
                execution_id: None,
                agent_id: None,
                principal,
                workspace,
                timestamp: chrono::Utc::now().timestamp_millis(),
            },
        );
    }
    tracing::info!(
        correlation_id = %correlation_id,
        source = %body.source,
        "Pure-acked a synthetic debug HITL resolution (no backing record); broadcast HitlResolved to clear all surfaces"
    );
    HttpResponse::Ok().json(serde_json::json!({
        "resolved": true,
        "debug": true,
        "correlation_id": correlation_id,
    }))
}

fn emit_approval_expired_event(
    v2_orchestrator: &Arc<MagicianV2Orchestrator>,
    principal: Option<&str>,
    workspace: Option<&str>,
    request: &ApprovalRequest,
    source: &str,
) {
    // Phase H6.4 — legacy `emit_agent_event("approval.expired", ...)`
    // path retired. Canonical `HitlResolved { outcome: "expired", ... }`
    // emit below covers downstream consumers.
    let _ = source;
    if let Some(broadcaster) = v2_orchestrator.event_broadcaster() {
        // Announce the expiry to the approval's ORIGINATING scope (captured at
        // create time), falling back to the caller's scope only for legacy
        // approvals that predate the stored scope. Mirrors the resolve path
        // (`emit_approval_resolved_event`): a cross-surface expiry — e.g. the
        // background sweep or a list/get call running under a different scope
        // than the one that received the original `HitlRequested` — must still
        // clear the originating overlay's card and decrement its tray badge.
        let event_principal = request.principal.as_deref().or(principal);
        let event_workspace = request.workspace.as_deref().or(workspace);
        let mut update = magician::magician_v2::agents::agent_update::AgentUpdate::new(
            event_workspace.unwrap_or_default().to_string(),
            request.agent_id.clone(),
            magician::magician_v2::agents::agent_update::AgentUpdateKind::ApprovalExpired {
                approval_id: request.approval_id.clone(),
            },
        );
        if !request.cycle_id.is_empty() {
            update = update.with_cycle(request.cycle_id.clone());
        }
        magician::magician_v2::agents::agent_update_emitter::publish_agent_update(
            &broadcaster,
            event_principal,
            event_workspace,
            update,
        );
        // Phase H4.6 — canonical HITL dual-emit for approval expiration.
        broadcaster.emit_transport_only(
            magician::magician_v2::realtime_events::RuntimeTransportEvent::HitlResolved {
                correlation_id: request.approval_id.clone(),
                source: "approval".to_string(),
                outcome: "expired".to_string(),
                decision: None,
                task_id: None,
                execution_id: request.execution_id.clone(),
                agent_id: Some(request.agent_id.clone()),
                principal: event_principal.map(|s| s.to_string()),
                workspace: event_workspace.map(|s| s.to_string()),
                timestamp: chrono::Utc::now().timestamp_millis(),
            },
        );
    }
}

fn proposal_decision_event_value(decision: &ProposalDecision) -> &'static str {
    match decision {
        ProposalDecision::Approve => "approved",
        ProposalDecision::Reject => "rejected",
        ProposalDecision::Defer => "deferred",
    }
}

const PROPOSAL_CREATED_EVENT_TYPE: &str = "proposal.created";
const PROPOSAL_RESOLVED_EVENT_TYPE: &str = "proposal.resolved";

fn proposal_owner_agent_id(
    proposal: &magician::magician_v2::agents::DefinitionProposal,
) -> Option<&str> {
    proposal
        .payload
        .as_object()
        .and_then(|payload| payload.get("owner_agent_id"))
        .and_then(|value| value.as_str())
        .map(str::trim)
        .filter(|value| !value.is_empty())
}

fn proposal_created_event_payload(
    proposal: &magician::magician_v2::agents::DefinitionProposal,
    source: &str,
) -> serde_json::Value {
    serde_json::json!({
        "proposal_id": proposal.proposal_id,
        "agent_id": proposal.agent_id,
        "status": serde_json::to_value(&proposal.status).unwrap_or_default(),
        "created_at": proposal.created_at.to_rfc3339(),
        "source": source,
        "proposal_source": proposal.source,
        "owner_agent_id": proposal_owner_agent_id(proposal),
    })
}

fn proposal_resolved_event_payload(
    proposal: &magician::magician_v2::agents::DefinitionProposal,
    decision: &ProposalDecision,
    resolved_by: &str,
    source: &str,
) -> serde_json::Value {
    serde_json::json!({
        "proposal_id": proposal.proposal_id,
        "agent_id": proposal.agent_id,
        "status": serde_json::to_value(&proposal.status).unwrap_or_default(),
        "decision": proposal_decision_event_value(decision),
        "resolved_by": resolved_by,
        "resolved_at": proposal.resolved_at.map(|ts| ts.to_rfc3339()),
        "source": source,
        "proposal_source": proposal.source,
        "owner_agent_id": proposal_owner_agent_id(proposal),
    })
}

fn emit_proposal_resolved_event(
    v2_orchestrator: &Arc<MagicianV2Orchestrator>,
    principal: &str,
    workspace: &str,
    proposal: &magician::magician_v2::agents::DefinitionProposal,
    decision: &ProposalDecision,
    resolved_by: &str,
    source: &str,
) {
    emit_agent_event(
        v2_orchestrator,
        Some(principal),
        Some(workspace),
        PROPOSAL_RESOLVED_EVENT_TYPE,
        &proposal.agent_id,
        proposal_resolved_event_payload(proposal, decision, resolved_by, source),
    );
}

fn emit_proposal_created_event(
    v2_orchestrator: &Arc<MagicianV2Orchestrator>,
    principal: &str,
    workspace: &str,
    proposal: &magician::magician_v2::agents::DefinitionProposal,
    source: &str,
) {
    emit_agent_event(
        v2_orchestrator,
        Some(principal),
        Some(workspace),
        PROPOSAL_CREATED_EVENT_TYPE,
        &proposal.agent_id,
        proposal_created_event_payload(proposal, source),
    );
}

const PROPOSAL_APPLIED_EVENT_TYPE: &str = "proposal.applied";

fn emit_proposal_applied_event(
    v2_orchestrator: &Arc<MagicianV2Orchestrator>,
    principal: &str,
    workspace: &str,
    proposal: &magician::magician_v2::agents::DefinitionProposal,
    new_version: u32,
) {
    emit_agent_event(
        v2_orchestrator,
        Some(principal),
        Some(workspace),
        PROPOSAL_APPLIED_EVENT_TYPE,
        &proposal.agent_id,
        serde_json::json!({
            "proposal_id": proposal.proposal_id,
            "agent_id": proposal.agent_id,
            "new_version": new_version,
            "source": proposal.source,
            "proposal_source": proposal.source,
            "owner_agent_id": proposal_owner_agent_id(proposal),
        }),
    );
}

/// Result of applying a proposal: definition, version, and whether this was a fresh apply
/// (vs an idempotent early return for an already-applied proposal).
#[derive(Debug)]
struct ApplyProposalResult {
    #[allow(dead_code)] // Used in tests for assertion
    definition: AgentDefinition,
    version: u32,
    freshly_applied: bool,
    retired: bool,
    retired_state_reconciled: bool,
    application_warning: Option<String>,
}

fn merge_application_warning(existing: Option<String>, next: Option<String>) -> Option<String> {
    match (existing, next) {
        (None, None) => None,
        (Some(message), None) | (None, Some(message)) => Some(message),
        (Some(existing), Some(next)) => Some(format!("{existing}; {next}")),
    }
}

fn proposal_action_kind(
    proposal: &magician::magician_v2::agents::DefinitionProposal,
) -> Option<&str> {
    proposal
        .payload
        .get("action_kind")
        .and_then(|value| value.as_str())
        .map(str::trim)
        .filter(|value| !value.is_empty())
}

async fn apply_approved_proposal(
    agent_api: &AgentApiServices,
    proposal: &magician::magician_v2::agents::DefinitionProposal,
    proposal_principal: &str,
    proposal_workspace: &str,
) -> Result<ApplyProposalResult, magician::magician_v2::agents::ProposalApplicationError> {
    use magician::magician_v2::agents::ProposalApplicationError;

    if proposal.status != ProposalStatus::Approved {
        return Err(ProposalApplicationError::NotApproved(
            proposal.proposal_id.clone(),
        ));
    }
    if let Some(already_applied_version) = proposal.applied_version {
        // Already applied — return the current definition and the version this
        // proposal originally created.  Caller uses the version for audit only.
        let record = agent_api
            .resolve_definition_store(proposal_principal, proposal_workspace)
            .get_definition(&proposal.agent_id)
            .await?
            .ok_or_else(|| ProposalApplicationError::AgentNotFound(proposal.agent_id.clone()))?;
        let retired = matches!(
            proposal_action_kind(proposal),
            Some(magician::magician_v2::harness::RETIRE_AGENT_TOOL_NAME)
        );
        let (retired_state_reconciled, application_warning) = if retired {
            ensure_retired_agent_paused_state(
                agent_api,
                proposal_principal,
                proposal_workspace,
                &proposal.agent_id,
            )
            .await
        } else {
            (false, None)
        };
        return Ok(ApplyProposalResult {
            definition: record.definition,
            version: already_applied_version,
            freshly_applied: false,
            retired,
            retired_state_reconciled,
            application_warning,
        });
    }

    let parsed = AgentDefinition::from_yaml_str(&proposal.yaml_after)
        .map_err(|err| ProposalApplicationError::InvalidYaml(err.to_string()))?;
    if parsed.agent_id != proposal.agent_id {
        return Err(ProposalApplicationError::InvalidYaml(format!(
            "yaml_after agent_id `{}` does not match proposal agent_id `{}`",
            parsed.agent_id, proposal.agent_id
        )));
    }
    let principal = parsed
        .principal
        .clone()
        .ok_or_else(|| ProposalApplicationError::InvalidYaml("missing principal".to_string()))?;
    let workspace = parsed
        .workspace
        .clone()
        .ok_or_else(|| ProposalApplicationError::InvalidYaml("missing workspace".to_string()))?;
    if principal != proposal_principal || workspace != proposal_workspace {
        return Err(ProposalApplicationError::InvalidYaml(format!(
            "yaml_after scope `{principal}/{workspace}` does not match proposal scope `{proposal_principal}/{proposal_workspace}`"
        )));
    }
    let action_kind = proposal_action_kind(proposal);
    let retired = matches!(
        action_kind,
        Some(magician::magician_v2::harness::RETIRE_AGENT_TOOL_NAME)
    );
    let definition_store = agent_api.resolve_definition_store(&principal, &workspace);
    if harness_owner_agent_id_from_source(&proposal.source).is_some() {
        validate_harness_structural_proposal(
            &definition_store,
            proposal_principal,
            proposal_workspace,
            &proposal.source,
            &proposal.payload,
            &proposal.agent_id,
            &parsed,
        )
        .await
        .map_err(ProposalApplicationError::InvalidYaml)?;
    }
    validate_definition_trust_policy_for_proposal_apply(agent_api, &parsed).await?;
    // Use the version from yaml_after as the expected version. This ensures
    // sequential approvals against the same agent fail with a version conflict
    // when the definition has been updated between proposal creation and application.
    let expected_version = parsed.version;

    let (definition, new_version) = if matches!(
        action_kind,
        Some(magician::magician_v2::harness::CREATE_AGENT_TOOL_NAME)
    ) {
        match definition_store.create_definition(parsed.clone()).await {
            Ok(created_record) => {
                let v = created_record.version();
                (created_record.definition, v)
            },
            Err(DefinitionStoreError::AlreadyExists(_)) => {
                let current = definition_store
                    .get_definition(&proposal.agent_id)
                    .await?
                    .ok_or_else(|| {
                        ProposalApplicationError::AgentNotFound(proposal.agent_id.clone())
                    })?;
                let current_version = current.version();
                let mut expected = parsed.clone();
                expected.apply_defaults();
                expected.version = current_version;
                if expected == current.definition {
                    (current.definition, current_version)
                } else {
                    return Err(ProposalApplicationError::DefinitionStore(
                        DefinitionStoreError::AlreadyExists(proposal.agent_id.clone()),
                    ));
                }
            },
            Err(err) => return Err(ProposalApplicationError::DefinitionStore(err)),
        }
    } else {
        match definition_store
            .update_definition(&proposal.agent_id, parsed.clone(), expected_version)
            .await
        {
            Ok(updated_record) => {
                let v = updated_record.version();
                (updated_record.definition, v)
            },
            Err(DefinitionStoreError::VersionConflict {
                current_version, ..
            }) => {
                // Crash recovery: a previous attempt may have written the definition
                // but failed before mark_applied completed.  Re-read the current
                // definition and verify it matches what we were trying to write.
                let current = definition_store
                    .get_definition(&proposal.agent_id)
                    .await?
                    .ok_or_else(|| {
                        ProposalApplicationError::AgentNotFound(proposal.agent_id.clone())
                    })?;
                let mut expected = parsed.clone();
                expected.version = current_version;
                if expected == current.definition {
                    (current.definition, current_version)
                } else {
                    // Genuine conflict from a different proposal — propagate.
                    return Err(ProposalApplicationError::DefinitionStore(
                        DefinitionStoreError::VersionConflict {
                            agent_id: proposal.agent_id.clone(),
                            expected_version,
                            current_version,
                        },
                    ));
                }
            },
            Err(err) => return Err(ProposalApplicationError::DefinitionStore(err)),
        }
    };

    // Mark applied before hot-reload: if mark_applied fails, the definition is
    // durably on disk but the runtime is not dirtied, allowing a clean retry.
    // If it succeeds but the subsequent upsert_definition panics (shouldn't — it
    // is an in-memory RwLock insert), the next process restart reloads from disk.
    agent_api
        .resolve_proposal_store(&principal, &workspace)
        .await
        .mark_applied(&proposal.proposal_id, new_version)
        .await?;

    let definition_for_reload: AgentDefinition = definition.clone();
    agent_api
        .runtime()
        .upsert_definition(definition_for_reload)
        .await;

    let scheduler_warning =
        if let Err(err) = reconcile_autonomous_scheduler_entries(agent_api, &definition).await {
            warn!(
                proposal_id = %proposal.proposal_id,
                agent_id = %proposal.agent_id,
                error = %err,
                "Failed to reconcile autonomous scheduler entries after proposal apply"
            );
            Some(format!(
                "failed to reconcile autonomous scheduler entries for agent `{}`: {}",
                definition.agent_id, err
            ))
        } else {
            None
        };

    let (retired_state_reconciled, retired_warning) = if retired {
        ensure_retired_agent_paused_state(agent_api, &principal, &workspace, &proposal.agent_id)
            .await
    } else {
        (false, None)
    };

    Ok(ApplyProposalResult {
        definition,
        version: new_version,
        freshly_applied: true,
        retired,
        retired_state_reconciled,
        application_warning: merge_application_warning(scheduler_warning, retired_warning),
    })
}

async fn ensure_retired_agent_paused_state(
    agent_api: &AgentApiServices,
    principal: &str,
    workspace: &str,
    agent_id: &str,
) -> (bool, Option<String>) {
    let paused_agents = agent_api.resolve_paused_agents(principal, workspace).await;
    let inserted = paused_agents.write().await.insert(agent_id.to_string());
    let cleared_pending =
        clear_pending_dispatches_for_agent(agent_api, principal, workspace, agent_id).await;
    if cleared_pending > 0 {
        info!(
            agent_id = %agent_id,
            cleared_pending = cleared_pending,
            "Cleared queued trigger dispatches while reconciling retired agent state"
        );
    }
    let warning = persist_paused_agents_state(agent_api, principal, workspace)
        .await
        .err()
        .map(|err| format!("failed to persist paused state for retired agent `{agent_id}`: {err}"));

    (inserted || cleared_pending > 0, warning)
}

async fn validate_definition_trust_policy_for_proposal_apply(
    agent_api: &AgentApiServices,
    definition: &AgentDefinition,
) -> Result<(), magician::magician_v2::agents::ProposalApplicationError> {
    if let Err(response) = validate_definition_trust_policy(agent_api, definition).await {
        let status = response.status();
        let body = response.into_body();
        let message = match actix_web::body::to_bytes(body).await {
            Ok(bytes) => serde_json::from_slice::<ApiErrorEnvelope>(&bytes)
                .map(trust_policy_application_error_message)
                .unwrap_or_else(|_| format!("trust policy validation failed with HTTP {status}")),
            Err(_) => format!("trust policy validation failed with HTTP {status}"),
        };
        return Err(magician::magician_v2::agents::ProposalApplicationError::TrustPolicy(message));
    }
    Ok(())
}

fn trust_policy_application_error_message(payload: ApiErrorEnvelope) -> String {
    payload
        .details
        .as_ref()
        .and_then(|details| details.get("validation_errors"))
        .and_then(|value| value.as_array())
        .and_then(|errors| errors.first())
        .and_then(|value| value.as_str())
        .map(str::trim)
        .filter(|value| !value.is_empty())
        .map(|value| value.to_string())
        .unwrap_or(payload.error)
}

async fn maybe_create_for_confirmation_pause_with_event(
    approval_service: &Arc<ApprovalService>,
    v2_orchestrator: &Arc<MagicianV2Orchestrator>,
    pause_state: &AgenticPauseState,
    action_summary: &str,
    reason: &str,
    action_json: &str,
    source: &str,
) -> Result<Option<ApprovalRequest>, ApprovalServiceError> {
    let expired_requests = approval_service.expire_pending_requests(Utc::now()).await?;
    for request in expired_requests {
        emit_approval_expired_event(
            v2_orchestrator,
            pause_state.principal.as_deref(),
            pause_state.workspace.as_deref(),
            &request,
            source,
        );
    }

    let create_outcome = approval_service
        .maybe_create_for_confirmation_pause_with_outcome(
            pause_state,
            action_summary,
            reason,
            action_json,
        )
        .await?;

    if create_outcome.created_new {
        if let Some(request) = create_outcome.request.as_ref() {
            emit_approval_requested_event(
                v2_orchestrator,
                pause_state.principal.as_deref(),
                pause_state.workspace.as_deref(),
                request,
                source,
            );
        }
    }

    Ok(create_outcome.request)
}

fn definition_store_error_response(err: DefinitionStoreError) -> HttpResponse {
    match err {
        DefinitionStoreError::NotFound(agent_id) => api_error_response(
            StatusCode::NOT_FOUND,
            "agent_definition_not_found",
            "Agent definition not found",
            Some(serde_json::json!({
                "agent_id": agent_id,
            })),
        ),
        DefinitionStoreError::AlreadyExists(agent_id) => api_error_response(
            StatusCode::CONFLICT,
            "agent_definition_exists",
            "Agent definition already exists",
            Some(serde_json::json!({
                "agent_id": agent_id,
            })),
        ),
        DefinitionStoreError::VersionConflict {
            agent_id,
            expected_version,
            current_version,
        } => with_etag(
            api_error_response(
                StatusCode::PRECONDITION_FAILED,
                "definition_version_conflict",
                "Definition version conflict",
                Some(serde_json::json!({
                    "agent_id": agent_id,
                    "expected_version": expected_version,
                    "current_version": current_version,
                })),
            ),
            &format!("v{current_version}"),
        ),
        DefinitionStoreError::Validation(details) => {
            let validation_issues = parse_validation_issues(&details);
            api_error_response(
                StatusCode::UNPROCESSABLE_ENTITY,
                "invalid_agent_definition",
                "Invalid agent definition",
                Some(serde_json::json!({
                    "validation_errors": validation_issues,
                })),
            )
        },
        DefinitionStoreError::AgentIdMismatch {
            path_agent_id,
            payload_agent_id,
        } => api_error_response(
            StatusCode::BAD_REQUEST,
            "agent_id_mismatch",
            "Agent ID mismatch",
            Some(serde_json::json!({
                "path_agent_id": path_agent_id,
                "payload_agent_id": payload_agent_id,
            })),
        ),
        DefinitionStoreError::LockTimeout { lock_path, wait_ms } => {
            warn!(
                lock_path = %lock_path,
                wait_ms = wait_ms,
                "definition store lock timeout"
            );
            api_error_response(
                StatusCode::SERVICE_UNAVAILABLE,
                "definition_store_busy",
                "Definition store is busy",
                Some(serde_json::json!({
                    "wait_ms": wait_ms,
                })),
            )
        },
        DefinitionStoreError::Storage(AgentStorageError::InvalidIdentifier(agent_id)) => {
            api_error_response(
                StatusCode::BAD_REQUEST,
                "invalid_agent_id",
                "Invalid agent_id",
                Some(serde_json::json!({
                    "agent_id": agent_id,
                })),
            )
        },
        DefinitionStoreError::Storage(details) => {
            warn!(error = %details, "definition storage failure");
            api_error_response(
                StatusCode::INTERNAL_SERVER_ERROR,
                "definition_storage_failure",
                "Definition storage failure",
                None,
            )
        },
        DefinitionStoreError::Definition(details) => {
            warn!(error = %details, "definition parse failure");
            api_error_response(
                StatusCode::INTERNAL_SERVER_ERROR,
                "definition_parse_failure",
                "Definition parse failure",
                None,
            )
        },
    }
}

fn trust_policy_missing_response(
    trust_policy_path: &Path,
    trust_policy_template_path: &Path,
    trust_policy_default_path: &Path,
) -> HttpResponse {
    api_error_response(
        StatusCode::INTERNAL_SERVER_ERROR,
        "trust_policy_missing",
        "Trust policy file is missing",
        Some(serde_json::json!({
            "path": trust_policy_path.display().to_string(),
            "template_path": trust_policy_template_path.display().to_string(),
            "default_path": trust_policy_default_path.display().to_string(),
            "hint": "Restore the scoped trust_policies.yaml from trust_policies.default.yaml (recommended) or trust_policies.template.yaml",
        })),
    )
}

fn trust_policy_validation_fields(
    err: &TrustPolicyError,
) -> (
    String,
    Option<usize>,
    Option<usize>,
    &'static str,
    &'static str,
) {
    match err {
        TrustPolicyError::Yaml(yaml_err) => {
            let (line, column) = yaml_err
                .location()
                .map(|location| (Some(location.line()), Some(location.column())))
                .unwrap_or((None, None));
            (
                yaml_err.to_string(),
                line,
                column,
                "trust_policy_invalid_yaml",
                "Trust policy YAML is invalid",
            )
        },
        TrustPolicyError::Validation(message) => (
            message.clone(),
            None,
            None,
            "trust_policy_validation_failed",
            "Trust policy validation failed",
        ),
        TrustPolicyError::Io(io_err) => (
            io_err.to_string(),
            None,
            None,
            "trust_policy_io_error",
            "Trust policy I/O error",
        ),
    }
}

fn trust_policy_validation_error_response(path: &Path, err: &TrustPolicyError) -> HttpResponse {
    let (validation_error, line, column, code, error_message) = trust_policy_validation_fields(err);
    let mut details = serde_json::json!({
        "path": path.display().to_string(),
        "validation_error": validation_error,
    });
    if let Some(line) = line {
        details["line"] = serde_json::json!(line);
    }
    if let Some(column) = column {
        details["column"] = serde_json::json!(column);
    }
    api_error_response(
        StatusCode::UNPROCESSABLE_ENTITY,
        code,
        error_message,
        Some(details),
    )
}

fn trust_policy_document_response(
    trust_policy_path: &Path,
    trust_policy_template_path: &Path,
    trust_policy_default_path: &Path,
    content: String,
) -> TrustPolicyDocumentResponse {
    let validation_error = TrustPolicyEnforcer::from_yaml_str(&content).err();
    let (is_valid, validation_error, validation_line, validation_column) =
        if let Some(err) = validation_error.as_ref() {
            let (error_text, line, column, _, _) = trust_policy_validation_fields(err);
            (false, Some(error_text), line, column)
        } else {
            (true, None, None, None)
        };

    TrustPolicyDocumentResponse {
        path: trust_policy_path.display().to_string(),
        template_path: trust_policy_template_path.display().to_string(),
        default_path: trust_policy_default_path.display().to_string(),
        content,
        is_valid,
        validation_error,
        validation_line,
        validation_column,
    }
}

fn scoped_trust_policy_storage(
    agent_api: &AgentApiServices,
    principal: &str,
    workspace: &str,
) -> magician::magician_v2::agents::AgentStorage {
    agent_api
        .resolve_definition_store(principal, workspace)
        .storage()
        .clone()
}

async fn read_trust_policy_document_impl(
    storage: &magician::magician_v2::agents::AgentStorage,
) -> Result<TrustPolicyDocumentResponse, HttpResponse> {
    if let Err(err) = storage.ensure_base_layout().await {
        warn!(error = %err, "failed to ensure base layout before trust policy read");
        return Err(api_error_response(
            StatusCode::INTERNAL_SERVER_ERROR,
            "trust_policy_load_failed",
            "Failed to load trust policy",
            None,
        ));
    }

    let trust_policy_path = storage.trust_policies_path();
    let trust_policy_template_path = storage.trust_policies_template_path();
    let trust_policy_default_path = storage.trust_policies_default_path();
    let content = match tokio::fs::read_to_string(&trust_policy_path).await {
        Ok(content) => content,
        Err(err) if err.kind() == std::io::ErrorKind::NotFound => {
            warn!(
                path = %trust_policy_path.display(),
                template_path = %trust_policy_template_path.display(),
                default_path = %trust_policy_default_path.display(),
                "trust policy file is missing"
            );
            return Err(trust_policy_missing_response(
                &trust_policy_path,
                &trust_policy_template_path,
                &trust_policy_default_path,
            ));
        },
        Err(err) => {
            warn!(
                path = %trust_policy_path.display(),
                error = %err,
                "failed to read trust policy file"
            );
            return Err(api_error_response(
                StatusCode::INTERNAL_SERVER_ERROR,
                "trust_policy_load_failed",
                "Failed to read trust policy",
                Some(serde_json::json!({
                    "path": trust_policy_path.display().to_string(),
                })),
            ));
        },
    };

    Ok(trust_policy_document_response(
        &trust_policy_path,
        &trust_policy_template_path,
        &trust_policy_default_path,
        content,
    ))
}

async fn update_trust_policy_impl(
    storage: &magician::magician_v2::agents::AgentStorage,
    request: UpdateTrustPolicyRequest,
) -> HttpResponse {
    if let Err(err) = storage.ensure_base_layout().await {
        warn!(error = %err, "failed to ensure base layout before trust policy update");
        return api_error_response(
            StatusCode::INTERNAL_SERVER_ERROR,
            "trust_policy_update_failed",
            "Failed to update trust policy",
            None,
        );
    }

    let trust_policy_path = storage.trust_policies_path();
    let trust_policy_template_path = storage.trust_policies_template_path();
    let trust_policy_default_path = storage.trust_policies_default_path();
    if let Err(err) = TrustPolicyEnforcer::from_yaml_str(&request.content) {
        return trust_policy_validation_error_response(&trust_policy_path, &err);
    }

    if let Err(err) = storage
        .write_bytes_atomic(trust_policy_path.clone(), request.content.as_bytes())
        .await
    {
        warn!(
            path = %trust_policy_path.display(),
            error = %err,
            "failed to write trust policy file"
        );
        return api_error_response(
            StatusCode::INTERNAL_SERVER_ERROR,
            "trust_policy_update_failed",
            "Failed to update trust policy",
            Some(serde_json::json!({
                "path": trust_policy_path.display().to_string(),
            })),
        );
    }

    HttpResponse::Ok().json(trust_policy_document_response(
        &trust_policy_path,
        &trust_policy_template_path,
        &trust_policy_default_path,
        request.content,
    ))
}

async fn update_trust_policy_controlled(
    storage: &magician::magician_v2::agents::AgentStorage,
    request: UpdateTrustPolicyRequest,
) -> HttpResponse {
    update_trust_policy_impl(storage, request).await
}

async fn restore_trust_policy_template_impl(
    storage: &magician::magician_v2::agents::AgentStorage,
) -> HttpResponse {
    if let Err(err) = storage.ensure_base_layout().await {
        warn!(
            error = %err,
            "failed to ensure base layout before trust policy template restore"
        );
        return api_error_response(
            StatusCode::INTERNAL_SERVER_ERROR,
            "trust_policy_restore_failed",
            "Failed to restore trust policy template",
            None,
        );
    }

    let trust_policy_path = storage.trust_policies_path();
    let trust_policy_template_path = storage.trust_policies_template_path();
    let trust_policy_default_path = storage.trust_policies_default_path();
    let template_content = match tokio::fs::read_to_string(&trust_policy_template_path).await {
        Ok(content) => content,
        Err(err) => {
            warn!(
                path = %trust_policy_template_path.display(),
                error = %err,
                "failed to read trust policy template file"
            );
            return api_error_response(
                StatusCode::INTERNAL_SERVER_ERROR,
                "trust_policy_restore_failed",
                "Failed to restore trust policy template",
                Some(serde_json::json!({
                    "template_path": trust_policy_template_path.display().to_string(),
                })),
            );
        },
    };
    if let Err(err) = TrustPolicyEnforcer::from_yaml_str(&template_content) {
        return trust_policy_validation_error_response(&trust_policy_template_path, &err);
    }

    if let Err(err) = storage
        .write_bytes_atomic(trust_policy_path.clone(), template_content.as_bytes())
        .await
    {
        warn!(
            path = %trust_policy_path.display(),
            error = %err,
            "failed to restore trust policy from template"
        );
        return api_error_response(
            StatusCode::INTERNAL_SERVER_ERROR,
            "trust_policy_restore_failed",
            "Failed to restore trust policy template",
            Some(serde_json::json!({
                "path": trust_policy_path.display().to_string(),
            })),
        );
    }

    HttpResponse::Ok().json(trust_policy_document_response(
        &trust_policy_path,
        &trust_policy_template_path,
        &trust_policy_default_path,
        template_content,
    ))
}

async fn restore_trust_policy_template_controlled(
    storage: &magician::magician_v2::agents::AgentStorage,
) -> HttpResponse {
    restore_trust_policy_template_impl(storage).await
}

async fn load_trust_policy_enforcer(
    storage: &magician::magician_v2::agents::AgentStorage,
) -> Result<TrustPolicyEnforcer, HttpResponse> {
    if let Err(err) = storage.ensure_base_layout().await {
        warn!(error = %err, "failed to ensure base layout before trust policy load");
        return Err(api_error_response(
            StatusCode::INTERNAL_SERVER_ERROR,
            "trust_policy_load_failed",
            "Failed to load trust policies",
            None,
        ));
    }

    let trust_policy_path = storage.trust_policies_path();
    let trust_policy_template_path = storage.trust_policies_template_path();
    let trust_policy_default_path = storage.trust_policies_default_path();
    match TrustPolicyEnforcer::from_yaml_file(&trust_policy_path) {
        Ok(enforcer) => Ok(enforcer),
        Err(TrustPolicyError::Io(err)) if err.kind() == std::io::ErrorKind::NotFound => {
            warn!(
                path = %trust_policy_path.display(),
                template_path = %trust_policy_template_path.display(),
                default_path = %trust_policy_default_path.display(),
                "trust policy file is missing"
            );
            Err(trust_policy_missing_response(
                &trust_policy_path,
                &trust_policy_template_path,
                &trust_policy_default_path,
            ))
        },
        Err(err) => {
            warn!(
                path = %trust_policy_path.display(),
                error = %err,
                "failed to parse trust policy file"
            );
            Err(api_error_response(
                StatusCode::INTERNAL_SERVER_ERROR,
                "trust_policy_load_failed",
                "Failed to load trust policies",
                Some(serde_json::json!({
                    "path": trust_policy_path.display().to_string(),
                })),
            ))
        },
    }
}

fn validate_report_targets_against_trust_policy(
    definition: &AgentDefinition,
    trust_level: &TrustLevel,
    enforcer: &TrustPolicyEnforcer,
) -> Result<(), HttpResponse> {
    for rule in &definition.memory_consolidation {
        let Some(channel) = rule.target.strip_prefix("report:").map(str::trim) else {
            continue;
        };

        if channel.is_empty() {
            continue;
        }

        if enforcer.is_allowed(trust_level, "report", channel) {
            continue;
        }

        return Err(definition_store_error_response(
            DefinitionStoreError::Validation(format!(
                "consolidation rule `{}` target `report:{}` is not allowed for trust level `{}`",
                rule.name, channel, trust_level.0
            )),
        ));
    }
    Ok(())
}

fn pattern_matches_declared_tool(pattern_tool: &str, declared_tool: &str) -> bool {
    pattern_tool == "*" || pattern_tool.eq_ignore_ascii_case(declared_tool)
}

fn validate_declared_tools_against_trust_policy(
    definition: &AgentDefinition,
    trust_level: &TrustLevel,
    enforcer: &TrustPolicyEnforcer,
) -> Result<(), HttpResponse> {
    let Some(policy) = enforcer
        .policies()
        .iter()
        .find(|policy| policy.level.trim().eq_ignore_ascii_case(&trust_level.0))
    else {
        return Err(definition_store_error_response(
            DefinitionStoreError::Validation(format!(
                "trust_level `{}` is not defined in trust policy file",
                trust_level.0
            )),
        ));
    };

    for declared_tool in &definition.tools {
        let declared_tool = declared_tool.trim();
        if declared_tool.is_empty() {
            continue;
        }

        let has_allow_pattern = policy
            .allow
            .iter()
            .any(|pattern| pattern_matches_declared_tool(&pattern.tool, declared_tool));
        let denied_all_actions = policy.deny.iter().any(|pattern| {
            pattern_matches_declared_tool(&pattern.tool, declared_tool)
                && pattern.action.matches("*")
        });

        if !has_allow_pattern || denied_all_actions {
            return Err(definition_store_error_response(
                DefinitionStoreError::Validation(format!(
                    "declared tool `{}` is not allowed for trust level `{}`",
                    declared_tool, trust_level.0
                )),
            ));
        }
    }

    Ok(())
}

fn normalized_trust_level(definition: &AgentDefinition) -> TrustLevel {
    definition.trust_level.canonicalized()
}

/// Refuse a write that pins an agent to a profile the runtime config does not
/// define (Crew page "Models" panel, YAML editor, API). A missing name would
/// fail every run that reaches that lane, far from the edit that caused it.
/// Only names the write introduces are checked; an untouched stale pin does
/// not block an unrelated edit. With no readable config there is nothing to
/// check against, and the write proceeds as it always has.
async fn validate_definition_llm_routing(
    definition_store: &AgentDefinitionStore,
    agent_id: &str,
    definition: &AgentDefinition,
) -> Result<(), HttpResponse> {
    if definition.llm_routing.is_none() {
        return Ok(());
    }
    let Ok(config) =
        magician::config::load_magician_config_from_path(&magician::config::magician_config_path())
    else {
        return Ok(());
    };
    let known_profiles = config
        .llm
        .router
        .as_ref()
        .map(|router| router.profiles.keys().cloned().collect())
        .unwrap_or_default();
    let known_coding_profiles = config
        .coding
        .profiles
        .iter()
        .map(|profile| profile.id.clone())
        .collect();
    let previous = definition_store
        .get_definition(agent_id)
        .await
        .ok()
        .flatten()
        .and_then(|record| record.definition.llm_routing);
    let unknown = magician::magician_v2::agents::unknown_llm_routing_references(
        definition.llm_routing.as_ref(),
        previous.as_ref(),
        &known_profiles,
        &known_coding_profiles,
    );
    if unknown.is_empty() {
        return Ok(());
    }
    Err(api_error_response(
        StatusCode::UNPROCESSABLE_ENTITY,
        "unknown_pinned_profile",
        format!(
            "llm_routing names profiles the runtime config does not define: {}",
            unknown.join(", ")
        ),
        Some(serde_json::json!({ "agent_id": agent_id, "unknown": unknown })),
    ))
}

async fn validate_definition_trust_policy(
    agent_api: &AgentApiServices,
    definition: &AgentDefinition,
) -> Result<(), HttpResponse> {
    let (principal, workspace) = agent_api.definition_scope(definition, &definition.agent_id)?;
    let storage = scoped_trust_policy_storage(agent_api, &principal, &workspace);
    let enforcer = load_trust_policy_enforcer(&storage).await?;
    let trust_level = normalized_trust_level(definition);
    if !enforcer.has_level_exact(&trust_level.0) {
        return Err(definition_store_error_response(
            DefinitionStoreError::Validation(format!(
                "trust_level `{}` is not defined in trust policy file",
                definition.trust_level.0
            )),
        ));
    }
    validate_declared_tools_against_trust_policy(definition, &trust_level, &enforcer)?;
    validate_report_targets_against_trust_policy(definition, &trust_level, &enforcer)
}

fn scheduler_error_response(
    operation: &str,
    agent_id: Option<&str>,
    goal_id: Option<&str>,
    err: &SchedulerError,
) -> HttpResponse {
    warn!(
        operation = operation,
        agent_id = agent_id.unwrap_or(""),
        goal_id = goal_id.unwrap_or(""),
        error = %err,
        "agent scheduler operation failed"
    );
    match err {
        SchedulerError::LockTimeout { wait_ms, .. } => api_error_response(
            StatusCode::SERVICE_UNAVAILABLE,
            "agent_scheduler_busy",
            "Agent scheduler is busy",
            Some(serde_json::json!({
                "operation": operation,
                "agent_id": agent_id,
                "goal_id": goal_id,
                "wait_ms": wait_ms,
            })),
        ),
        _ => api_error_response(
            StatusCode::INTERNAL_SERVER_ERROR,
            "agent_scheduler_failure",
            "Agent scheduler operation failed",
            Some(serde_json::json!({
                "operation": operation,
                "agent_id": agent_id,
                "goal_id": goal_id,
            })),
        ),
    }
}

