async fn ensure_agent_loaded_for_api_with_store(
    agent_api: &AgentApiServices,
    definition_store: &AgentDefinitionStore,
    agent_id: &str,
) -> Result<AgentDefinition, HttpResponse> {
    match definition_store.get_definition(agent_id).await {
        Ok(Some(record)) => {
            let definition = record.definition;
            let (principal, workspace) = agent_api.definition_scope(&definition, agent_id)?;
            let cached = agent_api
                .runtime
                .get_definition_in_scope(&principal, &workspace, agent_id)
                .await;
            if cached.as_ref() != Some(&definition) {
                agent_api
                    .runtime
                    .upsert_definition(definition.clone())
                    .await;
            }
            Ok(definition)
        },
        Ok(None) => Err(api_error_response(
            StatusCode::NOT_FOUND,
            "agent_definition_not_found",
            "Agent definition not found",
            Some(serde_json::json!({
                "agent_id": agent_id,
            })),
        )),
        Err(err) => Err(definition_store_control_read_error_response(agent_id, err)),
    }
}

