fn agent_memory_error_response(
    operation: &'static str,
    agent_id: &str,
    tier_name: Option<&str>,
    err: impl std::fmt::Display,
) -> HttpResponse {
    let mut details = serde_json::json!({
        "operation": operation,
        "agent_id": agent_id,
    });
    if let Some(tier_name) = tier_name {
        details["tier_name"] = serde_json::Value::String(tier_name.to_string());
    }

    warn!(
        operation = operation,
        agent_id = %agent_id,
        tier_name = tier_name.unwrap_or_default(),
        error = %err,
        "Agent memory operation failed"
    );

    api_error_response(
        StatusCode::INTERNAL_SERVER_ERROR,
        "agent_memory_operation_failed",
        "Agent memory operation failed",
        Some(details),
    )
}

fn goal_ids_for_definition(definition: &AgentDefinition) -> Vec<String> {
    definition
        .autonomous_config
        .as_ref()
        .map(|config| {
            config
                .focus_areas
                .iter()
                .map(|focus_area| {
                    magician::magician_v2::agents::focus_area_goal_id(
                        &definition.agent_id,
                        focus_area,
                    )
                })
                .collect::<Vec<_>>()
        })
        .unwrap_or_default()
}

fn parse_goal_id_filter(value: Option<&str>) -> Option<String> {
    value
        .map(str::trim)
        .filter(|goal_id| !goal_id.is_empty())
        .map(str::to_string)
}

fn shared_tier_enabled(_definition: &AgentDefinition, _tier_name: &str) -> bool {
    // shared_tiers was removed from CoordinationConfig; shared memory tiers
    // are no longer configured via the coordination block.
    false
}

fn infer_memory_tier_renderer(tier_definition: &MemoryTierDefinition) -> MemoryTierRenderer {
    let format = tier_definition.render.format.trim().to_ascii_lowercase();
    match format.as_str() {
        "key_value" | "key-value" => return MemoryTierRenderer::KeyValue,
        "scored_list" | "scored-list" => return MemoryTierRenderer::ScoredList,
        "append_log" | "append-log" => return MemoryTierRenderer::AppendLog,
        "archive" => return MemoryTierRenderer::Archive,
        _ => {},
    }

    // Non-canonical values are interpreted from declared format tokens only.
    // This keeps renderer selection deterministic across payload shape changes.
    if format.contains("archive") || format.contains("summary") {
        return MemoryTierRenderer::Archive;
    }
    if format.contains("append") || format.contains("log") || format.contains("journal") {
        return MemoryTierRenderer::AppendLog;
    };
    if format.contains("score") || format.contains("rank") {
        return MemoryTierRenderer::ScoredList;
    }

    MemoryTierRenderer::KeyValue
}

fn resolve_goal_id_for_tier(
    definition: &AgentDefinition,
    tier_definition: &MemoryTierDefinition,
    requested_goal_id: Option<&str>,
) -> Result<Option<String>, HttpResponse> {
    if !matches!(tier_definition.scope, TierScope::AgentGoal) {
        return Ok(None);
    }

    let available_goal_ids = goal_ids_for_definition(definition);
    if available_goal_ids.is_empty() {
        return Err(api_error_response(
            StatusCode::UNPROCESSABLE_ENTITY,
            "agent_goal_scope_unavailable",
            "Agent has no goals for an agent_goal memory tier",
            Some(serde_json::json!({
                "tier_name": tier_definition.name,
            })),
        ));
    }

    if let Some(goal_id) = parse_goal_id_filter(requested_goal_id) {
        if available_goal_ids
            .iter()
            .any(|available| available == &goal_id)
        {
            return Ok(Some(goal_id));
        }
        return Err(api_error_response(
            StatusCode::BAD_REQUEST,
            "invalid_goal_id",
            "goal_id does not exist on this agent",
            Some(serde_json::json!({
                "tier_name": tier_definition.name,
                "goal_id": goal_id,
                "available_goal_ids": available_goal_ids,
            })),
        ));
    }

    if available_goal_ids.len() == 1 {
        return Ok(available_goal_ids.first().cloned());
    }

    Err(api_error_response(
        StatusCode::BAD_REQUEST,
        "memory_goal_id_required",
        "goal_id is required for agent_goal tiers when multiple goals are configured",
        Some(serde_json::json!({
            "tier_name": tier_definition.name,
            "available_goal_ids": available_goal_ids,
        })),
    ))
}

