async fn get_agent_episodes_with_store(
    agent_api: &AgentApiServices,
    definition_store: &AgentDefinitionStore,
    agent_id: &str,
    query: &AgentEpisodesQuery,
) -> HttpResponse {
    let definition =
        match ensure_agent_loaded_for_api_with_store(agent_api, definition_store, agent_id).await {
            Ok(definition) => definition,
            Err(response) => return response,
        };
    let (offset, limit) = match normalized_episode_pagination(query) {
        Ok(pagination) => pagination,
        Err(response) => return response,
    };
    let memory_service = match agent_api.resolve_cycle_memory_service(&definition, agent_id) {
        Ok(service) => service,
        Err(error) => return agent_scope_error_response(agent_id, error),
    };

    // goal_id is not validated against agent definition — an unknown goal_id
    // simply returns no matching episodes, which is safe and expected.
    let mut episodes = if let Some(ref goal_id) = query.goal_id {
        match memory_service
            .load_native_episodes_for_goal(agent_id, goal_id)
            .await
        {
            Ok(episodes) => episodes,
            Err(err) => {
                return agent_memory_error_response(
                    "load_native_episodes_for_goal",
                    agent_id,
                    Some(goal_id),
                    err,
                )
            },
        }
    } else {
        match memory_service.load_native_episodes(agent_id).await {
            Ok(episodes) => episodes,
            Err(err) => {
                return agent_memory_error_response("load_native_episodes", agent_id, None, err)
            },
        }
    };
    episodes.sort_by(|left, right| {
        right
            .started_at
            .cmp(&left.started_at)
            .then_with(|| right.completed_at.cmp(&left.completed_at))
            .then_with(|| right.trigger_seq.cmp(&left.trigger_seq))
    });
    let total_count = episodes.len();
    if offset > 0 {
        episodes = episodes.into_iter().skip(offset).collect();
    }
    episodes.truncate(limit);

    HttpResponse::Ok().json(AgentEpisodesResponse {
        agent_id: agent_id.to_string(),
        total_count,
        episodes,
    })
}

