async fn get_agent_artifacts_with_store(
    agent_api: &AgentApiServices,
    definition_store: &AgentDefinitionStore,
    agent_id: &str,
    query: &AgentArtifactsQuery,
) -> HttpResponse {
    let definition =
        match ensure_agent_loaded_for_api_with_store(agent_api, definition_store, agent_id).await {
            Ok(definition) => definition,
            Err(response) => return response,
        };
    let limit = query.limit.unwrap_or(50).min(AGENT_EPISODES_LIMIT_MAX);
    if limit == 0 {
        return api_error_response(
            StatusCode::BAD_REQUEST,
            "invalid_pagination_limit",
            "limit must be > 0",
            None,
        );
    }
    let offset = query.offset.unwrap_or(0);
    let memory_service = match agent_api.resolve_cycle_memory_service(&definition, agent_id) {
        Ok(service) => service,
        Err(error) => return agent_scope_error_response(agent_id, error),
    };

    let episodes = match memory_service.load_native_episodes(agent_id).await {
        Ok(episodes) => episodes,
        Err(err) => {
            return agent_memory_error_response("load_native_episodes", agent_id, None, err)
        },
    };

    let mut entries: Vec<AgentArtifactEntry> = episodes
        .into_iter()
        .filter(|ep| {
            query
                .goal_id
                .as_deref()
                .is_none_or(|gid| ep.goal_id() == gid)
        })
        .filter_map(|ep| {
            Some(AgentArtifactEntry {
                episode_id: ep.episode_id.clone(),
                goal_id: ep.goal_id().to_string(),
                produced_at: ep.completed_at_dt().ok()?,
                artifact_output: ep.artifact_output?,
            })
        })
        .collect();

    // Newest first
    entries.sort_by(|a, b| b.produced_at.cmp(&a.produced_at));
    let total_count = entries.len();
    if offset > 0 {
        entries = entries.into_iter().skip(offset).collect();
    }
    entries.truncate(limit);

    HttpResponse::Ok().json(AgentArtifactsResponse {
        agent_id: agent_id.to_string(),
        artifacts: entries,
        total_count,
    })
}

