async fn get_agent_memory_with_store(
    agent_api: &AgentApiServices,
    definition_store: &AgentDefinitionStore,
    agent_id: &str,
    query: &AgentMemoryQuery,
) -> HttpResponse {
    let definition =
        match ensure_agent_loaded_for_api_with_store(agent_api, definition_store, agent_id).await {
            Ok(definition) => definition,
            Err(response) => return response,
        };
    let available_goal_ids = goal_ids_for_definition(&definition);
    let memory_service = match agent_api.resolve_cycle_memory_service(&definition, agent_id) {
        Ok(service) => service,
        Err(error) => return agent_scope_error_response(agent_id, error),
    };
    let requested_goal_id = parse_goal_id_filter(query.goal_id.as_deref());
    if let Some(goal_id) = requested_goal_id.as_deref() {
        if !available_goal_ids
            .iter()
            .any(|available| available == goal_id)
        {
            return api_error_response(
                StatusCode::BAD_REQUEST,
                "invalid_goal_id",
                "goal_id does not exist on this agent",
                Some(serde_json::json!({
                    "goal_id": goal_id,
                    "available_goal_ids": available_goal_ids,
                })),
            );
        }
    }

    let mut tiers = Vec::with_capacity(definition.memory_tiers.len());
    for tier_definition in &definition.memory_tiers {
        let goal_id = match tier_definition.scope {
            TierScope::AgentGoal => {
                if let Some(requested) = &requested_goal_id {
                    Some(requested.clone())
                } else if available_goal_ids.len() == 1 {
                    available_goal_ids.first().cloned()
                } else {
                    None
                }
            },
            TierScope::Agent | TierScope::User => None,
        };
        let data = if matches!(tier_definition.scope, TierScope::AgentGoal) && goal_id.is_none() {
            None
        } else {
            match memory_service
                .load_native_tier(agent_id, tier_definition, goal_id.as_deref())
                .await
            {
                Ok(data) => data,
                Err(err) => {
                    return agent_memory_error_response(
                        "load_native_tier",
                        agent_id,
                        Some(&tier_definition.name),
                        err,
                    )
                },
            }
        };

        tiers.push(AgentMemoryTierSummary {
            tier_name: tier_definition.name.clone(),
            scope: tier_definition.scope.clone(),
            description: tier_definition.description.clone(),
            render_format: tier_definition.render.format.clone(),
            renderer: infer_memory_tier_renderer(tier_definition),
            shared: shared_tier_enabled(&definition, &tier_definition.name),
            goal_id,
            available_goal_ids: if matches!(tier_definition.scope, TierScope::AgentGoal) {
                available_goal_ids.clone()
            } else {
                Vec::new()
            },
            has_data: data.is_some(),
            last_updated: data.map(|tier| tier.last_updated),
        });
    }
    tiers.sort_by(|left, right| left.tier_name.cmp(&right.tier_name));

    HttpResponse::Ok().json(AgentMemoryResponse {
        agent_id: agent_id.to_string(),
        total_count: tiers.len(),
        tiers,
    })
}

async fn get_agent_memory_consolidation_health_with_store(
    agent_api: &AgentApiServices,
    definition_store: &AgentDefinitionStore,
    agent_id: &str,
    query: &AgentMemoryQuery,
) -> HttpResponse {
    let definition =
        match ensure_agent_loaded_for_api_with_store(agent_api, definition_store, agent_id).await {
            Ok(definition) => definition,
            Err(response) => return response,
        };
    let available_goal_ids = goal_ids_for_definition(&definition);
    let memory_service = match agent_api.resolve_cycle_memory_service(&definition, agent_id) {
        Ok(service) => service,
        Err(error) => return agent_scope_error_response(agent_id, error),
    };
    let requested_goal_id = parse_goal_id_filter(query.goal_id.as_deref());
    if let Some(goal_id) = requested_goal_id.as_deref() {
        if !available_goal_ids
            .iter()
            .any(|available| available == goal_id)
        {
            return api_error_response(
                StatusCode::BAD_REQUEST,
                "invalid_goal_id",
                "goal_id does not exist on this agent",
                Some(serde_json::json!({
                    "goal_id": goal_id,
                    "available_goal_ids": available_goal_ids,
                })),
            );
        }
    }

    let mut tiers = Vec::with_capacity(definition.memory_tiers.len());
    for tier_definition in &definition.memory_tiers {
        let goal_id = match tier_definition.scope {
            TierScope::AgentGoal => {
                if let Some(requested) = &requested_goal_id {
                    Some(requested.clone())
                } else if available_goal_ids.len() == 1 {
                    available_goal_ids.first().cloned()
                } else {
                    None
                }
            },
            TierScope::Agent | TierScope::User => None,
        };

        let (last_consolidated_at, error) =
            if matches!(tier_definition.scope, TierScope::AgentGoal) && goal_id.is_none() {
                (None, None)
            } else {
                match memory_service
                    .load_native_tier(agent_id, tier_definition, goal_id.as_deref())
                    .await
                {
                    Ok(data) => (data.map(|tier| tier.last_updated), None),
                    Err(err) => (None, Some(err.to_string())),
                }
            };

        tiers.push(AgentMemoryConsolidationHealthTier {
            tier_name: tier_definition.name.clone(),
            scope: tier_definition.scope.clone(),
            last_consolidated_at,
            pending_episode_count: 0,
            error,
        });
    }
    tiers.sort_by(|left, right| left.tier_name.cmp(&right.tier_name));

    HttpResponse::Ok().json(AgentMemoryConsolidationHealthResponse {
        agent_id: agent_id.to_string(),
        tiers,
    })
}

