async fn get_agent_memory_tier_with_store(
    agent_api: &AgentApiServices,
    definition_store: &AgentDefinitionStore,
    agent_id: &str,
    tier_name: &str,
    query: &AgentMemoryQuery,
) -> HttpResponse {
    let requested_tier = tier_name.trim();
    if requested_tier.is_empty() {
        return api_error_response(
            StatusCode::BAD_REQUEST,
            "invalid_memory_tier",
            "tier path parameter must not be empty",
            Some(serde_json::json!({
                "agent_id": agent_id,
            })),
        );
    }

    let definition =
        match ensure_agent_loaded_for_api_with_store(agent_api, definition_store, agent_id).await {
            Ok(definition) => definition,
            Err(response) => return response,
        };

    let Some(tier_definition) = definition
        .memory_tiers
        .iter()
        .find(|tier| tier.name == requested_tier)
    else {
        return api_error_response(
            StatusCode::NOT_FOUND,
            "agent_memory_tier_not_found",
            "Agent memory tier not found",
            Some(serde_json::json!({
                "agent_id": agent_id,
                "tier_name": requested_tier,
            })),
        );
    };

    let goal_id =
        match resolve_goal_id_for_tier(&definition, tier_definition, query.goal_id.as_deref()) {
            Ok(goal_id) => goal_id,
            Err(response) => return response,
        };
    let memory_service = match agent_api.resolve_cycle_memory_service(&definition, agent_id) {
        Ok(service) => service,
        Err(error) => return agent_scope_error_response(agent_id, error),
    };

    let data = match memory_service
        .load_native_tier(agent_id, tier_definition, goal_id.as_deref())
        .await
    {
        Ok(data) => data,
        Err(err) => {
            return agent_memory_error_response(
                "load_native_tier",
                agent_id,
                Some(&tier_definition.name),
                err,
            )
        },
    };

    let shared = shared_tier_enabled(&definition, &tier_definition.name);
    let mut shared_with_agents = Vec::new();
    if shared {
        match definition_store.list_definitions().await {
            Ok(records) => {
                for record in records {
                    if record.definition.agent_id == agent_id {
                        continue;
                    }
                    if shared_tier_enabled(&record.definition, &tier_definition.name) {
                        shared_with_agents.push(record.definition.agent_id);
                    }
                }
                shared_with_agents.sort();
                shared_with_agents.dedup();
            },
            Err(err) => {
                warn!(
                    agent_id = %agent_id,
                    tier_name = %tier_definition.name,
                    error = %err,
                    "Failed to compute cross-agent memory sharing list"
                );
            },
        }
    }

    let consolidation_rules = definition
        .memory_consolidation
        .iter()
        .filter(|rule| rule.target == tier_definition.name)
        .cloned()
        .collect::<Vec<_>>();

    HttpResponse::Ok().json(AgentMemoryTierResponse {
        agent_id: agent_id.to_string(),
        tier: tier_definition.clone(),
        goal_id,
        available_goal_ids: if matches!(tier_definition.scope, TierScope::AgentGoal) {
            goal_ids_for_definition(&definition)
        } else {
            Vec::new()
        },
        shared,
        renderer: infer_memory_tier_renderer(tier_definition),
        data,
        consolidation_rules,
        shared_with_agents,
    })
}

#[cfg(test)]
async fn list_triggers_impl(
    agent_api: &AgentApiServices,
    query: &ListTriggersQuery,
) -> HttpResponse {
    list_triggers_with_store(agent_api, agent_api.definition_store.as_ref(), query).await
}

async fn list_triggers_with_store(
    agent_api: &AgentApiServices,
    definition_store: &AgentDefinitionStore,
    query: &ListTriggersQuery,
) -> HttpResponse {
    let agent_id_filter = parse_goal_id_filter(query.agent_id.as_deref());
    let agent_name_by_id: HashMap<String, String> = match definition_store.list_definitions().await
    {
        Ok(records) => records
            .into_iter()
            .map(|record| (record.definition.agent_id, record.definition.name))
            .collect(),
        Err(err) => {
            warn!(error = %err, "Failed to load definitions while listing triggers");
            HashMap::new()
        },
    };

    let scheduler = match definition_store.current_scope() {
        Some((principal, workspace)) => {
            match agent_api.resolve_scheduler(&principal, &workspace).await {
                Ok(scheduler) => scheduler,
                Err(err) => {
                    return scheduler_error_response("resolve_scheduler", None, None, &err);
                },
            }
        },
        None => {
            return api_error_response(
                StatusCode::UNPROCESSABLE_ENTITY,
                "missing_scope",
                "Trigger listing requires a scoped agent store",
                None,
            );
        },
    };
    let mut entries = scheduler
        .snapshot()
        .await
        .entries
        .into_values()
        .collect::<Vec<_>>();
    entries.sort_by(|left, right| {
        left.agent_id
            .cmp(&right.agent_id)
            .then_with(|| left.goal_id.cmp(&right.goal_id))
            .then_with(|| left.trigger_seq.cmp(&right.trigger_seq))
    });

    let mut triggers = Vec::with_capacity(entries.len());
    for entry in entries {
        if let Some(agent_id) = agent_id_filter.as_deref() {
            if entry.agent_id != agent_id {
                continue;
            }
        }

        let (trigger_kind, schedule, timezone, event_pattern, event_filter, next_fire_at) =
            match entry.registration {
                SchedulerTriggerRegistration::Cron {
                    schedule,
                    timezone,
                    next_run_at,
                } => (
                    "cron".to_string(),
                    Some(schedule),
                    Some(timezone),
                    None,
                    HashMap::new(),
                    next_run_at,
                ),
                SchedulerTriggerRegistration::Event { pattern, filter } => {
                    ("event".to_string(), None, None, Some(pattern), filter, None)
                },
                SchedulerTriggerRegistration::Idle => {
                    ("idle".to_string(), None, None, None, HashMap::new(), None)
                },
            };

        triggers.push(TriggerMonitorEntry {
            agent_name: agent_name_by_id.get(&entry.agent_id).cloned(),
            agent_id: entry.agent_id,
            goal_id: entry.goal_id,
            trigger_seq: entry.trigger_seq,
            trigger_kind,
            schedule,
            timezone,
            event_pattern,
            event_filter,
            next_fire_at,
            last_triggered_at: entry.last_triggered,
        });
    }

    HttpResponse::Ok().json(TriggerMonitorResponse {
        total_count: triggers.len(),
        triggers,
    })
}

/// Generate a unique agent_id by checking the definition store.
/// Tries the base slug first, then appends a 4-char random suffix.
/// Skips the bare base if it fails `validate_agent_identifier` (e.g., reserved names like "approvals").
async fn generate_unique_agent_id(store: &AgentDefinitionStore, base: &str) -> String {
    use magician::magician_v2::agents::storage::validate_agent_identifier;

    // Try base slug first — but only if it passes identifier validation
    // (reserved names like "approvals" would fail here and skip to suffixed variants)
    if validate_agent_identifier(base).is_ok() && !agent_id_exists(store, base).await {
        return base.to_string();
    }
    // Append random suffix, retry up to 5 times
    for _ in 0..5 {
        let suffix = random_suffix();
        let candidate = format!("{base}-{suffix}");
        if validate_agent_identifier(&candidate).is_ok()
            && !agent_id_exists(store, &candidate).await
        {
            return candidate;
        }
    }
    // Fallback: full UUID segment (extremely unlikely to reach here)
    format!("{base}-{}", &uuid::Uuid::new_v4().to_string()[..8])
}

async fn agent_id_exists(store: &AgentDefinitionStore, id: &str) -> bool {
    match store.storage().agent_definition_path(id) {
        Ok(path) => tokio::fs::try_exists(&path).await.unwrap_or(false),
        Err(_) => false,
    }
}

fn random_suffix() -> String {
    use rand::Rng;
    let mut rng = rand::thread_rng();
    let chars: Vec<char> = (0..4)
        .map(|_| {
            let idx = rng.gen_range(0..36u8);
            if idx < 10 {
                (b'0' + idx) as char
            } else {
                (b'a' + idx - 10) as char
            }
        })
        .collect();
    chars.into_iter().collect()
}

#[cfg(test)]
async fn create_agent_definition_impl(
    agent_api: &AgentApiServices,
    definition: AgentDefinition,
) -> HttpResponse {
    create_agent_definition_with_store(agent_api, agent_api.definition_store.as_ref(), definition)
        .await
}

async fn create_agent_definition_with_store(
    agent_api: &AgentApiServices,
    definition_store: &AgentDefinitionStore,
    mut definition: AgentDefinition,
) -> HttpResponse {
    // Auto-generate agent_id from name when omitted.
    if definition.agent_id.trim().is_empty() {
        let base = slugify_name(&definition.name);
        definition.agent_id = generate_unique_agent_id(definition_store, &base).await;
    }

    if let Err(response) = validate_definition_trust_policy(agent_api, &definition).await {
        return response;
    }

    if let Err(response) = agent_api
        .definition_scope(&definition, &definition.agent_id)
        .map(|_| ())
    {
        return response;
    }

    match definition_store.create_definition(definition).await {
        Ok(record) => {
            let etag = record.etag();
            let agent_id = record.definition.agent_id.clone();
            agent_api
                .runtime
                .upsert_definition(record.definition.clone())
                .await;
            if let Err(err) =
                reconcile_autonomous_scheduler_entries(agent_api, &record.definition).await
            {
                warn!(
                    agent_id = %agent_id,
                    error = %err,
                    "Failed to reconcile autonomous scheduler entries after create"
                );
            }
            invalidate_agent_list_cache(agent_api).await;

            with_etag(
                HttpResponse::Created()
                    .append_header((
                        header::LOCATION,
                        format!("/api/magician/v2/agents/{agent_id}"),
                    ))
                    .json(agent_definition_record_response(agent_api, record).await),
                &etag,
            )
        },
        Err(err) => definition_store_error_response(err),
    }
}

