async fn update_agent_definition_with_store(
    agent_api: &AgentApiServices,
    definition_store: &AgentDefinitionStore,
    agent_id: &str,
    definition: AgentDefinition,
    expected_version: u32,
) -> HttpResponse {
    if definition.agent_id != agent_id {
        return definition_store_error_response(DefinitionStoreError::AgentIdMismatch {
            path_agent_id: agent_id.to_string(),
            payload_agent_id: definition.agent_id.clone(),
        });
    }

    if let Err(response) = validate_definition_trust_policy(agent_api, &definition).await {
        return response;
    }
    if let Err(response) =
        validate_definition_llm_routing(definition_store, agent_id, &definition).await
    {
        return response;
    }

    match definition_store
        .update_definition(agent_id, definition, expected_version)
        .await
    {
        Ok(record) => {
            let etag = record.etag();
            agent_api
                .runtime
                .upsert_definition(record.definition.clone())
                .await;
            if let Err(err) =
                reconcile_autonomous_scheduler_entries(agent_api, &record.definition).await
            {
                warn!(
                    agent_id = %record.definition.agent_id,
                    error = %err,
                    "Failed to reconcile autonomous scheduler entries after update"
                );
            }
            invalidate_agent_list_cache(agent_api).await;

            with_etag(
                HttpResponse::Ok().json(agent_definition_record_response(agent_api, record).await),
                &etag,
            )
        },
        Err(err) => definition_store_error_response(err),
    }
}

#[cfg(test)]
async fn delete_agent_definition_impl(
    agent_api: &AgentApiServices,
    agent_id: &str,
) -> HttpResponse {
    delete_agent_definition_with_store(agent_api, agent_api.definition_store.as_ref(), agent_id)
        .await
}

async fn delete_agent_definition_with_store(
    agent_api: &AgentApiServices,
    definition_store: &AgentDefinitionStore,
    agent_id: &str,
) -> HttpResponse {
    match definition_store.get_definition(agent_id).await {
        Ok(Some(_record)) => {},
        Ok(None) => {
            if let Some((principal, workspace)) = definition_store.current_scope() {
                if let Err(err) =
                    clear_local_agent_state(agent_api, &principal, &workspace, agent_id).await
                {
                    warn!(
                        agent_id = %agent_id,
                        error = %err,
                        "Failed to clear local runtime/scheduler state for missing definition"
                    );
                }
            }
            return api_error_response(
                StatusCode::NOT_FOUND,
                "agent_definition_not_found",
                "Agent definition not found",
                Some(serde_json::json!({
                    "agent_id": agent_id,
                })),
            );
        },
        Err(err) => return definition_store_error_response(err),
    }

    let scope = definition_store.current_scope();

    match definition_store.delete_definition(agent_id).await {
        Ok(true) => {
            if let Some((principal, workspace)) = scope.as_ref() {
                if let Err(err) =
                    clear_local_agent_runtime_state(agent_api, principal, workspace, agent_id).await
                {
                    return scheduler_error_response(
                        "clear_local_agent_runtime_state",
                        Some(agent_id),
                        None,
                        &err,
                    );
                }
                let scheduler = match agent_api.resolve_scheduler(principal, workspace).await {
                    Ok(scheduler) => scheduler,
                    Err(err) => {
                        return scheduler_error_response(
                            "resolve_scheduler",
                            Some(agent_id),
                            None,
                            &err,
                        );
                    },
                };
                if let Err(err) = scheduler.unregister_agent(agent_id).await {
                    return scheduler_error_response(
                        "unregister_agent",
                        Some(agent_id),
                        None,
                        &err,
                    );
                }
            }
            invalidate_agent_list_cache(agent_api).await;
            HttpResponse::NoContent().finish()
        },
        Ok(false) => {
            if let Some((principal, workspace)) = scope.as_ref() {
                if let Err(err) =
                    clear_local_agent_runtime_state(agent_api, principal, workspace, agent_id).await
                {
                    warn!(
                        agent_id = %agent_id,
                        error = %err,
                        "Failed to clear local runtime state after delete miss"
                    );
                }
                match agent_api.resolve_scheduler(principal, workspace).await {
                    Ok(scheduler) => {
                        if let Err(err) = scheduler.unregister_agent(agent_id).await {
                            warn!(
                                agent_id = %agent_id,
                                error = %err,
                                "Failed to clear stale scheduler state after delete miss"
                            );
                        }
                    },
                    Err(err) => warn!(
                        agent_id = %agent_id,
                        error = %err,
                        "Failed to resolve scheduler while clearing stale state after delete miss"
                    ),
                }
            }
            api_error_response(
                StatusCode::NOT_FOUND,
                "agent_definition_not_found",
                "Agent definition not found",
                Some(serde_json::json!({
                    "agent_id": agent_id,
                })),
            )
        },
        Err(err) => definition_store_error_response(err),
    }
}

#[cfg(test)]
#[allow(dead_code)]
async fn set_primary_agent_impl(agent_api: &AgentApiServices, agent_id: &str) -> HttpResponse {
    set_primary_agent_with_store(agent_api, agent_api.definition_store.as_ref(), agent_id)
        .await
        .response
}

struct SetPrimaryAgentResult {
    response: HttpResponse,
    previous_primary_agent_id: Option<String>,
}

async fn set_primary_agent_with_store(
    agent_api: &AgentApiServices,
    definition_store: &AgentDefinitionStore,
    agent_id: &str,
) -> SetPrimaryAgentResult {
    let previous_primary_agent_id = match definition_store.get_primary_agent().await {
        Ok(record) => record
            .map(|record| record.definition.agent_id)
            .filter(|existing_id| existing_id != agent_id),
        Err(err) => {
            return SetPrimaryAgentResult {
                response: definition_store_error_response(err),
                previous_primary_agent_id: None,
            };
        },
    };

    match definition_store.set_primary(agent_id).await {
        Ok(record) => {
            let etag = record.etag();
            agent_api
                .runtime
                .upsert_definition(record.definition.clone())
                .await;
            if let Some(previous_primary_agent_id) = previous_primary_agent_id.as_deref() {
                if let Ok(Some(previous_record)) = definition_store
                    .get_definition(previous_primary_agent_id)
                    .await
                {
                    agent_api
                        .runtime
                        .upsert_definition(previous_record.definition)
                        .await;
                }
            }
            invalidate_agent_list_cache(agent_api).await;

            SetPrimaryAgentResult {
                response: with_etag(
                    HttpResponse::Ok()
                        .json(agent_definition_record_response(agent_api, record).await),
                    &etag,
                ),
                previous_primary_agent_id,
            }
        },
        Err(err) => SetPrimaryAgentResult {
            response: definition_store_error_response(err),
            previous_primary_agent_id: None,
        },
    }
}

#[cfg(test)]
async fn consolidate_user_memory_impl(
    agent_api: &AgentApiServices,
    agent_id: &str,
) -> HttpResponse {
    consolidate_user_memory_with_store(agent_api, agent_api.definition_store.as_ref(), agent_id)
        .await
}

async fn consolidate_user_memory_with_store(
    agent_api: &AgentApiServices,
    definition_store: &AgentDefinitionStore,
    agent_id: &str,
) -> HttpResponse {
    let definition =
        match ensure_agent_loaded_for_api_with_store(agent_api, definition_store, agent_id).await {
            Ok(definition) => definition,
            Err(response) => return response,
        };

    match definition.user_memory_isolation {
        UserMemoryIsolation::Shared => api_error_response(
            StatusCode::BAD_REQUEST,
            "shared_memory",
            "Agent uses shared memory, nothing to consolidate",
            Some(serde_json::json!({ "agent_id": agent_id })),
        ),
        UserMemoryIsolation::FullyIsolated => {
            let memory_service = match agent_api.resolve_cycle_memory_service(&definition, agent_id)
            {
                Ok(service) => service,
                Err(error) => return agent_scope_error_response(agent_id, error),
            };
            match memory_service.merge_isolated_to_shared(agent_id).await {
                Ok(merged_count) => HttpResponse::Ok().json(serde_json::json!({
                    "status": "merged",
                    "agent_id": agent_id,
                    "tiers_merged": merged_count,
                })),
                Err(err) => api_error_response(
                    StatusCode::INTERNAL_SERVER_ERROR,
                    "consolidation_failed",
                    format!("Failed to consolidate user memory: {err}"),
                    Some(serde_json::json!({ "agent_id": agent_id })),
                ),
            }
        },
    }
}

#[derive(Debug, Clone, Serialize)]
struct UserKnowledgePromotionEntry {
    key: String,
    confidence: f64,
    source_type: String,
    target_tier: String,
    rationale: String,
    value: Value,
    delete_path: String,
}

#[derive(Debug, Clone, Serialize)]
struct UserKnowledgeSkipEntry {
    source_id: String,
    reason: String,
    delete_path: String,
}

#[derive(Debug, Clone, Serialize)]
struct UserKnowledgePage<T> {
    items: Vec<T>,
    total_count: usize,
    limit: usize,
    offset: usize,
}

fn user_knowledge_string(record: &serde_json::Map<String, Value>, field: &str) -> String {
    record
        .get(field)
        .and_then(Value::as_str)
        .unwrap_or_default()
        .to_string()
}

fn user_knowledge_promotion_entry(
    tier_key: &str,
    raw: &Value,
    delete_path: String,
) -> Option<UserKnowledgePromotionEntry> {
    let record = raw.as_object()?;
    Some(UserKnowledgePromotionEntry {
        key: user_knowledge_string(record, "key")
            .if_empty_then(|| user_knowledge_string(record, "source_id"))
            .if_empty_then(|| "unknown".to_string()),
        confidence: record
            .get("confidence")
            .and_then(Value::as_f64)
            .unwrap_or(0.0),
        source_type: user_knowledge_string(record, "source_type")
            .if_empty_then(|| "unknown".to_string()),
        target_tier: user_knowledge_string(record, "target_tier")
            .if_empty_then(|| tier_key.to_string()),
        rationale: user_knowledge_string(record, "rationale"),
        value: record
            .get("value")
            .cloned()
            .unwrap_or_else(|| serde_json::json!({})),
        delete_path,
    })
}

fn user_knowledge_skip_entry(raw: &Value, delete_path: String) -> Option<UserKnowledgeSkipEntry> {
    let record = raw.as_object()?;
    Some(UserKnowledgeSkipEntry {
        source_id: user_knowledge_string(record, "source_id")
            .if_empty_then(|| "unknown".to_string()),
        reason: user_knowledge_string(record, "reason"),
        delete_path,
    })
}

fn flatten_user_knowledge(
    knowledge: &Value,
) -> (
    Vec<UserKnowledgePromotionEntry>,
    Vec<UserKnowledgeSkipEntry>,
) {
    let mut promotions = Vec::new();
    let mut skips = Vec::new();
    let Some(root) = knowledge.as_object() else {
        return (promotions, skips);
    };

    for (tier_key, tier_value) in root {
        if let Some(entries) = tier_value.as_array() {
            for (idx, raw) in entries.iter().enumerate() {
                if let Some(entry) =
                    user_knowledge_promotion_entry(tier_key, raw, format!("{tier_key}.{idx}"))
                {
                    promotions.push(entry);
                }
            }
            continue;
        }

        let Some(obj) = tier_value.as_object() else {
            continue;
        };
        if let Some(entries) = obj.get("promotions").and_then(Value::as_array) {
            for (idx, raw) in entries.iter().enumerate() {
                if let Some(entry) = user_knowledge_promotion_entry(
                    tier_key,
                    raw,
                    format!("{tier_key}.promotions.{idx}"),
                ) {
                    promotions.push(entry);
                }
            }
        }
        if let Some(entries) = obj.get("skipped").and_then(Value::as_array) {
            for (idx, raw) in entries.iter().enumerate() {
                if let Some(entry) =
                    user_knowledge_skip_entry(raw, format!("{tier_key}.skipped.{idx}"))
                {
                    skips.push(entry);
                }
            }
        }
    }

    (promotions, skips)
}

fn page_user_knowledge<T: Clone>(items: &[T], offset: usize, limit: usize) -> UserKnowledgePage<T> {
    let end = offset.saturating_add(limit).min(items.len());
    let page_items = if offset >= items.len() {
        Vec::new()
    } else {
        items[offset..end].to_vec()
    };
    UserKnowledgePage {
        items: page_items,
        total_count: items.len(),
        limit,
        offset,
    }
}

trait EmptyStringFallback {
    fn if_empty_then(self, fallback: impl FnOnce() -> String) -> String;
}

impl EmptyStringFallback for String {
    fn if_empty_then(self, fallback: impl FnOnce() -> String) -> String {
        if self.is_empty() {
            fallback()
        } else {
            self
        }
    }
}

/// GET /api/magician/v2/memory/user-knowledge
///
/// Returns the user-level knowledge store (cross-agent promoted insights,
/// preferences, workflows). This data lives outside any single agent's
/// memory tiers at `user/knowledge.json`.
async fn get_user_knowledge_scoped_impl(
    memory_service: &AgentMemoryService,
    query: &UserKnowledgeQuery,
) -> HttpResponse {
    match memory_service.load_user_knowledge().await {
        Ok(knowledge) => {
            let (promotions, skips) = flatten_user_knowledge(&knowledge);
            let mut body = serde_json::json!({
                "promotions": page_user_knowledge(
                    &promotions,
                    query.promotions_offset(),
                    query.promotions_limit(),
                ),
                "skips": page_user_knowledge(
                    &skips,
                    query.skips_offset(),
                    query.skips_limit(),
                ),
            });
            if query.include_knowledge() {
                if let Some(obj) = body.as_object_mut() {
                    obj.insert("knowledge".to_string(), knowledge);
                }
            }
            HttpResponse::Ok().json(body)
        },
        Err(err) => api_error_response(
            StatusCode::INTERNAL_SERVER_ERROR,
            "load_user_knowledge_failed",
            format!("Failed to load user knowledge: {err}"),
            None,
        ),
    }
}

/// DELETE /api/magician/v2/memory/user-knowledge/{path}
///
/// Remove a key from user knowledge. The path uses dot notation
/// (e.g. `preferences.promotions.0`) to target a nested value.
async fn delete_user_knowledge_key_scoped_impl(
    memory_service: &AgentMemoryService,
    key_path: &str,
) -> HttpResponse {
    let trimmed = key_path.trim();
    if trimmed.is_empty() {
        return api_error_response(
            StatusCode::BAD_REQUEST,
            "empty_key_path",
            "key_path must not be empty",
            None,
        );
    }

    let _flock =
        match magician::magician_v2::agents::storage::AgentStorage::acquire_file_lock_exclusive(
            &memory_service.storage().user_knowledge_path(),
        )
        .await
        {
            Ok(guard) => guard,
            Err(err) => {
                return api_error_response(
                    StatusCode::INTERNAL_SERVER_ERROR,
                    "user_knowledge_lock_failed",
                    format!("Failed to lock user knowledge: {err}"),
                    None,
                );
            },
        };
    let mut knowledge = match memory_service.load_user_knowledge().await {
        Ok(k) => k,
        Err(err) => {
            return api_error_response(
                StatusCode::INTERNAL_SERVER_ERROR,
                "load_user_knowledge_failed",
                format!("Failed to load user knowledge: {err}"),
                None,
            );
        },
    };

    // Navigate to parent and remove the target key/index
    let segments: Vec<&str> = trimmed.split('.').collect();
    if segments.len() == 1 {
        // Top-level key
        if let Some(obj) = knowledge.as_object_mut() {
            if obj.remove(segments[0]).is_none() {
                return api_error_response(
                    StatusCode::NOT_FOUND,
                    "key_not_found",
                    format!("Key '{}' not found in user knowledge", trimmed),
                    None,
                );
            }
        }
    } else {
        // Navigate to parent
        let parent_path = &segments[..segments.len() - 1];
        let leaf = segments[segments.len() - 1];
        let mut cursor = &mut knowledge;
        for seg in parent_path {
            if let Ok(idx) = seg.parse::<usize>() {
                cursor = match cursor.as_array_mut().and_then(|arr| arr.get_mut(idx)) {
                    Some(v) => v,
                    None => {
                        return api_error_response(
                            StatusCode::NOT_FOUND,
                            "key_not_found",
                            format!("Path '{}' not found in user knowledge", trimmed),
                            None,
                        );
                    },
                };
            } else {
                cursor = match cursor.as_object_mut().and_then(|obj| obj.get_mut(*seg)) {
                    Some(v) => v,
                    None => {
                        return api_error_response(
                            StatusCode::NOT_FOUND,
                            "key_not_found",
                            format!("Path '{}' not found in user knowledge", trimmed),
                            None,
                        );
                    },
                };
            }
        }
        // Remove leaf
        if let Ok(idx) = leaf.parse::<usize>() {
            if let Some(arr) = cursor.as_array_mut() {
                if idx < arr.len() {
                    arr.remove(idx);
                } else {
                    return api_error_response(
                        StatusCode::NOT_FOUND,
                        "key_not_found",
                        format!("Index {} out of bounds at '{}'", idx, trimmed),
                        None,
                    );
                }
            } else {
                return api_error_response(
                    StatusCode::BAD_REQUEST,
                    "type_mismatch",
                    format!(
                        "Numeric index '{}' but parent is not an array at '{}'",
                        idx, trimmed
                    ),
                    None,
                );
            }
        } else if let Some(obj) = cursor.as_object_mut() {
            if obj.remove(leaf).is_none() {
                return api_error_response(
                    StatusCode::NOT_FOUND,
                    "key_not_found",
                    format!("Key '{}' not found in user knowledge", trimmed),
                    None,
                );
            }
        } else {
            return api_error_response(
                StatusCode::BAD_REQUEST,
                "type_mismatch",
                format!(
                    "String key '{}' but parent is not an object at '{}'",
                    leaf, trimmed
                ),
                None,
            );
        }
    }

    // Save back
    if let Err(err) = memory_service.persist_user_knowledge(&knowledge).await {
        return api_error_response(
            StatusCode::INTERNAL_SERVER_ERROR,
            "save_user_knowledge_failed",
            format!("Failed to save user knowledge: {err}"),
            None,
        );
    }

    HttpResponse::Ok().json(serde_json::json!({
        "status": "deleted",
        "key_path": trimmed,
    }))
}

/// GET /api/magician/v2/memory/pending-tasks
///
/// Returns completed/failed tasks that don't have episodic memory records yet.
/// Used to populate the "Synthesize Memory" task picker in the Lore UI.
async fn memory_pending_tasks_impl(agent_api: &AgentApiServices) -> HttpResponse {
    if let Err(response) = ensure_agent_startup_hydrated(agent_api).await {
        return response;
    }

    let artifact_v2_service = match resolve_artifact_v2_service(&agent_api.runtime) {
        Ok(service) => service,
        Err(error) => {
            return api_error_response(
                StatusCode::SERVICE_UNAVAILABLE,
                "artifact_v2_service_unavailable",
                error,
                None,
            );
        },
    };

    let task_summaries = match artifact_v2_service.list_tasks_across_scopes().await {
        Ok(tasks) => tasks,
        Err(err) => {
            return api_error_response(
                StatusCode::INTERNAL_SERVER_ERROR,
                "list_v3_tasks_failed",
                format!("Failed to list V3 tasks: {err}"),
                None,
            );
        },
    };

    let primary_agent_id = agent_api
        .definition_store
        .get_primary_agent()
        .await
        .ok()
        .flatten()
        .map(|r| r.definition.agent_id)
        .unwrap_or_else(|| "personal-assistant".to_string());

    let mut pending = Vec::new();
    let mut already_synthesized = Vec::new();

    for scoped_task in &task_summaries {
        let summary = &scoped_task.task;
        if !matches!(
            summary.status.as_str(),
            "completed" | "failed" | "cancelled"
        ) {
            continue;
        }

        let agent_id = if summary.agent_id.is_empty() {
            &primary_agent_id
        } else {
            &summary.agent_id
        };
        let scoped_memory_service = agent_api.resolve_memory_service(
            Some(scoped_task.scope.principal()),
            Some(scoped_task.scope.workspace()),
        );

        let has_episode = scoped_memory_service
            .load_native_episodes_for_goal(agent_id, &summary.id)
            .await
            .map(|eps| !eps.is_empty())
            .unwrap_or(false);

        let entry = serde_json::json!({
            "task_id": summary.id,
            "title": summary.title,
            "status": summary.status,
            "agent_id": agent_id,
        });

        if has_episode {
            already_synthesized.push(entry);
        } else {
            pending.push(entry);
        }
    }

    let inflight: Vec<String> = SYNTHESIZE_INFLIGHT
        .iter()
        .map(|r| r.key().clone())
        .collect();

    HttpResponse::Ok().json(serde_json::json!({
        "pending": pending,
        "already_synthesized": already_synthesized,
        "synthesizing": inflight,
    }))
}

/// POST /api/magician/v2/memory/synthesize
///
/// Creates episodic memory records for the specified tasks and runs consolidation
/// (entity extraction, insight extraction, etc.) for each.
/// Accepts: `{ "task_ids": ["id1", "id2", ...] }`
/// Guard to prevent concurrent synthesize operations for the same task_id.
/// Without this, two concurrent requests could both see "no episodes" and
/// both create duplicate episodes before either has written.
static SYNTHESIZE_INFLIGHT: std::sync::LazyLock<DashSet<String>> =
    std::sync::LazyLock::new(DashSet::new);

async fn memory_synthesize_impl(
    agent_api: &AgentApiServices,
    task_ids: Vec<String>,
) -> HttpResponse {
    if let Err(response) = ensure_agent_startup_hydrated(agent_api).await {
        return response;
    }

    if task_ids.is_empty() {
        return api_error_response(
            StatusCode::BAD_REQUEST,
            "no_task_ids",
            "At least one task_id is required",
            None,
        );
    }

    let artifact_v2_service = match resolve_artifact_v2_service(&agent_api.runtime) {
        Ok(service) => service,
        Err(error) => {
            return api_error_response(
                StatusCode::SERVICE_UNAVAILABLE,
                "artifact_v2_service_unavailable",
                error,
                None,
            );
        },
    };

    let definitions = agent_api.runtime.list_definitions().await;
    let primary_agent_id = agent_api
        .definition_store
        .get_primary_agent()
        .await
        .ok()
        .flatten()
        .map(|r| r.definition.agent_id)
        .unwrap_or_else(|| "personal-assistant".to_string());
    let mut results = Vec::new();

    for task_id in &task_ids {
        // Acquire per-task guard to prevent duplicate episode creation from
        // concurrent synthesize requests for the same task.
        if !SYNTHESIZE_INFLIGHT.insert(task_id.clone()) {
            results.push(serde_json::json!({
                "task_id": task_id,
                "skipped": true,
                "reason": "synthesize already in progress for this task",
            }));
            continue;
        }
        // Drop guard removes task_id from inflight set on scope exit.
        struct SynthesizeGuard(String);
        impl Drop for SynthesizeGuard {
            fn drop(&mut self) {
                SYNTHESIZE_INFLIGHT.remove(&self.0);
            }
        }
        let _guard = SynthesizeGuard(task_id.clone());

        // 1. Load the task to get its agent_id
        let (task_scope, task) = match artifact_v2_service.get_task_by_id(task_id).await {
            Ok(Some((scope, task))) => (scope, task),
            Ok(None) => {
                results.push(serde_json::json!({
                    "task_id": task_id,
                    "error": "Task not found",
                }));
                continue;
            },
            Err(err) => {
                results.push(serde_json::json!({
                    "task_id": task_id,
                    "error": format!("Failed to load task: {err}"),
                }));
                continue;
            },
        };

        let agent_id = if task.manifest.agent_id.is_empty() {
            primary_agent_id.clone()
        } else {
            task.manifest.agent_id.clone()
        };
        let scoped_memory_service = agent_api
            .resolve_memory_service(Some(task_scope.principal()), Some(task_scope.workspace()));
        let scoped_memory_consolidator = agent_api.resolve_memory_consolidator(
            Some(task_scope.principal()),
            Some(task_scope.workspace()),
        );

        // 2. Check if episode already exists
        let has_episode = scoped_memory_service
            .load_native_episodes_for_goal(&agent_id, task_id)
            .await
            .map(|eps| !eps.is_empty())
            .unwrap_or(false);

        // 3. Create episode if needed
        let episode_created = if has_episode {
            false
        } else {
            match artifact_v2_service
                .backfill_task_memory_episode(task_id)
                .await
            {
                Ok(Some(backfilled)) => backfilled.recorded.created,
                Ok(None) => {
                    results.push(serde_json::json!({
                        "task_id": task_id,
                        "error": "Task not found",
                    }));
                    continue;
                },
                Err(err) => {
                    results.push(serde_json::json!({
                        "task_id": task_id,
                        "error": format!("Failed to synthesize task episode: {err}"),
                    }));
                    continue;
                },
            }
        };

        // 4. Run cycle_completed consolidation for this task's episode
        let definition = definitions
            .iter()
            .find(|d| d.agent_id == agent_id)
            .or_else(|| definitions.iter().find(|d| d.agent_id == primary_agent_id));
        let mut consolidation_targets = Vec::new();
        let mut consolidation_error: Option<String> = None;

        if definition.is_none() {
            warn!(
                task_id = %task_id,
                agent_id = %agent_id,
                "No agent definition found for synthesize — skipping consolidation rules"
            );
        }

        if let Some(definition) = definition {
            let episodes = scoped_memory_service
                .load_native_episodes_for_goal(&agent_id, task_id)
                .await
                .unwrap_or_default();

            for episode in &episodes {
                match scoped_memory_consolidator
                    .consolidate_cycle_completed_v3(
                        definition,
                        &agent_id,
                        episode.goal_id(),
                        episode,
                    )
                    .await
                {
                    Ok(outcome) => {
                        consolidation_targets.extend(outcome.updated_targets);
                    },
                    Err(err) => {
                        warn!(
                            task_id = %task_id,
                            error = %err,
                            "Cycle-completed consolidation failed during synthesize"
                        );
                        consolidation_error = Some(format!("{err}"));
                    },
                }
            }

            // Run StepCompleted rules (extract_entities, extract_insights,
            // update_task_progress) against the episode data. These normally
            // only fire during pipeline execution per-step; during replay we
            // feed each terminal episode through the same goal key it was
            // recorded with.
            for episode in &episodes {
                match scoped_memory_consolidator
                    .run_step_rules_for_v3_episodes(
                        definition,
                        &agent_id,
                        episode.goal_id(),
                        std::slice::from_ref(episode),
                    )
                    .await
                {
                    Ok(outcome) => {
                        consolidation_targets.extend(outcome.updated_targets);
                    },
                    Err(err) => {
                        warn!(
                            task_id = %task_id,
                            goal_id = %episode.goal_id(),
                            error = %err,
                            "Step-rules consolidation failed during synthesize"
                        );
                        if consolidation_error.is_none() {
                            consolidation_error = Some(format!("{err}"));
                        }
                    },
                }
            }
        }

        consolidation_targets.sort();
        consolidation_targets.dedup();

        results.push(serde_json::json!({
            "task_id": task_id,
            "title": task.manifest.title,
            "agent_id": agent_id,
            "episode_created": episode_created,
            "consolidation_targets": consolidation_targets,
            "consolidation_error": consolidation_error,
        }));
    }

    // 5. Run batch sweep to process any new unprocessed episodes through LLM rules
    //    (entity extraction, insight extraction, etc.)
    //    Reset time gates first so batch rules fire immediately.
    let mut batch_results: Vec<serde_json::Value> = Vec::new();
    let swept_agent_ids: std::collections::HashSet<String> = results
        .iter()
        .filter_map(|r| r.get("agent_id").and_then(|v| v.as_str()).map(String::from))
        .collect();

    for agent_id in &swept_agent_ids {
        if let Some(definition) = definitions.iter().find(|d| d.agent_id == *agent_id) {
            let (principal, workspace) = match agent_api.cycle_memory_scope(definition, agent_id) {
                Ok(scope) => scope,
                Err(error) => {
                    warn!(
                        agent_id = %agent_id,
                        error = %error,
                        "Skipping synthesize batch sweep because the agent definition is missing explicit scope"
                    );
                    continue;
                },
            };
            let scoped_memory_consolidator = agent_api
                .resolve_memory_consolidator(Some(principal.as_str()), Some(workspace.as_str()));
            if let Err(err) = scoped_memory_consolidator.clear_run_state(agent_id).await {
                warn!(
                    agent_id = %agent_id,
                    principal = %principal,
                    workspace = %workspace,
                    error = %err,
                    "Failed to clear consolidation run state during synthesize"
                );
            }

            match scoped_memory_consolidator
                .run_batch_sweep_for_agent(definition, agent_id, Utc::now())
                .await
            {
                Ok(outcome) => {
                    batch_results.push(serde_json::json!({
                        "agent_id": agent_id,
                        "updated_targets": outcome.updated_targets,
                        "skipped_rules": outcome.skipped_rules,
                        "reports": outcome.reports.iter().map(|r| serde_json::json!({
                            "rule": r.rule_name,
                            "target": r.target,
                            "message": r.message,
                        })).collect::<Vec<_>>(),
                    }));
                },
                Err(err) => {
                    batch_results.push(serde_json::json!({
                        "agent_id": agent_id,
                        "error": format!("{err}"),
                    }));
                },
            }
        }
    }

    HttpResponse::Ok().json(serde_json::json!({
        "status": "synthesize_complete",
        "results": results,
        "batch_consolidation": batch_results,
    }))
}

#[cfg(test)]
async fn create_agent_definition_controlled(
    agent_api: &AgentApiServices,
    definition: AgentDefinition,
) -> HttpResponse {
    create_agent_definition_controlled_with_store(
        agent_api,
        agent_api.definition_store.as_ref(),
        definition,
    )
    .await
}

async fn create_agent_definition_controlled_with_store(
    agent_api: &AgentApiServices,
    definition_store: &AgentDefinitionStore,
    definition: AgentDefinition,
) -> HttpResponse {
    if let Err(response) = ensure_agent_startup_hydrated(agent_api).await {
        return response;
    }
    let _control_guard = agent_api.control_gate.lock().await;
    create_agent_definition_with_store(agent_api, definition_store, definition).await
}

#[cfg(test)]
async fn update_agent_definition_controlled(
    agent_api: &AgentApiServices,
    agent_id: &str,
    definition: AgentDefinition,
    if_match: IfMatchCondition,
) -> HttpResponse {
    update_agent_definition_controlled_with_store(
        agent_api,
        agent_api.definition_store.as_ref(),
        agent_id,
        definition,
        if_match,
    )
    .await
}

async fn update_agent_definition_controlled_with_store(
    agent_api: &AgentApiServices,
    definition_store: &AgentDefinitionStore,
    agent_id: &str,
    definition: AgentDefinition,
    if_match: IfMatchCondition,
) -> HttpResponse {
    // Early exit before hydration/lock — matches PATCH's guard placement.
    if let Err(response) = ensure_agent_startup_hydrated(agent_api).await {
        return response;
    }
    let _control_guard = agent_api.control_gate.lock().await;
    let current_record = match definition_store.get_definition(agent_id).await {
        Ok(Some(record)) => record,
        Ok(None) => {
            return api_error_response(
                StatusCode::NOT_FOUND,
                "agent_definition_not_found",
                "Agent definition not found",
                Some(serde_json::json!({
                    "agent_id": agent_id,
                })),
            );
        },
        Err(err) => return definition_store_error_response(err),
    };
    let current_version = current_record.definition.version;
    let expected_version = match if_match {
        IfMatchCondition::Any => current_version,
        IfMatchCondition::Versions(versions) => {
            if versions.contains(&current_version) {
                current_version
            } else {
                return with_etag(
                    api_error_response(
                        StatusCode::PRECONDITION_FAILED,
                        "definition_version_conflict",
                        "Definition version conflict",
                        Some(serde_json::json!({
                            "agent_id": agent_id,
                            "expected_versions": versions,
                            "current_version": current_version,
                        })),
                    ),
                    &format!("v{current_version}"),
                );
            }
        },
    };

    update_agent_definition_with_store(
        agent_api,
        definition_store,
        agent_id,
        definition,
        expected_version,
    )
    .await
}

/// RFC 7386 JSON Merge Patch: recursively merge `patch` into `target`.
/// - Null values in patch remove the corresponding key from target.
/// - Object values are recursively merged when the target also has an object.
/// - All other values replace the target key.
fn json_merge_patch(target: &mut Value, patch: &Value) {
    if let Value::Object(patch_obj) = patch {
        if !target.is_object() {
            *target = Value::Object(serde_json::Map::new());
        }
        let target_obj = target.as_object_mut().unwrap();
        for (key, patch_value) in patch_obj {
            if patch_value.is_null() {
                target_obj.remove(key);
            } else if patch_value.is_object() {
                let entry = target_obj
                    .entry(key.clone())
                    .or_insert_with(|| Value::Object(serde_json::Map::new()));
                json_merge_patch(entry, patch_value);
            } else {
                target_obj.insert(key.clone(), patch_value.clone());
            }
        }
    } else {
        *target = patch.clone();
    }
}

#[cfg(test)]
async fn patch_agent_definition_controlled(
    agent_api: &AgentApiServices,
    agent_id: &str,
    patch: &Value,
    if_match: IfMatchCondition,
) -> HttpResponse {
    patch_agent_definition_controlled_with_store(
        agent_api,
        agent_api.definition_store.as_ref(),
        agent_id,
        patch,
        if_match,
    )
    .await
}

async fn patch_agent_definition_controlled_with_store(
    agent_api: &AgentApiServices,
    definition_store: &AgentDefinitionStore,
    agent_id: &str,
    patch: &Value,
    if_match: IfMatchCondition,
) -> HttpResponse {
    if let Err(response) = ensure_agent_startup_hydrated(agent_api).await {
        return response;
    }
    let _control_guard = agent_api.control_gate.lock().await;

    // Load existing definition
    let current_record = match definition_store.get_definition(agent_id).await {
        Ok(Some(record)) => record,
        Ok(None) => {
            return api_error_response(
                StatusCode::NOT_FOUND,
                "agent_definition_not_found",
                "Agent definition not found",
                Some(serde_json::json!({ "agent_id": agent_id })),
            );
        },
        Err(err) => return definition_store_error_response(err),
    };

    // Version check (same pattern as PUT)
    let current_version = current_record.definition.version;
    let expected_version = match if_match {
        IfMatchCondition::Any => current_version,
        IfMatchCondition::Versions(versions) => {
            if versions.contains(&current_version) {
                current_version
            } else {
                return with_etag(
                    api_error_response(
                        StatusCode::PRECONDITION_FAILED,
                        "definition_version_conflict",
                        "Definition version conflict",
                        Some(serde_json::json!({
                            "agent_id": agent_id,
                            "expected_versions": versions,
                            "current_version": current_version,
                        })),
                    ),
                    &format!("v{current_version}"),
                );
            }
        },
    };

    // Serialize existing definition to Value, apply merge patch
    let mut base = match serde_json::to_value(&current_record.definition) {
        Ok(v) => v,
        Err(err) => {
            return api_error_response(
                StatusCode::INTERNAL_SERVER_ERROR,
                "definition_serialization_error",
                format!("Failed to serialize existing definition: {err}"),
                None,
            );
        },
    };

    json_merge_patch(&mut base, patch);

    // Pin immutable identity fields (prevent mutation via patch body)
    if let Value::Object(ref mut obj) = base {
        obj.insert("agent_id".to_string(), Value::String(agent_id.to_string()));
        obj.insert("version".to_string(), Value::Number(current_version.into()));
    }

    // Deserialize merged value back to AgentDefinition
    let merged_definition: AgentDefinition = match serde_json::from_value(base) {
        Ok(d) => d,
        Err(err) => {
            return api_error_response(
                StatusCode::UNPROCESSABLE_ENTITY,
                "invalid_merged_definition",
                format!("Merged definition is invalid: {err}"),
                None,
            );
        },
    };

    if let Err(response) = validate_definition_trust_policy(agent_api, &merged_definition).await {
        return response;
    }

    update_agent_definition_with_store(
        agent_api,
        definition_store,
        agent_id,
        merged_definition,
        expected_version,
    )
    .await
}

#[derive(Debug, Clone)]
struct ManualTriggerDispatch {
    agent_id: String,
    principal: String,
    workspace: String,
    goal_id: String,
    trigger: String,
    trigger_seq: u64,
    cycle_id: String,
    task_id: Option<String>,
    execution_id: Option<String>,
    runtime_execution_id: Option<String>,
    definition_version: u32,
    goal_description: String,
    max_iterations: Option<usize>,
    trust_level: String,
    trust_policies_path: PathBuf,
    preloaded_trust_enforcer: Arc<TrustPolicyEnforcer>,
    approval_rules: Vec<ApprovalRule>,
    strategy_summary: String,
    strategy_hint_enabled: bool,
    llm_routing_overrides: Option<OperationRoutingOverrides>,
    workflow_inputs: HashMap<String, Value>,
    definition: AgentDefinition,
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
enum ManualDispatchSchedule {
    StartNow,
    Queued { queue_position: usize },
}

use magician::magician_v2::agents::runtime::AUTO_SELECT_STRATEGY_CANDIDATES;

fn trim_non_empty(raw: Option<&str>) -> Option<String> {
    raw.map(str::trim)
        .filter(|value| !value.is_empty())
        .map(str::to_string)
}

fn routing_endpoint_override(
    endpoint: Option<&magician::magician_v2::agents::LlmEndpoint>,
) -> Option<OperationRoutingEndpoint> {
    endpoint.and_then(|value| {
        // Prefer profile reference (inherits all config from magician-config.yaml).
        // Fall back to raw provider/model if no profile is set.
        if let Some(profile) = &value.profile {
            OperationRoutingEndpoint::for_profile(profile)
        } else {
            OperationRoutingEndpoint::new(&value.provider, &value.model)
        }
    })
}

fn llm_routing_overrides(definition: &AgentDefinition) -> Option<OperationRoutingOverrides> {
    let llm_routing = definition.llm_routing.as_ref()?;
    let overrides = OperationRoutingOverrides {
        planning: routing_endpoint_override(llm_routing.planning.as_ref()),
        evaluation: routing_endpoint_override(llm_routing.evaluation.as_ref()),
        correction_extraction: routing_endpoint_override(
            llm_routing.correction_extraction.as_ref(),
        ),
        memory_consolidation: routing_endpoint_override(llm_routing.memory_consolidation.as_ref()),
        operations: std::collections::BTreeMap::new(),
        parent_engine: None,
    };
    overrides.normalized()
}

fn prompt_identity_for_manual_dispatch(dispatch: &ManualTriggerDispatch) -> PromptIdentityContext {
    let base_persona = trim_non_empty(Some(dispatch.definition.persona.as_str()));

    PromptIdentityContext {
        agent_kind: Some(if dispatch.agent_id.starts_with("system:") {
            PromptAgentKind::System
        } else {
            PromptAgentKind::User
        }),
        base_persona: base_persona.clone(),
        source_agent_id: Some(dispatch.agent_id.clone()),
        source_agent_name: Some(dispatch.definition.name.trim().to_string()),
        source_agent_aliases: magician::magician_v2::presentation_identity::bounded_agent_aliases(
            &dispatch.definition.aliases,
        ),
        source_agent_persona: base_persona,
        autonomous_controls: None,
    }
}

async fn resolve_manual_trigger_strategy_summary(
    agent_api: &AgentApiServices,
    definition: &AgentDefinition,
    agent_id: &str,
    goal_id: &str,
) -> String {
    let memory_service = match agent_api.resolve_cycle_memory_service(definition, agent_id) {
        Ok(service) => service,
        Err(error) => {
            warn!(
                agent_id = %agent_id,
                goal_id = %goal_id,
                error = %error,
                "Skipping auto-select strategy lookup because the agent definition is missing explicit scope"
            );
            return agent_api
                .runtime
                .resolve_strategy_preference(definition.strategy.as_ref(), None);
        },
    };
    let auto_selected = if matches!(definition.strategy, Some(StrategyPreference::AutoSelect)) {
        match memory_service
            .select_effective_strategy_for_goal(agent_id, goal_id, &AUTO_SELECT_STRATEGY_CANDIDATES)
            .await
        {
            Ok(value) => value,
            Err(error) => {
                warn!(
                    agent_id = %agent_id,
                    goal_id = %goal_id,
                    error = %error,
                    "Auto-select strategy effectiveness lookup failed; falling back to default strategy"
                );
                None
            },
        }
    } else {
        None
    };

    agent_api
        .runtime
        .resolve_strategy_preference(definition.strategy.as_ref(), auto_selected.as_deref())
}

#[cfg(test)]
async fn delete_agent_definition_controlled(
    agent_api: &AgentApiServices,
    agent_id: &str,
) -> (
    HttpResponse,
    Vec<magician::magician_v2::agents::AgentCycleReservation>,
) {
    delete_agent_definition_controlled_with_store(
        agent_api,
        agent_api.definition_store.as_ref(),
        agent_id,
    )
    .await
}

async fn delete_agent_definition_controlled_with_store(
    agent_api: &AgentApiServices,
    definition_store: &AgentDefinitionStore,
    agent_id: &str,
) -> (
    HttpResponse,
    Vec<magician::magician_v2::agents::AgentCycleReservation>,
) {
    if let Err(response) = ensure_agent_startup_hydrated(agent_api).await {
        return (response, Vec::new());
    }

    let _control_guard = agent_api.control_gate.lock().await;
    let active_cycle_snapshot = match definition_store.current_scope() {
        Some((principal, workspace)) => agent_api
            .runtime
            .active_cycles_for_agent_in_scope(&principal, &workspace, agent_id)
            .await
            .into_iter()
            .collect(),
        None => Vec::new(),
    };
    let response = delete_agent_definition_with_store(agent_api, definition_store, agent_id).await;
    (response, active_cycle_snapshot)
}

const AGENT_SESSION_THREAD_PREFIX: &str = "agentic-session-";

async fn normalize_execution_lookup_id(
    _agent_api: &AgentApiServices,
    requested_id: &str,
) -> String {
    if let Some(normalized) = requested_id.strip_prefix(AGENT_SESSION_THREAD_PREFIX) {
        return normalized.to_string();
    }

    requested_id.to_string()
}

fn manual_trigger_response(
    dispatch: &ManualTriggerDispatch,
    schedule: ManualDispatchSchedule,
) -> ManualAgentTriggerResponse {
    let (status, queue_position) = match schedule {
        ManualDispatchSchedule::StartNow => ("triggered".to_string(), None),
        ManualDispatchSchedule::Queued { queue_position } => {
            ("queued".to_string(), Some(queue_position))
        },
    };
    ManualAgentTriggerResponse {
        agent_id: dispatch.agent_id.clone(),
        goal_id: dispatch.goal_id.clone(),
        trigger: dispatch.trigger.clone(),
        trigger_seq: dispatch.trigger_seq,
        cycle_id: dispatch.cycle_id.clone(),
        execution_id: dispatch.runtime_execution_id.clone(),
        definition_version: dispatch.definition_version,
        status,
        queue_position,
    }
}

fn required_cycle_principal(
    definition: &AgentDefinition,
    agent_id: &str,
) -> Result<String, String> {
    definition
        .principal
        .as_deref()
        .map(str::trim)
        .filter(|value| !value.is_empty())
        .map(str::to_string)
        .ok_or_else(|| {
            format!(
                "agent `{}` is missing an explicit principal; update the agent definition before using cycle-owned runtime features",
                agent_id
            )
        })
}

fn required_cycle_workspace(
    definition: &AgentDefinition,
    agent_id: &str,
) -> Result<String, String> {
    definition
        .workspace
        .as_deref()
        .map(str::trim)
        .filter(|value| !value.is_empty())
        .map(str::to_string)
        .ok_or_else(|| {
            format!(
                "agent `{}` is missing an explicit workspace; update the agent definition before using cycle-owned runtime features",
                agent_id
            )
        })
}

fn required_cycle_scope(
    definition: &AgentDefinition,
    agent_id: &str,
) -> Result<(String, String), String> {
    Ok((
        required_cycle_principal(definition, agent_id)?,
        required_cycle_workspace(definition, agent_id)?,
    ))
}

fn resolve_cycle_goal_description(definition: &AgentDefinition, goal_id: &str) -> String {
    magician::magician_v2::agents::resolve_focus_area_goal_description(definition, goal_id)
        .unwrap_or_else(|| goal_id.to_string())
}

fn resolve_cycle_task_title(definition: &AgentDefinition, goal_id: &str) -> String {
    magician::magician_v2::agents::resolve_focus_area_task_title(definition, goal_id)
        .unwrap_or_else(|| format!("{} / {}", definition.agent_id, goal_id))
}

async fn reconcile_autonomous_scheduler_entries(
    agent_api: &AgentApiServices,
    definition: &AgentDefinition,
) -> Result<(), SchedulerError> {
    let Ok((principal, workspace)) = required_cycle_scope(definition, &definition.agent_id) else {
        return Ok(());
    };
    let scheduler = agent_api.resolve_scheduler(&principal, &workspace).await?;
    let disabled_agent_ids = agent_api
        .resolve_definition_store(&principal, &workspace)
        .disabled_hierarchy_agent_ids()
        .await
        .map_err(|err| SchedulerError::Storage {
            operation: "disabled_hierarchy_agent_ids",
            details: err.to_string(),
        })?;

    if !disabled_agent_ids.is_empty() {
        let stale_goal_ids_by_agent = scheduler
            .snapshot()
            .await
            .entries
            .into_values()
            .filter(|entry| disabled_agent_ids.contains(&entry.agent_id))
            .fold(HashMap::<String, Vec<String>>::new(), |mut acc, entry| {
                acc.entry(entry.agent_id).or_default().push(entry.goal_id);
                acc
            });
        let disabled_agents_to_unregister =
            stale_goal_ids_by_agent.keys().cloned().collect::<Vec<_>>();
        for disabled_agent_id in disabled_agents_to_unregister {
            scheduler.unregister_agent(&disabled_agent_id).await?;
        }
        if let Some(queue) = agent_api.runtime.wake_up_queue() {
            for (disabled_agent_id, stale_goal_ids) in stale_goal_ids_by_agent {
                for goal_id in stale_goal_ids {
                    queue
                        .cancel_scoped(&principal, &workspace, &disabled_agent_id, &goal_id)
                        .await;
                }
            }
        }
    }

    if disabled_agent_ids.contains(&definition.agent_id) {
        return Ok(());
    }

    let desired_goals = definition
        .autonomous_config
        .as_ref()
        .map(|config| {
            config
                .focus_areas
                .iter()
                .map(|focus_area| {
                    let goal_id = magician::magician_v2::agents::focus_area_goal_id(
                        &definition.agent_id,
                        focus_area,
                    );
                    let schedule = focus_area.effective_schedule(&config.schedule).to_string();
                    (goal_id, schedule)
                })
                .collect::<Vec<_>>()
        })
        .unwrap_or_default();
    let desired_goal_ids = desired_goals
        .iter()
        .map(|(goal_id, _)| goal_id.clone())
        .collect::<HashSet<_>>();

    let managed_goal_prefix = format!("harness:{}:", definition.agent_id);
    let stale_goals = scheduler
        .snapshot()
        .await
        .entries
        .into_values()
        .filter(|entry| {
            entry.agent_id == definition.agent_id
                && entry.goal_id.starts_with(&managed_goal_prefix)
                && !desired_goal_ids.contains(&entry.goal_id)
        })
        .map(|entry| entry.goal_id)
        .collect::<Vec<_>>();

    for (goal_id, schedule) in desired_goals {
        scheduler
            .register_entry(
                &definition.agent_id,
                &goal_id,
                SchedulerTriggerRegistration::Cron {
                    schedule: schedule.clone(),
                    timezone: "UTC".to_string(),
                    next_run_at: magician::magician_v2::agents::scheduler::compute_next_run_at(
                        &schedule,
                        "UTC",
                        Utc::now(),
                    ),
                },
            )
            .await?;
    }

    for goal_id in stale_goals {
        scheduler
            .unregister_agent_goal(&definition.agent_id, &goal_id)
            .await?;
        if let Some(queue) = agent_api.runtime.wake_up_queue() {
            queue
                .cancel_scoped(&principal, &workspace, &definition.agent_id, &goal_id)
                .await;
        }
    }

    for goal_id in desired_goal_ids {
        agent_api
            .runtime
            .resume_scheduler_agent_in_scope(&principal, &workspace, &definition.agent_id, &goal_id)
            .await;
    }

    Ok(())
}

fn cycle_dispatch_task_title(dispatch: &ManualTriggerDispatch) -> String {
    resolve_cycle_task_title(&dispatch.definition, &dispatch.goal_id)
}

fn cycle_dispatch_created_by(
    dispatch: &ManualTriggerDispatch,
) -> magician::magician_v2::storage::TaskCreatedBy {
    if dispatch.trigger == "cron" {
        magician::magician_v2::storage::TaskCreatedBy::Agent {
            agent_id: dispatch.agent_id.clone(),
        }
    } else {
        magician::magician_v2::storage::TaskCreatedBy::User
    }
}

fn resolve_artifact_v2_service(runtime: &AgentRuntime) -> Result<Arc<ArtifactV2Service>, String> {
    runtime
        .artifact_v2_service()
        .ok_or_else(|| "artifact_v2_service not wired".to_string())
}

async fn persist_v3_root_run_outcome(
    artifact_v2_service: &Arc<ArtifactV2Service>,
    execution_id: &str,
) -> Result<(), String> {
    artifact_v2_service
        .persist_runtime_execution_outcome_by_execution_id(execution_id)
        .await
        .map_err(|error| {
            format!(
                "failed to persist V3 execution outcome for {}: {}",
                execution_id, error
            )
        })
}

async fn maybe_persist_task_backed_execution_outcome(
    agent_api: &AgentApiServices,
    v2_orchestrator: &Arc<MagicianV2Orchestrator>,
    execution_id: &str,
    context: &str,
) {
    let execution = match v2_orchestrator.get_execution(execution_id).await {
        Ok(execution) => execution,
        Err(error) => {
            warn!(
                execution_id = %execution_id,
                error = %error,
                "Failed to reload execution while persisting V3 outcome after {}",
                context
            );
            return;
        },
    };

    if execution.task_id.is_none() {
        return;
    }

    match resolve_artifact_v2_service(&agent_api.runtime) {
        Ok(artifact_v2_service) => {
            if let Err(error) =
                persist_v3_root_run_outcome(&artifact_v2_service, execution_id).await
            {
                warn!(
                    execution_id = %execution_id,
                    error = %error,
                    "Failed to persist V3 outcome after {}",
                    context
                );
            }
        },
        Err(error) => {
            warn!(
                execution_id = %execution_id,
                error = %error,
                "Failed to resolve V3 task service while persisting outcome after {}",
                context
            );
        },
    }
}

async fn persist_task_backed_cancelled_execution(
    agent_api: &AgentApiServices,
    v2_orchestrator: &Arc<MagicianV2Orchestrator>,
    execution_id: &str,
) {
    maybe_persist_task_backed_execution_outcome(
        agent_api,
        v2_orchestrator,
        execution_id,
        "cancellation",
    )
    .await;
}

fn v3_task_retry_status_can_execute(status: &str) -> bool {
    matches!(status, "ready" | "paused" | "deferred")
}

fn v3_task_schedule_status_can_execute(status: &str) -> bool {
    status == "ready"
}

fn v3_task_is_autonomous_bootstrap(
    task: &magician::magician_v2::artifact_v2::models::TaskRecord,
) -> bool {
    task.manifest.created_by == "system:bootstrap"
}

async fn v3_task_dependencies_blocked(
    artifact_v2_service: &ArtifactV2Service,
    scope: &ScopeRef,
    task: &magician::magician_v2::artifact_v2::models::TaskRecord,
) -> Result<bool, String> {
    for dependency_task_id in &task.manifest.depends_on {
        match artifact_v2_service
            .get_task(scope, dependency_task_id)
            .await
        {
            Ok(dependency) if dependency.state.status == "completed" => {},
            Ok(_) => return Ok(true),
            Err(error) => {
                return Err(format!(
                    "failed to load dependency {} for task {}: {}",
                    dependency_task_id, task.manifest.task_id, error
                ));
            },
        }
    }
    Ok(false)
}

async fn load_v3_scheduled_task(
    artifact_v2_service: &ArtifactV2Service,
    task_id: &str,
) -> Result<
    Option<(
        ScopeRef,
        magician::magician_v2::artifact_v2::models::TaskRecord,
    )>,
    String,
> {
    let Some(scope) = artifact_v2_service
        .find_task_scope(task_id)
        .await
        .map_err(|error| format!("failed to resolve V3 task scope for {}: {}", task_id, error))?
    else {
        return Ok(None);
    };

    let task = artifact_v2_service
        .get_task(&scope, task_id)
        .await
        .map_err(|error| format!("failed to load V3 task {}: {}", task_id, error))?;
    Ok(Some((scope, task)))
}

async fn launch_v3_task_retry_wake(runtime: &AgentRuntime, task_id: &str) -> Result<(), String> {
    let artifact_v2_service = resolve_artifact_v2_service(runtime)?;
    let Some((scope, task)) = load_v3_scheduled_task(artifact_v2_service.as_ref(), task_id).await?
    else {
        tracing::debug!(
            task_id = %task_id,
            "web_api wakeup loop: V3 scheduled task no longer exists"
        );
        return Ok(());
    };

    if !v3_task_retry_status_can_execute(&task.state.status) {
        tracing::info!(
            task_id = %task_id,
            status = %task.state.status,
            "web_api wakeup loop: V3 scheduled task status not executable; skipping"
        );
        return Ok(());
    }

    if v3_task_dependencies_blocked(artifact_v2_service.as_ref(), &scope, &task).await? {
        tracing::info!(
            task_id = %task_id,
            deps = ?task.manifest.depends_on,
            "web_api wakeup loop: V3 scheduled task has unresolved dependencies; skipping"
        );
        return Ok(());
    }

    if v3_task_is_autonomous_bootstrap(&task) {
        return Err(format!(
            "autonomous bootstrap scheduled tasks must be migrated onto a V3-native bootstrap writer before launch: {}",
            task.manifest.task_id
        ));
    }

    artifact_v2_service
        .clone()
        .start_execution(scope.clone(), task.manifest.task_id.clone(), None, false)
        .await
        .map_err(|error| {
            format!(
                "failed to start V3 scheduled task {} in {}/{}: {}",
                task.manifest.task_id,
                scope.principal(),
                scope.workspace(),
                error
            )
        })?;
    tracing::info!(
        task_id = %task.manifest.task_id,
        principal = %scope.principal(),
        workspace = %scope.workspace(),
        "web_api wakeup loop: launched V3 scheduled task"
    );
    Ok(())
}

async fn recover_v3_task_schedule_wake(
    runtime: &AgentRuntime,
    task_id: &str,
) -> Result<(), String> {
    let artifact_v2_service = resolve_artifact_v2_service(runtime)?;
    let Some((scope, task)) = load_v3_scheduled_task(artifact_v2_service.as_ref(), task_id).await?
    else {
        return Ok(());
    };
    let Some(execution_id) = task.state.active_root_execution_id.as_deref() else {
        return Ok(());
    };
    artifact_v2_service
        .launch_accepted_scheduled_execution(&scope, task_id, execution_id)
        .await
        .map_err(|error| format!("failed to recover accepted schedule fire: {error}"))?;
    Ok(())
}

async fn sync_v3_task_scheduler_registrations(
    scheduler: &magician::magician_v2::storage::task_scheduler::TaskSchedulerService,
    known_task_ids: &mut HashSet<String>,
    artifact_v2_service: &Arc<ArtifactV2Service>,
) -> Result<usize, String> {
    let registrations = artifact_v2_service
        .list_scheduled_tasks_across_scopes()
        .await
        .map_err(|error| format!("failed to list scheduled V3 tasks: {}", error))?;
    let current_ids = registrations
        .iter()
        .map(|entry| entry.task_id.clone())
        .collect::<HashSet<_>>();

    for task_id in known_task_ids.difference(&current_ids) {
        scheduler.unregister_task(task_id);
    }
    for entry in &registrations {
        if let Some(execution_id) = entry.active_schedule_execution_id.as_deref() {
            scheduler.unregister_task(&entry.task_id);
            if let Err(error) = artifact_v2_service
                .launch_accepted_scheduled_execution(&entry.scope, &entry.task_id, execution_id)
                .await
            {
                warn!(
                    task_id = %entry.task_id,
                    execution_id = %execution_id,
                    error = %error,
                    "Task scheduler: accepted execution recovery launch failed"
                );
            }
            continue;
        }
        let registration = match &entry.schedule_kind {
            magician::magician_v2::storage::TaskScheduleKind::Cron { expression, .. } => {
                scheduler.register_task(&entry.task_id, expression)
            },
            magician::magician_v2::storage::TaskScheduleKind::Once { at } => {
                scheduler.register_once_task(&entry.task_id, *at)
            },
            magician::magician_v2::storage::TaskScheduleKind::Interval { .. }
            | magician::magician_v2::storage::TaskScheduleKind::OnEvent { .. } => continue,
        };
        if let Err(error) = registration {
            warn!(
                task_id = %entry.task_id,
                principal = %entry.scope.principal(),
                workspace = %entry.scope.workspace(),
                error = %error,
                "Task scheduler: failed to register V3 task schedule"
            );
        }
    }

    *known_task_ids = current_ids;
    Ok(registrations.len())
}

#[allow(clippy::too_many_arguments)]
async fn create_task_backed_execution_shell(
    artifact_v2_service: &ArtifactV2Service,
    orchestrator: &Arc<MagicianV2Orchestrator>,
    principal: &str,
    workspace: &str,
    ui_thread_id: &str,
    title: Option<&str>,
    description_hint: Option<&str>,
    active_owner_agent_id: &str,
    created_by: magician::magician_v2::storage::TaskCreatedBy,
    debug_run: bool,
    internal: bool,
    // Threaded rather than dropped. This is the planning-backed twin of the
    // direct root run, and a request that named its work must not lose that
    // confinement just because it did not set `skip_planning` — a run the
    // caller believes is bound and is not is the one failure mode nothing
    // downstream can detect.
    work: Option<&magician::magician_v2::work_context::WorkContextKind>,
) -> Result<(String, String, String), String> {
    let description = description_hint
        .map(str::trim)
        .filter(|value| !value.is_empty())
        .map(ToOwned::to_owned)
        .or_else(|| {
            title
                .map(str::trim)
                .filter(|value| !value.is_empty())
                .map(ToOwned::to_owned)
        })
        .unwrap_or_else(|| "Execution shell".to_string());

    // Debug and explicitly-internal execution shells stay out of the user's
    // durable task commitments. This shell intentionally remains dormant
    // until the accepted-launch intent is durable.
    let lifecycle = if debug_run || internal {
        magician::magician_v2::artifact_v2::models::TaskLifecycle::Internal
    } else {
        magician::magician_v2::artifact_v2::models::TaskLifecycle::default()
    };
    let created_by = if debug_run {
        "__system__".to_owned()
    } else {
        legacy_task_created_by_to_v3(&created_by)
    };

    let input = CreateTaskInput {
        principal: principal.to_string(),
        workspace: workspace.to_string(),
        ui_thread_id: ui_thread_id.to_string(),
        title: direct_root_task_title(title, &description),
        description,
        agent_id: active_owner_agent_id.to_string(),
        goal_id: None,
        priority: None,
        due_date: None,
        tags: Vec::new(),
        created_by,
        depends_on: Vec::new(),
        approved: true,
        schedule: None,
        output_mode: magician::magician_v2::artifact_v2::models::TaskOutputMode::Accumulate,
        chat_session_id: None,
        lifecycle,
        sync_mode: magician::magician_v2::artifact_v2::models::TaskSyncMode::default(),
    };
    create_v3_task_execution_shell_under_work(artifact_v2_service, orchestrator, input, work).await
}

/// Sanitize an identifier into a safe `ui_thread_id` component: keep ASCII
/// alphanumerics, `_` and `-`; map every other character (scope `:` separators,
/// whitespace, slashes, …) to `-`. Never returns empty, so an oddly-shaped
/// agent_id can never form an invalid thread id for the V3 task shell.
fn sanitize_thread_id_component(raw: &str) -> String {
    let mut out = String::with_capacity(raw.len());
    for ch in raw.chars() {
        if ch.is_ascii_alphanumeric() || ch == '_' || ch == '-' {
            out.push(ch);
        } else {
            out.push('-');
        }
    }
    if out.is_empty() {
        out.push_str("agent");
    }
    out
}

async fn ensure_dispatch_task_backed_root(
    agent_api: &AgentApiServices,
    v2_orchestrator: &Arc<MagicianV2Orchestrator>,
    dispatch: &mut ManualTriggerDispatch,
    execution_goal: &str,
) -> Result<String, String> {
    let owned_agent_api = agent_api.clone();
    let owned_orchestrator = Arc::clone(v2_orchestrator);
    let mut owned_dispatch = dispatch.clone();
    let owned_execution_goal = execution_goal.to_string();
    let principal = owned_dispatch.principal.clone();
    let workspace = owned_dispatch.workspace.clone();
    let mut jobs = tokio::task::JoinSet::new();
    jobs.spawn(async move {
        // Both futures are boxed to keep this task's stack frame small. An
        // `async fn` holds its callee's state machine inline, and measured at a
        // stack overflow in the P3-14 integration test this chain
        // (`with_secret_scope` + `_inner` + the task-shell factory below it)
        // was ~450 KiB of a 1.29 MiB stack. Provisioning a task-backed root is
        // a once-per-dispatch path, so two allocations are not worth counting.
        let result = Box::pin(magician::magician_v2::secrets::with_secret_scope(
            &principal,
            &workspace,
            Box::pin(ensure_dispatch_task_backed_root_inner(
                &owned_agent_api,
                &owned_orchestrator,
                &mut owned_dispatch,
                &owned_execution_goal,
            )),
        ))
        .await;
        result.map(|execution_id| (execution_id, owned_dispatch))
    });
    let (execution_id, updated_dispatch) = jobs
        .join_next()
        .await
        .ok_or_else(|| "task-backed root provisioning task disappeared".to_string())?
        .map_err(|error| format!("task-backed root provisioning task failed to join: {error}"))??;
    *dispatch = updated_dispatch;
    Ok(execution_id)
}

async fn ensure_dispatch_task_backed_root_inner(
    agent_api: &AgentApiServices,
    v2_orchestrator: &Arc<MagicianV2Orchestrator>,
    dispatch: &mut ManualTriggerDispatch,
    execution_goal: &str,
) -> Result<String, String> {
    if let (Some(task_id), Some(execution_id), Some(runtime_execution_id)) = (
        dispatch.task_id.clone(),
        dispatch.execution_id.clone(),
        dispatch.runtime_execution_id.clone(),
    ) {
        let _ = (task_id, execution_id);
        return Ok(runtime_execution_id);
    }

    let artifact_v2_service = resolve_artifact_v2_service(&agent_api.runtime)?;
    let principal = dispatch.principal.clone();
    let workspace = dispatch.workspace.clone();
    let input = CreateTaskInput {
        principal: principal.clone(),
        workspace: workspace.clone(),
        ui_thread_id: format!("agent-{}", sanitize_thread_id_component(&dispatch.agent_id)),
        title: cycle_dispatch_task_title(dispatch),
        description: execution_goal.to_string(),
        agent_id: dispatch.agent_id.clone(),
        goal_id: Some(dispatch.goal_id.clone()),
        priority: None,
        due_date: None,
        tags: Vec::new(),
        created_by: legacy_task_created_by_to_v3(&cycle_dispatch_created_by(dispatch)),
        depends_on: Vec::new(),
        approved: true,
        schedule: None,
        output_mode: magician::magician_v2::artifact_v2::models::TaskOutputMode::Accumulate,
        chat_session_id: None,
        lifecycle: magician::magician_v2::artifact_v2::models::TaskLifecycle::Internal,
        sync_mode: magician::magician_v2::artifact_v2::models::TaskSyncMode::default(),
    };
    let (task_id, execution_id, runtime_execution_id) =
        create_v3_task_execution_shell_boxed(artifact_v2_service.as_ref(), v2_orchestrator, input)
            .await
            .map_err(|error| format!("failed to create V3 cycle task: {}", error))?;

    let mut bound = agent_api
        .runtime
        .bind_active_cycle_execution_id_in_scope(
            Some(&dispatch.principal),
            Some(&dispatch.workspace),
            &dispatch.agent_id,
            &dispatch.goal_id,
            &dispatch.cycle_id,
            &runtime_execution_id,
        )
        .await;
    if !bound {
        // Branch C: the active reservation may have been promoted to a fresh
        // cycle_id for this SAME trigger (ties into Branch A's single-in-flight
        // dedupe). Retry the bind once against the promoted reservation before
        // failing — but only when it is genuinely the same trigger identity
        // (goal + trigger + trigger_seq), never a different trigger.
        if let Some(active) = agent_api
            .runtime
            .active_cycle_in_scope(
                Some(&dispatch.principal),
                Some(&dispatch.workspace),
                &dispatch.agent_id,
                &dispatch.goal_id,
            )
            .await
        {
            if active.cycle_id != dispatch.cycle_id
                && active.goal_id == dispatch.goal_id
                && active.trigger == dispatch.trigger
                && active.trigger_seq == dispatch.trigger_seq
                && agent_api
                    .runtime
                    .bind_active_cycle_execution_id_in_scope(
                        Some(&dispatch.principal),
                        Some(&dispatch.workspace),
                        &dispatch.agent_id,
                        &dispatch.goal_id,
                        &active.cycle_id,
                        &runtime_execution_id,
                    )
                    .await
            {
                dispatch.cycle_id = active.cycle_id.clone();
                bound = true;
            }
        }
    }
    if !bound {
        let _ = artifact_v2_service
            .archive_task_with_options(&scope_ref(&principal, &workspace), &task_id, true)
            .await;
        return Err(format!(
            "active cycle reservation changed before execution {} could be bound to {}",
            runtime_execution_id, dispatch.cycle_id
        ));
    }

    if let Err(error) = artifact_v2_service
        .activate_execution(&scope_ref(&principal, &workspace), &task_id, &execution_id)
        .await
    {
        let _ = artifact_v2_service
            .update_task_status(&scope_ref(&principal, &workspace), &task_id, "failed")
            .await;
        return Err(format!(
            "failed to activate V3 cycle task execution for {}: {}",
            task_id, error
        ));
    }

    dispatch.task_id = Some(task_id);
    dispatch.execution_id = Some(execution_id);
    dispatch.runtime_execution_id = Some(runtime_execution_id.clone());
    Ok(runtime_execution_id)
}

async fn execution_goal_for_manual_dispatch(
    agent_api: &AgentApiServices,
    dispatch: &ManualTriggerDispatch,
) -> Result<String, PromptPipelineError> {
    let owned_agent_api = agent_api.clone();
    let owned_dispatch = dispatch.clone();
    let principal = owned_dispatch.principal.clone();
    let workspace = owned_dispatch.workspace.clone();
    let mut jobs = tokio::task::JoinSet::new();
    jobs.spawn(async move {
        magician::magician_v2::secrets::with_secret_scope(
            &principal,
            &workspace,
            execution_goal_for_manual_dispatch_inner(&owned_agent_api, &owned_dispatch),
        )
        .await
    });
    jobs.join_next()
        .await
        .ok_or_else(|| PromptPipelineError::SourceResolution {
            source_ref: "manual_dispatch".to_string(),
            reason: "prompt assembly task disappeared".to_string(),
        })?
        .map_err(|error| PromptPipelineError::SourceResolution {
            source_ref: "manual_dispatch".to_string(),
            reason: format!("prompt assembly task failed to join: {error}"),
        })?
}

async fn execution_goal_for_manual_dispatch_inner(
    agent_api: &AgentApiServices,
    dispatch: &ManualTriggerDispatch,
) -> Result<String, PromptPipelineError> {
    let strategy_hint = if dispatch.strategy_hint_enabled {
        dispatch.strategy_summary.trim()
    } else {
        ""
    };
    let Some(prompt_pipeline) = dispatch.definition.prompt_pipeline.as_ref() else {
        if strategy_hint.is_empty() {
            return Ok(dispatch.goal_description.clone());
        }
        return Ok(format!(
            "{}\n\nStrategy Preference:\n{}",
            dispatch.goal_description.trim(),
            strategy_hint
        ));
    };

    // P6-T3: Consume feedback injections from previous cycle.
    let feedback_injections = agent_api
        .runtime
        .take_feedback_injections(&dispatch.agent_id)
        .await;
    let memory_service = agent_api.resolve_memory_service(
        Some(dispatch.principal.as_str()),
        Some(dispatch.workspace.as_str()),
    );
    let memory_tier_interpreter = agent_api.resolve_memory_tier_interpreter(
        Some(dispatch.principal.as_str()),
        Some(dispatch.workspace.as_str()),
    );

    let runtime_inputs = PromptPipelineRuntimeInputs {
        definition: &dispatch.definition,
        agent_id: &dispatch.agent_id,
        triggered_goal_id: &dispatch.goal_id,
        memory_service: &memory_service,
        memory_tier_interpreter: &memory_tier_interpreter,
        feedback_injections,
    };

    let context = agent_api
        .prompt_pipeline_interpreter
        .assemble_runtime(prompt_pipeline, &runtime_inputs)
        .await?;

    if context.trim().is_empty() {
        if dispatch.workflow_inputs.is_empty() && strategy_hint.is_empty() {
            let mut goal = dispatch.goal_description.clone();
            append_harness_program_context(agent_api, dispatch, &mut goal).await;
            return Ok(goal);
        }
        let mut assembled = dispatch.goal_description.trim().to_string();
        if !strategy_hint.is_empty() {
            assembled.push_str("\n\nStrategy Preference:\n");
            assembled.push_str(strategy_hint);
        }
        append_harness_program_context(agent_api, dispatch, &mut assembled).await;
        if !dispatch.workflow_inputs.is_empty() {
            let rendered_inputs = serde_json::to_string_pretty(&dispatch.workflow_inputs)
                .unwrap_or_else(|_| "{}".to_string());
            assembled.push_str("\n\nWorkflow Inputs:\n");
            assembled.push_str(&rendered_inputs);
        }
        return Ok(assembled);
    }

    let mut assembled = format!("Goal: {}", dispatch.goal_description.trim());
    if !strategy_hint.is_empty() {
        assembled.push_str("\n\nStrategy Preference:\n");
        assembled.push_str(strategy_hint);
    }
    append_harness_program_context(agent_api, dispatch, &mut assembled).await;
    assembled.push_str("\n\n");
    assembled.push_str(&context);
    if !dispatch.workflow_inputs.is_empty() {
        let rendered_inputs = serde_json::to_string_pretty(&dispatch.workflow_inputs)
            .unwrap_or_else(|_| "{}".to_string());
        assembled.push_str("\n\n## workflow_inputs\n");
        assembled.push_str(&rendered_inputs);
    }
    Ok(assembled)
}

/// Run a git subcommand in `root`, returning trimmed stdout on success (best-effort).
async fn run_harness_git(root: &std::path::Path, args: &[&str]) -> Option<String> {
    let output = time::timeout(StdDuration::from_secs(2), async {
        tokio::process::Command::new("git")
            .arg("-C")
            .arg(root)
            .args(args)
            .output()
            .await
    })
    .await
    .ok()?
    .ok()?;
    output
        .status
        .success()
        .then(|| String::from_utf8_lossy(&output.stdout).trim().to_string())
}

/// Best-effort snapshot of the live magician repo for harness cycle prompts:
/// current branch, uncommitted-file count, and the last few commits. Returns
/// None when the live repo can't be located (e.g. a data-only deployment) or
/// git isn't available — we do NOT probe the process cwd, so an unrelated repo
/// the server happens to sit inside is never surfaced to the C-suite prompt.
async fn harness_repo_state_block() -> Option<String> {
    let (root, _) = magician::magician_v2::execution::coding_engine::live_repo_source_fence()?;
    let branch = run_harness_git(&root, &["rev-parse", "--abbrev-ref", "HEAD"]).await?;
    let commits = run_harness_git(&root, &["log", "--oneline", "-5"])
        .await
        .unwrap_or_default();
    let dirty = run_harness_git(&root, &["status", "--short"])
        .await
        .map(|s| s.lines().filter(|line| !line.trim().is_empty()).count())
        .unwrap_or(0);
    Some(format!(
        "branch: {branch}\n{dirty} uncommitted file(s)\nrecent commits:\n{commits}"
    ))
}

async fn append_harness_program_context(
    agent_api: &AgentApiServices,
    dispatch: &ManualTriggerDispatch,
    assembled: &mut String,
) {
    // Deterministic program context is only assembled for harness-enabled
    // personal agents (the C-suite / owner agents that run the meta-harness).
    if dispatch.definition.kind != magician::magician_v2::agents::types::AgentKind::Personal
        || dispatch.definition.harness.is_none()
    {
        return;
    }

    let loader = magician::magician_v2::harness::ProgramLoader::new(
        agent_api.durable_artifact_workspace.clone(),
    );
    let program = match loader
        .load_for_goal(
            &dispatch.principal,
            &dispatch.workspace,
            &dispatch.definition,
            Some(dispatch.goal_id.as_str()),
        )
        .await
    {
        Ok(Some(program)) => program,
        Ok(None) => return,
        Err(error) => {
            warn!(
                agent_id = %dispatch.agent_id,
                goal_id = %dispatch.goal_id,
                principal = %dispatch.principal,
                workspace = %dispatch.workspace,
                error = %error,
                "[API] Failed to load harness program context for manual dispatch"
            );
            if !assembled.trim().is_empty() {
                assembled.push_str("\n\n");
            }
            assembled.push_str("## Program Context\nUnavailable: ");
            assembled.push_str(error.trim());
            return;
        },
    };

    // (a) Deterministic program doc/section content.
    if !assembled.trim().is_empty() {
        assembled.push_str("\n\n");
    }
    assembled.push_str("## Program Context\n");
    if let Some(section) = program.section.as_deref() {
        assembled.push_str(&format!(
            "Source: {} [{}]\n\n",
            program.relative_path, section
        ));
    } else {
        assembled.push_str(&format!("Source: {}\n\n", program.relative_path));
    }
    assembled.push_str(program.content.trim());
    assembled.push_str(
        "\n\n### Harness Progress Contract\n\
         Do not finish a harness cycle with only a narrative briefing when a concrete \
         next action is available. Use the harness tools to create/promote assigned \
         work, update durable program state, draft a reviewable proposal, or escalate \
         a real blocker. Harness-created and promoted tasks start execution by default; \
         use `start_immediately=false` only when deliberately parking tracked work.",
    );

    // (a.1) Boundary D — versioned supplemental guidance, if any has been
    // approved for this program. Read here rather than stored and admired:
    // an evidence-gated revision that never reaches a cycle prompt changes
    // nothing, which is the failure mode this boundary was built to avoid.
    // It sits after the program doc and before runtime state deliberately —
    // it supplements the program, and can never replace it.
    match load_harness_supplemental_profile(
        agent_api,
        &dispatch.principal,
        &dispatch.workspace,
        &program.relative_path,
    )
    .await
    {
        Ok(Some(profile)) => {
            if let Some(block) = profile.render_block() {
                assembled.push_str("\n\n");
                assembled.push_str(&block);
            }
        },
        Ok(None) => {},
        Err(error) => {
            // Guidance is an enhancement; a cycle without it is degraded, not
            // broken. Never block the prompt on it.
            warn!(
                agent_id = %dispatch.agent_id,
                goal_id = %dispatch.goal_id,
                error = %error,
                "[API] Failed to load supplemental harness guidance for program context"
            );
        },
    }

    // (b) Prior runtime state (current_phase / current_step / open_loops /
    // next_action_hints / last_run_summary / stop_conditions). Calling
    // `load_or_create_runtime_state` here also guarantees the
    // `programs/state/<file>.json` exists from cycle 1, so the loop's evolving
    // memory has a durable home even before any update is applied.
    match loader
        .load_or_create_runtime_state(
            &dispatch.principal,
            &dispatch.workspace,
            &program,
            Some(dispatch.goal_id.as_str()),
        )
        .await
    {
        Ok(state) => {
            if let Some(block) = render_program_runtime_state_block(&state) {
                assembled.push_str("\n\n### Runtime State\n");
                assembled.push_str(&block);
            }
        },
        Err(error) => {
            warn!(
                agent_id = %dispatch.agent_id,
                goal_id = %dispatch.goal_id,
                error = %error,
                "[API] Failed to load/create harness runtime state for program context"
            );
        },
    }

    // (b.1) Surface this agent's OWN open anomalies so the cycle can act on the
    // failures it caused/hit. Best-effort and deterministic: a missing dir or a
    // list error is ignored here and later reflected in the scope-wide health
    // block where useful; it never blocks the cycle prompt.
    let anomaly_store = magician::magician_v2::harness::AnomalyStore::new(
        agent_api.durable_artifact_workspace.clone(),
    );
    if let Ok(anomalies) = anomaly_store.list(&dispatch.principal, &dispatch.workspace) {
        let open_for_agent: Vec<&magician::magician_v2::harness::HarnessAnomaly> = anomalies
            .iter()
            .filter(|a| a.agent_id == dispatch.agent_id && a.status_wire() == "open")
            .take(5)
            .collect();
        if !open_for_agent.is_empty() {
            assembled.push_str("\n\n### Anomalies caught (open)\n");
            for a in &open_for_agent {
                assembled.push_str(&format!(
                    "- {:?} · {} (×{})\n",
                    a.kind, a.summary, a.occurrences
                ));
            }
        }
    }

    // (b.2) Surface scope-wide harness health so reliability-focused harness
    // agents can act on scheduler/backlog/anomaly stalls without first
    // rediscovering where the evidence lives.
    if let Some(block) = harness_health_block(agent_api, dispatch).await {
        assembled.push_str("\n\n### Harness Health\n");
        assembled.push_str(&block);
    }

    // (b.3) Surface the OPEN company backlog (all agents' proposals, scope-wide)
    // so the CTO/CPO can groom and promote directives. Best-effort: a missing dir
    // or list error is ignored and never blocks the cycle prompt.
    let backlog_store = magician::magician_v2::harness::BacklogStore::new(
        agent_api.durable_artifact_workspace.clone(),
    );
    if let Ok(items) = backlog_store.list(&dispatch.principal, &dispatch.workspace) {
        let mut proposed: Vec<&magician::magician_v2::harness::BacklogItem> = items
            .iter()
            .filter(|item| item.status_wire() == "proposed")
            .collect();
        // Surface owner-directed (cross-owner-requested) items FIRST so a request never
        // falls outside the take(8) window and silently rots. Stable sort preserves the
        // list()'s priority/recency order within each group.
        proposed.sort_by_key(|item| item.requested_owner_agent.is_none());
        let open: Vec<&magician::magician_v2::harness::BacklogItem> =
            proposed.into_iter().take(8).collect();
        if !open.is_empty() {
            assembled.push_str("\n\n### Company Backlog (open)\n");
            for item in &open {
                // Surface a cross-owner promotion request so the target agent's owner can
                // act on it (a sibling officer flagged this item for an agent outside its
                // own scope; only the owner whose scope contains that agent can promote it).
                let owner_request = match (&item.requested_owner_agent, &item.requested_by_officer)
                {
                    (Some(agent), Some(by)) => format!(
                        " [→ requested for `{agent}` by `{by}`: if `{agent}` is one of your agents, promote this item in your scope]"
                    ),
                    (Some(agent), _) => format!(
                        " [→ requested for `{agent}`: if `{agent}` is one of your agents, promote this item in your scope]"
                    ),
                    _ => String::new(),
                };
                assembled.push_str(&format!(
                    "- [{}] {} — proposed by {} (id {}){}\n",
                    item.priority_wire(),
                    item.title,
                    item.source_agent,
                    item.id,
                    owner_request,
                ));
            }
        }
    }

    // (b.4) Real repository state (branch, dirty count, recent commits) so the
    // technical agents reason against the actual codebase, not a stale model.
    if let Some(block) = harness_repo_state_block().await {
        assembled.push_str("\n\n### Repo State\n");
        assembled.push_str(&block);
    }

    // (c) Live Success Metrics (current values vs. targets), reusing the same
    // evaluation path as the on-demand `evaluate_harness` tool so the model sees
    // its gradient deterministically without having to call the tool.
    match resolve_artifact_v2_service(&agent_api.runtime) {
        Ok(artifact_service) => {
            let harness_services = magician::magician_v2::harness::HarnessServices {
                definition_store: Arc::clone(&agent_api.definition_store),
                memory_resolver: agent_api.memory_resolver.clone(),
                artifact_service,
                runtime: Arc::clone(&agent_api.runtime),
                user_request_service: None,
                control_gate: None,
                scoped_paused_agents: Some(agent_api.paused_agents_index()),
            };
            match magician::magician_v2::execution::harness_provider::render_goal_program_metrics_block(
                &harness_services,
                &dispatch.principal,
                &dispatch.workspace,
                &dispatch.agent_id,
                &dispatch.goal_id,
            )
            .await
            {
                Ok(Some(block)) => {
                    assembled.push_str("\n\n### Success Metrics (live)\n");
                    assembled.push_str(&block);
                },
                Ok(None) => {},
                Err(error) => {
                    warn!(
                        agent_id = %dispatch.agent_id,
                        goal_id = %dispatch.goal_id,
                        error = %error,
                        "[API] Failed to evaluate harness program metrics for program context"
                    );
                },
            }
        },
        Err(error) => {
            warn!(
                agent_id = %dispatch.agent_id,
                goal_id = %dispatch.goal_id,
                error = %error,
                "[API] Harness program metrics unavailable: artifact service not ready"
            );
        },
    }
}

async fn harness_health_block(
    agent_api: &AgentApiServices,
    dispatch: &ManualTriggerDispatch,
) -> Option<String> {
    let mut lines = Vec::new();
    let mut issues = Vec::new();
    let now = Utc::now();

    match agent_api
        .resolve_scheduler(&dispatch.principal, &dispatch.workspace)
        .await
    {
        Ok(scheduler) => {
            let snapshot = match time::timeout(StdDuration::from_secs(2), scheduler.snapshot())
                .await
            {
                Ok(snapshot) => Some(snapshot),
                Err(_) => {
                    issues.push("scheduler snapshot timed out".to_string());
                    lines
                        .push("- scheduler: unavailable (snapshot timed out after 2s)".to_string());
                    None
                },
            };

            if let Some(snapshot) = snapshot {
                let mut harness_entries: Vec<_> = snapshot
                    .entries
                    .values()
                    .filter(|entry| entry.goal_id.starts_with("harness:"))
                    .collect();
                harness_entries.sort_by(|left, right| {
                    left.agent_id
                        .cmp(&right.agent_id)
                        .then_with(|| left.goal_id.cmp(&right.goal_id))
                });

                let mut due_or_missed = Vec::new();
                let mut without_next_run = Vec::new();
                for entry in &harness_entries {
                    if let SchedulerTriggerRegistration::Cron { next_run_at, .. } =
                        &entry.registration
                    {
                        match next_run_at {
                            Some(next_run_at) if *next_run_at <= now => {
                                due_or_missed.push(format!(
                                    "{} / {} next_run_at={}",
                                    entry.agent_id,
                                    entry.goal_id,
                                    next_run_at.to_rfc3339()
                                ));
                            },
                            Some(_) => {},
                            None => {
                                without_next_run
                                    .push(format!("{} / {}", entry.agent_id, entry.goal_id));
                            },
                        }
                    }
                }

                lines.push(format!(
                    "- scheduler: {} harness goal(s), {} due/missed, {} without next_run_at",
                    harness_entries.len(),
                    due_or_missed.len(),
                    without_next_run.len()
                ));
                if harness_entries.is_empty() {
                    issues.push("no harness scheduler entries registered".to_string());
                }
                if !due_or_missed.is_empty() {
                    issues.push(format!(
                        "{} harness goal(s) due or missed",
                        due_or_missed.len()
                    ));
                    lines.push("- due/missed goals:".to_string());
                    for item in due_or_missed.iter().take(5) {
                        lines.push(format!("    - {item}"));
                    }
                }
                if !without_next_run.is_empty() {
                    issues.push(format!(
                        "{} harness cron goal(s) missing next_run_at",
                        without_next_run.len()
                    ));
                    lines.push("- cron goals without next_run_at:".to_string());
                    for item in without_next_run.iter().take(5) {
                        lines.push(format!("    - {item}"));
                    }
                }
            }
        },
        Err(error) => {
            issues.push("scheduler snapshot unavailable".to_string());
            lines.push(format!(
                "- scheduler: unavailable ({})",
                compact_harness_health_detail(&error.to_string())
            ));
        },
    }

    let anomaly_store = magician::magician_v2::harness::AnomalyStore::new(
        agent_api.durable_artifact_workspace.clone(),
    );
    match anomaly_store.list(&dispatch.principal, &dispatch.workspace) {
        Ok(anomalies) => {
            let open_count = anomalies
                .iter()
                .filter(|item| item.status == magician::magician_v2::harness::AnomalyStatus::Open)
                .count();
            let fix_dispatched_count = anomalies
                .iter()
                .filter(|item| {
                    item.status == magician::magician_v2::harness::AnomalyStatus::FixDispatched
                })
                .count();
            let open_anomalies: Vec<_> = anomalies
                .iter()
                .filter(|item| item.status == magician::magician_v2::harness::AnomalyStatus::Open)
                .collect();
            let artifact_service = resolve_artifact_v2_service(&agent_api.runtime).ok();
            let scope = ScopeRef::system_internal_unauthenticated(
                &dispatch.principal.clone(),
                &dispatch.workspace.clone(),
            );
            let mut fix_dispatches_needing_attention = Vec::new();
            for item in anomalies.iter().filter(|item| {
                item.status == magician::magician_v2::harness::AnomalyStatus::FixDispatched
            }) {
                let old_enough = item.last_fix_dispatch_at.as_ref().map_or(true, |seen| {
                    now.signed_duration_since(*seen) >= chrono::Duration::minutes(90)
                });
                if !old_enough {
                    continue;
                }

                let Some(task_id) = item
                    .fix_task_id
                    .as_deref()
                    .map(str::trim)
                    .filter(|value| !value.is_empty())
                else {
                    fix_dispatches_needing_attention.push(format!(
                        "{} / {} / {} fix_task_id=missing last_fix_dispatch_at={}",
                        item.agent_id,
                        item.goal_id,
                        item.signature,
                        item.last_fix_dispatch_at
                            .as_ref()
                            .map(|value| value.to_rfc3339())
                            .unwrap_or_else(|| "missing".to_string())
                    ));
                    continue;
                };

                let Some(artifact_service) = artifact_service.as_ref() else {
                    fix_dispatches_needing_attention.push(format!(
                        "{} / {} / {} fix_task_id={} task_status=unavailable",
                        item.agent_id, item.goal_id, item.signature, task_id
                    ));
                    continue;
                };

                match time::timeout(
                    StdDuration::from_secs(2),
                    artifact_service.get_task(&scope, task_id),
                )
                .await
                {
                    Ok(Ok(task)) => match task.state.status.as_str() {
                        "completed" => fix_dispatches_needing_attention.push(format!(
                            "{} / {} / {} fix_task_id={} task_status=completed needs_resolution_review",
                            item.agent_id, item.goal_id, item.signature, task_id
                        )),
                        "running" | "planning" => fix_dispatches_needing_attention.push(format!(
                            "{} / {} / {} fix_task_id={} task_status={} older_than=90m",
                            item.agent_id,
                            item.goal_id,
                            item.signature,
                            task_id,
                            task.state.status
                        )),
                        status => fix_dispatches_needing_attention.push(format!(
                            "{} / {} / {} fix_task_id={} task_status={}",
                            item.agent_id, item.goal_id, item.signature, task_id, status
                        )),
                    },
                    Ok(Err(error)) => fix_dispatches_needing_attention.push(format!(
                        "{} / {} / {} fix_task_id={} task_read_error={}",
                        item.agent_id,
                        item.goal_id,
                        item.signature,
                        task_id,
                        compact_harness_health_detail(&error.to_string())
                    )),
                    Err(_) => fix_dispatches_needing_attention.push(format!(
                        "{} / {} / {} fix_task_id={} task_read_timeout=2s",
                        item.agent_id, item.goal_id, item.signature, task_id
                    )),
                }
            }
            lines.push(format!(
                "- anomalies: {open_count} open, {fix_dispatched_count} fix dispatched, {} repair dispatch(es) need attention",
                fix_dispatches_needing_attention.len()
            ));
            if open_count > 0 {
                issues.push(format!("{open_count} open harness anomaly/anomalies"));
                lines.push("- open anomalies:".to_string());
                for item in open_anomalies.iter().take(5) {
                    lines.push(format!(
                        "    - {} / {} / {} — {} (x{})",
                        item.agent_id, item.goal_id, item.signature, item.summary, item.occurrences
                    ));
                }
            }
            if !fix_dispatches_needing_attention.is_empty() {
                issues.push(format!(
                    "{} anomaly repair dispatch(es) need attention",
                    fix_dispatches_needing_attention.len()
                ));
                lines.push("- repair dispatches needing attention:".to_string());
                for item in fix_dispatches_needing_attention.iter().take(5) {
                    lines.push(format!("    - {item}"));
                }
            }
        },
        Err(error) => {
            issues.push("anomaly store unavailable".to_string());
            lines.push(format!(
                "- anomalies: unavailable ({})",
                compact_harness_health_detail(&error.to_string())
            ));
        },
    }

    let backlog_store = magician::magician_v2::harness::BacklogStore::new(
        agent_api.durable_artifact_workspace.clone(),
    );
    match backlog_store.list(&dispatch.principal, &dispatch.workspace) {
        Ok(items) => {
            let proposed_count = items
                .iter()
                .filter(|item| {
                    item.status == magician::magician_v2::harness::BacklogStatus::Proposed
                })
                .count();
            let promoted_count = items
                .iter()
                .filter(|item| {
                    item.status == magician::magician_v2::harness::BacklogStatus::Promoted
                })
                .count();
            let delivered_count = items
                .iter()
                .filter(|item| {
                    item.status == magician::magician_v2::harness::BacklogStatus::Delivered
                })
                .count();
            let promoted_without_task: Vec<_> = items
                .iter()
                .filter(|item| {
                    item.status == magician::magician_v2::harness::BacklogStatus::Promoted
                        && item
                            .promoted_task_id
                            .as_deref()
                            .map(str::trim)
                            .filter(|value| !value.is_empty())
                            .is_none()
                })
                .map(|item| (item.id.clone(), item.title.clone()))
                .collect();

            let artifact_service = resolve_artifact_v2_service(&agent_api.runtime).ok();
            let scope = ScopeRef::system_internal_unauthenticated(
                &dispatch.principal.clone(),
                &dispatch.workspace.clone(),
            );
            let promoted_with_task: Vec<_> = items
                .iter()
                .filter(|item| {
                    item.status == magician::magician_v2::harness::BacklogStatus::Promoted
                })
                .filter_map(|item| {
                    item.promoted_task_id
                        .as_deref()
                        .map(str::trim)
                        .filter(|task_id| !task_id.is_empty())
                        .map(|task_id| (item.id.clone(), item.title.clone(), task_id.to_string()))
                })
                .collect();
            let mut deliveries_needing_review = Vec::new();
            let task_checks = if let Some(artifact_service) = artifact_service {
                stream::iter(promoted_with_task.into_iter())
                    .map(|(item_id, title, task_id)| {
                        let artifact_service = Arc::clone(&artifact_service);
                        let scope = scope.clone();
                        async move {
                            let result = time::timeout(
                                StdDuration::from_secs(2),
                                artifact_service.get_task(&scope, &task_id),
                            )
                            .await;
                            (item_id, title, task_id, result)
                        }
                    })
                    .buffer_unordered(4)
                    .collect::<Vec<_>>()
                    .await
            } else {
                for (item_id, title, task_id) in promoted_with_task {
                    deliveries_needing_review.push(format!(
                        "{} / {} / task={} status=unavailable: artifact service not ready",
                        item_id, title, task_id
                    ));
                }
                Vec::new()
            };
            for (item_id, title, task_id, result) in task_checks {
                match result {
                    Ok(Ok(task)) => {
                        let status = task.state.status.trim().to_ascii_lowercase();
                        match status.as_str() {
                            "completed" => deliveries_needing_review.push(format!(
                                "{item_id} / {title} / task={task_id} status=completed delivery_review=pending"
                            )),
                            "failed" | "cancelled" | "canceled" | "ready" => {
                                deliveries_needing_review.push(format!(
                                    "{item_id} / {title} / task={task_id} status={status} delivery_review=pending"
                                ));
                            },
                            "running" | "planning" | "paused" | "pending" | "deferred" => {},
                            other => deliveries_needing_review.push(format!(
                                "{item_id} / {title} / task={task_id} status={other} delivery_review=pending"
                            )),
                        }
                    },
                    Ok(Err(error)) => deliveries_needing_review.push(format!(
                        "{item_id} / {title} / task={task_id} read_error={}",
                        compact_harness_health_detail(&error.to_string())
                    )),
                    Err(_) => deliveries_needing_review.push(format!(
                        "{item_id} / {title} / task={task_id} read_timeout=2s"
                    )),
                }
            }
            lines.push(format!(
                "- backlog: {proposed_count} proposed, {promoted_count} promoted, {delivered_count} delivered, {} missing task id, {} delivery review(s) pending",
                promoted_without_task.len(),
                deliveries_needing_review.len()
            ));
            if !promoted_without_task.is_empty() {
                issues.push(format!(
                    "{} promoted backlog item(s) missing task linkage",
                    promoted_without_task.len()
                ));
                lines.push("- promoted backlog items missing task linkage:".to_string());
                for (item_id, title) in promoted_without_task.iter().take(5) {
                    lines.push(format!("    - {item_id} / {title}"));
                }
            }
            if !deliveries_needing_review.is_empty() {
                issues.push(format!(
                    "{} promoted backlog delivery/deliveries need outcome review",
                    deliveries_needing_review.len()
                ));
                lines.push("- promoted deliveries needing review:".to_string());
                for item in deliveries_needing_review.iter().take(8) {
                    lines.push(format!("    - {item}"));
                }
            }
        },
        Err(error) => {
            issues.push("backlog store unavailable".to_string());
            lines.push(format!(
                "- backlog: unavailable ({})",
                compact_harness_health_detail(&error.to_string())
            ));
        },
    }

    if lines.is_empty() {
        return None;
    }

    if issues.is_empty() {
        lines.push("- reliability read: healthy".to_string());
    } else {
        lines.push("- reliability read: needs attention".to_string());
        lines.push("- priority checks:".to_string());
        for issue in issues.iter().take(6) {
            lines.push(format!("    - {issue}"));
        }
    }

    Some(lines.join("\n"))
}

fn compact_harness_health_detail(value: &str) -> String {
    let compacted = value
        .trim()
        .split_whitespace()
        .collect::<Vec<_>>()
        .join(" ");
    if compacted.chars().count() <= 180 {
        return compacted;
    }
    let mut truncated = compacted.chars().take(177).collect::<String>();
    truncated.push_str("...");
    truncated
}

/// Render the durable runtime-state fields of a harness program into a compact,
/// deterministic block for the cycle prompt. Returns `None` when the state has
/// no populated fields worth surfacing.
/// Boundary D: load the approved supplemental guidance for one program.
///
/// `Ok(None)` when a program has none, which is the ordinary case and not a
/// problem — the file only exists once a revision has been approved and
/// applied. Stored beside the program's runtime state so a scope's harness
/// artifacts stay in one place, and keyed by the program's own path so
/// guidance written for one program can never be read into another.
async fn load_harness_supplemental_profile(
    agent_api: &AgentApiServices,
    principal: &str,
    workspace: &str,
    program_relative_path: &str,
) -> Result<Option<magician::magician_v2::harness::HarnessSupplementalProfile>, String> {
    // The store that applies revisions spells this path through the same
    // helper; a reader with its own spelling reads a file nobody writes.
    let path = agent_api
        .durable_artifact_workspace
        .programs_supplemental_profile_path(principal, workspace, program_relative_path);
    let exists = agent_api
        .durable_artifact_workspace
        .exists_path(&path)
        .await
        .map_err(|error| error.to_string())?;
    if !exists {
        return Ok(None);
    }
    let profile: magician::magician_v2::harness::HarnessSupplementalProfile = agent_api
        .durable_artifact_workspace
        .read_json_bounded_stream_path(&path, 1024 * 1024, 16, 100_000)
        .await
        .map_err(|error| error.to_string())?;
    // Guidance written for another scope or another program is not this
    // cycle's to read, however it got onto disk.
    if profile.principal != principal
        || profile.workspace != workspace
        || profile.program_relative_path != program_relative_path
    {
        return Err(format!(
            "supplemental profile at {} belongs to a different scope or program",
            path.display()
        ));
    }
    Ok(Some(profile))
}

fn render_program_runtime_state_block(
    state: &magician::magician_v2::harness::ProgramRuntimeState,
) -> Option<String> {
    let mut lines = Vec::new();
    if let Some(phase) = state
        .current_phase
        .as_deref()
        .map(str::trim)
        .filter(|value| !value.is_empty())
    {
        lines.push(format!("- current_phase: {phase}"));
    }
    if let Some(step) = state
        .current_step
        .as_deref()
        .map(str::trim)
        .filter(|value| !value.is_empty())
    {
        lines.push(format!("- current_step: {step}"));
    }
    if !state.open_loops.is_empty() {
        lines.push(format!("- open_loops ({}):", state.open_loops.len()));
        for item in state.open_loops.iter().take(8) {
            lines.push(format!("    - {}", summarize_program_state_value(item)));
        }
    }
    if !state.next_action_hints.is_empty() {
        lines.push("- next_action_hints:".to_string());
        for hint in state.next_action_hints.iter().take(8) {
            lines.push(format!("    - {}", hint.trim()));
        }
    }
    if let Some(summary) = state.last_run_summary.as_ref() {
        lines.push(format!(
            "- last_run_summary: {}",
            summarize_program_state_value(summary)
        ));
    }
    if let Some(blocked) = state.blocked.as_ref() {
        lines.push(format!(
            "- blocked: {}",
            summarize_program_state_value(blocked)
        ));
    }
    if !state.stop_conditions.is_empty() {
        lines.push(format!(
            "- stop_conditions ({}):",
            state.stop_conditions.len()
        ));
        for condition in state.stop_conditions.iter().take(8) {
            lines.push(format!(
                "    - {}",
                summarize_program_state_value(condition)
            ));
        }
    }
    if lines.is_empty() {
        None
    } else {
        Some(lines.join("\n"))
    }
}

/// Collapse a JSON runtime-state value into a single compact, length-bounded
/// line for prompt injection.
fn summarize_program_state_value(value: &serde_json::Value) -> String {
    let rendered = match value {
        serde_json::Value::String(text) => text.trim().to_string(),
        other => other.to_string(),
    };
    let normalized = rendered.split_whitespace().collect::<Vec<_>>().join(" ");
    if normalized.chars().count() > 240 {
        let truncated: String = normalized.chars().take(237).collect();
        format!("{truncated}...")
    } else {
        normalized
    }
}

#[derive(Debug, Clone)]
struct ResolveProposalImplResult {
    proposal: magician::magician_v2::agents::DefinitionProposal,
    resolved: bool,
    decision: ProposalDecision,
    channel: String,
}

#[cfg(test)]
async fn create_proposal_impl(
    agent_api: &AgentApiServices,
    req: CreateProposalRequest,
) -> Result<magician::magician_v2::agents::DefinitionProposal, HttpResponse> {
    create_proposal_with_store(agent_api, agent_api.definition_store.as_ref(), req).await
}

async fn create_proposal_with_store(
    agent_api: &AgentApiServices,
    definition_store: &AgentDefinitionStore,
    req: CreateProposalRequest,
) -> Result<magician::magician_v2::agents::DefinitionProposal, HttpResponse> {
    ensure_agent_startup_hydrated(agent_api).await?;
    if magician::magician_v2::agents::storage::validate_agent_identifier(&req.agent_id).is_err() {
        return Err(proposal_store_error_response(
            ProposalStoreError::InvalidRequest(
                "agent_id must be a valid agent identifier".to_string(),
            ),
            None,
        ));
    }
    if req.source.trim().is_empty() {
        return Err(proposal_store_error_response(
            ProposalStoreError::InvalidRequest("source must not be empty".to_string()),
            None,
        ));
    }
    if req.yaml_before.trim().is_empty() {
        return Err(proposal_store_error_response(
            ProposalStoreError::InvalidRequest("yaml_before must not be empty".to_string()),
            None,
        ));
    }
    if req.yaml_after.trim().is_empty() {
        return Err(proposal_store_error_response(
            ProposalStoreError::InvalidRequest("yaml_after must not be empty".to_string()),
            None,
        ));
    }

    // Keep proposal create serialized with definition mutations so agent-existence
    // validation and proposal persistence observe a single control window.
    let _control_guard = agent_api.control_gate.lock().await;
    ensure_agent_exists_for_api_with_store(agent_api, definition_store, &req.agent_id).await?;
    let Some((principal, workspace)) = definition_store.current_scope() else {
        return Err(api_error_response(
            StatusCode::UNPROCESSABLE_ENTITY,
            "missing_scope",
            "Proposal creation requires a scoped agent store",
            None,
        ));
    };
    if harness_owner_agent_id_from_source(&req.source).is_some() {
        let parsed = AgentDefinition::from_yaml_str(&req.yaml_after).map_err(|error| {
            proposal_store_error_response(
                ProposalStoreError::InvalidRequest(format!(
                    "harness proposals require `yaml_after` to deserialize to a full agent definition: {error}"
                )),
                None,
            )
        })?;
        validate_harness_structural_proposal(
            definition_store,
            &principal,
            &workspace,
            &req.source,
            &req.payload,
            &req.agent_id,
            &parsed,
        )
        .await
        .map_err(|error| {
            proposal_store_error_response(ProposalStoreError::InvalidRequest(error), None)
        })?;
    }

    let proposal = NewDefinitionProposal {
        agent_id: req.agent_id,
        source: req.source,
        payload: req.payload,
        yaml_before: req.yaml_before,
        yaml_after: req.yaml_after,
    };
    agent_api
        .resolve_proposal_store(&principal, &workspace)
        .await
        .create_proposal(proposal)
        .await
        .map_err(|err| proposal_store_error_response(err, None))
}

async fn list_proposals_impl(
    agent_api: &AgentApiServices,
    principal: &str,
    workspace: &str,
    query: ListProposalsQuery,
) -> HttpResponse {
    // Hydration check ensures proposal files from previous process lifetimes are loaded.
    if let Err(response) = ensure_agent_startup_hydrated(agent_api).await {
        return response;
    }
    let agent_id_filter = query
        .agent_id
        .as_deref()
        .map(str::trim)
        .filter(|value| !value.is_empty())
        .map(|value| value.to_string());
    let status_filter = match parse_proposal_status_filter(query.status.as_deref()) {
        Ok(status) => status,
        Err(response) => return response,
    };

    let proposals = match agent_api
        .resolve_proposal_store(principal, workspace)
        .await
        .list_proposals(ProposalFilter {
            agent_id: agent_id_filter,
            status: status_filter,
        })
        .await
    {
        Ok(proposals) => proposals,
        Err(err) => return proposal_store_error_response(err, None),
    };
    let total_count = proposals.len();
    HttpResponse::Ok().json(ProposalListResponse {
        proposals,
        total_count,
    })
}

#[cfg(test)]
async fn get_proposal_impl(agent_api: &AgentApiServices, proposal_id: &str) -> HttpResponse {
    if let Err(response) = ensure_agent_startup_hydrated(agent_api).await {
        return response;
    }
    if let Err(err) =
        magician::magician_v2::agents::ProposalStore::validate_proposal_id(proposal_id)
    {
        return proposal_store_error_response(err, Some(proposal_id));
    }
    let stores = agent_api
        .scoped_proposal_stores
        .read()
        .await
        .values()
        .cloned()
        .collect::<Vec<_>>();
    for store in stores {
        match store.get_proposal(proposal_id).await {
            Ok(Some(proposal)) => {
                return HttpResponse::Ok().json(ProposalDetailsResponse { proposal });
            },
            Ok(None) => continue,
            Err(err) => return proposal_store_error_response(err, Some(proposal_id)),
        }
    }
    api_error_response(
        StatusCode::NOT_FOUND,
        "proposal_not_found",
        "Proposal not found",
        Some(serde_json::json!({ "proposal_id": proposal_id })),
    )
}

async fn get_proposal_impl_with_scope(
    agent_api: &AgentApiServices,
    principal: &str,
    workspace: &str,
    proposal_id: &str,
) -> HttpResponse {
    if let Err(response) = ensure_agent_startup_hydrated(agent_api).await {
        return response;
    }
    let store = agent_api.resolve_proposal_store(principal, workspace).await;
    match store.get_proposal(proposal_id).await {
        Ok(Some(proposal)) => HttpResponse::Ok().json(ProposalDetailsResponse { proposal }),
        Ok(None) => api_error_response(
            StatusCode::NOT_FOUND,
            "proposal_not_found",
            "Proposal not found",
            Some(serde_json::json!({ "proposal_id": proposal_id })),
        ),
        Err(err) => proposal_store_error_response(err, Some(proposal_id)),
    }
}

async fn resolve_proposal_impl(
    agent_api: &AgentApiServices,
    principal: &str,
    workspace: &str,
    proposal_id: &str,
    req: ResolveProposalRequest,
) -> Result<ResolveProposalImplResult, HttpResponse> {
    ensure_agent_startup_hydrated(agent_api).await?;
    let channel = req.channel.trim();
    if channel.is_empty() {
        return Err(api_error_response(
            StatusCode::BAD_REQUEST,
            "invalid_proposal_request",
            "channel must not be empty",
            Some(serde_json::json!({ "proposal_id": proposal_id })),
        ));
    }

    let decision = req.decision;
    let proposal_store = agent_api.resolve_proposal_store(principal, workspace).await;
    let (proposal, outcome) = proposal_store
        .resolve_proposal(proposal_id, decision.clone(), channel)
        .await
        .map_err(|err| proposal_store_error_response(err, Some(proposal_id)))?;

    Ok(ResolveProposalImplResult {
        proposal,
        resolved: matches!(outcome, ProposalResolveOutcome::Resolved),
        decision,
        channel: channel.to_string(),
    })
}

#[derive(Debug, Clone)]
struct DerivedAgentEvent {
    event_type: String,
    payload: serde_json::Value,
}

#[derive(Debug, Clone)]
struct ManualCyclePostExecution {
    episode: V3EpisodeRecord,
    episode_outcome: EpisodeOutcome,
    evaluation_result: EvaluationResult,
    circuit_decision: CircuitDecision,
    events: Vec<DerivedAgentEvent>,
}

fn goal_success_criteria(
    _definition: &AgentDefinition,
    _goal_id: &str,
) -> Vec<magician::magician_v2::agents::EvaluationCriterion> {
    // Goals (and their success_criteria) are no longer stored on AgentDefinition.
    // Evaluation criteria are now managed through Task definitions.
    Vec::new()
}

fn structured_output_from_outcome(outcome: &AgenticOutcome) -> Option<serde_json::Value> {
    let AgenticOutcome::Success { artifacts, .. } = outcome else {
        return None;
    };
    let json_artifacts: Vec<serde_json::Value> = artifacts
        .iter()
        .filter(|a| {
            a.content_type
                .to_ascii_lowercase()
                .starts_with("application/json")
        })
        .filter_map(|a| serde_json::from_slice(&a.data).ok())
        .collect();
    match json_artifacts.len() {
        0 => None,
        1 => json_artifacts.into_iter().next(),
        _ => Some(serde_json::Value::Array(json_artifacts)),
    }
}

fn outcome_had_error(outcome: &AgenticOutcome) -> bool {
    matches!(
        outcome,
        AgenticOutcome::Failed { .. }
            | AgenticOutcome::CannotProceed { .. }
            | AgenticOutcome::LoopDetected { .. }
            | AgenticOutcome::BudgetExhausted { .. }
            | AgenticOutcome::MaxIterationsReached {
                pause_state: None,
                ..
            }
    )
}

/// Extract the first JSON artifact as a single object for evaluation criteria.
///
/// Evaluation criteria use `.as_object()` on structured_output, so this must
/// return a single JSON object (not an array). Use `structured_output_from_outcome`
/// when collecting all artifacts is desired (e.g. for `artifact_output` storage).
fn first_json_artifact_from_outcome(outcome: &AgenticOutcome) -> Option<serde_json::Value> {
    let AgenticOutcome::Success { artifacts, .. } = outcome else {
        return None;
    };
    artifacts.iter().find_map(|a| {
        if !a
            .content_type
            .to_ascii_lowercase()
            .starts_with("application/json")
        {
            return None;
        }
        serde_json::from_slice(&a.data).ok()
    })
}

fn evaluation_input_from_outcome(outcome: &AgenticOutcome) -> EvaluationInput {
    EvaluationInput {
        structured_output: first_json_artifact_from_outcome(outcome),
        had_error: outcome_had_error(outcome),
        actions_taken: u32::try_from(outcome.iterations_used()).unwrap_or(u32::MAX),
        updated_memory_keys: HashSet::new(),
    }
}

fn fallback_evaluation_result(outcome: &AgenticOutcome) -> EvaluationResult {
    match outcome {
        AgenticOutcome::Success { .. } => EvaluationResult::Succeeded,
        AgenticOutcome::Failed { reason, .. } => EvaluationResult::Failed {
            reason: reason.clone(),
        },
        AgenticOutcome::CannotProceed { reason, .. } => EvaluationResult::Failed {
            reason: reason.clone(),
        },
        AgenticOutcome::LoopDetected {
            detection_type,
            recommendation,
            ..
        } => EvaluationResult::Failed {
            reason: format!("loop detected ({detection_type}); recommendation: {recommendation}"),
        },
        AgenticOutcome::BudgetExhausted { dimension, .. } => EvaluationResult::Failed {
            reason: format!("budget exhausted: {dimension:?}"),
        },
        AgenticOutcome::MaxIterationsReached {
            iterations_used,
            pause_state,
            ..
        } => {
            if pause_state.is_some() {
                EvaluationResult::Inconclusive
            } else {
                EvaluationResult::Failed {
                    reason: format!("max iterations reached ({iterations_used})"),
                }
            }
        },
        AgenticOutcome::WaitingForUser { .. } | AgenticOutcome::WaitingForConfirmation { .. } => {
            EvaluationResult::Inconclusive
        },
        AgenticOutcome::PausedByUser { .. } => EvaluationResult::Inconclusive,
        AgenticOutcome::WaitingForChildren { .. } => EvaluationResult::Inconclusive,
        AgenticOutcome::Sleeping { .. } => EvaluationResult::Inconclusive,
    }
}

fn episode_outcome_from_evaluation(
    outcome: &AgenticOutcome,
    evaluation_result: &EvaluationResult,
) -> EpisodeOutcome {
    match outcome {
        AgenticOutcome::WaitingForUser { question, .. } => EpisodeOutcome::Paused {
            pending_actions: vec![format!("awaiting_user_input: {question}")],
        },
        AgenticOutcome::WaitingForConfirmation { action_summary, .. } => EpisodeOutcome::Paused {
            pending_actions: vec![format!("awaiting_confirmation: {action_summary}")],
        },
        AgenticOutcome::MaxIterationsReached {
            pause_state: Some(_),
            iterations_used,
            ..
        } => EpisodeOutcome::Paused {
            pending_actions: vec![format!("max_iterations_reached: {iterations_used}")],
        },
        // A resumable token/cost budget stop is a "Continue execution?" pause,
        // not a cycle failure — record it as Paused (parity with the
        // MaxIterationsReached{Some} arm) so a low-budget watchdog cycle does
        // not surface as a failure or count toward the circuit breaker.
        AgenticOutcome::BudgetExhausted {
            pause_state: Some(_),
            iterations_completed,
            ..
        } => EpisodeOutcome::Paused {
            pending_actions: vec![format!("budget_reached: {iterations_completed}")],
        },
        AgenticOutcome::PausedByUser { .. } => EpisodeOutcome::Paused {
            pending_actions: vec!["paused_by_user".to_string()],
        },
        _ => match evaluation_result {
            EvaluationResult::Succeeded => EpisodeOutcome::GoalAchieved {
                summary: "structured success criteria satisfied".to_string(),
            },
            EvaluationResult::Failed { reason } => EpisodeOutcome::Failed {
                error: reason.clone(),
            },
            EvaluationResult::Inconclusive => match outcome {
                AgenticOutcome::Success { .. } => EpisodeOutcome::GoalAchieved {
                    summary: "goal achieved".to_string(),
                },
                AgenticOutcome::Failed { reason, .. }
                | AgenticOutcome::CannotProceed { reason, .. } => EpisodeOutcome::Failed {
                    error: reason.clone(),
                },
                AgenticOutcome::LoopDetected {
                    detection_type,
                    recommendation,
                    ..
                } => EpisodeOutcome::Failed {
                    error: format!(
                        "loop detected ({detection_type}); recommendation: {recommendation}"
                    ),
                },
                AgenticOutcome::BudgetExhausted { .. } => EpisodeOutcome::BudgetExhausted,
                AgenticOutcome::MaxIterationsReached {
                    iterations_used,
                    pause_state: None,
                    ..
                } => EpisodeOutcome::Failed {
                    error: format!("max iterations reached ({iterations_used})"),
                },
                AgenticOutcome::WaitingForUser { .. }
                | AgenticOutcome::WaitingForConfirmation { .. }
                | AgenticOutcome::PausedByUser { .. }
                | AgenticOutcome::WaitingForChildren { .. }
                | AgenticOutcome::MaxIterationsReached {
                    pause_state: Some(_),
                    ..
                } => EpisodeOutcome::Paused {
                    pending_actions: vec!["awaiting_user_input".to_string()],
                },
                AgenticOutcome::Sleeping { .. } => EpisodeOutcome::Paused {
                    pending_actions: vec!["agent_sleeping".to_string()],
                },
            },
        },
    }
}

fn cycle_outcome_status(outcome: &EpisodeOutcome) -> &'static str {
    match outcome {
        EpisodeOutcome::GoalAchieved { .. } => "success",
        EpisodeOutcome::Paused { .. } => "paused",
        EpisodeOutcome::CircuitOpen { .. } => "circuit_open",
        EpisodeOutcome::PartialProgress { .. } => "partial_progress",
        EpisodeOutcome::UserIntervened { .. } => "user_intervened",
        EpisodeOutcome::Failed { .. } | EpisodeOutcome::BudgetExhausted => "failure",
    }
}

fn cycle_event_type_for_outcome(outcome: &EpisodeOutcome) -> &'static str {
    match outcome {
        EpisodeOutcome::GoalAchieved { .. } => "agent.cycle.completed",
        EpisodeOutcome::Paused { .. } => "agent.cycle.paused",
        _ => "agent.cycle.failed",
    }
}

fn evaluation_result_payload(result: &EvaluationResult) -> serde_json::Value {
    match result {
        EvaluationResult::Succeeded => serde_json::json!({ "status": "succeeded" }),
        EvaluationResult::Inconclusive => serde_json::json!({ "status": "inconclusive" }),
        EvaluationResult::Failed { reason } => {
            serde_json::json!({ "status": "failed", "reason": reason })
        },
    }
}

fn circuit_decision_payload(decision: &CircuitDecision) -> serde_json::Value {
    match decision {
        CircuitDecision::NoAction => serde_json::json!({ "action": "none" }),
        CircuitDecision::InjectFailureContext { escalation } => serde_json::json!({
            "action": "inject_failure_context",
            "escalation": escalation
        }),
        CircuitDecision::OpenCircuit {
            threshold_failures,
            effective_max_failures,
            notify_targets,
        } => serde_json::json!({
            "action": "open_circuit",
            "threshold_failures": threshold_failures,
            "effective_max_failures": effective_max_failures,
            "notify_targets": notify_targets
        }),
    }
}

fn default_circuit_max_failures(definition: &AgentDefinition) -> usize {
    definition
        .circuit_breaker
        .as_ref()
        .and_then(|policy| {
            policy
                .thresholds
                .iter()
                .filter(|threshold| matches!(threshold.action, CircuitAction::OpenCircuit))
                .map(|threshold| threshold.failures)
                .max()
        })
        .unwrap_or(2)
}

fn consolidation_muij_component_id(
    agent_id: &str,
    report: &magician::magician_v2::agents::ConsolidationReport,
) -> String {
    format!(
        "{}-consolidation-report-{}",
        sanitize_segment(agent_id),
        sanitize_segment(&report.rule_name)
    )
}

async fn emit_consolidation_reports(
    agent_api: &AgentApiServices,
    definition: &AgentDefinition,
    v2_orchestrator: &Arc<MagicianV2Orchestrator>,
    agent_id: &str,
    goal_id: &str,
    cycle_id: &str,
    reports: &[magician::magician_v2::agents::ConsolidationReport],
) {
    if reports.is_empty() {
        return;
    }
    let trust_level = normalized_trust_level(definition);
    let (principal, workspace) = match required_cycle_scope(definition, agent_id) {
        Ok(scope) => scope,
        Err(error) => {
            warn!(
                agent_id = %agent_id,
                error = %error,
                "Skipping consolidation report emission because the agent definition is missing explicit scope"
            );
            return;
        },
    };
    let trust_policy_storage = scoped_trust_policy_storage(agent_api, &principal, &workspace);
    let enforcer = match load_trust_policy_enforcer(&trust_policy_storage).await {
        Ok(enforcer) => enforcer,
        Err(_) => {
            warn!(
                agent_id = %agent_id,
                "Skipping consolidation report emission because trust policy is unavailable"
            );
            return;
        },
    };
    if !enforcer.has_level_exact(&trust_level.0) {
        warn!(
            agent_id = %agent_id,
            trust_level = %trust_level.0,
            "Skipping consolidation report emission because trust level is not defined in trust policy file"
        );
        return;
    }

    for report in reports {
        if !enforcer.is_allowed(&trust_level, "report", &report.channel) {
            warn!(
                agent_id = %agent_id,
                rule_name = %report.rule_name,
                channel = %report.channel,
                trust_level = %trust_level.0,
                "Skipping consolidation report emission because trust policy denies report channel"
            );
            continue;
        }

        if report.channel == "muij" {
            emit_agent_event(
                v2_orchestrator,
                Some(principal.as_str()),
                Some(workspace.as_str()),
                "agent.ui.delta",
                agent_id,
                serde_json::json!({
                    "op": "upsert",
                    "component_id": consolidation_muij_component_id(agent_id, report),
                    "data": {
                        "component_type": "Notification",
                        "label": "Consolidation Report",
                        "props": {
                            "title": format!("Consolidation · {}", report.rule_name),
                            "body": report.message,
                            "timestamp": Utc::now().timestamp_millis(),
                            "principal": principal.clone(),
                            "workspace": workspace.clone(),
                            "channel": report.channel,
                            "target": report.target,
                            "goal_id": goal_id,
                            "cycle_id": cycle_id,
                        }
                    }
                }),
            );
        }

        emit_agent_event(
            v2_orchestrator,
            Some(principal.as_str()),
            Some(workspace.as_str()),
            "agent.memory.report",
            agent_id,
            serde_json::json!({
                "message": report.message,
                "entity_key": format!("memory-report:{}:{}", agent_id, report.rule_name),
                "rule_name": report.rule_name,
                "target": report.target,
                "channel": report.channel,
                "principal": principal.clone(),
                "workspace": workspace.clone(),
                "goal_id": goal_id,
                "cycle_id": cycle_id,
            }),
        );
    }
}

async fn derive_manual_cycle_post_execution(
    agent_api: &AgentApiServices,
    definition: &AgentDefinition,
    agent_id: &str,
    goal_id: &str,
    trigger: &str,
    trigger_seq: u64,
    cycle_id: &str,
    runtime_execution_id: &str,
    started_at: DateTime<Utc>,
    completed_at: DateTime<Utc>,
    outcome: &AgenticOutcome,
    strategy_summary: Option<&str>,
) -> Result<ManualCyclePostExecution, String> {
    let criteria = goal_success_criteria(definition, goal_id);
    let evaluation_input = evaluation_input_from_outcome(outcome);
    let mut evaluation_result = if outcome.is_terminal() {
        agent_api
            .runtime
            .evaluate_before_llm_fallback(&criteria, &evaluation_input, || {
                fallback_evaluation_result(outcome)
            })
    } else {
        EvaluationResult::Inconclusive
    };

    // Structured criteria are authoritative only for successful execution runs.
    // A terminal non-success outcome must remain non-success even if criteria
    // happen to pass due partial/missing signal coverage.
    if !matches!(outcome, AgenticOutcome::Success { .. })
        && matches!(evaluation_result, EvaluationResult::Succeeded)
    {
        evaluation_result = fallback_evaluation_result(outcome);
    }

    let mut episode_outcome = episode_outcome_from_evaluation(outcome, &evaluation_result);
    let outcome_transition = if outcome.is_terminal() {
        let succeeded = matches!(episode_outcome, EpisodeOutcome::GoalAchieved { .. });
        agent_api
            .runtime
            .record_goal_outcome_transition_in_scope(
                definition.principal.as_deref(),
                definition.workspace.as_deref(),
                agent_id,
                goal_id,
                succeeded,
                definition.circuit_breaker.as_ref(),
                default_circuit_max_failures(definition),
            )
            .await
    } else {
        magician::magician_v2::agents::GoalOutcomeTransition {
            circuit_decision: CircuitDecision::NoAction,
            recovered: false,
            previous_failures: 0,
        }
    };
    let circuit_decision = outcome_transition.circuit_decision.clone();

    if matches!(circuit_decision, CircuitDecision::OpenCircuit { .. }) {
        let failure_count = agent_api
            .runtime
            .consecutive_failures_in_scope(
                definition.principal.as_deref(),
                definition.workspace.as_deref(),
                agent_id,
                goal_id,
            )
            .await;
        let last_error = match &evaluation_result {
            EvaluationResult::Failed { reason } => reason.clone(),
            _ => {
                let summary = episode_outcome.error_summary();
                if summary.is_empty() {
                    "circuit breaker opened".to_string()
                } else {
                    summary
                }
            },
        };
        episode_outcome = EpisodeOutcome::CircuitOpen {
            failure_count,
            last_error,
        };
    }

    let (principal, workspace) = required_cycle_scope(definition, agent_id)?;

    let artifact_output = structured_output_from_outcome(outcome).and_then(|value| {
        let serialized_len = json_encoded_len(&value).unwrap_or(usize::MAX);
        if serialized_len <= 512 * 1024 {
            Some(value)
        } else {
            tracing::warn!(
                agent_id = %agent_id,
                cycle_id = %cycle_id,
                serialized_bytes = serialized_len,
                "artifact_output exceeds 512KB limit; dropping from episode record"
            );
            discard_json_iteratively(value);
            None
        }
    });
    let cycle_event_type = cycle_event_type_for_outcome(&episode_outcome).to_string();
    let cycle_payload = serde_json::json!({
        "execution_id": runtime_execution_id,
        "principal": principal.clone(),
        "workspace": workspace.clone(),
        "cycle_id": cycle_id,
        "goal_id": goal_id,
        "trigger": trigger,
        "trigger_seq": trigger_seq,
        "iterations_used": outcome.iterations_used(),
        "outcome": cycle_outcome_status(&episode_outcome),
        "evaluation": evaluation_result_payload(&evaluation_result),
        "circuit": circuit_decision_payload(&circuit_decision),
    });

    let mut events = vec![DerivedAgentEvent {
        event_type: "agent.cycle.completed".to_string(),
        payload: cycle_payload.clone(),
    }];
    if cycle_event_type != "agent.cycle.completed" {
        events.push(DerivedAgentEvent {
            event_type: cycle_event_type.clone(),
            payload: cycle_payload.clone(),
        });
    }
    if outcome_transition.recovered {
        events.push(DerivedAgentEvent {
            event_type: "agent.goal.recovered".to_string(),
            payload: serde_json::json!({
                "execution_id": runtime_execution_id,
                "principal": principal.clone(),
                "workspace": workspace.clone(),
                "cycle_id": cycle_id,
                "goal_id": goal_id,
                "trigger_seq": trigger_seq,
                "after_failures": outcome_transition.previous_failures,
            }),
        });
        // If the circuit was ACTUALLY open on the previous failure run
        // (previous_failures >= configured threshold), emit
        // `agent.circuit.recovered`. Gating on the threshold avoids
        // spurious "CircuitRecovered" cards for single-failure blips that
        // never actually tripped the breaker.
        let circuit_open_threshold = definition.constraints.max_consecutive_failures;
        if circuit_open_threshold > 0
            && outcome_transition.previous_failures >= circuit_open_threshold
        {
            events.push(DerivedAgentEvent {
                event_type: "agent.circuit.recovered".to_string(),
                payload: serde_json::json!({
                    "execution_id": runtime_execution_id,
                    "principal": principal.clone(),
                    "workspace": workspace.clone(),
                    "cycle_id": cycle_id,
                    "goal_id": goal_id,
                    "trigger_seq": trigger_seq,
                    "after_failures": outcome_transition.previous_failures,
                    "threshold": circuit_open_threshold,
                    "recovered_at": chrono::Utc::now().timestamp_millis(),
                }),
            });
        }
    }

    let episode = V3EpisodeRecord::new_memory_episode(
        Some((principal.as_str(), workspace.as_str())),
        agent_id.to_string(),
        cycle_id.to_string(),
        goal_id.to_string(),
        trigger.to_string(),
        trigger_seq,
        started_at,
        None,
        started_at,
        completed_at,
        &episode_outcome,
        Vec::new(),
        Vec::new(),
        Vec::new(),
        trim_non_empty(strategy_summary),
        None,
        artifact_output,
    );
    let feedback_signals = agent_api
        .runtime
        .feedback_signals_v3(&definition.feedback_loops, &episode);
    if !feedback_signals.is_empty() {
        let serialized_signals = feedback_signals
            .iter()
            .map(|signal| {
                serde_json::json!({
                    "loop_name": signal.loop_name,
                    "target": signal.target,
                    "payload": signal.payload,
                })
            })
            .collect::<Vec<_>>();
        events.push(DerivedAgentEvent {
            event_type: "agent.feedback.generated".to_string(),
            payload: serde_json::json!({
                "execution_id": runtime_execution_id,
                "principal": principal.clone(),
                "workspace": workspace.clone(),
                "cycle_id": cycle_id,
                "goal_id": goal_id,
                "signal_count": serialized_signals.len(),
                "signals": serialized_signals,
            }),
        });

        // P6-10: Apply feedback transforms and emit injection event.
        let scoped_memory_service =
            agent_api.resolve_memory_service(Some(principal.as_str()), Some(workspace.as_str()));
        let injections = apply_feedback_transforms(
            &agent_api.feedback_transformer_registry,
            &feedback_signals,
            &scoped_memory_service,
            agent_id,
        )
        .await;
        if !injections.is_empty() {
            // P6-T3: Persist injections so the next goal cycle can consume them.
            agent_api
                .runtime
                .store_feedback_injections(agent_id, injections.clone())
                .await;
            events.push(DerivedAgentEvent {
                event_type: "agent.feedback.injections".to_string(),
                payload: serde_json::json!({
                    "agent_id": agent_id,
                    "execution_id": runtime_execution_id,
                    "principal": principal.clone(),
                    "workspace": workspace.clone(),
                    "cycle_id": cycle_id,
                    "injection_targets": injections,
                }),
            });
        }
    }

    match &circuit_decision {
        CircuitDecision::OpenCircuit {
            threshold_failures,
            effective_max_failures,
            notify_targets,
        } => {
            let circuit_payload = serde_json::json!({
                "execution_id": runtime_execution_id,
                "principal": principal.clone(),
                "workspace": workspace.clone(),
                "cycle_id": cycle_id,
                "goal_id": goal_id,
                "trigger_seq": trigger_seq,
                "threshold_failures": threshold_failures,
                "effective_max_failures": effective_max_failures,
                "notify_targets": notify_targets,
                "failure_count": agent_api.runtime.consecutive_failures_in_scope(
                    definition.principal.as_deref(),
                    definition.workspace.as_deref(),
                    agent_id,
                    goal_id,
                ).await,
            });
            events.push(DerivedAgentEvent {
                event_type: "agent.circuit.opened".to_string(),
                payload: circuit_payload.clone(),
            });
        },
        CircuitDecision::InjectFailureContext { escalation } => {
            if escalation.is_some() {
                events.push(DerivedAgentEvent {
                    event_type: "agent.circuit.failure_context".to_string(),
                    payload: serde_json::json!({
                        "execution_id": runtime_execution_id,
                        "principal": principal.clone(),
                        "workspace": workspace.clone(),
                        "cycle_id": cycle_id,
                        "goal_id": goal_id,
                        "trigger_seq": trigger_seq,
                        "escalation": escalation,
                    }),
                });
            }
        },
        CircuitDecision::NoAction => {},
    }

    Ok(ManualCyclePostExecution {
        episode,
        episode_outcome,
        evaluation_result,
        circuit_decision,
        events,
    })
}

/// Apply all registered feedback transformers to the given signals and collect
/// injection targets. Returns a map of target → injected text.
async fn apply_feedback_transforms(
    registry: &magician::magician_v2::agents::feedback::FeedbackTransformerRegistry,
    signals: &[magician::magician_v2::agents::feedback::FeedbackSignal],
    memory: &AgentMemoryService,
    agent_id: &str,
) -> std::collections::HashMap<String, String> {
    let mut injections = std::collections::HashMap::new();
    for signal in signals {
        for (_name, transformer) in registry.iter() {
            match transformer.apply(signal, memory, agent_id).await {
                Ok(Some(text)) => {
                    injections
                        .entry(signal.target.clone())
                        .and_modify(|existing: &mut String| {
                            existing.push('\n');
                            existing.push_str(&text);
                        })
                        .or_insert(text);
                },
                Ok(None) => {},
                Err(e) => {
                    tracing::warn!(
                        agent_id,
                        transformer = _name,
                        error = %e,
                        "feedback transformer failed; skipping"
                    );
                },
            }
        }
    }
    injections
}

#[cfg(test)]
fn default_environment_state_for_mode(execution_mode: &str) -> EnvironmentState {
    match execution_mode.trim().to_lowercase().as_str() {
        "http" => EnvironmentState::Http(HttpState::default()),
        "file" => EnvironmentState::Filesystem(FilesystemState::default()),
        "bash" => EnvironmentState::Shell(ShellState::default()),
        _ => EnvironmentState::Browser(magician::magician_v2::execution::PageState::default()),
    }
}

fn emit_derived_agent_events(
    v2_orchestrator: &Arc<MagicianV2Orchestrator>,
    principal: &str,
    workspace: &str,
    agent_id: &str,
    events: &[DerivedAgentEvent],
) {
    let broadcaster = v2_orchestrator.event_broadcaster();
    for event in events {
        emit_agent_event(
            v2_orchestrator,
            Some(principal),
            Some(workspace),
            &event.event_type,
            agent_id,
            event.payload.clone(),
        );

        // Parallel AgentUpdate emission for event types handled by the
        // translator table in agent_update::agent_update_from_legacy_event.
        // Cycle and approval event types return `None` from the translator
        // because they already emit AgentUpdate inline at their call sites.
        if let Some(ref broadcaster) = broadcaster {
            if let Some(update) =
                magician::magician_v2::agents::agent_update::agent_update_from_legacy_event(
                    &event.event_type,
                    &event.payload,
                    agent_id,
                    workspace,
                )
            {
                magician::magician_v2::agents::agent_update_emitter::publish_agent_update(
                    broadcaster,
                    Some(principal),
                    Some(workspace),
                    update,
                );
            }
        }
    }
}

/// Shared post-cycle pipeline: episode derivation → persist → lifecycle catalog →
/// artifact registration → memory consolidation → circuit breaker → event emission.
///
/// Used by both manual trigger dispatch and autonomous execution paths.
/// Returns the episode outcome for status mapping by the caller.
async fn run_post_cycle_pipeline(
    agent_api: &AgentApiServices,
    v2_orchestrator: &Arc<MagicianV2Orchestrator>,
    definition: &AgentDefinition,
    outcome: &AgenticOutcome,
    agent_id: &str,
    goal_id: &str,
    cycle_id: &str,
    runtime_execution_id: &str,
    trigger: &str,
    trigger_seq: u64,
    started_at: DateTime<Utc>,
    completed_at: DateTime<Utc>,
    strategy_summary: Option<&str>,
    task_id: Option<&str>,
) -> EpisodeOutcome {
    let scoped_memory_service = match agent_api.resolve_cycle_memory_service(definition, agent_id) {
        Ok(service) => service,
        Err(error) => {
            warn!(
                agent_id = %agent_id,
                goal_id = %goal_id,
                cycle_id = %cycle_id,
                error = %error,
                "Post-cycle pipeline aborted because the agent definition is missing explicit scope"
            );
            return EpisodeOutcome::Failed { error };
        },
    };
    let scoped_memory_consolidator = match agent_api
        .resolve_cycle_memory_consolidator(definition, agent_id)
        .await
    {
        Ok(consolidator) => consolidator,
        Err(error) => {
            warn!(
                agent_id = %agent_id,
                goal_id = %goal_id,
                cycle_id = %cycle_id,
                error = %error,
                "Post-cycle pipeline aborted because the agent definition is missing explicit scope"
            );
            return EpisodeOutcome::Failed { error };
        },
    };

    // 1. Derive post-execution record (episode, evaluation, circuit, events).
    let mut post_execution = match derive_manual_cycle_post_execution(
        agent_api,
        definition,
        agent_id,
        goal_id,
        trigger,
        trigger_seq,
        cycle_id,
        runtime_execution_id,
        started_at,
        completed_at,
        outcome,
        strategy_summary,
    )
    .await
    {
        Ok(post_execution) => post_execution,
        Err(error) => {
            warn!(
                agent_id = %agent_id,
                goal_id = %goal_id,
                cycle_id = %cycle_id,
                error = %error,
                "Post-cycle pipeline aborted because the agent definition is missing explicit scope"
            );
            return EpisodeOutcome::Failed { error };
        },
    };

    // 1b. Enrich episode with plan steps and step results from the execution runtime.
    enrich_episode_from_execution(
        &mut post_execution.episode,
        v2_orchestrator,
        runtime_execution_id,
        None,
    )
    .await;

    // 2. Persist episode. Every harness cycle MUST leave a tagged episode (even a
    // no-op/failed review), so retry a bounded number of times on *transient*
    // I/O (lock contention, a filesystem hiccup) before giving up. Permanent
    // errors (validation, serialization) are never retried — they fail fast.
    const EPISODE_PERSIST_MAX_ATTEMPTS: usize = 3;
    let mut episode_persisted = false;
    let mut last_episode_error: Option<String> = None;
    for attempt in 1..=EPISODE_PERSIST_MAX_ATTEMPTS {
        match scoped_memory_service
            .append_native_episode(agent_id, &post_execution.episode)
            .await
        {
            Ok(()) => {
                episode_persisted = true;
                break;
            },
            Err(err) => {
                let transient = err.is_transient();
                warn!(
                    agent_id = %agent_id,
                    goal_id = %goal_id,
                    cycle_id = %cycle_id,
                    attempt = attempt,
                    transient = transient,
                    error = %err,
                    "Post-cycle pipeline: failed to persist episode record"
                );
                last_episode_error = Some(err.to_string());
                if !transient || attempt == EPISODE_PERSIST_MAX_ATTEMPTS {
                    break;
                }
                tokio::time::sleep(StdDuration::from_millis(50 * attempt as u64)).await;
            },
        }
    }
    let cycle_outcome = if episode_persisted {
        magician::magician_v2::harness::HarnessCycleDispatchOutcome::EpisodePersisted
    } else {
        magician::magician_v2::harness::HarnessCycleDispatchOutcome::EpisodePersistFailed
    };
    magician::magician_v2::harness::record_harness_cycle_outcome(
        &harness_cycle_outcome_store(agent_api),
        definition.principal.as_deref().unwrap_or_default(),
        definition.workspace.as_deref().unwrap_or_default(),
        agent_id,
        goal_id,
        Some(cycle_id),
        Some(trigger_seq),
        cycle_outcome,
        serde_json::json!({ "trigger": trigger, "error": last_episode_error }),
    );
    // Boundary C: every harness cycle settles on exactly one continuation
    // decision. This is the single funnel every cycle passes through, so a
    // decision recorded here cannot be skipped by a lane that forgot to state
    // one — an unstated decision is inferred from the outcome rather than left
    // absent.
    let continuation = magician::magician_v2::harness::decide_continuation(
        // No producer states a decision yet, so inference from the outcome is
        // authoritative today. The stated path stays open for the cycle that
        // learns to name its own reason; it is not fabricated from prose here.
        None,
        &post_execution.episode.outcome_kind,
        magician::magician_v2::harness::CycleBudgetSnapshot {
            elapsed_ms: u64::try_from((completed_at - started_at).num_milliseconds()).ok(),
            retries: post_execution
                .episode
                .failure_count
                .and_then(|count| u32::try_from(count).ok()),
            // Program runtime state is not loaded on this path, so open loops
            // are unmeasured rather than zero.
            open_loops: None,
            pending_actions: post_execution.episode.pending_actions.len(),
            // Token and cost telemetry does not reach this boundary yet.
            tokens: None,
            cost_microunits: None,
        },
    );
    magician::magician_v2::harness::record_cycle_continuation(
        &harness_cycle_outcome_store(agent_api),
        definition.principal.as_deref().unwrap_or_default(),
        definition.workspace.as_deref().unwrap_or_default(),
        agent_id,
        goal_id,
        Some(cycle_id),
        Some(trigger_seq),
        &continuation,
    );
    // Shadow-mode anomaly detection: turn a failed/dropped harness cycle into a
    // reviewable anomaly. Best-effort; never blocks the pipeline. (Phase 1 detect-only.)
    if magician::magician_v2::harness::cycle_outcome::is_harness_goal(goal_id) {
        let outcome_str = cycle_outcome.as_str();
        let episode_failed = !episode_persisted || post_execution.episode_outcome.is_failed();
        let detail = last_episode_error.clone().unwrap_or_else(|| {
            let status = cycle_outcome_status(&post_execution.episode_outcome);
            let error = post_execution.episode_outcome.error_summary();
            if error.trim().is_empty() {
                format!("episode_outcome={status}")
            } else {
                format!("episode_outcome={status}; error={error}")
            }
        });
        let anomaly_store = magician::magician_v2::harness::AnomalyStore::new(
            agent_api.durable_artifact_workspace.clone(),
        );
        let anomaly_principal = definition.principal.as_deref().unwrap_or_default();
        let anomaly_workspace = definition.workspace.as_deref().unwrap_or_default();
        if let Some((kind, summary)) =
            magician::magician_v2::harness::anomaly::classify_cycle_anomaly(
                outcome_str,
                episode_failed,
                &detail,
            )
        {
            let anomaly = magician::magician_v2::harness::HarnessAnomaly::new(
                anomaly_principal,
                anomaly_workspace,
                agent_id,
                goal_id,
                kind,
                &summary,
                &detail,
            );
            if let Err(e) = anomaly_store.upsert(&anomaly) {
                tracing::warn!(error = %e, agent_id = %agent_id, goal_id = %goal_id, "harness anomaly upsert failed");
            }
        } else if !episode_failed {
            // #27: a healthy cycle auto-resolves any standing anomalies for this
            // agent+goal, so a subsequent success clears the reliability queue
            // (which previously only ever grew — a None classification did
            // nothing to open anomalies).
            match anomaly_store.resolve_open_for_agent_goal(
                anomaly_principal,
                anomaly_workspace,
                agent_id,
                goal_id,
            ) {
                Ok(resolved) if resolved > 0 => {
                    info!(
                        agent_id = %agent_id,
                        goal_id = %goal_id,
                        resolved,
                        "Healthy harness cycle auto-resolved standing anomalies"
                    );
                },
                Ok(_) => {},
                Err(e) => {
                    tracing::warn!(error = %e, agent_id = %agent_id, goal_id = %goal_id, "harness anomaly auto-resolve failed");
                },
            }
        }
    }
    if episode_persisted {
        magician::magician_v2::learning::spawn_learning_reflection(
            magician::magician_v2::learning::LearningReflectionRuntime::new(
                agent_api.durable_artifact_workspace.clone(),
                v2_orchestrator.operation_llm_router(),
                v2_orchestrator.prompt_manager(),
            )
            .with_event_broadcaster(v2_orchestrator.event_broadcaster()),
            magician::magician_v2::learning::LearningReflectionInput {
                boundary: "agent_cycle_completed".to_string(),
                episode: post_execution.episode.clone(),
                extra_context: serde_json::json!({
                    "source": "agent_api_post_cycle_pipeline",
                    "evaluation": evaluation_result_payload(&post_execution.evaluation_result),
                    "trigger": trigger,
                    "trigger_seq": trigger_seq,
                    "task_id": task_id,
                }),
            },
        );
    }

    // 3. Materialize dashboardable artifacts if outcome was successful.
    if let AgenticOutcome::Success { ref artifacts, .. } = outcome {
        if let Ok(store) = agent_api.resolve_cycle_durable_store(definition, agent_id) {
            magician::magician_v2::surfaces::auto_publisher::materialize_dashboardable_artifacts(
                artifacts,
                agent_id,
                cycle_id,
                &store,
                task_id,
                Some(runtime_execution_id),
            )
            .await;
        }
    }

    // 5. Memory consolidation (skip for paused outcomes).
    if episode_persisted && !post_execution.episode_outcome.is_paused() {
        match scoped_memory_consolidator
            .consolidate_cycle_completed_v3(definition, agent_id, goal_id, &post_execution.episode)
            .await
        {
            Ok(consolidation) => {
                emit_consolidation_reports(
                    agent_api,
                    definition,
                    v2_orchestrator,
                    agent_id,
                    goal_id,
                    cycle_id,
                    &consolidation.reports,
                )
                .await;
            },
            Err(err) => {
                warn!(
                    agent_id = %agent_id,
                    goal_id = %goal_id,
                    cycle_id = %cycle_id,
                    error = %err,
                    "Post-cycle pipeline: failed to apply memory consolidation"
                );
            },
        }

        // 5b. Run StepCompleted rules retroactively against the episode.
        // The agentic loop is monolithic (no per-step pipeline executor), so
        // extract_entities / extract_insights / update_task_progress never fire
        // during execution. Feed them the enriched episode now.
        match scoped_memory_consolidator
            .run_step_rules_for_v3_episodes(
                definition,
                agent_id,
                goal_id,
                std::slice::from_ref(&post_execution.episode),
            )
            .await
        {
            Ok(_) => {},
            Err(err) => {
                warn!(
                    agent_id = %agent_id,
                    goal_id = %goal_id,
                    cycle_id = %cycle_id,
                    error = %err,
                    "Post-cycle pipeline: failed to run step rules for episode"
                );
            },
        }
    }

    // 6. Log circuit breaker / evaluation warnings.
    if let EvaluationResult::Failed { reason } = &post_execution.evaluation_result {
        warn!(
            agent_id = %agent_id,
            goal_id = %goal_id,
            cycle_id = %cycle_id,
            reason = %reason,
            "Post-cycle pipeline: structured evaluation marked cycle as failed"
        );
    }
    if matches!(
        post_execution.circuit_decision,
        CircuitDecision::OpenCircuit { .. }
    ) {
        warn!(
            agent_id = %agent_id,
            goal_id = %goal_id,
            cycle_id = %cycle_id,
            "Post-cycle pipeline: circuit breaker opened"
        );
    }

    // 7. Emit derived agent events.
    emit_derived_agent_events(
        v2_orchestrator,
        definition.principal.as_deref().unwrap_or_default(),
        definition.workspace.as_deref().unwrap_or_default(),
        agent_id,
        &post_execution.events,
    );

    post_execution.episode_outcome
}

fn prompt_pipeline_assembly_error_response(
    agent_id: &str,
    goal_id: &str,
    error: &PromptPipelineError,
) -> HttpResponse {
    let code = match error {
        PromptPipelineError::MissingRequiredSection { .. }
        | PromptPipelineError::RequiredSectionTruncated { .. } => {
            "prompt_pipeline_missing_required_context"
        },
        PromptPipelineError::SourceResolution { .. } => "prompt_pipeline_source_resolution_failed",
    };
    api_error_response(
        StatusCode::UNPROCESSABLE_ENTITY,
        code,
        "Prompt pipeline assembly failed",
        Some(serde_json::json!({
            "agent_id": agent_id,
            "goal_id": goal_id,
            "error": error.to_string(),
        })),
    )
}

#[cfg(test)]
async fn prepare_manual_trigger(
    agent_api: &AgentApiServices,
    agent_id: &str,
    request: ManualAgentTriggerRequest,
) -> Result<(ManualTriggerDispatch, ManualDispatchSchedule), HttpResponse> {
    prepare_manual_trigger_with_store(
        agent_api,
        agent_api.definition_store.as_ref(),
        agent_id,
        request,
    )
    .await
}

async fn prepare_manual_trigger_with_store(
    agent_api: &AgentApiServices,
    definition_store: &AgentDefinitionStore,
    agent_id: &str,
    request: ManualAgentTriggerRequest,
) -> Result<(ManualTriggerDispatch, ManualDispatchSchedule), HttpResponse> {
    let definition =
        match ensure_agent_loaded_for_api_with_store(agent_api, definition_store, agent_id).await {
            Ok(definition) => definition,
            Err(response) => return Err(response),
        };
    let (principal, workspace) = agent_api.definition_scope(&definition, agent_id)?;
    if !definition
        .invocation_policy
        .permits_direct_surface(magician::magician_v2::agents::InvocationSurface::Task)
    {
        return Err(api_error_response(
            StatusCode::UNPROCESSABLE_ENTITY,
            "agent_not_surface_eligible",
            "This agent cannot be started from the generic manual-trigger surface",
            Some(serde_json::json!({
                "agent_id": agent_id,
                "surface": magician::magician_v2::agents::InvocationSurface::Task.as_str(),
            })),
        ));
    }
    let disabled_agent_ids = agent_api
        .resolve_definition_store(&principal, &workspace)
        .disabled_hierarchy_agent_ids()
        .await
        .map_err(|error| {
            api_error_response(
                StatusCode::INTERNAL_SERVER_ERROR,
                "agent_disabled_hierarchy_unavailable",
                "Failed to resolve disabled agent hierarchy",
                Some(serde_json::json!({
                    "agent_id": agent_id,
                    "error": error.to_string(),
                })),
            )
        })?;
    if disabled_agent_ids.contains(agent_id) {
        return Err(api_error_response(
            StatusCode::CONFLICT,
            "agent_disabled",
            "Agent is disabled by hierarchy configuration",
            Some(serde_json::json!({
                "agent_id": agent_id,
            })),
        ));
    }
    if definition.harness.is_some() && harness_globally_paused() {
        return Err(api_error_response(
            StatusCode::CONFLICT,
            "harness_globally_paused",
            "Harness agents are turned off",
            Some(serde_json::json!({
                "agent_id": agent_id,
            })),
        ));
    }
    let trust_policy_storage = scoped_trust_policy_storage(agent_api, &principal, &workspace);
    let enforcer = Arc::new(load_trust_policy_enforcer(&trust_policy_storage).await?);
    let trust_level = normalized_trust_level(&definition);
    if !enforcer.has_level_exact(&trust_level.0) {
        return Err(definition_store_error_response(
            DefinitionStoreError::Validation(format!(
                "trust_level `{}` is not defined in trust policy file",
                definition.trust_level.0
            )),
        ));
    }
    if agent_api
        .is_agent_paused(&principal, &workspace, agent_id)
        .await
    {
        return Err(api_error_response(
            StatusCode::CONFLICT,
            "agent_paused",
            "Agent is paused",
            Some(serde_json::json!({
                "agent_id": agent_id,
            })),
        ));
    }

    let available_goal_ids = goal_ids_for_definition(&definition);
    let goal_id = match request.goal_id {
        Some(goal_id) => {
            let goal_id = goal_id.trim().to_string();
            if goal_id.is_empty() {
                return Err(api_error_response(
                    StatusCode::BAD_REQUEST,
                    "invalid_goal_id",
                    "goal_id must not be empty",
                    Some(serde_json::json!({
                        "agent_id": agent_id,
                    })),
                ));
            }
            if !available_goal_ids.is_empty()
                && !available_goal_ids
                    .iter()
                    .any(|available_goal_id| available_goal_id == &goal_id)
            {
                return Err(api_error_response(
                    StatusCode::BAD_REQUEST,
                    "invalid_goal_id",
                    "goal_id does not exist on this agent",
                    Some(serde_json::json!({
                        "agent_id": agent_id,
                        "goal_id": goal_id,
                        "available_goal_ids": available_goal_ids,
                    })),
                ));
            }
            goal_id
        },
        None => {
            if available_goal_ids.len() == 1 {
                available_goal_ids[0].clone()
            } else if !available_goal_ids.is_empty() {
                return Err(api_error_response(
                    StatusCode::BAD_REQUEST,
                    "manual_goal_id_required",
                    "goal_id is required when multiple triggerable goals are configured",
                    Some(serde_json::json!({
                        "agent_id": agent_id,
                        "available_goal_ids": available_goal_ids,
                    })),
                ));
            } else {
                "default".to_string()
            }
        },
    };

    let trigger = request
        .trigger
        .map(|raw| raw.trim().to_string())
        .filter(|raw| !raw.is_empty())
        .unwrap_or_else(|| "manual".to_string());
    let scheduler = match agent_api.resolve_scheduler(&principal, &workspace).await {
        Ok(scheduler) => scheduler,
        Err(err) => {
            return Err(scheduler_error_response(
                "resolve_scheduler",
                Some(agent_id),
                Some(&goal_id),
                &err,
            ));
        },
    };

    let trigger_seq = match scheduler.allocate_trigger_seq(agent_id, &goal_id).await {
        Ok(seq) => seq,
        Err(SchedulerError::NotRegistered { .. }) => {
            // Auto-register an Idle scheduler entry so manual triggers can
            // allocate a trigger_seq even when no cron/event schedule exists.
            if let Err(err) = scheduler
                .register_entry(agent_id, &goal_id, SchedulerTriggerRegistration::Idle)
                .await
            {
                return Err(scheduler_error_response(
                    "register_entry",
                    Some(agent_id),
                    Some(&goal_id),
                    &err,
                ));
            }
            match scheduler.allocate_trigger_seq(agent_id, &goal_id).await {
                Ok(seq) => seq,
                Err(err) => {
                    return Err(trigger_sequence_allocation_error_response(
                        agent_id, &goal_id, &err,
                    ));
                },
            }
        },
        Err(err) => {
            return Err(trigger_sequence_allocation_error_response(
                agent_id, &goal_id, &err,
            ));
        },
    };

    let (principal, workspace) = match required_cycle_scope(&definition, agent_id) {
        Ok(scope) => scope,
        Err(error) => {
            return Err(api_error_response(
                StatusCode::UNPROCESSABLE_ENTITY,
                "agent_scope_missing",
                error,
                Some(serde_json::json!({
                    "agent_id": agent_id,
                })),
            ));
        },
    };
    let cycle_id = AgentRuntime::cycle_id_for_scope(
        Some(&principal),
        Some(&workspace),
        agent_id,
        &goal_id,
        trigger_seq,
    );
    let goal_description = resolve_cycle_goal_description(&definition, &goal_id);
    let max_iterations = usize::try_from(definition.constraints.max_iterations).ok();
    let strategy_summary =
        resolve_manual_trigger_strategy_summary(agent_api, &definition, agent_id, &goal_id).await;
    let llm_routing_overrides = llm_routing_overrides(&definition);

    let dispatch = ManualTriggerDispatch {
        agent_id: agent_id.to_string(),
        principal,
        workspace,
        goal_id,
        trigger,
        trigger_seq,
        cycle_id,
        task_id: None,
        execution_id: None,
        runtime_execution_id: None,
        definition_version: definition.version,
        goal_description,
        max_iterations,
        trust_level: trust_level.0,
        trust_policies_path: trust_policy_storage.trust_policies_path(),
        preloaded_trust_enforcer: enforcer,
        approval_rules: magician::magician_v2::agents::approval::harness_merged_approval_rules(
            &definition,
        ),
        strategy_summary,
        strategy_hint_enabled: definition.strategy.is_some(),
        llm_routing_overrides,
        workflow_inputs: HashMap::new(),
        definition,
    };

    // Stage the dispatch payload before runtime admission so completion-time promotion
    // always has a payload to pick up if queue handoff races with admission.
    let staged_pending_payload = {
        let mut pending = agent_api.pending_cycle_dispatches.write().await;
        if pending.contains_key(&dispatch.cycle_id) {
            false
        } else {
            pending.insert(dispatch.cycle_id.clone(), dispatch.clone());
            true
        }
    };

    match agent_api
        .runtime
        .admit_trigger_in_scope(
            Some(&dispatch.principal),
            Some(&dispatch.workspace),
            &dispatch.agent_id,
            &dispatch.goal_id,
            &dispatch.trigger,
            dispatch.trigger_seq,
        )
        .await
    {
        TriggerAdmission::StartNow { .. } => {
            agent_api
                .pending_cycle_dispatches
                .write()
                .await
                .remove(&dispatch.cycle_id);
            Ok((dispatch, ManualDispatchSchedule::StartNow))
        },
        TriggerAdmission::Queued { queue_position, .. } => {
            Ok((dispatch, ManualDispatchSchedule::Queued { queue_position }))
        },
        TriggerAdmission::Duplicate { cycle_id } => {
            if staged_pending_payload {
                agent_api
                    .pending_cycle_dispatches
                    .write()
                    .await
                    .remove(&dispatch.cycle_id);
            }
            Err(api_error_response(
                StatusCode::CONFLICT,
                "duplicate_trigger_tuple",
                "Trigger tuple is already active, queued, or completed",
                Some(serde_json::json!({
                    "agent_id": dispatch.agent_id,
                    "goal_id": dispatch.goal_id,
                    "trigger_seq": dispatch.trigger_seq,
                    "cycle_id": cycle_id,
                })),
            ))
        },
        TriggerAdmission::QueueFull { capacity, .. } => {
            if staged_pending_payload {
                agent_api
                    .pending_cycle_dispatches
                    .write()
                    .await
                    .remove(&dispatch.cycle_id);
            }
            Err(api_error_response(
                StatusCode::TOO_MANY_REQUESTS,
                "agent_cycle_queue_full",
                "Agent trigger queue is full",
                Some(serde_json::json!({
                    "agent_id": dispatch.agent_id,
                    "capacity": capacity,
                })),
            ))
        },
    }
}

async fn clear_pending_dispatches_for_agent(
    agent_api: &AgentApiServices,
    principal: &str,
    workspace: &str,
    agent_id: &str,
) -> usize {
    let cleared = agent_api
        .runtime
        .clear_pending_triggers_in_scope(Some(principal), Some(workspace), agent_id)
        .await;
    if cleared.is_empty() {
        return 0;
    }
    let mut pending = agent_api.pending_cycle_dispatches.write().await;
    for reservation in &cleared {
        pending.remove(&reservation.cycle_id);
    }
    cleared.len()
}

async fn complete_cycle_and_take_next_dispatch(
    agent_api: &AgentApiServices,
    principal: &str,
    workspace: &str,
    agent_id: &str,
    goal_id: &str,
    cycle_id: &str,
    drain_queue: bool,
) -> Option<ManualTriggerDispatch> {
    let promoted = if drain_queue {
        agent_api
            .runtime
            .complete_active_cycle_in_scope(
                Some(principal),
                Some(workspace),
                agent_id,
                goal_id,
                cycle_id,
            )
            .await
    } else {
        let _ = agent_api
            .runtime
            .complete_active_cycle_without_promotion_in_scope(
                Some(principal),
                Some(workspace),
                agent_id,
                goal_id,
                cycle_id,
            )
            .await;
        None
    };

    let Some(promoted) = promoted else {
        return None;
    };

    let mut pending = agent_api.pending_cycle_dispatches.write().await;
    let next_dispatch = pending.remove(&promoted.cycle_id);
    if next_dispatch.is_none() {
        warn!(
            agent_id = %agent_id,
            promoted_cycle_id = %promoted.cycle_id,
            "Promoted queued cycle has no dispatch payload; dropping promoted cycle"
        );
    }
    next_dispatch
}

async fn complete_cycle_and_take_next_dispatch_controlled(
    agent_api: &AgentApiServices,
    principal: &str,
    workspace: &str,
    agent_id: &str,
    goal_id: &str,
    cycle_id: &str,
    drain_queue: bool,
) -> Option<ManualTriggerDispatch> {
    let _control_guard = agent_api.control_gate.lock().await;
    complete_cycle_and_take_next_dispatch(
        agent_api,
        principal,
        workspace,
        agent_id,
        goal_id,
        cycle_id,
        drain_queue,
    )
    .await
}

async fn abandon_cycle_and_take_next_dispatch(
    agent_api: &AgentApiServices,
    principal: &str,
    workspace: &str,
    agent_id: &str,
    goal_id: &str,
    cycle_id: &str,
    promote_queue: bool,
) -> Option<ManualTriggerDispatch> {
    let promoted = if promote_queue {
        agent_api
            .runtime
            .abandon_active_cycle_and_promote_next_in_scope(
                Some(principal),
                Some(workspace),
                agent_id,
                goal_id,
                cycle_id,
            )
            .await
    } else {
        let _ = agent_api
            .runtime
            .clear_active_cycle_if_matches_in_scope(
                Some(principal),
                Some(workspace),
                agent_id,
                goal_id,
                cycle_id,
            )
            .await;
        None
    };

    let Some(promoted) = promoted else {
        return None;
    };

    let mut pending = agent_api.pending_cycle_dispatches.write().await;
    let next_dispatch = pending.remove(&promoted.cycle_id);
    if next_dispatch.is_none() {
        warn!(
            agent_id = %agent_id,
            promoted_cycle_id = %promoted.cycle_id,
            "Promoted abandoned cycle has no dispatch payload; dropping promoted cycle"
        );
    }
    next_dispatch
}

async fn abandon_cycle_and_take_next_dispatch_controlled(
    agent_api: &AgentApiServices,
    principal: &str,
    workspace: &str,
    agent_id: &str,
    goal_id: &str,
    cycle_id: &str,
    promote_queue: bool,
) -> Option<ManualTriggerDispatch> {
    let _control_guard = agent_api.control_gate.lock().await;
    abandon_cycle_and_take_next_dispatch(
        agent_api,
        principal,
        workspace,
        agent_id,
        goal_id,
        cycle_id,
        promote_queue,
    )
    .await
}

async fn launch_manual_trigger_dispatch(
    agent_api: &AgentApiServices,
    v2_orchestrator: &Arc<MagicianV2Orchestrator>,
    dispatch: ManualTriggerDispatch,
    harness_root_permit: Option<HarnessRootPermit>,
) {
    let mut current = Some(dispatch);
    let mut inherited_harness_root_permit = harness_root_permit;
    while let Some(mut dispatch) = current {
        let _agent_lifecycle_exclusion = match acquire_agent_dispatch_lifecycle_exclusion(
            v2_orchestrator,
            &dispatch.principal,
            &dispatch.workspace,
            &dispatch.agent_id,
        )
        .await
        {
            Ok(exclusion) => exclusion,
            Err(_) => {
                let _ = abandon_cycle_and_take_next_dispatch_controlled(
                    agent_api,
                    &dispatch.principal,
                    &dispatch.workspace,
                    &dispatch.agent_id,
                    &dispatch.goal_id,
                    &dispatch.cycle_id,
                    false,
                )
                .await;
                return;
            },
        };
        {
            let _control_guard = agent_api.control_gate.lock().await;
            if agent_api
                .is_agent_paused(&dispatch.principal, &dispatch.workspace, &dispatch.agent_id)
                .await
                || !scheduled_dispatch_definition_still_exists(agent_api, &dispatch).await
            {
                let _ = abandon_cycle_and_take_next_dispatch(
                    agent_api,
                    &dispatch.principal,
                    &dispatch.workspace,
                    &dispatch.agent_id,
                    &dispatch.goal_id,
                    &dispatch.cycle_id,
                    false,
                )
                .await;
                return;
            }
        }
        let harness_root_permit =
            match try_admit_harness_root(&dispatch.goal_id, inherited_harness_root_permit.take()) {
                Ok(permit) => permit,
                Err(HarnessRootCapacityExhausted) => {
                    info!(
                        agent_id = %dispatch.agent_id,
                        goal_id = %dispatch.goal_id,
                        cycle_id = %dispatch.cycle_id,
                        "Dropping promoted harness trigger because root capacity is exhausted"
                    );
                    record_harness_root_capacity_drop(agent_api, &dispatch);
                    current = abandon_cycle_and_take_next_dispatch_controlled(
                        agent_api,
                        &dispatch.principal,
                        &dispatch.workspace,
                        &dispatch.agent_id,
                        &dispatch.goal_id,
                        &dispatch.cycle_id,
                        true,
                    )
                    .await;
                    continue;
                },
            };
        let execution_goal = match execution_goal_for_manual_dispatch(agent_api, &dispatch).await {
            Ok(goal) => goal,
            Err(err) => {
                warn!(
                    agent_id = %dispatch.agent_id,
                    goal_id = %dispatch.goal_id,
                    cycle_id = %dispatch.cycle_id,
                    error = %err,
                    "Prompt pipeline assembly failed before dispatch"
                );
                current = complete_cycle_and_take_next_dispatch_controlled(
                    agent_api,
                    &dispatch.principal,
                    &dispatch.workspace,
                    &dispatch.agent_id,
                    &dispatch.goal_id,
                    &dispatch.cycle_id,
                    true,
                )
                .await;
                inherited_harness_root_permit = harness_root_permit;
                continue;
            },
        };
        if let Err(error) = ensure_dispatch_task_backed_root(
            agent_api,
            v2_orchestrator,
            &mut dispatch,
            &execution_goal,
        )
        .await
        {
            warn!(
                agent_id = %dispatch.agent_id,
                goal_id = %dispatch.goal_id,
                cycle_id = %dispatch.cycle_id,
                error = %error,
                "Exact thread provisioning failed before dispatch"
            );
            current = abandon_cycle_and_take_next_dispatch_controlled(
                agent_api,
                &dispatch.principal,
                &dispatch.workspace,
                &dispatch.agent_id,
                &dispatch.goal_id,
                &dispatch.cycle_id,
                true,
            )
            .await;
            inherited_harness_root_permit = harness_root_permit;
            continue;
        }
        dispatch_manual_trigger_cycle(
            agent_api,
            v2_orchestrator,
            dispatch,
            execution_goal,
            harness_root_permit,
        );
        return;
    }
}

fn dispatch_manual_trigger_cycle(
    agent_api: &AgentApiServices,
    v2_orchestrator: &Arc<MagicianV2Orchestrator>,
    dispatch: ManualTriggerDispatch,
    execution_goal: String,
    harness_root_permit: Option<HarnessRootPermit>,
) {
    // Admission already reserved runtime cycle tracking in prepare_manual_trigger.

    if let Some(broadcaster) = v2_orchestrator.event_broadcaster() {
        emit_agent_triggered(
            &broadcaster,
            Some(&dispatch.principal),
            Some(&dispatch.workspace),
            &dispatch.agent_id,
            &dispatch.goal_id,
            &dispatch.trigger,
        );
    }

    let agent_api = agent_api.clone();
    let v2_orchestrator = Arc::clone(v2_orchestrator);
    spawn_execution_job(move || async move {
        let harness_root_permit = harness_root_permit;
        let prompt_identity = prompt_identity_for_manual_dispatch(&dispatch);
        let agent_id = dispatch.agent_id;
        let goal_id = dispatch.goal_id;
        let trigger = dispatch.trigger;
        let trigger_seq = dispatch.trigger_seq;
        let cycle_id = dispatch.cycle_id;
        let dispatch_principal = dispatch.principal;
        let dispatch_workspace = dispatch.workspace;
        let task_id = dispatch.task_id;
        let execution_id = dispatch.execution_id;
        let Some(runtime_execution_id) = dispatch.runtime_execution_id else {
            warn!(
                agent_id = %agent_id,
                goal_id = %goal_id,
                cycle_id = %cycle_id,
                "Manual trigger dispatch launched without an exact execution id; abandoning cycle"
            );
            magician::magician_v2::harness::record_harness_cycle_outcome(
                &harness_cycle_outcome_store(&agent_api),
                &dispatch_principal,
                &dispatch_workspace,
                &agent_id,
                &goal_id,
                Some(cycle_id.as_str()),
                Some(trigger_seq),
                magician::magician_v2::harness::HarnessCycleDispatchOutcome::DroppedNoExecutionId,
                serde_json::json!({ "reason": "missing_runtime_execution_id" }),
            );
            let next_dispatch = abandon_cycle_and_take_next_dispatch_controlled(
                &agent_api,
                &dispatch_principal,
                &dispatch_workspace,
                &agent_id,
                &goal_id,
                &cycle_id,
                true,
            )
            .await;
            if let Some(next_dispatch) = next_dispatch {
                launch_manual_trigger_dispatch(
                    &agent_api,
                    &v2_orchestrator,
                    next_dispatch,
                    harness_root_permit,
                )
                .await;
            }
            return;
        };
        let max_iterations = dispatch.max_iterations;
        let trust_level = dispatch.trust_level;
        let trust_policies_path = dispatch.trust_policies_path;
        let preloaded_trust_enforcer = dispatch.preloaded_trust_enforcer;
        let approval_rules = dispatch.approval_rules;
        let strategy_summary = dispatch.strategy_summary;
        let llm_routing_overrides = dispatch.llm_routing_overrides;
        let definition = dispatch.definition;
        let (principal, workspace) = match required_cycle_scope(&definition, &agent_id) {
            Ok(scope) => scope,
            Err(error) => {
                warn!(
                    agent_id = %agent_id,
                    goal_id = %goal_id,
                    cycle_id = %cycle_id,
                    error = %error,
                    "Skipping manual trigger dispatch because the agent definition is missing explicit scope"
                );
                magician::magician_v2::harness::record_harness_cycle_outcome(
                    &harness_cycle_outcome_store(&agent_api),
                    &dispatch_principal,
                    &dispatch_workspace,
                    &agent_id,
                    &goal_id,
                    Some(cycle_id.as_str()),
                    Some(trigger_seq),
                    magician::magician_v2::harness::HarnessCycleDispatchOutcome::DroppedProvisionFailed,
                    serde_json::json!({ "reason": "missing_scope", "error": error.as_str() }),
                );
                let _ = complete_cycle_and_take_next_dispatch_controlled(
                    &agent_api,
                    &dispatch_principal,
                    &dispatch_workspace,
                    &agent_id,
                    &goal_id,
                    &cycle_id,
                    false,
                )
                .await;
                return;
            },
        };
        let scoped_memory_service = match agent_api
            .resolve_cycle_memory_service(&definition, &agent_id)
        {
            Ok(service) => service,
            Err(error) => {
                warn!(
                    agent_id = %agent_id,
                    goal_id = %goal_id,
                    cycle_id = %cycle_id,
                    error = %error,
                    "Skipping manual trigger dispatch because the agent definition is missing explicit scope"
                );
                magician::magician_v2::harness::record_harness_cycle_outcome(
                    &harness_cycle_outcome_store(&agent_api),
                    &principal,
                    &workspace,
                    &agent_id,
                    &goal_id,
                    Some(cycle_id.as_str()),
                    Some(trigger_seq),
                    magician::magician_v2::harness::HarnessCycleDispatchOutcome::DroppedProvisionFailed,
                    serde_json::json!({ "reason": "memory_service_unavailable", "error": error.as_str() }),
                );
                let _ = complete_cycle_and_take_next_dispatch_controlled(
                    &agent_api, &principal, &workspace, &agent_id, &goal_id, &cycle_id, false,
                )
                .await;
                return;
            },
        };

        let dispatch_mutex = agent_api
            .runtime
            .dispatch_mutex_in_scope(&principal, &workspace, &agent_id, &goal_id)
            .await;
        let _dispatch_guard = dispatch_mutex.lock().await;

        if agent_api
            .is_agent_paused(&principal, &workspace, &agent_id)
            .await
        {
            info!(
                agent_id = %agent_id,
                goal_id = %goal_id,
                cycle_id = %cycle_id,
                "Skipping manual trigger dispatch because agent is paused"
            );
            magician::magician_v2::harness::record_harness_cycle_outcome(
                &harness_cycle_outcome_store(&agent_api),
                &principal,
                &workspace,
                &agent_id,
                &goal_id,
                Some(cycle_id.as_str()),
                Some(trigger_seq),
                magician::magician_v2::harness::HarnessCycleDispatchOutcome::DroppedPaused,
                serde_json::json!({ "reason": "agent_paused_before_dispatch" }),
            );
            let _ = complete_cycle_and_take_next_dispatch_controlled(
                &agent_api, &principal, &workspace, &agent_id, &goal_id, &cycle_id, false,
            )
            .await;
            return;
        }

        let is_duplicate_tuple = match scoped_memory_service
            .has_episode_for_trigger(&agent_id, &goal_id, trigger_seq)
            .await
        {
            Ok(found) => found,
            Err(error) => {
                warn!(
                    agent_id = %agent_id,
                    goal_id = %goal_id,
                    cycle_id = %cycle_id,
                    trigger_seq = trigger_seq,
                    error = %error,
                    "Duplicate trigger tuple check failed; continuing with execution"
                );
                false
            },
        };
        if is_duplicate_tuple {
            info!(
                agent_id = %agent_id,
                goal_id = %goal_id,
                cycle_id = %cycle_id,
                trigger_seq = trigger_seq,
                "Skipping duplicate trigger tuple: episode already exists"
            );
            magician::magician_v2::harness::record_harness_cycle_outcome(
                &harness_cycle_outcome_store(&agent_api),
                &principal,
                &workspace,
                &agent_id,
                &goal_id,
                Some(cycle_id.as_str()),
                Some(trigger_seq),
                magician::magician_v2::harness::HarnessCycleDispatchOutcome::DroppedDuplicate,
                serde_json::json!({
                    "reason": "episode_already_exists_for_trigger",
                    "trigger_seq": trigger_seq,
                }),
            );
            let next_dispatch = complete_cycle_and_take_next_dispatch_controlled(
                &agent_api, &principal, &workspace, &agent_id, &goal_id, &cycle_id, true,
            )
            .await;
            if let Some(next_dispatch) = next_dispatch {
                launch_manual_trigger_dispatch(
                    &agent_api,
                    &v2_orchestrator,
                    next_dispatch,
                    harness_root_permit,
                )
                .await;
            }
            return;
        }

        emit_agent_event(
            &v2_orchestrator,
            Some(&principal),
            Some(&workspace),
            "agent.cycle.started",
            &agent_id,
            serde_json::json!({
                "execution_id": runtime_execution_id.clone(),
                "cycle_id": cycle_id.clone(),
                "goal_id": goal_id.clone(),
                "trigger": trigger.clone(),
                "trigger_seq": trigger_seq,
            }),
        );

        let started_at = Utc::now();
        let max_spawned_tasks = definition
            .autonomous_config
            .as_ref()
            .map(|config| config.max_tasks_per_cycle);
        let mut context_overrides = build_direct_context_overrides(
            task_id
                .as_ref()
                .zip(execution_id.as_ref())
                .map(|(task_id, execution_id)| (task_id.as_str(), execution_id.as_str())),
            None,
            None,
        );
        if let Some(max_spawned_tasks) = max_spawned_tasks {
            context_overrides
                .get_or_insert_with(
                    magician::magician_v2::execution::AgenticContextOverrides::default,
                )
                .max_spawned_tasks = Some(max_spawned_tasks);
        }

        let outcome_result = async {
            let observed = v2_orchestrator.get_execution(&runtime_execution_id).await?;
            let mut context_overrides = context_overrides.unwrap_or_default();
            v2_orchestrator
                .bind_server_owned_fresh_launch_overrides(&observed, &mut context_overrides)
                .await?;
            v2_orchestrator
                .execute_agentic_direct_with_outcome(
                    &runtime_execution_id,
                    &execution_goal,
                    max_iterations,
                    Some(AgenticTrustContext {
                        trust_level,
                        trust_policies_path,
                        preloaded_trust_enforcer: Some(preloaded_trust_enforcer),
                        approval_rules,
                        agent_id: Some(agent_id.clone()),
                        goal_id: Some(goal_id.clone()),
                        cycle_id: Some(cycle_id.clone()),
                        llm_routing_overrides,
                        prompt_identity: Some(prompt_identity),
                    }),
                    Some(context_overrides),
                )
                .await
        }
        .await;
        let outcome = match outcome_result {
            Ok(outcome) => outcome,
            Err(err) => {
                warn!(
                    agent_id = %agent_id,
                    goal_id = %goal_id,
                    cycle_id = %cycle_id,
                    error = %err,
                    "Manual trigger execution failed"
                );
                AgenticOutcome::Failed {
                    reason: format!("manual trigger execution failed: {err}"),
                    last_state: EnvironmentState::Browser(
                        magician::magician_v2::execution::PageState::default(),
                    ),
                    iterations_used: 0,
                }
            },
        };
        // P1.5-permit fix (a): a delegating officer parked as WaitingForChildren
        // is NOT consuming a compute slot — its children run under the separate
        // DELEGATED_CHILD_SEMAPHORE. Holding the harness-root permit for the whole
        // (up to ~2h) child window starved the small root pool and, on a
        // deleted/unreadable execution, leaked forever. Release the root permit
        // now instead of pinning it: it flows to the next queued officer dispatch
        // below (permit hand-off) or drops here, freeing the slot for the loop.
        if harness_root_permit_requires_terminal_retention(&outcome)
            && harness_root_permit.is_some()
        {
            debug!(
                agent_id = %agent_id,
                goal_id = %goal_id,
                cycle_id = %cycle_id,
                execution_id = %runtime_execution_id,
                "Releasing harness root permit on WaitingForChildren; children hold their own semaphore"
            );
        }
        let completed_at = Utc::now();

        let episode_outcome = run_post_cycle_pipeline(
            &agent_api,
            &v2_orchestrator,
            &definition,
            &outcome,
            &agent_id,
            &goal_id,
            &cycle_id,
            &runtime_execution_id,
            &trigger,
            trigger_seq,
            started_at,
            completed_at,
            Some(&strategy_summary),
            task_id.as_deref(),
        )
        .await;

        if let Some(ref task_id) = task_id {
            match resolve_artifact_v2_service(&agent_api.runtime) {
                Ok(artifact_v2_service) => {
                    if let Err(error) =
                        persist_v3_root_run_outcome(&artifact_v2_service, &runtime_execution_id)
                            .await
                    {
                        warn!(
                            agent_id = %agent_id,
                            goal_id = %goal_id,
                            cycle_id = %cycle_id,
                            task_id = %task_id,
                            error = %error,
                            "Failed to persist task-backed manual cycle outcome"
                        );
                    }
                },
                Err(error) => {
                    warn!(
                        agent_id = %agent_id,
                        goal_id = %goal_id,
                        cycle_id = %cycle_id,
                        task_id = %task_id,
                        error = %error,
                        "Failed to resolve V3 task service for manual cycle outcome persistence"
                    );
                },
            }
        }

        let agent_paused = agent_api
            .is_agent_paused(&principal, &workspace, &agent_id)
            .await;
        let drain_queue = !episode_outcome.is_paused() && !agent_paused;
        let next_dispatch = complete_cycle_and_take_next_dispatch_controlled(
            &agent_api,
            &principal,
            &workspace,
            &agent_id,
            &goal_id,
            &cycle_id,
            drain_queue,
        )
        .await;
        if let Some(next_dispatch) = next_dispatch {
            launch_manual_trigger_dispatch(
                &agent_api,
                &v2_orchestrator,
                next_dispatch,
                harness_root_permit,
            )
            .await;
        }
    });
}

async fn cancel_execution_with_retries(
    v2_orchestrator: &Arc<MagicianV2Orchestrator>,
    execution_id: &str,
    max_attempts: usize,
    retry_delay: StdDuration,
) -> Result<bool, String> {
    if v2_orchestrator
        .get_execution(execution_id)
        .await
        .ok()
        .is_some_and(|execution| is_canonical_app_workflow_task_id(execution.task_id.as_deref()))
    {
        return Err("governed app cancellation requires effect settlement".to_owned());
    }
    let attempts = max_attempts.max(1);
    for attempt in 1..=attempts {
        match v2_orchestrator.cancel_execution_tree(execution_id).await {
            Ok(true) => return Ok(true),
            Ok(false) if attempt < attempts => tokio::time::sleep(retry_delay).await,
            Ok(false) => return Ok(false),
            Err(err) => return Err(err),
        }
    }
    Ok(false)
}

fn is_canonical_app_workflow_task_id(task_id: Option<&str>) -> bool {
    task_id.is_some_and(is_canonical_app_task_id)
}

