async fn cancel_active_agent_cycles(
    agent_api: &AgentApiServices,
    v2_orchestrator: &Arc<MagicianV2Orchestrator>,
    principal: &str,
    workspace: &str,
    agent_id: &str,
    admitted_execution_ids: &[String],
) -> bool {
    let active_cycles = agent_api
        .runtime
        .active_cycles_for_agent_in_scope(principal, workspace, agent_id)
        .await;
    let mut execution_ids = admitted_execution_ids.to_vec();
    for active_cycle in &active_cycles {
        let Some(execution_id) = active_cycle.execution_id.as_deref() else {
            warn!(
                agent_id = %agent_id,
                goal_id = %active_cycle.goal_id,
                cycle_id = %active_cycle.cycle_id,
                "Skipping active cycle cancellation because no exact execution id is bound"
            );
            continue;
        };
        execution_ids.push(execution_id.to_owned());
    }
    execution_ids.sort();
    execution_ids.dedup();
    let mut all_settled = true;

    for execution_id in execution_ids {
        if v2_orchestrator
            .get_execution(&execution_id)
            .await
            .ok()
            .is_some_and(|execution| {
                is_canonical_app_workflow_task_id(execution.task_id.as_deref())
            })
        {
            warn!(
                %principal,
                %workspace,
                %agent_id,
                %execution_id,
                "Skipping generic cancellation for a governed app workflow while its effect settlement is unknown"
            );
            all_settled = false;
            continue;
        }

        let settled = match cancel_execution_with_retries(
            v2_orchestrator,
            &execution_id,
            CANCEL_ACTIVE_CYCLE_MAX_ATTEMPTS,
            CANCEL_ACTIVE_CYCLE_RETRY_DELAY,
        )
        .await
        {
            Ok(true) => true,
            Ok(false) => match v2_orchestrator.get_execution(&execution_id).await {
                Ok(execution) if execution.waiting_state.is_terminal() => true,
                Err(error) if execution_lookup_error_is_missing(&error) => true,
                Ok(_) | Err(_) => {
                    warn!(
                        agent_id = %agent_id,
                        execution_id = %execution_id,
                        "Cancellation reported no-op while the execution remains nonterminal"
                    );
                    false
                },
            },
            Err(err) => {
                warn!(
                    agent_id = %agent_id,
                    execution_id = %execution_id,
                    error = %err,
                    "Failed to cancel active cycle while pausing agent; reservation preserved"
                );
                false
            },
        };
        if settled {
            for active_cycle in active_cycles
                .iter()
                .filter(|cycle| cycle.execution_id.as_deref() == Some(execution_id.as_str()))
            {
                let cleared = agent_api
                    .runtime
                    .clear_active_cycle_if_matches_in_scope(
                        Some(principal),
                        Some(workspace),
                        agent_id,
                        &active_cycle.goal_id,
                        &active_cycle.cycle_id,
                    )
                    .await;
                if !cleared {
                    warn!(
                        agent_id = %agent_id,
                        goal_id = %active_cycle.goal_id,
                        cycle_id = %active_cycle.cycle_id,
                        execution_id = %execution_id,
                        "Cancelled execution but active reservation changed before clear"
                    );
                }
            }
        } else {
            all_settled = false;
        }
    }
    all_settled
}

#[derive(Debug, Default)]
struct HarnessRuntimeStopSummary {
    harness_agents_seen: usize,
    active_cycles_targeted: usize,
    pending_dispatches_cleared: usize,
    warnings: Vec<String>,
}

async fn stop_active_harness_agents(
    agent_api: &AgentApiServices,
    v2_orchestrator: &Arc<MagicianV2Orchestrator>,
    full_pause_store: &Arc<FullPauseStore>,
) -> HarnessRuntimeStopSummary {
    let mut summary = HarnessRuntimeStopSummary::default();
    let records = match agent_api
        .definition_store
        .list_all_definitions_across_scopes()
        .await
    {
        Ok(records) => records,
        Err(error) => {
            summary
                .warnings
                .push(format!("failed to enumerate harness agents: {error}"));
            return summary;
        },
    };
    let mut seen = HashSet::new();
    let mut harness_agents = Vec::new();
    for record in records {
        let definition = record.definition;
        if definition.harness.is_none() {
            continue;
        }
        let (Some(principal), Some(workspace)) = (
            definition.principal.as_deref(),
            definition.workspace.as_deref(),
        ) else {
            continue;
        };
        let key = (
            principal.to_string(),
            workspace.to_string(),
            definition.agent_id.clone(),
        );
        if !seen.insert(key.clone()) {
            continue;
        }
        harness_agents.push(key);
    }
    harness_agents.sort();
    for (principal, workspace, agent_id) in harness_agents {
        summary.harness_agents_seen += 1;
        let admission = match acquire_agent_lifecycle_mutation_admission(
            agent_api,
            v2_orchestrator,
            full_pause_store,
            &principal,
            &workspace,
            &agent_id,
        )
        .await
        {
            Ok(admission) => admission,
            Err(_) => {
                summary.warnings.push(format!(
                    "deferred harness stop for agent {agent_id}: durable lifecycle admission is unavailable"
                ));
                continue;
            },
        };
        summary.pending_dispatches_cleared +=
            clear_pending_dispatches_for_agent(agent_api, &principal, &workspace, &agent_id).await;
        summary.active_cycles_targeted += admission.execution_ids.len();
        if !cancel_active_agent_cycles(
            agent_api,
            v2_orchestrator,
            &principal,
            &workspace,
            &agent_id,
            &admission.execution_ids,
        )
        .await
        {
            summary.warnings.push(format!(
                "harness stop for agent {agent_id} left at least one durable execution unsettled"
            ));
        }
    }
    summary
}

fn should_cancel_active_cycle_after_delete(status: StatusCode) -> bool {
    status.is_success()
}

/// Full 10-step admission pipeline for manual agent triggers.
///
/// Pub(crate) visibility allows the WebSocket `ui.interaction` handler (GC-B02)
/// to reuse the same pipeline without duplicating admission logic.
/// R749: Transport-agnostic result from the manual trigger pipeline.
/// Used by the WebSocket handler to avoid HttpResponse abstraction leak.
#[derive(Debug)]
// R884: Note — `#[non_exhaustive]` has no effect on `pub(crate)` enums within the
// same crate. New variants will produce compile errors at existing match sites automatically.
pub(crate) enum ManualTriggerOutcome {
    /// 202 Accepted — cycle dispatched or queued.
    Accepted(ManualAgentTriggerResponse),
    /// Pipeline error — wraps the HTTP status code and the ApiErrorEnvelope body.
    Error {
        http_status: u16,
        body: HttpResponse,
    },
}

impl ManualTriggerOutcome {
    /// Convert to HttpResponse for REST API callers.
    pub(crate) fn into_http_response(self) -> HttpResponse {
        match self {
            ManualTriggerOutcome::Accepted(response) => HttpResponse::Accepted().json(response),
            ManualTriggerOutcome::Error { body, .. } => body,
        }
    }
}

async fn acquire_agent_dispatch_lifecycle_exclusion(
    v2_orchestrator: &Arc<MagicianV2Orchestrator>,
    principal: &str,
    workspace: &str,
    agent_id: &str,
) -> std::result::Result<StatelessTerminalAgentLifecycleExclusion, ()> {
    let Some(full_pause_store) = v2_orchestrator.full_pause_store_handle() else {
        warn!(
            %principal,
            %workspace,
            %agent_id,
            "Agent execution admission has no shared durable pause store"
        );
        return Err(());
    };
    full_pause_store
        .acquire_stateless_agent_lifecycle_exclusion_scoped(principal, workspace, agent_id)
        .await
        .map_err(|error| {
            warn!(
                %principal,
                %workspace,
                %agent_id,
                %error,
                "Agent execution admission could not acquire its durable lifecycle fence"
            );
            ()
        })
}

/// R749: Transport-agnostic trigger pipeline entry point.
/// Returns structured result that both REST and WebSocket handlers can consume.
pub(crate) async fn trigger_agent_controlled(
    agent_api: &AgentApiServices,
    definition_store: &AgentDefinitionStore,
    v2_orchestrator: Option<&Arc<MagicianV2Orchestrator>>,
    agent_id: &str,
    request: ManualAgentTriggerRequest,
) -> ManualTriggerOutcome {
    if let Err(response) = ensure_agent_startup_hydrated(agent_api).await {
        return ManualTriggerOutcome::Error {
            http_status: response.status().as_u16(),
            body: response,
        };
    }
    let _agent_lifecycle_exclusion = if let Some(orchestrator) = v2_orchestrator {
        let Some((principal, workspace)) = definition_store.current_scope() else {
            let body = api_error_response(
                StatusCode::UNPROCESSABLE_ENTITY,
                "agent_scope_missing",
                "Triggering an agent requires an explicit principal/workspace-scoped store",
                Some(serde_json::json!({ "agent_id": agent_id })),
            );
            return ManualTriggerOutcome::Error {
                http_status: body.status().as_u16(),
                body,
            };
        };
        match acquire_agent_dispatch_lifecycle_exclusion(
            orchestrator,
            &principal,
            &workspace,
            agent_id,
        )
        .await
        {
            Ok(exclusion) => Some(exclusion),
            Err(()) => {
                let body = agent_lifecycle_admission_unavailable_response(agent_id, None);
                return ManualTriggerOutcome::Error {
                    http_status: body.status().as_u16(),
                    body,
                };
            },
        }
    } else {
        None
    };
    let _control_guard = agent_api.control_gate.lock().await;
    match prepare_manual_trigger_with_store(agent_api, definition_store, agent_id, request).await {
        Ok((mut dispatch, schedule)) => {
            let harness_root_permit = if matches!(schedule, ManualDispatchSchedule::StartNow)
                && v2_orchestrator.is_some()
            {
                match try_admit_harness_root(&dispatch.goal_id, None) {
                    Ok(permit) => permit,
                    Err(HarnessRootCapacityExhausted) => {
                        info!(
                            agent_id = %dispatch.agent_id,
                            goal_id = %dispatch.goal_id,
                            cycle_id = %dispatch.cycle_id,
                            "Rejecting manual harness trigger because root capacity is exhausted"
                        );
                        record_harness_root_capacity_drop(agent_api, &dispatch);
                        let _ = agent_api
                            .runtime
                            .clear_active_cycle_if_matches_in_scope(
                                Some(&dispatch.principal),
                                Some(&dispatch.workspace),
                                &dispatch.agent_id,
                                &dispatch.goal_id,
                                &dispatch.cycle_id,
                            )
                            .await;
                        return ManualTriggerOutcome::Error {
                            http_status: StatusCode::TOO_MANY_REQUESTS.as_u16(),
                            body: api_error_response(
                                StatusCode::TOO_MANY_REQUESTS,
                                "harness_root_capacity_exhausted",
                                "Harness root capacity is exhausted",
                                Some(serde_json::json!({
                                    "agent_id": dispatch.agent_id,
                                    "goal_id": dispatch.goal_id,
                                    "cycle_id": dispatch.cycle_id,
                                })),
                            ),
                        };
                    },
                }
            } else {
                None
            };
            let execution_goal = if matches!(schedule, ManualDispatchSchedule::StartNow) {
                match execution_goal_for_manual_dispatch(agent_api, &dispatch).await {
                    Ok(goal) => Some(goal),
                    Err(err) => {
                        let _ = agent_api
                            .runtime
                            .clear_active_cycle_if_matches_in_scope(
                                Some(&dispatch.principal),
                                Some(&dispatch.workspace),
                                &dispatch.agent_id,
                                &dispatch.goal_id,
                                &dispatch.cycle_id,
                            )
                            .await;
                        let response = prompt_pipeline_assembly_error_response(
                            &dispatch.agent_id,
                            &dispatch.goal_id,
                            &err,
                        );
                        return ManualTriggerOutcome::Error {
                            http_status: response.status().as_u16(),
                            body: response,
                        };
                    },
                }
            } else {
                None
            };
            if matches!(schedule, ManualDispatchSchedule::StartNow) {
                if let Some(orchestrator) = v2_orchestrator {
                    if let Err(error) = ensure_dispatch_task_backed_root(
                        agent_api,
                        orchestrator,
                        &mut dispatch,
                        execution_goal.as_deref().expect(
                            "execution_goal must exist for ManualDispatchSchedule::StartNow",
                        ),
                    )
                    .await
                    {
                        let _ = agent_api
                            .runtime
                            .clear_active_cycle_if_matches_in_scope(
                                Some(&dispatch.principal),
                                Some(&dispatch.workspace),
                                &dispatch.agent_id,
                                &dispatch.goal_id,
                                &dispatch.cycle_id,
                            )
                            .await;
                        return ManualTriggerOutcome::Error {
                            http_status: StatusCode::INTERNAL_SERVER_ERROR.as_u16(),
                            body: api_error_response(
                                StatusCode::INTERNAL_SERVER_ERROR,
                                "cycle_thread_provision_failed",
                                format!("Failed to create execution thread for cycle: {error}"),
                                Some(serde_json::json!({
                                    "agent_id": dispatch.agent_id,
                                    "goal_id": dispatch.goal_id,
                                    "cycle_id": dispatch.cycle_id,
                                })),
                            ),
                        };
                    }
                }
            }
            let response_body = manual_trigger_response(&dispatch, schedule);
            if matches!(schedule, ManualDispatchSchedule::StartNow) {
                if let Some(orchestrator) = v2_orchestrator {
                    let goal = execution_goal
                        .expect("execution_goal must exist for ManualDispatchSchedule::StartNow");
                    dispatch_manual_trigger_cycle(
                        agent_api,
                        orchestrator,
                        dispatch,
                        goal,
                        harness_root_permit,
                    );
                } else {
                    // Test-only helper paths can call this without an orchestrator.
                    // Release the reservation so follow-up tests are not blocked.
                    let _ = agent_api
                        .runtime
                        .clear_active_cycle_if_matches_in_scope(
                            Some(&dispatch.principal),
                            Some(&dispatch.workspace),
                            &dispatch.agent_id,
                            &dispatch.goal_id,
                            &dispatch.cycle_id,
                        )
                        .await;
                }
            }
            ManualTriggerOutcome::Accepted(response_body)
        },
        Err(response) => ManualTriggerOutcome::Error {
            http_status: response.status().as_u16(),
            body: response,
        },
    }
}

