async fn resume_agent_with_store(
    agent_api: &AgentApiServices,
    definition_store: &AgentDefinitionStore,
    agent_id: &str,
) -> HttpResponse {
    if let Err(response) = ensure_agent_startup_hydrated(agent_api).await {
        return response;
    }
    let _control_guard = agent_api.control_gate.lock().await;
    if let Err(response) =
        ensure_agent_exists_for_api_with_store(agent_api, definition_store, agent_id).await
    {
        return response;
    }
    let Some((principal, workspace)) = definition_store.current_scope() else {
        return api_error_response(
            StatusCode::UNPROCESSABLE_ENTITY,
            "agent_scope_missing",
            "Resuming an agent requires an explicit principal/workspace-scoped store",
            Some(serde_json::json!({ "agent_id": agent_id })),
        );
    };
    let paused_agents = agent_api
        .resolve_paused_agents(&principal, &workspace)
        .await;

    let removed = paused_agents.write().await.remove(agent_id);
    if removed {
        if let Err(err) = persist_paused_agents_state(agent_api, &principal, &workspace).await {
            paused_agents.write().await.insert(agent_id.to_string());
            warn!(
                agent_id = %agent_id,
                error = %err,
                "Failed to persist paused agent state"
            );
            return api_error_response(
                StatusCode::INTERNAL_SERVER_ERROR,
                "pause_state_persist_failed",
                "Failed to persist paused state",
                Some(serde_json::json!({
                    "agent_id": agent_id,
                })),
            );
        }
    }
    HttpResponse::Ok().json(AgentPauseResumeResponse {
        agent_id: agent_id.to_string(),
        status: "idle".to_string(),
        changed: removed,
    })
}

