#[derive(Debug, Clone, Deserialize)]
pub struct UserKnowledgeQuery {
    #[serde(default)]
    pub promotions_limit: Option<usize>,
    #[serde(default)]
    pub promotions_offset: Option<usize>,
    #[serde(default)]
    pub skips_limit: Option<usize>,
    #[serde(default)]
    pub skips_offset: Option<usize>,
    #[serde(default)]
    pub include_knowledge: Option<bool>,
}

impl UserKnowledgeQuery {
    fn requested_pagination(&self) -> bool {
        self.promotions_limit.is_some()
            || self.promotions_offset.is_some()
            || self.skips_limit.is_some()
            || self.skips_offset.is_some()
    }

    fn promotions_limit(&self) -> usize {
        user_knowledge_limit(self.promotions_limit)
    }

    fn promotions_offset(&self) -> usize {
        self.promotions_offset.unwrap_or(0)
    }

    fn skips_limit(&self) -> usize {
        user_knowledge_limit(self.skips_limit)
    }

    fn skips_offset(&self) -> usize {
        self.skips_offset.unwrap_or(0)
    }

    fn include_knowledge(&self) -> bool {
        self.include_knowledge
            .unwrap_or_else(|| !self.requested_pagination())
    }
}

fn user_knowledge_limit(limit: Option<usize>) -> usize {
    limit
        .unwrap_or(USER_KNOWLEDGE_DEFAULT_LIMIT)
        .clamp(1, USER_KNOWLEDGE_MAX_LIMIT)
}

