    /// PUT /api/magician/v2/agents/{id}
    pub async fn update_agent_definition(
        &self,
        path: web::Path<String>,
        request: HttpRequest,
        payload: web::Bytes,
    ) -> Result<HttpResponse> {
        let (principal, workspace) = match resolve_required_scope_from_request(&request) {
            Ok(scope) => scope,
            Err(response) => return Ok(response),
        };
        let definition_store = self
            .agent_api
            .resolve_definition_store(&principal, &workspace);
        let agent_id = path.into_inner();
        let if_match = match parse_if_match_condition(&request) {
            Ok(condition) => condition,
            Err(response) => return Ok(response),
        };
        let definition = match parse_agent_definition_payload(&request, &payload) {
            Ok(definition) => definition,
            Err(response) => return Ok(response),
        };

        let response = update_agent_definition_controlled_with_store(
            &self.agent_api,
            &definition_store,
            &agent_id,
            definition,
            if_match,
        )
        .await;
        if response.status().is_success() {
            emit_agent_event(
                &self.v2_orchestrator,
                Some(&principal),
                Some(&workspace),
                "agent.updated",
                &agent_id,
                serde_json::json!({ "status": "updated" }),
            );
            self.reconcile_progress_subscriptions().await;
            emit_agent_definition_changed(&self.v2_orchestrator, &principal, &workspace, &agent_id);
        }
        Ok(response)
    }

    /// PATCH /api/magician/v2/agents/{id} — JSON Merge Patch (RFC 7386)
    pub async fn patch_agent_definition(
        &self,
        path: web::Path<String>,
        request: HttpRequest,
        payload: web::Bytes,
    ) -> Result<HttpResponse> {
        let (principal, workspace) = match resolve_required_scope_from_request(&request) {
            Ok(scope) => scope,
            Err(response) => return Ok(response),
        };
        let definition_store = self
            .agent_api
            .resolve_definition_store(&principal, &workspace);
        let agent_id = path.into_inner();
        let if_match = match parse_if_match_condition(&request) {
            Ok(condition) => condition,
            Err(response) => return Ok(response),
        };

        let patch: Value = match serde_json::from_slice(&payload) {
            Ok(v) => v,
            Err(err) => {
                return Ok(api_error_response(
                    StatusCode::BAD_REQUEST,
                    "invalid_json",
                    format!("Invalid JSON in PATCH body: {err}"),
                    None,
                ));
            },
        };

        if !patch.is_object() {
            return Ok(api_error_response(
                StatusCode::BAD_REQUEST,
                "patch_must_be_object",
                "PATCH body must be a JSON object",
                None,
            ));
        }

        let response = patch_agent_definition_controlled_with_store(
            &self.agent_api,
            &definition_store,
            &agent_id,
            &patch,
            if_match,
        )
        .await;

        if response.status().is_success() {
            emit_agent_event(
                &self.v2_orchestrator,
                Some(&principal),
                Some(&workspace),
                "agent.updated",
                &agent_id,
                serde_json::json!({ "status": "patched" }),
            );
            self.reconcile_progress_subscriptions().await;
            emit_agent_definition_changed(&self.v2_orchestrator, &principal, &workspace, &agent_id);
        }
        Ok(response)
    }

    /// DELETE /api/magician/v2/agents/{id}
    pub async fn delete_agent_definition(
        &self,
        path: web::Path<String>,
        request: HttpRequest,
    ) -> Result<HttpResponse> {
        let (principal, workspace) = match resolve_required_scope_from_request(&request) {
            Ok(scope) => scope,
            Err(response) => return Ok(response),
        };
        let definition_store = self
            .agent_api
            .resolve_definition_store(&principal, &workspace);
        let agent_id = path.into_inner();
        let admission = match acquire_agent_lifecycle_mutation_admission(
            &self.agent_api,
            &self.v2_orchestrator,
            &self.full_pause_store,
            &principal,
            &workspace,
            &agent_id,
        )
        .await
        {
            Ok(admission) => admission,
            Err(response) => return Ok(response),
        };
        if !cancel_active_agent_cycles(
            &self.agent_api,
            &self.v2_orchestrator,
            &principal,
            &workspace,
            &agent_id,
            &admission.execution_ids,
        )
        .await
        {
            return Ok(agent_lifecycle_admission_unavailable_response(
                &agent_id, None,
            ));
        }
        let (response, active_cycle_snapshot) = delete_agent_definition_controlled_with_store(
            &self.agent_api,
            &definition_store,
            &agent_id,
        )
        .await;
        if should_cancel_active_cycle_after_delete(response.status()) {
            let mut execution_ids = admission.execution_ids.clone();
            for active_cycle in active_cycle_snapshot {
                let Some(execution_id) = active_cycle.execution_id else {
                    warn!(
                        agent_id = %agent_id,
                        goal_id = %active_cycle.goal_id,
                        cycle_id = %active_cycle.cycle_id,
                        "Clearing pre-execution active reservation during agent deletion"
                    );
                    let _ = self
                        .agent_api
                        .runtime
                        .clear_active_cycle_if_matches_in_scope(
                            Some(&principal),
                            Some(&workspace),
                            &agent_id,
                            &active_cycle.goal_id,
                            &active_cycle.cycle_id,
                        )
                        .await;
                    continue;
                };
                execution_ids.push(execution_id);
            }
            execution_ids.sort();
            execution_ids.dedup();
            let _ = cancel_active_agent_cycles(
                &self.agent_api,
                &self.v2_orchestrator,
                &principal,
                &workspace,
                &agent_id,
                &execution_ids,
            )
            .await;
        }
        if response.status() == actix_web::http::StatusCode::NO_CONTENT {
            emit_agent_event(
                &self.v2_orchestrator,
                Some(&principal),
                Some(&workspace),
                "agent.deleted",
                &agent_id,
                serde_json::json!({ "status": "deleted" }),
            );
            self.reconcile_progress_subscriptions().await;
            emit_agent_definition_changed(&self.v2_orchestrator, &principal, &workspace, &agent_id);
        }
        Ok(response)
    }

    /// POST /api/magician/v2/agents/{id}/set-primary
    pub async fn set_primary_agent(
        &self,
        path: web::Path<String>,
        request: HttpRequest,
    ) -> Result<HttpResponse> {
        let (principal, workspace) = match resolve_required_scope_from_request(&request) {
            Ok(scope) => scope,
            Err(response) => return Ok(response),
        };
        let definition_store = self
            .agent_api
            .resolve_definition_store(&principal, &workspace);
        let agent_id = path.into_inner();
        if let Err(response) = ensure_agent_startup_hydrated(&self.agent_api).await {
            return Ok(response);
        }
        let _control_guard = self.agent_api.control_gate.lock().await;
        let result =
            set_primary_agent_with_store(&self.agent_api, &definition_store, &agent_id).await;
        if result.response.status().is_success() {
            emit_agent_event(
                &self.v2_orchestrator,
                Some(&principal),
                Some(&workspace),
                "agent.updated",
                &agent_id,
                serde_json::json!({ "status": "primary_set" }),
            );
            emit_agent_definition_changed(&self.v2_orchestrator, &principal, &workspace, &agent_id);
            if let Some(previous_primary_agent_id) = result.previous_primary_agent_id.as_deref() {
                emit_agent_event(
                    &self.v2_orchestrator,
                    Some(&principal),
                    Some(&workspace),
                    "agent.updated",
                    previous_primary_agent_id,
                    serde_json::json!({ "status": "primary_cleared" }),
                );
                emit_agent_definition_changed(
                    &self.v2_orchestrator,
                    &principal,
                    &workspace,
                    previous_primary_agent_id,
                );
            }
        }
        Ok(result.response)
    }

