    /// POST /api/magician/v2/memory/search
    ///
    /// Owner debug recall. Same ranking and match shape as the `search_memory`
    /// tool, without recording a temperature use.
    pub async fn search_memory(
        &self,
        req: &HttpRequest,
        body: MemorySearchRequest,
    ) -> Result<HttpResponse> {
        let (principal, workspace) = match resolve_required_scope_from_request(req) {
            Ok(scope) => scope,
            Err(response) => return Ok(response),
        };
        let query = body.query.trim();
        if query.is_empty() {
            return Ok(HttpResponse::BadRequest().json(serde_json::json!({
                "status": "error",
                "reason": "query is required",
            })));
        }
        let agent_id = body
            .agent_id
            .as_deref()
            .map(str::trim)
            .filter(|value| !value.is_empty())
            .unwrap_or(magician::magician_v2::chat::DEFAULT_AGENT_ID);
        let tier = body
            .tier
            .as_deref()
            .map(str::trim)
            .filter(|value| !value.is_empty())
            .map(str::to_ascii_lowercase);
        let limit = body.limit.unwrap_or(20).clamp(1, 50);
        let response = magician::magician_v2::execution::compiled_handlers::search_memory::search_memory_recall(
            &self.agent_api.definition_store,
            &self.agent_api.memory_resolver,
            &principal,
            &workspace,
            agent_id,
            query,
            tier.as_deref(),
            limit,
            &magician::magician_v2::agents::RetrievalScope::Unbound,
            false,
        )
        .await;
        Ok(HttpResponse::Ok().json(response))
    }

