    /// GET /api/magician/v2/approvals
    pub async fn list_approvals(
        &self,
        request: HttpRequest,
        query: web::Query<ListApprovalsQuery>,
    ) -> Result<HttpResponse> {
        let (principal, workspace) = match resolve_required_scope_from_request(&request) {
            Ok(scope) => scope,
            Err(response) => return Ok(response),
        };
        let approval_service = match self
            .agent_api
            .resolve_approval_service(&principal, &workspace)
            .await
        {
            Ok(service) => service,
            Err(err) => return Ok(approval_service_error_response(err, None)),
        };
        let query = query.into_inner();
        let status_filter = query.status.as_deref();
        let agent_id_filter = query
            .agent_id
            .as_deref()
            .map(str::trim)
            .filter(|value| !value.is_empty());

        let expired_requests = match approval_service.expire_pending_requests(Utc::now()).await {
            Ok(requests) => requests,
            Err(err) => return Ok(approval_service_error_response(err, None)),
        };
        for request in expired_requests {
            emit_approval_expired_event(
                &self.v2_orchestrator,
                Some(&principal),
                Some(&workspace),
                &request,
                "approval_list_endpoint",
            );
        }

        let approvals = match approval_service.list_requests_raw().await {
            Ok(approvals) => approvals,
            Err(err) => return Ok(approval_service_error_response(err, None)),
        };

        let approvals = approvals
            .into_iter()
            .filter(|request| approval_matches_status_filter(request, status_filter))
            .filter(|request| {
                agent_id_filter
                    .map(|agent_id| request.agent_id == agent_id)
                    .unwrap_or(true)
            })
            .collect::<Vec<_>>();
        let total_count = approvals.len();

        Ok(HttpResponse::Ok().json(ApprovalListResponse {
            approvals,
            total_count,
        }))
    }

    /// GET /api/magician/v2/approvals/{approval_id}
    pub async fn get_approval(
        &self,
        request: HttpRequest,
        path: web::Path<String>,
    ) -> Result<HttpResponse> {
        let (principal, workspace) = match resolve_required_scope_from_request(&request) {
            Ok(scope) => scope,
            Err(response) => return Ok(response),
        };
        let approval_service = match self
            .agent_api
            .resolve_approval_service(&principal, &workspace)
            .await
        {
            Ok(service) => service,
            Err(err) => return Ok(approval_service_error_response(err, None)),
        };
        let approval_id = path.into_inner();
        let (request, expired_on_read) = match approval_service
            .get_request_with_transition(&approval_id)
            .await
        {
            Ok((Some(request), expired_on_read)) => (request, expired_on_read),
            Ok((None, _)) => {
                return Ok(api_error_response(
                    StatusCode::NOT_FOUND,
                    "approval_not_found",
                    "Approval not found",
                    Some(serde_json::json!({ "approval_id": approval_id })),
                ));
            },
            Err(err) => return Ok(approval_service_error_response(err, Some(&approval_id))),
        };
        if expired_on_read {
            emit_approval_expired_event(
                &self.v2_orchestrator,
                Some(&principal),
                Some(&workspace),
                &request,
                "approval_get_endpoint",
            );
        }

        let deliveries = match approval_service.list_deliveries(&approval_id).await {
            Ok(deliveries) => deliveries,
            Err(err) => return Ok(approval_service_error_response(err, Some(&approval_id))),
        };

        Ok(HttpResponse::Ok().json(ApprovalDetailsResponse {
            request,
            deliveries,
        }))
    }

    /// POST /api/magician/v2/approvals/{approval_id}/resolve
    pub async fn resolve_approval(
        &self,
        request: HttpRequest,
        path: web::Path<String>,
        req: web::Json<ResolveApprovalRequest>,
    ) -> Result<HttpResponse> {
        let (principal, workspace) = match resolve_required_scope_from_request(&request) {
            Ok(scope) => scope,
            Err(response) => return Ok(response),
        };
        let approval_service = match self
            .agent_api
            .resolve_approval_service(&principal, &workspace)
            .await
        {
            Ok(service) => service,
            Err(err) => return Ok(approval_service_error_response(err, None)),
        };
        let approval_id = path.into_inner();
        let req = req.into_inner();
        let decision = req.decision.clone();
        let channel = req.channel.trim();
        if channel.is_empty() {
            return Ok(api_error_response(
                StatusCode::BAD_REQUEST,
                "invalid_approval_request",
                "channel must not be empty",
                Some(serde_json::json!({ "approval_id": approval_id })),
            ));
        }

        // Approval resolution mutates durable approval state before the
        // auto-resume path gets a chance to inspect the pause. Fence that
        // mutation against the exact hidden terminal generation first. The
        // non-transitioning read avoids expiring or otherwise resolving the
        // approval while receipt settlement still owns publication.
        let approval_snapshot = match approval_service.get_request(&approval_id).await {
            Ok(Some(request)) => request,
            Ok(None) => {
                return Ok(api_error_response(
                    StatusCode::NOT_FOUND,
                    "approval_not_found",
                    "Approval not found",
                    Some(serde_json::json!({ "approval_id": approval_id })),
                ));
            },
            Err(err) => return Ok(approval_service_error_response(err, Some(&approval_id))),
        };
        let approval_pause_key = pause_storage_key_for_agent_ids(
            &approval_snapshot.agent_id,
            &approval_snapshot.goal_id,
            &approval_snapshot.cycle_id,
        );
        let _hitl_lifecycle_exclusion = match acquire_hitl_lifecycle_mutation_admission(
            &self.full_pause_store,
            approval_snapshot.execution_id.as_deref(),
            &approval_pause_key,
            &principal,
            &workspace,
            &approval_snapshot.agent_id,
            "resolve_approval",
        )
        .await
        {
            Ok(exclusion) => exclusion,
            Err(response) => return Ok(response),
        };

        let (existing, expired_on_read) = match approval_service
            .get_request_with_transition(&approval_id)
            .await
        {
            Ok((Some(request), expired_on_read)) => (request, expired_on_read),
            Ok((None, _)) => {
                return Ok(api_error_response(
                    StatusCode::NOT_FOUND,
                    "approval_not_found",
                    "Approval not found",
                    Some(serde_json::json!({ "approval_id": approval_id })),
                ));
            },
            Err(err) => return Ok(approval_service_error_response(err, Some(&approval_id))),
        };
        if expired_on_read {
            emit_approval_expired_event(
                &self.v2_orchestrator,
                Some(&principal),
                Some(&workspace),
                &existing,
                "approval_resolve_endpoint",
            );
        }
        if existing.status == ApprovalStatus::Expired {
            return Ok(api_error_response(
                StatusCode::GONE,
                "approval_expired",
                "Approval is expired",
                Some(serde_json::json!({ "approval_id": existing.approval_id })),
            ));
        }

        let current_plan_hash = if req.decision == ApprovalDecision::Approve {
            current_plan_hash_for_approval(&self.full_pause_store, &existing)
        } else {
            None
        };

        let outcome = match approval_service
            .resolve_with_outcome(
                &approval_id,
                decision.clone(),
                channel,
                current_plan_hash.as_deref(),
            )
            .await
        {
            Ok(outcome) => outcome,
            Err(err) => return Ok(approval_service_error_response(err, Some(&approval_id))),
        };

        let resolved = match outcome {
            ApprovalResolveOutcome::Resolved => true,
            ApprovalResolveOutcome::Noop => false,
            ApprovalResolveOutcome::Expired { transitioned } => {
                if transitioned {
                    match approval_service.get_request(&approval_id).await {
                        Ok(Some(expired_request)) => emit_approval_expired_event(
                            &self.v2_orchestrator,
                            Some(&principal),
                            Some(&workspace),
                            &expired_request,
                            "approval_resolve_endpoint",
                        ),
                        Ok(None) => {},
                        Err(err) => {
                            warn!(
                                approval_id = %approval_id,
                                error = %err,
                                "Failed to load expired approval after resolve transition"
                            );
                        },
                    }
                }
                return Ok(api_error_response(
                    StatusCode::GONE,
                    "approval_expired",
                    "Approval is expired",
                    Some(serde_json::json!({ "approval_id": approval_id })),
                ));
            },
        };

        if resolved {
            emit_approval_resolved_event(
                &self.v2_orchestrator,
                Some(&principal),
                Some(&workspace),
                &existing,
                &decision,
                channel,
                "approval_resolve_endpoint",
            );
        }

        if should_auto_resume_on_approval_resolution(&decision, resolved) {
            let auto_resume_api = self.clone();
            let approval_snapshot = existing.clone();
            let resume_principal = principal.clone();
            let resume_workspace = workspace.clone();
            spawn_execution_job(move || async move {
                let approval_id = approval_snapshot.approval_id.clone();
                let Some(execution_hint) = execution_hint_for_approval(
                    &auto_resume_api.full_pause_store,
                    &approval_snapshot,
                    &resume_principal,
                    &resume_workspace,
                ) else {
                    warn!(
                        approval_id = %approval_id,
                        agent_id = %approval_snapshot.agent_id,
                        goal_id = %approval_snapshot.goal_id,
                        cycle_id = %approval_snapshot.cycle_id,
                        principal = %resume_principal,
                        workspace = %resume_workspace,
                        "Auto-resume skipped because no unique scoped pause matched the approval"
                    );
                    return;
                };
                let auto_resume_request =
                    build_auto_resume_request_for_approval(&approval_snapshot);
                match auto_resume_api
                    .resume_agentic_execution_with_scope(
                        web::Path::from(execution_hint.clone()),
                        web::Json(auto_resume_request),
                        Some((resume_principal.clone(), resume_workspace.clone())),
                    )
                    .await
                {
                    Ok(response) => {
                        let status = response.status();
                        if status.is_success() {
                            info!(
                                approval_id = %approval_id,
                                agent_id = %approval_snapshot.agent_id,
                                goal_id = %approval_snapshot.goal_id,
                                cycle_id = %approval_snapshot.cycle_id,
                                status = %status,
                                "Auto-resume started after approval resolve"
                            );
                        } else if is_benign_auto_resume_race(status) {
                            info!(
                                approval_id = %approval_id,
                                agent_id = %approval_snapshot.agent_id,
                                goal_id = %approval_snapshot.goal_id,
                                cycle_id = %approval_snapshot.cycle_id,
                                status = %status,
                                "Auto-resume skipped because pause state was already consumed"
                            );
                        } else {
                            warn!(
                                approval_id = %approval_id,
                                agent_id = %approval_snapshot.agent_id,
                                goal_id = %approval_snapshot.goal_id,
                                cycle_id = %approval_snapshot.cycle_id,
                                status = %status,
                                "Auto-resume failed after approval resolve"
                            );
                        }
                    },
                    Err(err) => {
                        warn!(
                            approval_id = %approval_id,
                            agent_id = %approval_snapshot.agent_id,
                            goal_id = %approval_snapshot.goal_id,
                            cycle_id = %approval_snapshot.cycle_id,
                            error = %err,
                            "Auto-resume task errored after approval resolve"
                        );
                    },
                }
            });
        }

        Ok(HttpResponse::Ok().json(ResolveApprovalResponse { resolved }))
    }

    /// POST /api/magician/v2/proposals
    pub async fn create_proposal(
        &self,
        request: HttpRequest,
        req: web::Json<CreateProposalRequest>,
    ) -> Result<HttpResponse> {
        let (principal, workspace) = match resolve_required_scope_from_request(&request) {
            Ok(scope) => scope,
            Err(response) => return Ok(response),
        };
        let definition_store = self
            .agent_api
            .resolve_definition_store(&principal, &workspace);
        let proposal =
            match create_proposal_with_store(&self.agent_api, &definition_store, req.into_inner())
                .await
            {
                Ok(proposal) => proposal,
                Err(response) => return Ok(response),
            };

        emit_proposal_created_event(
            &self.v2_orchestrator,
            &principal,
            &workspace,
            &proposal,
            "proposal_create_endpoint",
        );
        Ok(HttpResponse::Created().json(CreateProposalResponse { proposal }))
    }

