    /// POST /api/magician/v2/proposals/{proposal_id}/resolve
    pub async fn resolve_proposal(
        &self,
        request: HttpRequest,
        path: web::Path<String>,
        req: web::Json<ResolveProposalRequest>,
    ) -> Result<HttpResponse> {
        let (principal, workspace) = match resolve_required_scope_from_request(&request) {
            Ok(scope) => scope,
            Err(response) => return Ok(response),
        };
        let proposal_id = path.into_inner();
        let req = req.into_inner();
        let mut retire_admission: Option<AgentLifecycleMutationAdmission> = None;
        if matches!(&req.decision, ProposalDecision::Approve) {
            if let Err(response) = ensure_agent_startup_hydrated(&self.agent_api).await {
                return Ok(response);
            }
            let proposal_store = self
                .agent_api
                .resolve_proposal_store(&principal, &workspace)
                .await;
            match proposal_store.get_proposal(&proposal_id).await {
                Ok(Some(proposal))
                    if matches!(
                        proposal_action_kind(&proposal),
                        Some(magician::magician_v2::harness::RETIRE_AGENT_TOOL_NAME)
                    ) =>
                {
                    retire_admission = Some(
                        match acquire_agent_lifecycle_mutation_admission(
                            &self.agent_api,
                            &self.v2_orchestrator,
                            &self.full_pause_store,
                            &principal,
                            &workspace,
                            &proposal.agent_id,
                        )
                        .await
                        {
                            Ok(admission) => admission,
                            Err(response) => return Ok(response),
                        },
                    );
                },
                Ok(Some(_)) | Ok(None) => {},
                Err(error) => {
                    return Ok(proposal_store_error_response(error, Some(&proposal_id)));
                },
            }
        }
        let mut resolved =
            match resolve_proposal_impl(&self.agent_api, &principal, &workspace, &proposal_id, req)
                .await
            {
                Ok(resolved) => resolved,
                Err(response) => return Ok(response),
            };

        if resolved.resolved {
            emit_proposal_resolved_event(
                &self.v2_orchestrator,
                &principal,
                &workspace,
                &resolved.proposal,
                &resolved.decision,
                &resolved.channel,
                "proposal_resolve_endpoint",
            );
        }

        let mut applied_version = None;
        let mut application_error = None;
        let mut retired_agent_scope: Option<(String, String, String)> = None;

        // Attempt application when: (a) freshly approved, or (b) duplicate resolve
        // on an already-approved proposal that hasn't been applied yet (retry path).
        let should_apply = matches!(resolved.decision, ProposalDecision::Approve)
            && (resolved.resolved
                || resolved.proposal.applied_version.is_none()
                || matches!(
                    proposal_action_kind(&resolved.proposal),
                    Some(magician::magician_v2::harness::RETIRE_AGENT_TOOL_NAME)
                ));
        if should_apply {
            if matches!(
                proposal_action_kind(&resolved.proposal),
                Some(magician::magician_v2::harness::RETIRE_AGENT_TOOL_NAME)
            ) && retire_admission.is_none()
            {
                retire_admission = Some(
                    match acquire_agent_lifecycle_mutation_admission(
                        &self.agent_api,
                        &self.v2_orchestrator,
                        &self.full_pause_store,
                        &principal,
                        &workspace,
                        &resolved.proposal.agent_id,
                    )
                    .await
                    {
                        Ok(admission) => admission,
                        Err(response) => return Ok(response),
                    },
                );
            }
            if matches!(
                proposal_action_kind(&resolved.proposal),
                Some(magician::magician_v2::harness::RETIRE_AGENT_TOOL_NAME)
            ) {
                let admission = retire_admission
                    .as_ref()
                    .expect("retire proposal lifecycle admission must be held before apply");
                if !cancel_active_agent_cycles(
                    &self.agent_api,
                    &self.v2_orchestrator,
                    &principal,
                    &workspace,
                    &resolved.proposal.agent_id,
                    &admission.execution_ids,
                )
                .await
                {
                    return Ok(agent_lifecycle_admission_unavailable_response(
                        &resolved.proposal.agent_id,
                        None,
                    ));
                }
            }
            // Acquire control_gate to serialize with other definition-mutating
            // operations (create/update/delete, cycle dispatch, trust policy).
            let _control_guard = self.agent_api.control_gate.lock().await;
            match apply_approved_proposal(
                &self.agent_api,
                &resolved.proposal,
                &principal,
                &workspace,
            )
            .await
            {
                Ok(result) => {
                    if let Some(warning) = result.application_warning.clone() {
                        application_error = Some(warning);
                    }
                    if result.freshly_applied {
                        // Only emit events and invalidate cache on fresh application,
                        // not on the idempotent early-return path.
                        invalidate_agent_list_cache(&self.agent_api).await;
                        emit_proposal_applied_event(
                            &self.v2_orchestrator,
                            &principal,
                            &workspace,
                            &resolved.proposal,
                            result.version,
                        );
                        let applied_agent_event = if matches!(
                            proposal_action_kind(&resolved.proposal),
                            Some(magician::magician_v2::harness::CREATE_AGENT_TOOL_NAME)
                        ) {
                            ("agent.created", serde_json::json!({ "status": "created" }))
                        } else {
                            (
                                "agent.updated",
                                serde_json::json!({
                                    "status": if result.retired { "retired" } else { "updated" }
                                }),
                            )
                        };
                        emit_agent_event(
                            &self.v2_orchestrator,
                            Some(result.definition.principal.as_deref().unwrap_or(&principal)),
                            Some(result.definition.workspace.as_deref().unwrap_or(&workspace)),
                            applied_agent_event.0,
                            &result.definition.agent_id,
                            applied_agent_event.1,
                        );
                        self.reconcile_progress_subscriptions().await;
                        emit_agent_definition_changed(
                            &self.v2_orchestrator,
                            result.definition.principal.as_deref().unwrap_or(&principal),
                            result.definition.workspace.as_deref().unwrap_or(&workspace),
                            &result.definition.agent_id,
                        );
                        if result.retired {
                            retired_agent_scope = Some((
                                result.definition.principal.clone().unwrap_or_default(),
                                result.definition.workspace.clone().unwrap_or_default(),
                                result.definition.agent_id.clone(),
                            ));
                        }
                    } else if result.retired && result.retired_state_reconciled {
                        retired_agent_scope = Some((
                            result.definition.principal.clone().unwrap_or_default(),
                            result.definition.workspace.clone().unwrap_or_default(),
                            result.definition.agent_id.clone(),
                        ));
                    }
                    applied_version = Some(result.version);
                    // Re-fetch proposal to include applied_version in response.
                    // Fall back to in-memory mutation if re-fetch fails (e.g. transient I/O).
                    match self
                        .agent_api
                        .resolve_proposal_store(
                            result.definition.principal.as_deref().unwrap_or_default(),
                            result.definition.workspace.as_deref().unwrap_or_default(),
                        )
                        .await
                        .get_proposal(&resolved.proposal.proposal_id)
                        .await
                    {
                        Ok(Some(updated_proposal)) => {
                            resolved.proposal = updated_proposal;
                        },
                        _ => {
                            resolved.proposal.applied_version = Some(result.version);
                            resolved.proposal.applied_at = Some(chrono::Utc::now());
                        },
                    }
                },
                Err(err) => {
                    warn!(
                        proposal_id = %resolved.proposal.proposal_id,
                        agent_id = %resolved.proposal.agent_id,
                        error = %err,
                        "Failed to apply approved proposal — definition unchanged"
                    );
                    application_error = Some(err.to_string());
                },
            }
        }

        if let Some((retired_principal, retired_workspace, retired_agent_id)) = retired_agent_scope
        {
            let admitted_execution_ids = retire_admission
                .as_ref()
                .map(|admission| admission.execution_ids.as_slice())
                .unwrap_or_default();
            let _ = cancel_active_agent_cycles(
                &self.agent_api,
                &self.v2_orchestrator,
                &retired_principal,
                &retired_workspace,
                &retired_agent_id,
                admitted_execution_ids,
            )
            .await;
            emit_agent_event(
                &self.v2_orchestrator,
                Some(&retired_principal),
                Some(&retired_workspace),
                "agent.paused",
                &retired_agent_id,
                serde_json::json!({ "status": "paused" }),
            );
        }

        Ok(HttpResponse::Ok().json(ResolveProposalResponse {
            resolved: resolved.resolved,
            proposal: resolved.proposal,
            applied_version,
            application_error,
        }))
    }

    /// POST /api/magician/v2/executions/{id}/message
    /// Enhanced message processing with query analysis
    pub async fn post_message_v2(
        &self,
        path: web::Path<String>,
        req: web::Json<MagicianV2PostMessageRequest>,
        event_broadcaster: Option<
            Arc<magician::magician_v2::realtime_events::RuntimeTransportBroadcaster>,
        >,
    ) -> Result<HttpResponse> {
        let requested_execution_id = path.into_inner();
        let execution_id =
            normalize_execution_lookup_id(&self.agent_api, &requested_execution_id).await;
        info!(
            "[MAGICIAN-V2-API] V2: Processing message for execution: {}",
            execution_id
        );

        // Use V2 orchestrator for enhanced processing
        let orchestrator = &self.v2_orchestrator;

        let execution = match orchestrator.get_execution(&execution_id).await {
            Ok(execution) => execution,
            Err(err) => {
                error!(
                    "[MAGICIAN-V2-API] V2: Failed to load execution {}: {}",
                    requested_execution_id, err
                );
                return Ok(v2_execution_load_error(&requested_execution_id, &err));
            },
        };
        if !matches!(
            self.v2_orchestrator
                .is_governed_app_execution(&execution_id)
                .await,
            Ok(false)
        ) {
            return Ok(governed_app_generic_lifecycle_refused(&execution_id));
        }
        if let Err(error) = self
            .v2_orchestrator
            .require_stateless_scope_activated(&execution.principal, &execution.workspace)
            .await
        {
            return Ok(v2_execution_prepare_error(
                error,
                "Failed to verify stateless execution scope activation",
            ));
        }

        let execution_context = ExecutionContext {
            principal: execution.principal.clone(),
            workspace: execution.workspace.clone(),
            ..ExecutionContext::default()
        };
        let artifact_v2_service = match resolve_artifact_v2_service(&self.agent_api.runtime) {
            Ok(service) => service,
            Err(error) => {
                return Ok(v2_internal_error(
                    "Failed to resolve V3 task service",
                    Some(serde_json::json!({ "error": error })),
                ));
            },
        };

        debug!("[MAGICIAN-V2-API] V2: Starting enhanced message processing with query analysis");

        if req.skip_planning {
            if let Some(message) = direct_execution_block_reason(&execution.waiting_state) {
                return Ok(v2_conflict(
                    "Execution is not startable",
                    Some(serde_json::json!({
                        "execution_id": execution_id,
                        "waiting_state": execution.waiting_state,
                        "message": message,
                    })),
                ));
            }

            info!(
                "[MAGICIAN-V2-API] V2: Direct agentic execution (skip_planning=true) for execution {}",
                execution_id,
            );

            if let Err(error) = artifact_v2_service
                .accept_and_launch_runtime_request(
                    &execution_id,
                    AcceptedRuntimeLaunchRequest {
                        mode: AcceptedRuntimeLaunchMode::Direct,
                        message: req.text.clone(),
                        max_iterations: req.max_iterations,
                        llm_routing_overrides: client_llm_routing_overrides(
                            req.llm_routing_overrides.as_ref(),
                        ),
                        env_mode: None,
                        in_reply_to_slot_id: None,
                    },
                )
                .await
            {
                return Ok(v2_execution_prepare_error(
                    error.to_string(),
                    "Failed to durably accept direct execution message",
                ));
            }

            return Ok(HttpResponse::Accepted().json(serde_json::json!({
                "execution_id": execution_id,
                "skip_planning": true
            })));
        }

        // Enhanced processing: message analysis + conversation storage + strategy
        // execution
        if let Err(error) = artifact_v2_service
            .activate_execution_by_runtime_id(&execution_id)
            .await
        {
            error!(
                "[MAGICIAN-V2-API] V2: Failed to activate V3 execution {} before planning: {}",
                execution_id, error
            );
            return Ok(v2_internal_error(
                "Failed to activate V3 execution",
                Some(serde_json::json!({ "error": error.to_string() })),
            ));
        }

        match orchestrator
            .process_with_strategy(
                &req.text,
                execution_context,
                req.in_reply_to_slot_id.clone(),
                Some(execution_id.clone()),
                None,
            )
            .await
        {
            Ok(strategy_result) => {
                info!(
                    "[MAGICIAN-V2-API] V2: Strategy processing completed successfully for execution: \
                     {}",
                    execution_id
                );
                Ok(HttpResponse::Ok().json(strategy_result))
            },
            Err(e) => {
                error!(
                    "[MAGICIAN-V2-API] V2: Failed to process strategy for execution {}: {}",
                    execution_id, e
                );

                // Get the execution to retrieve its processing_correlation_id before clearing it
                let correlation_id = match orchestrator.get_execution(&execution_id).await {
                    Ok(execution) => execution.processing_correlation_id.unwrap_or_else(|| {
                        warn!("[MAGICIAN-V2-API] V2: Execution {} has no processing_correlation_id, generating fallback", execution_id);
                        format!("msg-{}-{}", execution_id, uuid::Uuid::new_v4())
                    }),
                    Err(get_err) => {
                        warn!("[MAGICIAN-V2-API] V2: Failed to get execution {}: {}, generating fallback correlation_id", execution_id, get_err);
                        format!("msg-{}-{}", execution_id, uuid::Uuid::new_v4())
                    }
                };

                // Update execution status to Failed (this also clears processing_correlation_id)
                if let Err(status_err) = orchestrator
                    .transition_status(
                        &execution_id,
                        magician::magician_v2::orchestrator::v2_orchestrator::WorkflowEvent::ExecutionFailed,
                    )
                    .await
                {
                    error!(
                        "[MAGICIAN-V2-API] V2: Failed to transition execution {} to Failed status: {}",
                        execution_id, status_err
                    );
                } else {
                    info!(
                        "[MAGICIAN-V2-API] V2: Execution {} status updated to Failed and processing_correlation_id cleared",
                        execution_id
                    );
                }

                // Emit ProcessingError event to update frontend state
                let error_message = e.to_string();
                let error_type = "StrategyProcessingError".to_string();

                if let Some(broadcaster) = &event_broadcaster {
                    broadcaster.processing_error(
                        &execution_id,
                        &correlation_id,
                        error_message.clone(),
                        error_type,
                    );
                    info!(
                        "[MAGICIAN-V2-API] V2: ProcessingError event emitted for execution {} with correlation_id {}",
                        execution_id, correlation_id
                    );
                } else {
                    warn!(
                        "[MAGICIAN-V2-API] V2: Event broadcaster not available, cannot emit \
                         ProcessingError event"
                    );
                }

                Ok(v2_internal_error(
                    "V2 strategy processing failed",
                    Some(serde_json::json!({
                        "execution_id": requested_execution_id,
                    })),
                ))
            },
        }
    }

    /// POST /api/magician/v2/executions/{id}/start
    /// Start direct agentic execution on an existing execution (no planning).
    pub async fn start_execution(
        &self,
        path: web::Path<String>,
        req: web::Json<StartExecutionRequest>,
    ) -> Result<HttpResponse> {
        let requested_execution_id = path.into_inner();
        let execution_id =
            normalize_execution_lookup_id(&self.agent_api, &requested_execution_id).await;
        let goal = req.goal.trim();

        if goal.is_empty() {
            return Ok(v2_invalid_request("Goal is required", None));
        }

        let execution = match self.v2_orchestrator.get_execution(&execution_id).await {
            Ok(execution) => execution,
            Err(err) => {
                error!(
                    "[MAGICIAN-V2-API] V2: Failed to load execution {}: {}",
                    requested_execution_id, err
                );
                return Ok(v2_execution_load_error(&requested_execution_id, &err));
            },
        };
        if !matches!(
            self.v2_orchestrator
                .is_governed_app_execution(&execution_id)
                .await,
            Ok(false)
        ) {
            return Ok(governed_app_generic_lifecycle_refused(&execution_id));
        }
        if let Err(error) = self
            .v2_orchestrator
            .require_stateless_scope_activated(&execution.principal, &execution.workspace)
            .await
        {
            return Ok(v2_execution_prepare_error(
                error,
                "Failed to verify stateless execution scope activation",
            ));
        }

        if let Some(message) = direct_execution_block_reason(&execution.waiting_state) {
            return Ok(v2_conflict(
                "Execution is not startable",
                Some(serde_json::json!({
                    "execution_id": execution_id,
                    "waiting_state": execution.waiting_state,
                    "message": message,
                })),
            ));
        }

        info!(
            "[MAGICIAN-V2-API] V2: Starting direct agentic execution for execution {}",
            execution_id,
        );

        let goal = goal.to_string();
        let artifact_v2_service = match resolve_artifact_v2_service(&self.agent_api.runtime) {
            Ok(service) => service,
            Err(error) => {
                return Ok(v2_internal_error(
                    "Failed to resolve V3 task service",
                    Some(serde_json::json!({ "error": error })),
                ));
            },
        };

        if let Err(error) = artifact_v2_service
            .accept_and_launch_runtime_request(
                &execution_id,
                AcceptedRuntimeLaunchRequest {
                    mode: AcceptedRuntimeLaunchMode::Direct,
                    message: goal,
                    max_iterations: req.max_iterations,
                    llm_routing_overrides: client_llm_routing_overrides(
                        req.llm_routing_overrides.as_ref(),
                    ),
                    env_mode: None,
                    in_reply_to_slot_id: None,
                },
            )
            .await
        {
            return Ok(v2_execution_prepare_error(
                error.to_string(),
                "Failed to durably accept direct execution start",
            ));
        }

        Ok(HttpResponse::Accepted().json(serde_json::json!({
            "execution_id": execution_id,
            "skip_planning": true
        })))
    }

    // ========================================================================
    // Execution Management Methods
    // ========================================================================

    /// POST /api/magician/v2/executions
    /// Create a new execution (optionally with an initial message)
    pub fn create_execution<'a>(
        &'a self,
        http_req: &'a HttpRequest,
        req: web::Json<CreateExecutionRequest>,
    ) -> Pin<Box<dyn Future<Output = Result<HttpResponse>> + 'a>> {
        // This route provisions a task shell and durably accepts its launch,
        // both of which are intentionally broad async graphs. Keep that graph
        // behind one definition-level heap boundary so direct Rust callers,
        // tests, and the Actix adapter all store only a trait-object pointer.
        // The allocation is one per create request on an I/O-bound path.
        Box::pin(self.create_execution_inner(http_req, req))
    }

    async fn create_execution_inner(
        &self,
        http_req: &HttpRequest,
        req: web::Json<CreateExecutionRequest>,
    ) -> Result<HttpResponse> {
        let (principal, workspace) = match resolve_required_scope_from_request(http_req) {
            Ok(scope) => scope,
            Err(response) => return Ok(response),
        };
        if let Err(error) = self
            .v2_orchestrator
            .require_stateless_scope_activated(&principal, &workspace)
            .await
        {
            return Ok(v2_execution_prepare_error(
                error,
                "Failed to verify stateless execution scope activation",
            ));
        }
        let title = req.title.clone();
        let initial_message = req.initial_message.clone();
        let ui_thread_id = req.ui_thread_id.clone();
        let skip_planning = req.skip_planning;
        let max_iterations = req.max_iterations;
        let llm_routing_overrides =
            client_llm_routing_overrides(req.llm_routing_overrides.as_ref());
        // Capability "env" scope (debug page / SOTA tests): when set, the
        // direct execution is restricted to that single tool (e.g. browser).
        let env_mode = req.env_mode.clone();
        // v0.6.655 — debug-page runs (SOTA fixtures, skill action
        // tests, agentic experiments) shouldn't pollute the user's
        // `/tasks` view. The handler sets `debug: true` so the
        // task-creation helper marks the V3 task NOT user-visible.
        let debug_run = req.debug;
        // Contextual/extension automation can be user-initiated while its task
        // remains execution machinery that should stay off the user's `/tasks`.
        let internal_task = req.internal;

        info!(
            "[MAGICIAN-V2-API] V2: Creating execution for principal={}, workspace={}, \
             initial_message={}, skip_planning={}",
            principal,
            workspace,
            initial_message.is_some(),
            skip_planning,
        );

        // Create the execution first so the caller gets an exact runtime id immediately.
        let definition_store = self
            .agent_api
            .resolve_definition_store(&principal, &workspace);
        let active_owner_agent_id = match definition_store.get_primary_agent().await {
            Ok(Some(record)) => record.definition.agent_id,
            _ => magician::magician_v2::chat::DEFAULT_AGENT_ID.to_string(),
        };
        let _agent_lifecycle_exclusion = match acquire_agent_dispatch_lifecycle_exclusion(
            &self.v2_orchestrator,
            &principal,
            &workspace,
            &active_owner_agent_id,
        )
        .await
        {
            Ok(exclusion) => exclusion,
            Err(()) => {
                return Ok(agent_lifecycle_admission_unavailable_response(
                    &active_owner_agent_id,
                    None,
                ))
            },
        };
        if active_owner_agent_id != magician::magician_v2::chat::DEFAULT_AGENT_ID {
            match definition_store
                .get_definition(&active_owner_agent_id)
                .await
            {
                Ok(Some(_)) => {},
                Ok(None) => {
                    return Ok(agent_lifecycle_admission_unavailable_response(
                        &active_owner_agent_id,
                        None,
                    ));
                },
                Err(error) => {
                    warn!(
                        agent_id = %active_owner_agent_id,
                        %principal,
                        %workspace,
                        %error,
                        "Direct execution owner could not be revalidated under lifecycle exclusion"
                    );
                    return Ok(agent_lifecycle_admission_unavailable_response(
                        &active_owner_agent_id,
                        None,
                    ));
                },
            }
        }
        let artifact_v2_service = match resolve_artifact_v2_service(&self.agent_api.runtime) {
            Ok(service) => service,
            Err(error) => {
                return Ok(v2_internal_error(
                    "Failed to resolve V3 task service",
                    Some(serde_json::json!({ "error": error })),
                ));
            },
        };
        // The work this run belongs to, as the generic carrier. Only the *name*
        // crosses this boundary; the orchestrator validates it against the live
        // roster and supplies the revision, so naming a work context is never
        // the same as being granted it.
        let requested_work = req.engagement_id.as_deref().map(|engagement_id| {
            magician::magician_v2::work_context::WorkContextKind::Engagement(
                engagement_id.to_string(),
            )
        });
        // HTTP acceptance always starts from a non-activating shell. The
        // exact request is sealed before Artifact becomes Running.
        let shell_root_run = match create_task_backed_execution_shell(
            artifact_v2_service.as_ref(),
            &self.v2_orchestrator,
            &principal,
            &workspace,
            &ui_thread_id,
            title.as_deref(),
            initial_message.as_deref(),
            &active_owner_agent_id,
            magician::magician_v2::storage::TaskCreatedBy::User,
            debug_run,
            internal_task,
            requested_work.as_ref(),
        )
        .await
        {
            Ok(root_run) => Some(root_run),
            Err(error) => {
                error!(
                    "[MAGICIAN-V2-API] V2: Failed to create task-backed execution shell: {}",
                    error
                );
                return Ok(v2_execution_prepare_error(
                    error,
                    "Failed to prepare task-backed execution",
                ));
            },
        };

        let execution_result = if let Some((_, _, runtime_execution_id)) = shell_root_run.as_ref() {
            self.v2_orchestrator
                .get_execution(runtime_execution_id)
                .await
        } else {
            Err("task-backed execution shell was not created".to_string())
        };

        match execution_result {
            Ok(execution) => {
                info!(
                    "[MAGICIAN-V2-API] V2: Execution created successfully: {}",
                    execution.id
                );

                // Return 202 only after the exact accepted request is durable.
                if let Some(initial_msg) = initial_message {
                    info!(
                        "[MAGICIAN-V2-API] V2: Scheduling initial message for execution {}",
                        execution.id
                    );

                    let request = AcceptedRuntimeLaunchRequest {
                        mode: if skip_planning {
                            AcceptedRuntimeLaunchMode::Direct
                        } else {
                            AcceptedRuntimeLaunchMode::Planning
                        },
                        message: initial_msg,
                        max_iterations: if skip_planning { max_iterations } else { None },
                        llm_routing_overrides: if skip_planning {
                            llm_routing_overrides
                        } else {
                            None
                        },
                        env_mode: if skip_planning { env_mode } else { None },
                        in_reply_to_slot_id: None,
                    };
                    if let Err(error) = artifact_v2_service
                        .accept_and_launch_runtime_request(&execution.id, request)
                        .await
                    {
                        return Ok(v2_execution_prepare_error(
                            error.to_string(),
                            "Failed to durably accept initial execution message",
                        ));
                    }

                    Ok(HttpResponse::Accepted().json(serde_json::json!({
                        "execution_id": execution.id,
                        "execution": execution,
                        "initial_message_enqueued": true,
                        "skip_planning": skip_planning
                    })))
                } else {
                    Ok(HttpResponse::Ok().json(serde_json::json!({
                        "execution_id": execution.id,
                        "execution": execution,
                        "initial_message_enqueued": false,
                        "skip_planning": skip_planning
                    })))
                }
            },
            Err(e) => {
                error!("[MAGICIAN-V2-API] V2: Failed to create execution: {}", e);
                Ok(v2_internal_error("Failed to create execution", None))
            },
        }
    }

    /// GET /api/magician/v2/executions
    /// List executions with pagination
    pub async fn list_executions(
        &self,
        http_req: &HttpRequest,
        query: web::Query<ListExecutionsQuery>,
    ) -> Result<HttpResponse> {
        let (principal, workspace) = match resolve_required_scope_from_request(http_req) {
            Ok(scope) => scope,
            Err(response) => return Ok(response),
        };
        let pagination = PaginationParams::new(query.limit, query.offset);

        debug!(
            "[MAGICIAN-V2-API] V2: Listing executions for principal={}, workspace={}, limit={}, \
             offset={}",
            principal, workspace, pagination.limit, pagination.offset
        );

        let orchestrator = &self.v2_orchestrator;

        match orchestrator
            .list_executions(&principal, &workspace, pagination)
            .await
        {
            Ok(mut result) => {
                debug!(
                    "[MAGICIAN-V2-API] V2: Found {} executions (total: {})",
                    result.items.len(),
                    result.pagination.total
                );
                // Enrich WaitingUser executions with escalation_trigger from pause store.
                for execution in result.items.iter_mut() {
                    if execution.waiting_state == WaitingState::WaitingUser {
                        if let Some(trigger) = self
                            .full_pause_store
                            .get_escalation_trigger_for_execution(&execution.id)
                        {
                            execution.escalation_trigger = Some(trigger);
                        }
                    }
                }
                Ok(HttpResponse::Ok().json(result))
            },
            Err(e) => {
                error!("[MAGICIAN-V2-API] V2: Failed to list executions: {}", e);
                Ok(v2_internal_error("Failed to list executions", None))
            },
        }
    }

    /// GET /api/magician/v2/executions/{id}
    /// Get a specific execution
    pub async fn get_execution(&self, path: web::Path<String>) -> Result<HttpResponse> {
        let requested_execution_id = path.into_inner();
        let execution_id =
            normalize_execution_lookup_id(&self.agent_api, &requested_execution_id).await;
        debug!("[MAGICIAN-V2-API] V2: Getting execution: {}", execution_id);

        let orchestrator = &self.v2_orchestrator;

        match orchestrator.get_execution(&execution_id).await {
            Ok(execution) => {
                let mut execution = execution;
                debug!("[MAGICIAN-V2-API] V2: Execution found: {}", execution.id);
                // Enrich with escalation_trigger if the execution is paused
                if execution.waiting_state == WaitingState::WaitingUser {
                    if let Some(trigger) = self
                        .full_pause_store
                        .get_escalation_trigger_for_execution(&execution.id)
                    {
                        execution.escalation_trigger = Some(trigger);
                    }
                }
                Ok(HttpResponse::Ok().json(execution))
            },
            Err(e) => {
                error!(
                    "[MAGICIAN-V2-API] V2: Failed to get execution {}: {}",
                    requested_execution_id, e
                );
                Ok(v2_execution_load_error(&requested_execution_id, &e))
            },
        }
    }

    /// DELETE /api/magician/v2/executions/{id}
    /// Delete an execution
    pub async fn delete_execution(
        &self,
        request: &HttpRequest,
        path: web::Path<String>,
    ) -> Result<HttpResponse> {
        let requested_execution_id = path.into_inner();
        let (execution_id, _execution) = match self
            .resolve_scoped_execution_control(request, &requested_execution_id)
            .await
        {
            Ok(resolved) => resolved,
            Err(response) => return Ok(response),
        };
        info!("[MAGICIAN-V2-API] V2: Deleting execution: {}", execution_id);

        let orchestrator = &self.v2_orchestrator;
        if !matches!(
            self.v2_orchestrator
                .is_governed_app_execution(&execution_id)
                .await,
            Ok(false)
        ) {
            return Ok(governed_app_generic_lifecycle_refused(&execution_id));
        }
        // Cancellation owns the exact cross-process execution fence through
        // preparation reconciliation, cleanup and the Cancelled status CAS.
        // Delete only after that atomic seam settles; a separate web preflight
        // would be a TOCTOU check and would block this async worker on disk IO.
        if let Err(error) = orchestrator.cancel_execution_tree(&execution_id).await {
            warn!(
                execution_id = %execution_id,
                error = %error,
                "[MAGICIAN-V2-API] V2: Refusing delete because cancellation did not settle"
            );
            return Ok(terminal_pause_settlement_pending_response(&execution_id));
        }

        match orchestrator.delete_execution(&execution_id).await {
            Ok(()) => {
                info!(
                    "[MAGICIAN-V2-API] V2: Execution deleted successfully: {}",
                    execution_id
                );
                Ok(HttpResponse::NoContent().finish())
            },
            Err(e) => {
                if e.to_ascii_lowercase().contains("not found") {
                    info!(
                        "[MAGICIAN-V2-API] V2: Execution not found for deletion: {}",
                        execution_id
                    );
                    Ok(v2_not_found(
                        "Execution not found",
                        Some(serde_json::json!({
                            "execution_id": requested_execution_id,
                        })),
                    ))
                } else {
                    error!(
                        "[MAGICIAN-V2-API] V2: Failed to delete execution {}: {}",
                        execution_id, e
                    );
                    Ok(v2_internal_error(
                        "Failed to delete execution",
                        Some(serde_json::json!({
                            "execution_id": requested_execution_id,
                        })),
                    ))
                }
            },
        }
    }

    /// GET /api/magician/v2/executions/{id}/turns
    /// List turns for an execution with pagination
    pub async fn list_turns(
        &self,
        path: web::Path<String>,
        query: web::Query<ListTurnsQuery>,
    ) -> Result<HttpResponse> {
        let execution_id = normalize_execution_lookup_id(&self.agent_api, &path.into_inner()).await;
        let pagination = PaginationParams::new(query.limit, query.offset);

        // Parse direction filter
        let direction_filter = query.direction.as_ref().and_then(|d| match d.as_str() {
            "Inbound" => Some(TurnDirection::Inbound),
            "Outbound" => Some(TurnDirection::Outbound),
            _ => None,
        });

        info!(
            "[MAGICIAN-V2-API] V2: Listing turns for execution={}, limit={}, offset={}, filter={:?}",
            execution_id, pagination.limit, pagination.offset, direction_filter
        );

        let orchestrator = &self.v2_orchestrator;
        match orchestrator
            .get_turns(&execution_id, pagination, direction_filter)
            .await
        {
            Ok(result) => {
                info!(
                    "[MAGICIAN-V2-API] V2: Found {} turns (total: {})",
                    result.items.len(),
                    result.pagination.total
                );
                Ok(HttpResponse::Ok().json(result))
            },
            Err(e) => {
                error!(
                    "[MAGICIAN-V2-API] V2: Failed to list turns for execution {}: {}",
                    execution_id, e
                );
                Ok(v2_internal_error(
                    "Failed to list turns",
                    Some(serde_json::json!({
                        "execution_id": execution_id,
                    })),
                ))
            },
        }
    }

    // ========================================================================
    // Execution Status Management
    // ========================================================================

    /// PUT /api/magician/v2/executions/{id}/status
    /// Update execution status
    pub async fn update_execution_status(
        &self,
        path: web::Path<String>,
        req: web::Json<UpdateExecutionStatusRequest>,
    ) -> Result<HttpResponse> {
        let execution_id = normalize_execution_lookup_id(&self.agent_api, &path.into_inner()).await;
        info!(
            "[MAGICIAN-V2-API] V2: Updating status for execution: {} to {:?}",
            execution_id, req.waiting_state
        );

        let orchestrator = &self.v2_orchestrator;
        let _execution = match orchestrator.get_execution(&execution_id).await {
            Ok(execution) => execution,
            Err(error) => return Ok(v2_execution_load_error(&execution_id, &error)),
        };
        if !matches!(
            self.v2_orchestrator
                .is_governed_app_execution(&execution_id)
                .await,
            Ok(false)
        ) {
            return Ok(governed_app_generic_lifecycle_refused(&execution_id));
        }

        match orchestrator
            .set_execution_status_with_side_effects(
                &execution_id,
                req.waiting_state.clone(),
                "Direct status update",
            )
            .await
        {
            Ok(_) => {
                maybe_persist_task_backed_execution_outcome(
                    &self.agent_api,
                    &self.v2_orchestrator,
                    &execution_id,
                    "direct status update",
                )
                .await;
                info!("[MAGICIAN-V2-API] V2: Execution status updated successfully");
                Ok(HttpResponse::Ok().json(serde_json::json!({
                    "execution_id": execution_id,
                    "waiting_state": req.waiting_state
                })))
            },
            Err(e) => {
                error!(
                    "[MAGICIAN-V2-API] V2: Failed to update execution status: {}",
                    e
                );
                Ok(v2_internal_error(
                    "Failed to update execution status",
                    Some(serde_json::json!({
                        "execution_id": execution_id,
                    })),
                ))
            },
        }
    }

    /// GET /api/magician/v2/executions/{id}/status
    /// Get execution status
    pub async fn get_execution_status(&self, path: web::Path<String>) -> Result<HttpResponse> {
        let execution_id = normalize_execution_lookup_id(&self.agent_api, &path.into_inner()).await;

        let orchestrator = &self.v2_orchestrator;

        match orchestrator.get_execution_status(&execution_id).await {
            Ok(status) => Ok(HttpResponse::Ok().json(serde_json::json!({
                "execution_id": execution_id,
                "waiting_state": status
            }))),
            Err(e) => {
                error!(
                    "[MAGICIAN-V2-API] V2: Failed to get execution status: {}",
                    e
                );
                Ok(v2_internal_error(
                    "Failed to get execution status",
                    Some(serde_json::json!({
                        "execution_id": execution_id,
                    })),
                ))
            },
        }
    }

    /// GET /api/magician/v2/executions/{id}/execution-summary
    /// Get the latest persisted agentic execution summary for an execution.
    pub async fn get_execution_summary(&self, path: web::Path<String>) -> Result<HttpResponse> {
        let requested_execution_id = path.into_inner();
        let execution_id =
            normalize_execution_lookup_id(&self.agent_api, &requested_execution_id).await;

        if let Err(err) = self.v2_orchestrator.get_execution(&execution_id).await {
            error!(
                "[MAGICIAN-V2-API] V2: Failed to load execution {}: {}",
                requested_execution_id, err
            );
            return Ok(v2_execution_load_error(&requested_execution_id, &err));
        }

        match self
            .screenshot_storage
            .get_execution_summary(&execution_id)
            .await
        {
            Ok(Some(summary)) => Ok(HttpResponse::Ok().json(ExecutionSummaryResponse {
                execution_id,
                summary,
            })),
            Ok(None) => Ok(v2_not_found(
                "Execution summary not found",
                Some(serde_json::json!({
                    "execution_id": execution_id,
                })),
            )),
            Err(err) => {
                error!(
                    "[MAGICIAN-V2-API] V2: Failed to read execution summary for execution {}: {}",
                    execution_id, err
                );
                Ok(v2_internal_error(
                    "Failed to read execution summary",
                    Some(serde_json::json!({
                        "execution_id": execution_id,
                    })),
                ))
            },
        }
    }

    /// GET /api/magician/v2/executions/{id}/responsibility
    /// Returns the current owner/handover/child-execution responsibility read model.
    pub async fn get_execution_responsibility(
        &self,
        path: web::Path<String>,
    ) -> Result<HttpResponse> {
        let requested_execution_id = path.into_inner();
        let execution_id =
            normalize_execution_lookup_id(&self.agent_api, &requested_execution_id).await;

        let execution = match self.v2_orchestrator.get_execution(&execution_id).await {
            Ok(execution) => execution,
            Err(err) => {
                error!(
                    "[MAGICIAN-V2-API] V2: Failed to load responsibility execution {}: {}",
                    requested_execution_id, err
                );
                return Ok(v2_execution_load_error(&requested_execution_id, &err));
            },
        };

        let latest_summary = match self
            .screenshot_storage
            .get_execution_summary(&execution_id)
            .await
        {
            Ok(summary) => summary,
            Err(error) => {
                warn!(
                    execution_id = %execution_id,
                    error = %error,
                    "[MAGICIAN-V2-API] Failed to load execution summary for responsibility view"
                );
                None
            },
        };

        let child_futures = execution.active_delegation_group.iter().map(|child_execution_id| {
            let child_execution_id = child_execution_id.clone();
            async move {
                let child_execution =
                    match self.v2_orchestrator.get_execution(&child_execution_id).await {
                        Ok(execution) => execution,
                        Err(error) => {
                            warn!(
                                child_execution_id = %child_execution_id,
                                error = %error,
                                "[MAGICIAN-V2-API] Failed to load active child execution for responsibility view"
                            );
                            return None;
                        },
                    };

                let latest_summary = match self
                    .screenshot_storage
                    .get_execution_summary(&child_execution_id)
                    .await
                {
                    Ok(summary) => summary,
                    Err(error) => {
                        warn!(
                            child_execution_id = %child_execution_id,
                            error = %error,
                            "[MAGICIAN-V2-API] Failed to load child execution summary for responsibility view"
                        );
                        None
                    },
                };

                Some(ExecutionResponsibilityChildResponse {
                    execution_id: child_execution.id.clone(),
                    title: child_execution.title.clone(),
                    waiting_state: child_execution.waiting_state.clone(),
                    active_owner_agent_id: child_execution.active_owner_agent_id.clone(),
                    delegation_chain: child_execution.delegation_chain.clone(),
                    current_stage: child_execution.current_stage.clone(),
                    current_provider: child_execution.current_provider.clone(),
                    latest_summary,
                    is_blocking: !child_execution.waiting_state.is_terminal(),
                })
            }
        });

        let active_children = join_all(child_futures)
            .await
            .into_iter()
            .flatten()
            .collect::<Vec<_>>();

        Ok(
            HttpResponse::Ok().json(build_execution_responsibility_response(
                &execution,
                latest_summary,
                active_children,
            )),
        )
    }

    // ========================================================================
    // Slot Management
    // ========================================================================

    /// POST /api/magician/v2/executions/{id}/slots
    /// Create a new slot for parameter elicitation
    pub async fn create_slot(
        &self,
        path: web::Path<String>,
        req: web::Json<CreateSlotRequest>,
    ) -> Result<HttpResponse> {
        let execution_id = normalize_execution_lookup_id(&self.agent_api, &path.into_inner()).await;
        info!(
            "[MAGICIAN-V2-API] V2: Creating slot '{}' for execution: {}",
            req.name, execution_id
        );

        let orchestrator = &self.v2_orchestrator;

        match orchestrator
            .create_slot(
                &execution_id,
                req.name.clone(),
                req.schema_json.clone(),
                req.required,
                req.asked_turn_id.clone(),
            )
            .await
        {
            Ok(slot) => {
                info!(
                    "[MAGICIAN-V2-API] V2: Slot created successfully: {}",
                    slot.id
                );
                Ok(HttpResponse::Ok().json(slot))
            },
            Err(e) => {
                error!("[MAGICIAN-V2-API] V2: Failed to create slot: {}", e);
                Ok(v2_internal_error(
                    "Failed to create slot",
                    Some(serde_json::json!({
                        "execution_id": execution_id,
                    })),
                ))
            },
        }
    }

