    async fn resolve_scoped_execution_control(
        &self,
        request: &HttpRequest,
        requested_execution_id: &str,
    ) -> std::result::Result<(String, ExecutionRun), HttpResponse> {
        let (principal, workspace) = resolve_required_scope_from_request(request)?;
        let execution_id =
            normalize_execution_lookup_id(&self.agent_api, requested_execution_id).await;
        let execution = self
            .v2_orchestrator
            .get_execution(&execution_id)
            .await
            .map_err(|err| v2_execution_load_error(requested_execution_id, &err))?;
        if execution.principal != principal || execution.workspace != workspace {
            return Err(v2_not_found(
                "Execution not found in the requested scope",
                Some(serde_json::json!({ "execution_id": requested_execution_id })),
            ));
        }
        Ok((execution_id, execution))
    }

    /// GET /api/magician/v2/executions/{id}/control-state
    /// Return server-authoritative availability for operator execution controls.
    pub async fn get_execution_control_state(
        &self,
        request: &HttpRequest,
        path: web::Path<String>,
    ) -> Result<HttpResponse> {
        let requested_execution_id = path.into_inner();
        let (execution_id, authorized_execution) = match self
            .resolve_scoped_execution_control(request, &requested_execution_id)
            .await
        {
            Ok(resolved) => resolved,
            Err(response) => return Ok(response),
        };

        let snapshot = match self
            .v2_orchestrator
            .execution_tree_control_snapshot(&execution_id)
            .await
        {
            Ok(snapshot) => snapshot,
            Err(error) => {
                error!(
                    execution_id = %execution_id,
                    error = %error,
                    "Failed to build execution control-state snapshot"
                );
                return Ok(v2_internal_error(
                    "Failed to load execution control state",
                    Some(serde_json::json!({ "execution_id": execution_id })),
                ));
            },
        };
        if snapshot.execution.principal != authorized_execution.principal
            || snapshot.execution.workspace != authorized_execution.workspace
        {
            return Ok(v2_not_found(
                "Execution not found in the requested scope",
                Some(serde_json::json!({ "execution_id": execution_id })),
            ));
        }
        let pause_kind = if snapshot.execution.waiting_state == WaitingState::Paused {
            Some("manual".to_string())
        } else {
            snapshot.pause_kind.map(execution_pause_kind_name)
        };

        let mut response = execution_control_state_response(
            &snapshot.execution,
            snapshot.active,
            snapshot.manual_snapshot_ready,
            pause_kind,
        );
        response.can_pause = snapshot.capabilities.can_pause;
        response.can_resume = snapshot.capabilities.can_resume;
        Ok(HttpResponse::Ok().json(response))
    }

    /// POST /api/magician/v2/executions/{id}/pause - Pause active processing.
    /// Finalizes the run as a resumable `PausedByUser` state (not Cancelled);
    /// resume via `/resume`.
    pub async fn pause_processing(
        &self,
        request: &HttpRequest,
        path: web::Path<String>,
    ) -> Result<HttpResponse> {
        let requested_execution_id = path.into_inner();
        let (execution_id, execution) = match self
            .resolve_scoped_execution_control(request, &requested_execution_id)
            .await
        {
            Ok(resolved) => resolved,
            Err(response) => return Ok(response),
        };
        info!(
            "[MAGICIAN-V2-API] V2: Pausing processing for execution {}",
            execution_id
        );

        let orchestrator = &self.v2_orchestrator;

        if !matches!(
            orchestrator.is_governed_app_execution(&execution_id).await,
            Ok(false)
        ) {
            return Ok(governed_app_generic_lifecycle_refused(&execution_id));
        }

        if execution.waiting_state.is_terminal() {
            return Ok(v2_invalid_request(
                "No active execution to pause",
                Some(serde_json::json!({
                    "execution_id": execution_id,
                    "status": format!("{:?}", execution.waiting_state),
                })),
            ));
        }
        match orchestrator.pause_execution_tree(&execution_id).await {
            Ok(true) => Ok(HttpResponse::Ok().json(serde_json::json!({
                "execution_id": execution_id,
                "paused": true,
            }))),
            Ok(false) => Ok(v2_invalid_request(
                "No active execution to pause",
                Some(serde_json::json!({ "execution_id": execution_id })),
            )),
            Err(e) if stateless_terminal_lifecycle_retryable(&e) => {
                warn!(
                    %execution_id,
                    error = %e,
                    "Processing pause deferred while durable terminal admission converges"
                );
                Ok(terminal_pause_settlement_pending_response(&execution_id))
            },
            Err(e) => {
                error!(
                    "[MAGICIAN-V2-API] V2: Failed to pause execution {}: {}",
                    execution_id, e
                );
                Ok(v2_internal_error(
                    "Failed to pause processing",
                    Some(serde_json::json!({ "execution_id": execution_id })),
                ))
            },
        }
    }

    /// POST /api/magician/v2/executions/{id}/resume - Resume a paused execution
    /// tree (cascades to children; reconciles any that finished while paused).
    pub async fn resume_processing(
        &self,
        request: &HttpRequest,
        path: web::Path<String>,
    ) -> Result<HttpResponse> {
        let requested_execution_id = path.into_inner();
        let (execution_id, _execution) = match self
            .resolve_scoped_execution_control(request, &requested_execution_id)
            .await
        {
            Ok(resolved) => resolved,
            Err(response) => return Ok(response),
        };
        info!(
            "[MAGICIAN-V2-API] V2: Resuming processing for execution {}",
            execution_id
        );

        let orchestrator = &self.v2_orchestrator;
        if !matches!(
            orchestrator.is_governed_app_execution(&execution_id).await,
            Ok(false)
        ) {
            return Ok(governed_app_generic_lifecycle_refused(&execution_id));
        }
        match orchestrator.resume_execution_tree(&execution_id).await {
            Ok(true) => Ok(HttpResponse::Ok().json(serde_json::json!({
                "execution_id": execution_id,
                "resumed": true,
            }))),
            Ok(false) => Ok(v2_invalid_request(
                "Execution is not in a resumable paused state",
                Some(serde_json::json!({ "execution_id": execution_id })),
            )),
            Err(e) if stateless_terminal_lifecycle_retryable(&e) => {
                warn!(
                    %execution_id,
                    error = %e,
                    "Processing resume deferred while durable terminal admission converges"
                );
                Ok(terminal_pause_settlement_pending_response(&execution_id))
            },
            Err(e) => {
                error!(
                    "[MAGICIAN-V2-API] V2: Failed to resume execution {}: {}",
                    execution_id, e
                );
                Ok(v2_internal_error(
                    "Failed to resume processing",
                    Some(serde_json::json!({ "execution_id": execution_id })),
                ))
            },
        }
    }

    /// POST /api/magician/v2/executions/{id}/steer - inject an operator redirect
    /// into a live run's next decision turn. Body: `{ "message": "..." }`.
    /// Additive guidance only — tools still run through the existing gates.
    pub async fn steer_processing(
        &self,
        request: &HttpRequest,
        path: web::Path<String>,
        body: web::Json<SteerExecutionRequest>,
    ) -> Result<HttpResponse> {
        let requested_execution_id = path.into_inner();
        let (execution_id, execution) = match self
            .resolve_scoped_execution_control(request, &requested_execution_id)
            .await
        {
            Ok(resolved) => resolved,
            Err(response) => return Ok(response),
        };
        if !matches!(
            self.v2_orchestrator
                .is_governed_app_execution(&execution_id)
                .await,
            Ok(false)
        ) {
            return Ok(governed_app_generic_lifecycle_refused(&execution_id));
        }
        let _execution_lifecycle_exclusion = match acquire_execution_lifecycle_mutation_admission(
            &self.full_pause_store,
            &execution_id,
            None,
            &execution.principal,
            &execution.workspace,
            "steer_execution",
        )
        .await
        {
            Ok(exclusion) => exclusion,
            Err(response) => return Ok(response),
        };
        match self
            .v2_orchestrator
            .steer_execution(&execution_id, &body.message)
            .await
        {
            Ok(()) => {
                info!(
                    "[MAGICIAN-V2-API] V2: Steering execution {} ({} bytes)",
                    execution_id,
                    body.message.trim().len()
                );
                Ok(HttpResponse::Ok().json(serde_json::json!({
                    "execution_id": execution_id,
                    "steered": true,
                })))
            },
            Err(SteerExecutionError::EmptyMessage) => Ok(v2_invalid_request(
                "steer requires a non-empty `message`",
                Some(serde_json::json!({ "execution_id": execution_id })),
            )),
            Err(SteerExecutionError::MessageTooLong) => Ok(v2_invalid_request(
                format!("steer `message` must be at most {MAX_STEER_MESSAGE_BYTES} bytes"),
                Some(serde_json::json!({
                    "execution_id": execution_id,
                    "max_message_bytes": MAX_STEER_MESSAGE_BYTES,
                })),
            )),
            Err(SteerExecutionError::QueueFull) => Ok(v2_conflict(
                "Execution already has the maximum pending steer messages",
                Some(serde_json::json!({
                    "execution_id": execution_id,
                    "max_pending_steers": MAX_PENDING_STEERS,
                })),
            )),
            Err(SteerExecutionError::NotActive) => Ok(v2_invalid_request(
                "No active execution to steer",
                Some(serde_json::json!({ "execution_id": execution_id })),
            )),
            Err(SteerExecutionError::QueueUnavailable) => {
                error!(
                    execution_id = %execution_id,
                    "[MAGICIAN-V2-API] V2: Active execution steer queue is unavailable"
                );
                Ok(v2_internal_error(
                    "Active execution steer queue is unavailable",
                    Some(serde_json::json!({ "execution_id": execution_id })),
                ))
            },
            Err(SteerExecutionError::GovernedAppDenied) => {
                Ok(governed_app_generic_lifecycle_refused(&execution_id))
            },
        }
    }

    /// POST /api/magician/v2/executions/{id}/cancel - Cancel active processing
    pub async fn cancel_processing(
        &self,
        request: &HttpRequest,
        path: web::Path<String>,
    ) -> Result<HttpResponse> {
        let requested_execution_id = path.into_inner();
        let (execution_id, execution) = match self
            .resolve_scoped_execution_control(request, &requested_execution_id)
            .await
        {
            Ok(resolved) => resolved,
            Err(response) => return Ok(response),
        };
        info!(
            "[MAGICIAN-V2-API] V2: Cancelling processing for execution {}",
            execution_id
        );

        let orchestrator = &self.v2_orchestrator;

        if execution.waiting_state.is_terminal() {
            info!(
                "[MAGICIAN-V2-API] V2: Ignoring cancel for terminal execution {} ({:?})",
                execution_id, execution.waiting_state
            );
            return Ok(v2_invalid_request(
                "No active execution to cancel",
                Some(serde_json::json!({
                    "execution_id": execution_id,
                    "status": format!("{:?}", execution.waiting_state),
                })),
            ));
        }

        if !matches!(
            orchestrator.is_governed_app_execution(&execution_id).await,
            Ok(false)
        ) {
            return Ok(governed_app_cancellation_refused(&execution_id));
        }

        match orchestrator.cancel_execution_tree(&execution_id).await {
            Ok(true) => {
                persist_task_backed_cancelled_execution(
                    &self.agent_api,
                    orchestrator,
                    &execution_id,
                )
                .await;
                Ok(HttpResponse::Ok().json(serde_json::json!({
                    "execution_id": execution_id,
                    "cancelled": true,
                    "status": format!("{:?}", magician::magician_v2::storage::WaitingState::Cancelled),
                })))
            },
            Ok(false) => Ok(v2_invalid_request(
                "No active execution to cancel",
                Some(serde_json::json!({
                    "execution_id": execution_id,
                })),
            )),
            Err(e) if stateless_terminal_lifecycle_retryable(&e) => {
                warn!(
                    %execution_id,
                    error = %e,
                    "Processing cancellation deferred while durable terminal admission converges"
                );
                Ok(terminal_pause_settlement_pending_response(&execution_id))
            },
            Err(e) => {
                error!(
                    "[MAGICIAN-V2-API] V2: Failed to cancel processing for execution {}: {}",
                    execution_id, e
                );
                Ok(v2_internal_error(
                    "Failed to cancel processing",
                    Some(serde_json::json!({
                        "execution_id": execution_id,
                    })),
                ))
            },
        }
    }

