/// GET /api/magician/v2/agents/{id}/effective-tools
///
/// Operator-facing projection of the exact provider/dispatch policy snapshot
/// for a supported interactive surface. It intentionally omits tool schemas
/// and parameter-deny values while preserving policy provenance and every
/// effective category, including server-owned implicit tools.
pub async fn get_agent_effective_tools_handler(
    chat_api: web::Data<crate::chat_api::ChatApi>,
    path: web::Path<String>,
    request: HttpRequest,
    query: web::Query<AgentEffectiveToolsQuery>,
) -> Result<HttpResponse> {
    let (principal, workspace) = match resolve_required_scope_from_request(&request) {
        Ok(scope) => scope,
        Err(response) => return Ok(response),
    };
    let agent_id = path.into_inner();
    use magician::magician_v2::chat::service::EffectiveToolPolicyPreviewError;

    match chat_api
        .chat_service
        .effective_tool_policy_preview_for_agent(&principal, &workspace, &agent_id, query.surface)
        .await
    {
        Ok(preview) => Ok(with_no_cache(HttpResponse::Ok().json(preview))),
        Err(EffectiveToolPolicyPreviewError::NotFound { agent_id }) => Ok(api_error_response(
            StatusCode::NOT_FOUND,
            "agent_effective_tools_not_found",
            "Crew member has no enabled agent definition in this scope",
            Some(serde_json::json!({ "agent_id": agent_id })),
        )),
        Err(EffectiveToolPolicyPreviewError::SurfaceNotAvailable {
            requested,
            available,
        }) => Ok(api_error_response(
            StatusCode::UNPROCESSABLE_ENTITY,
            "agent_surface_not_available",
            "Crew member is not authorized on the requested interactive surface",
            Some(serde_json::json!({
                "agent_id": agent_id,
                "requested_surface": requested,
                "available_surfaces": available,
            })),
        )),
        Err(EffectiveToolPolicyPreviewError::Unavailable { reason }) => Ok(api_error_response(
            StatusCode::SERVICE_UNAVAILABLE,
            "agent_effective_tools_unavailable",
            "Effective tool policy could not be resolved safely",
            Some(serde_json::json!({ "agent_id": agent_id, "reason": reason })),
        )),
    }
}

/// GET /api/magician/v2/agents/{id}/runtime-context-cache
