/// POST /api/magician/v2/executions/{id}/execution/agentic-resume handler
///
/// Resume agentic execution that was paused waiting for user input.
pub async fn resume_agentic_execution_handler(
    _api: web::Data<MagicianV2Api>,
    _request: HttpRequest,
    _path: web::Path<String>,
    _req: web::Json<AgenticResumeRequest>,
) -> Result<HttpResponse> {
    // Phase H7.x — legacy resolve URL retired (returns 410 Gone).
    // Counter still records hits so we can identify remaining callers.
    // The canonical `respond_hitl_handler` dispatches to the same
    // underlying `resume_agentic_execution_with_scope` API method, so
    // dropping this HTTP entry point doesn't break the canonical
    // dispatcher.
    crate::hitl_deprecation_metrics::record_hit(
        "/api/magician/v2/executions/{id}/execution/agentic-resume",
    );
    Ok(HttpResponse::Gone().json(serde_json::json!({
        "error": "endpoint_retired",
        "message": "POST /api/magician/v2/hitl/{correlation_id}/respond with body { source: \"agentic\", value, execution_id }",
        "retired_in": "magician v0.6.502 (Phase H7.x)",
        "see": "docs/plans/2026-05-11-hitl-h5-h7-dual-emit-retirement.md",
    })))
}

// ────────────────────────────────────────────────────────────────────
// Phase H3 — Canonical HITL respond endpoint
//
// `POST /api/magician/v2/hitl/{correlation_id}/respond` accepts a
// canonical body `{ source, value }` and dispatches internally to the
// existing legacy resolve URLs (`/user-requests/.../respond`,
// `/executions/.../agentic-resume`, `/approvals/.../resolve`) based on
// `source`. Frontend `postHitlResponse()` uses this single endpoint
// instead of the per-source routing it does today; the dispatch logic
// stays here on the backend so a future canonical resolve service can
// take over without changing the wire shape again.
//
// `correlation_id` matches the canonical id emitted by `HitlRequested`
// (`pause_state_id` for agentic/inner-loop/escalation, `request_id` for
// user_request, `approval_id` for approval). `source` discriminates the
// dispatch.
// ────────────────────────────────────────────────────────────────────

#[derive(Clone, Deserialize)]
pub struct RespondHitlRequest {
    /// Where the request originated. Mirrors the canonical `HitlRequested`
    /// `source` field — `agentic` / `primitive` / `user_request` /
    /// `approval` / `clarification` / `escalation`.
    pub source: String,
    /// The operator's response. Same shape as the existing
    /// `AgenticResumeValue` enum so backend code can route directly.
    pub value: AgenticResumeValue,
    /// Original requested input type. Choice-shaped values are also used by
    /// specialized pauses such as tool authorization and sandbox override, so
    /// deriving this solely from `value` loses the pause contract. Older
    /// clients may omit it and retain the legacy value-derived fallback.
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub input_type: Option<String>,
    /// Optional channel attribution for the user-request / approval
    /// resolve paths. Defaults to `web` when absent.
    #[serde(default = "default_hitl_channel")]
    pub channel: String,
    /// Diff approvals can apply a selected subset of proposal files.
    /// Values are workspace-relative paths matching the diff payload's
    /// `files[].path`. Empty/absent means whole-proposal apply.
    #[serde(default, skip_serializing_if = "Vec::is_empty")]
    pub selected_paths: Vec<String>,
    /// Phase H4.4 — execution_id (a.k.a. workflow_id) for clarification
    /// dispatch. The canonical respond endpoint takes `correlation_id`
    /// (= question_id for clarifications) in the URL path; the
    /// `AskLoopApi::submit_clarification` API needs both
    /// `(workflow_id, question_id)` so callers must supply
    /// `execution_id` here. Optional because non-clarification sources
    /// don't need it. Frontend `HitlRequest.scope.execution_id` is
    /// always populated for canonical events emitted from clarifications,
    /// so the round-trip works.
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub execution_id: Option<String>,
    /// Task/workflow responder identity for planning clarifications and plan
    /// approvals. Kept distinct from the durable runtime execution id.
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub task_id: Option<String>,
}

fn default_hitl_channel() -> String {
    "web".to_string()
}

fn hitl_scope_matches(request_scope: &(String, String), principal: &str, workspace: &str) -> bool {
    request_scope.0 == principal && request_scope.1 == workspace
}

fn should_try_legacy_clarification(status: StatusCode) -> bool {
    status == StatusCode::NOT_FOUND
}

fn is_agentic_runtime_hitl_source(source: &str) -> bool {
    matches!(
        source,
        "agentic" | "primitive" | "inner_loop" | "escalation"
    )
}

#[derive(Debug, Clone, Serialize)]
pub struct RespondHitlResponse {
    pub accepted: bool,
    /// Echoes the `source` so the operator UI can confirm dispatch.
    pub source: String,
    /// Soft-failure reason when `accepted = false`, including
    /// `already_resolved`, `scope_mismatch`, or retryable
    /// `persistence_unavailable` from user-request resolution.
    #[serde(skip_serializing_if = "Option::is_none")]
    pub reason: Option<String>,
}

/// POST /api/magician/v2/hitl/{correlation_id}/respond handler
pub async fn respond_hitl_handler(
    api: web::Data<MagicianV2Api>,
    user_request_svc: Option<
        web::Data<Arc<magician::magician_v2::user_requests::UserRequestService>>,
    >,
    ask_loop_api: Option<web::Data<magician::magician_v2::ask_loop::AskLoopApi>>,
    task_api_v3: Option<web::Data<crate::task_api_v3::TaskApiV3>>,
    bot_api: Option<web::Data<crate::bot_api::BotApi>>,
    mcp_oauth_api: Option<web::Data<crate::mcp_oauth_api::McpOAuthApi>>,
    // Envoy diode return leg: when an `envoy.*` upward-request resolves, the
    // user_request arm relays the owner's decision back to the contact via
    // `ChatService::relay_envoy_owner_decision`. Optional — absent for callers
    // without chat wired; non-envoy user_requests don't need it.
    chat_api: Option<web::Data<crate::chat_api::ChatApi>>,
    device_policy: Option<
        web::Data<Arc<magician::magician_v2::device_governance::DevicePolicyStore>>,
    >,
    request: HttpRequest,
    path: web::Path<String>,
    body: web::Json<RespondHitlRequest>,
) -> Result<HttpResponse> {
    let correlation_id = path.into_inner();
    let body = body.into_inner();
    // The runtime's own automatic answerers keep their channel on the record
    // (secure HITL P6); nobody else may claim one. The value is dropped with
    // the body before anything reads it.
    if let Err(refused) = crate::verification_codes_api::answer_channel_policy(
        &request,
        &body.channel,
        device_policy.as_ref().map(|policy| policy.get_ref()),
    )
    .await
    {
        drop(body);
        return Ok(refused);
    }
    // Synthetic debug/test HITL events (minted by POST /v3/events/debug-emit)
    // have no backing pause/approval, so the source arms below would 404 and
    // leave the card stuck. Resolve them as a pure ack — broadcast HitlResolved
    // so web + desktop drop the card in sync — keyed strictly on the `debug-`
    // correlation prefix so genuinely-missing real records still 404.
    if crate::events_api::is_debug_hitl_correlation(&correlation_id) {
        return Ok(ack_debug_hitl_resolution(
            &api.v2_orchestrator,
            &request,
            &correlation_id,
            &body,
        ));
    }
    match body.source.as_str() {
        "service_health" => {
            let (principal, workspace) = match resolve_required_scope_from_request(&request) {
                Ok(scope) => scope,
                Err(response) => return Ok(response),
            };
            if !matches!(&body.value,
                AgenticResumeValue::Choice { selected_id, .. } if selected_id == "dismiss")
            {
                return Ok(HttpResponse::BadRequest().json(RespondHitlResponse {
                    accepted: false,
                    source: body.source,
                    reason: Some("service_health_requires_dismiss".into()),
                }));
            }
            let accepted = api.v2_orchestrator.event_broadcaster().is_some_and(|bus| {
                bus.dismiss_service_health_notice(&principal, &workspace, &correlation_id)
            });
            let response = RespondHitlResponse {
                accepted,
                source: body.source,
                reason: Some(
                    if accepted {
                        "dismissed"
                    } else {
                        "service_notice_not_pending"
                    }
                    .into(),
                ),
            };
            Ok(if accepted {
                HttpResponse::Ok().json(response)
            } else {
                HttpResponse::Conflict().json(response)
            })
        },

        "user_request" => {
            let Some(user_request_svc) = user_request_svc else {
                return Ok(missing_hitl_dependency_response(
                    &body.source,
                    "UserRequestService",
                ));
            };
            // Build the legacy RespondRequest shape and dispatch to the
            // user-request service directly. The service handles scope
            // checks, dedup, and broadcast.
            let (scope_principal, scope_workspace) =
                match resolve_required_scope_from_request(&request) {
                    Ok(scope) => scope,
                    Err(response) => return Ok(response),
                };
            // Recover the pending request BEFORE respond_scoped removes it, so an
            // envoy upward-request can relay the owner's decision back to the
            // contact. `request_type` discriminates — non-envoy user_requests
            // (e.g. notify_owner) are completely unaffected.
            let pending_snapshot = user_request_svc
                .pending_request_snapshot(
                    &correlation_id,
                    Some(&scope_principal),
                    Some(&scope_workspace),
                )
                .await;
            let decision_label = agentic_value_decision_label(&body.value);
            // The pending request's sensitivity spec decides the route, not the
            // request-type name. Secure material goes straight to service
            // custody through `input` and is never rendered as relay text.
            let (input, input_text) =
                match sensitive_transport_for_pending(pending_snapshot.as_ref(), &body.value) {
                    SensitiveTransport::Secure { input } => (input, None),
                    SensitiveTransport::Ordinary { input_text } => (input_text.clone(), input_text),
                };
            drop(body.value);
            let response = magician::magician_v2::user_requests::service::UserResponse {
                request_id: correlation_id,
                decision: decision_label.clone(),
                input,
                channel: body.channel,
                sensitive: Vec::new(),
            };
            match user_request_svc
                .respond_scoped(response, Some(&scope_principal), Some(&scope_workspace))
                .await
            {
                magician::magician_v2::user_requests::service::ScopedResponseResult::Accepted => {
                    // Envoy diode return leg: relay the owner's decision back to
                    // the external contact. Runs only for `envoy.*` requests and
                    // only after `respond_scoped` accepted (so a double-submit,
                    // which returns AlreadyResolved below, relays exactly once).
                    // The recipient is recovered from the request's stored
                    // channel/address — never from the owner's response text.
                    if let Some(req) = pending_snapshot
                        .filter(|req| req.request_type.starts_with("envoy."))
                    {
                        match chat_api {
                            Some(chat_api) => {
                                let chat_service = chat_api.chat_service.clone();
                                let ctx = req.context;
                                let request_kind = ctx
                                    .get("request_kind")
                                    .and_then(|value| value.as_str())
                                    .unwrap_or_default()
                                    .to_string();
                                let channel = ctx
                                    .get("channel")
                                    .and_then(|value| value.as_str())
                                    .unwrap_or_default()
                                    .to_string();
                                let address = ctx
                                    .get("address")
                                    .and_then(|value| value.as_str())
                                    .unwrap_or_default()
                                    .to_string();
                                let guest_thread_id = ctx
                                    .get("guest_thread_id")
                                    .and_then(|value| value.as_str())
                                    .unwrap_or_default()
                                    .to_string();
                                let payload = ctx
                                    .get("payload")
                                    .cloned()
                                    .unwrap_or(serde_json::Value::Null);
                                let principal = scope_principal.clone();
                                let workspace = scope_workspace.clone();
                                if channel.is_empty() || address.is_empty() {
                                    tracing::warn!(
                                        kind = "envoy_relay",
                                        %request_kind,
                                        "envoy request missing channel/address; cannot relay"
                                    );
                                } else {
                                    tokio::spawn(async move {
                                        if let Err(error) = chat_service
                                            .relay_envoy_owner_decision(
                                                &principal,
                                                &workspace,
                                                &guest_thread_id,
                                                &channel,
                                                &address,
                                                &request_kind,
                                                &decision_label,
                                                input_text.as_deref(),
                                                &payload,
                                            )
                                            .await
                                        {
                                            tracing::warn!(
                                                kind = "envoy_relay",
                                                %request_kind,
                                                error = %error,
                                                "envoy owner-decision relay failed"
                                            );
                                        }
                                    });
                                }
                            },
                            None => {
                                tracing::warn!(
                                    kind = "envoy_relay",
                                    "envoy request resolved but ChatApi is not wired; \
                                     cannot relay to contact"
                                );
                            },
                        }
                    }
                    Ok(HttpResponse::Ok().json(RespondHitlResponse {
                        accepted: true,
                        source: body.source,
                        reason: None,
                    }))
                },
                magician::magician_v2::user_requests::service::ScopedResponseResult::AlreadyResolved => {
                    Ok(HttpResponse::Conflict().json(RespondHitlResponse {
                        accepted: false,
                        source: body.source,
                        reason: Some("already_resolved".to_string()),
                    }))
                },
                magician::magician_v2::user_requests::service::ScopedResponseResult::ScopeMismatch => {
                    Ok(HttpResponse::Forbidden().json(RespondHitlResponse {
                        accepted: false,
                        source: body.source,
                        reason: Some("scope_mismatch".to_string()),
                    }))
                },
                magician::magician_v2::user_requests::service::ScopedResponseResult::PersistenceUnavailable => {
                    Ok(HttpResponse::ServiceUnavailable().json(RespondHitlResponse {
                        accepted: false,
                        source: body.source,
                        reason: Some("persistence_unavailable".to_string()),
                    }))
                },
            }
        },
        "approval" => {
            let approval_decision = match &body.value {
                AgenticResumeValue::Confirmation { confirmed: true } => {
                    magician::magician_v2::agents::approval_service::ApprovalDecision::Approve
                },
                AgenticResumeValue::Confirmation { confirmed: false } => {
                    magician::magician_v2::agents::approval_service::ApprovalDecision::Reject
                },
                AgenticResumeValue::Choice { selected_id, .. } => match selected_id.as_str() {
                    "approve" | "allow" | "yes" | "confirm" => {
                        magician::magician_v2::agents::approval_service::ApprovalDecision::Approve
                    },
                    "reject" | "deny" | "no" | "cancel" | "dismiss" => {
                        magician::magician_v2::agents::approval_service::ApprovalDecision::Reject
                    },
                    other => {
                        return Ok(HttpResponse::BadRequest().json(RespondHitlResponse {
                            accepted: false,
                            source: body.source,
                            reason: Some(format!("unrecognized approval choice id: {other:?}")),
                        }));
                    },
                },
                _ => {
                    return Ok(HttpResponse::BadRequest().json(RespondHitlResponse {
                        accepted: false,
                        source: body.source,
                        reason: Some("approval_requires_confirmation_or_choice".to_string()),
                    }));
                },
            };
            let resolve_req = ResolveApprovalRequest {
                decision: approval_decision,
                channel: body.channel,
            };
            let path = web::Path::from(correlation_id);
            let inner = web::Json(resolve_req);
            api.resolve_approval(request, path, inner).await
        },
        "clarification" => {
            let Some(task_api_v3) = task_api_v3 else {
                return Ok(missing_hitl_dependency_response(&body.source, "TaskApiV3"));
            };
            let Some(ask_loop_api) = ask_loop_api else {
                return Ok(missing_hitl_dependency_response(&body.source, "AskLoopApi"));
            };
            // Phase H4.4/H4.5 — clarification dispatch.
            //
            // V3 plan clarifications are the active production path
            // (the Plan Inspector + V3 task plan flow). V2 ask_loop
            // clarifications are a legacy parallel system. We dispatch
            // to V3 first; if the V3 path can't find the question, the
            // caller falls back to the legacy URL (we don't auto-fall
            // back here because V3 returns a structured 4xx that's more
            // informative than a generic dispatch error).
            //
            // The canonical correlation_id is the `question_id`. V3
            // `submit_task_plan_clarification` needs `(task_id,
            // question_id)`. New clients send that responder identity
            // explicitly; the execution field remains the durable
            // `planexec_*` identity. The execution fallback is limited to
            // historical clients where both identities were the workflow id.
            let task_id = body
                .task_id
                .as_deref()
                .map(str::trim)
                .filter(|value| !value.is_empty())
                .or_else(|| {
                    body.execution_id
                        .as_deref()
                        .map(str::trim)
                        .filter(|value| !value.is_empty())
                });
            let Some(task_id) = task_id else {
                return Ok(HttpResponse::BadRequest().json(RespondHitlResponse {
                    accepted: false,
                    source: body.source,
                    reason: Some("clarification_requires_task_id".to_string()),
                }));
            };
            if let AgenticResumeValue::Form { answers } = &body.value {
                let mut last_success = None;
                for answer in answers {
                    let v3_request = crate::task_api_v3::SubmitTaskPlanClarificationV3Request {
                        workspace: None,
                        response_text: form_answer_response_text(answer, None),
                    };
                    let v3_path = web::Path::from((task_id.to_string(), answer.id.clone()));
                    let v3_response = task_api_v3
                        .submit_task_plan_clarification(&request, v3_path, web::Json(v3_request))
                        .await?;
                    if !v3_response.status().is_success() {
                        return Ok(v3_response);
                    }
                    last_success = Some(v3_response);
                }
                if let Some(broadcaster) = api.orchestrator().event_broadcaster() {
                    let (principal, workspace) = match resolve_required_scope_from_request(&request)
                    {
                        Ok(scope) => (Some(scope.0), Some(scope.1)),
                        Err(_) => (None, None),
                    };
                    broadcaster.emit(
                        magician::magician_v2::realtime_events::RuntimeTransportEvent::HitlResolved {
                            correlation_id: correlation_id.clone(),
                            source: "clarification".to_string(),
                            outcome: "responded".to_string(),
                            decision: Some("form".to_string()),
                            task_id: Some(task_id.to_string()),
                            execution_id: body.execution_id.clone(),
                            agent_id: None,
                            principal,
                            workspace,
                            timestamp: chrono::Utc::now().timestamp_millis(),
                        },
                    );
                }
                return Ok(last_success.unwrap_or_else(|| {
                    HttpResponse::Ok().json(RespondHitlResponse {
                        accepted: true,
                        source: body.source,
                        reason: None,
                    })
                }));
            }
            // Map the canonical value into a single `response_text`
            // string. Choice flows pick the option id; text flows take
            // the value; confirmation maps to yes/no; multi_choice
            // takes the comma-joined ids.
            let response_text = agentic_value_input_text(&body.value, None)
                .or_else(|| match &body.value {
                    AgenticResumeValue::Choice { selected_id, .. } => Some(selected_id.clone()),
                    AgenticResumeValue::Confirmation { confirmed: true } => Some("yes".to_string()),
                    AgenticResumeValue::Confirmation { confirmed: false } => Some("no".to_string()),
                    _ => None,
                })
                .unwrap_or_default();
            // Try V3 first.
            let v3_request = crate::task_api_v3::SubmitTaskPlanClarificationV3Request {
                workspace: None,
                response_text: response_text.clone(),
            };
            let v3_path = web::Path::from((task_id.to_string(), correlation_id.clone()));
            let v3_response = task_api_v3
                .submit_task_plan_clarification(&request, v3_path, web::Json(v3_request))
                .await?;
            // If V3 returned 200/204 we're done. Forward its body so
            // surfaces that read the resulting plan can use it.
            if v3_response.status().is_success() {
                return Ok(v3_response);
            }
            // Only an explicit V3 not-found may be a legacy ask-loop
            // clarification. Validation, authorization, conflicts, and server
            // failures must remain authoritative; falling back on those statuses
            // bypasses V3's scope checks.
            let v2_status = v3_response.status();
            if !should_try_legacy_clarification(v2_status) {
                return Ok(v3_response);
            }
            let request_scope = match resolve_required_scope_from_request(&request) {
                Ok(scope) => scope,
                Err(response) => return Ok(response),
            };
            // Legacy AskLoopApi is keyed only by workflow/question ids. Bind
            // that unscoped lookup to the owning runtime execution before it is
            // allowed to consume a response.
            match api.orchestrator().get_execution(task_id).await {
                Ok(execution)
                    if hitl_scope_matches(
                        &request_scope,
                        &execution.principal,
                        &execution.workspace,
                    ) => {},
                Ok(_) => {
                    return Ok(HttpResponse::Forbidden().json(RespondHitlResponse {
                        accepted: false,
                        source: body.source,
                        reason: Some("clarification_scope_mismatch".to_string()),
                    }));
                },
                Err(_) => return Ok(v3_response),
            }
            let submission = magician::magician_v2::ask_loop::ClarificationSubmission {
                response_text,
                prompt_identity: None,
            };
            match ask_loop_api
                .submit_clarification(task_id, &correlation_id, submission)
                .await
            {
                Ok(_result) => Ok(HttpResponse::Ok().json(RespondHitlResponse {
                    accepted: true,
                    source: body.source,
                    reason: None,
                })),
                // #6: an already-answered / double-submitted / post-restart
                // clarification is a benign soft-success, not a hard failure.
                // ask_loop surfaces it as `TriggerError::AlreadyResolved`; return
                // 409 + reason so the UI's `already_resolved` branch dismisses the
                // card instead of showing a spurious 500.
                Err(magician::magician_v2::ask_loop::AskLoopError::Trigger(
                    magician::magician_v2::ask_loop::triggers::TriggerError::AlreadyResolved(_),
                )) => Ok(HttpResponse::Conflict().json(RespondHitlResponse {
                    accepted: false,
                    source: body.source,
                    reason: Some("already_resolved".to_string()),
                })),
                Err(err) => Ok(HttpResponse::build(v2_status).json(RespondHitlResponse {
                    accepted: false,
                    source: body.source,
                    reason: Some(format!(
                        "clarification_dispatch_failed: v3_status={}, v2_err={}",
                        v2_status, err
                    )),
                })),
            }
        },
        "plan_approval" => {
            // Phase F HITL consolidation: plan-version approval now
            // surfaces in /attention as a confirmation-shaped HITL.
            // `correlation_id` == `plan_id`; `body.task_id` carries the
            // task/workflow responder identity. Approve →
            // `approve_task_plan(task_id)`; reject → `reject_task_plan`.
            // The artifact service emits the matching `HitlResolved` on
            // success so `/attention` drops the row.
            let task_id = match body
                .task_id
                .as_deref()
                .map(str::trim)
                .filter(|id| !id.is_empty())
                .or_else(|| {
                    body.execution_id
                        .as_deref()
                        .map(str::trim)
                        .filter(|id| !id.is_empty())
                }) {
                Some(id) => id.to_string(),
                _ => {
                    return Ok(HttpResponse::BadRequest().json(RespondHitlResponse {
                        accepted: false,
                        source: body.source,
                        reason: Some("plan_approval_requires_task_id".to_string()),
                    }));
                },
            };
            let approve = match &body.value {
                AgenticResumeValue::Confirmation { confirmed } => *confirmed,
                AgenticResumeValue::Choice { selected_id, .. } => match selected_id.as_str() {
                    "approve" | "allow" | "yes" | "confirm" => true,
                    "reject" | "deny" | "no" | "cancel" => false,
                    other => {
                        return Ok(HttpResponse::BadRequest().json(RespondHitlResponse {
                            accepted: false,
                            source: body.source,
                            reason: Some(format!(
                                "plan_approval_unrecognized_selected_id: `{other}`"
                            )),
                        }));
                    },
                },
                _ => {
                    return Ok(HttpResponse::BadRequest().json(RespondHitlResponse {
                        accepted: false,
                        source: body.source,
                        reason: Some("plan_approval_requires_confirmation_or_choice".to_string()),
                    }));
                },
            };
            let request_scope = match resolve_required_scope_from_request(&request) {
                Ok(scope) => scope,
                Err(response) => return Ok(response),
            };
            let scope =
                magician::magician_v2::artifact_v2::ScopeRef::system_internal_unauthenticated(
                    &request_scope.0,
                    &request_scope.1,
                );
            let Some(service) = api.orchestrator().artifact_v2_service() else {
                return Ok(missing_hitl_dependency_response(
                    &body.source,
                    "ArtifactV2Service",
                ));
            };
            let result = if approve {
                service
                    .approve_task_plan_version(&scope, &task_id, &correlation_id)
                    .await
            } else {
                service
                    .reject_task_plan_version(&scope, &task_id, &correlation_id)
                    .await
            };
            match result {
                Ok(_) => Ok(HttpResponse::Ok().json(RespondHitlResponse {
                    accepted: true,
                    source: body.source,
                    reason: None,
                })),
                Err(magician::magician_v2::artifact_v2::ArtifactV2Error::InvalidRequest(
                    ref reason,
                )) if reason.starts_with("task_plan_version_mismatch:")
                    || reason.starts_with("task_plan_already_resolved:") =>
                {
                    Ok(HttpResponse::Conflict().json(RespondHitlResponse {
                        accepted: false,
                        source: body.source,
                        reason: Some("already_resolved".to_string()),
                    }))
                },
                Err(err) => Ok(HttpResponse::BadRequest().json(RespondHitlResponse {
                    accepted: false,
                    source: body.source,
                    reason: Some(format!("plan_approval_dispatch_failed: {err}")),
                })),
            }
        },
        "mcp_oauth" => {
            // Product-owned MCP OAuth requests open the authorization URL directly in
            // the system browser and resolve automatically from the exact callback.
            // The HITL action is therefore only a safe retry/dismiss control; no URL,
            // code, state, token, endpoint, or profile alias crosses this request body.
            let Some(mcp_oauth_api) = mcp_oauth_api else {
                return Ok(missing_hitl_dependency_response(
                    &body.source,
                    "McpOAuthApi",
                ));
            };
            let (principal, workspace) = match resolve_required_scope_from_request(&request) {
                Ok(scope) => scope,
                Err(response) => return Ok(response),
            };
            let scope = match tool_runtime_core::credential_profiles::CredentialScope::new(
                principal, workspace,
            ) {
                Ok(scope) => scope,
                Err(_) => {
                    return Ok(HttpResponse::Forbidden().json(RespondHitlResponse {
                        accepted: false,
                        source: body.source,
                        reason: Some("mcp_oauth_scope_mismatch".to_string()),
                    }));
                },
            };
            let action = match &body.value {
                AgenticResumeValue::ExternalActionCompleted { .. } => "retry",
                AgenticResumeValue::Choice { selected_id, .. }
                    if matches!(selected_id.as_str(), "retry" | "open_auth_flow") =>
                {
                    "retry"
                },
                AgenticResumeValue::Choice { selected_id, .. }
                    if matches!(selected_id.as_str(), "dismiss" | "cancel") =>
                {
                    "dismiss"
                },
                AgenticResumeValue::Aborted { .. } => "dismiss",
                _ => {
                    return Ok(HttpResponse::BadRequest().json(RespondHitlResponse {
                        accepted: false,
                        source: body.source,
                        reason: Some("mcp_oauth_requires_retry_or_dismiss".to_string()),
                    }));
                },
            };
            let result = if action == "dismiss" {
                mcp_oauth_api
                    .dismiss_correlation(&correlation_id, &scope)
                    .await
            } else {
                mcp_oauth_api
                    .retry_browser_for_correlation(&correlation_id, &scope)
                    .await
            };
            match result {
                Ok(()) => Ok(HttpResponse::Ok().json(RespondHitlResponse {
                    accepted: true,
                    source: body.source,
                    reason: Some(if action == "dismiss" {
                        "dismissed".to_string()
                    } else {
                        "browser_opened".to_string()
                    }),
                })),
                Err(error)
                    if error.code
                        == crate::mcp_oauth_api::McpOAuthProductErrorCode::ScopeMismatch =>
                {
                    Ok(HttpResponse::Forbidden().json(RespondHitlResponse {
                        accepted: false,
                        source: body.source,
                        reason: Some("mcp_oauth_scope_mismatch".to_string()),
                    }))
                },
                Err(error)
                    if matches!(
                        error.code,
                        crate::mcp_oauth_api::McpOAuthProductErrorCode::AuthorizationNotFound
                            | crate::mcp_oauth_api::McpOAuthProductErrorCode::AuthorizationNotLive
                    ) =>
                {
                    Ok(HttpResponse::Conflict().json(RespondHitlResponse {
                        accepted: false,
                        source: body.source,
                        reason: Some("mcp_oauth_flow_not_live".to_string()),
                    }))
                },
                Err(error)
                    if error.code
                        == crate::mcp_oauth_api::McpOAuthProductErrorCode::BrowserUnavailable =>
                {
                    Ok(
                        HttpResponse::ServiceUnavailable().json(RespondHitlResponse {
                            accepted: false,
                            source: body.source,
                            reason: Some("mcp_oauth_browser_unavailable".to_string()),
                        }),
                    )
                },
                Err(_) => Ok(HttpResponse::BadRequest().json(RespondHitlResponse {
                    accepted: false,
                    source: body.source,
                    reason: Some("mcp_oauth_request_rejected".to_string()),
                })),
            }
        },
        "bot_auth" => {
            // The HitlRequested envelope for bot_auth is emitted by
            // `bots/auth_hitl_broker.rs::AuthHitlBroker` when a bot
            // transitions into NeedsAuth / AccountMismatch. The
            // correlation_id is shaped as
            // `bot_auth:<principal>:<workspace>:<bot>` (see
            // `AuthHitlBroker::correlation_id`); we parse the bot name
            // out + dispatch the operator's selected_id to the bot
            // runtime.
            //
            // We deliberately don't depend on `web::Data<BotApi>` here
            // — keeping `respond_hitl_handler`'s signature stable
            // matters more than a slight tradeoff in indirection. The
            // orchestrator owns `bot_runtime` via its constructor, and
            // we reach it through `MagicianV2Api::bot_runtime()`.
            let parts: Vec<&str> = correlation_id.split(':').collect();
            if parts.len() != 4 || parts[0] != "bot_auth" {
                return Ok(HttpResponse::BadRequest().json(RespondHitlResponse {
                    accepted: false,
                    source: body.source,
                    reason: Some(format!(
                        "bot_auth correlation_id must be `bot_auth:<principal>:<workspace>:<bot>`; got `{correlation_id}`"
                    )),
                }));
            }
            let principal = parts[1].to_string();
            let workspace = parts[2].to_string();
            let bot_name = parts[3].to_string();
            let request_scope = match resolve_required_scope_from_request(&request) {
                Ok(scope) => scope,
                Err(response) => return Ok(response),
            };
            if !hitl_scope_matches(&request_scope, &principal, &workspace) {
                return Ok(HttpResponse::Forbidden().json(RespondHitlResponse {
                    accepted: false,
                    source: body.source,
                    reason: Some("bot_auth_scope_mismatch".to_string()),
                }));
            }
            let selected = match &body.value {
                AgenticResumeValue::Choice { selected_id, .. } => selected_id.clone(),
                AgenticResumeValue::ExternalActionCompleted { .. } => {
                    // Older clients that haven't migrated yet still
                    // post `external_action_completed`. Treat that as
                    // an implicit re-check (the broker's options now
                    // map onto a `choice` input shape; this is the
                    // graceful fallback).
                    "recheck".to_string()
                },
                AgenticResumeValue::Aborted { .. } => "dismiss".to_string(),
                _ => {
                    return Ok(HttpResponse::BadRequest().json(RespondHitlResponse {
                        accepted: false,
                        source: body.source,
                        reason: Some(
                            "bot_auth_requires_choice_or_external_action_value".to_string(),
                        ),
                    }));
                },
            };
            let Some(bot_api) = bot_api else {
                return Ok(missing_hitl_dependency_response(&body.source, "BotApi"));
            };
            let bot_runtime = Arc::clone(&bot_api.runtime);
            let auth_hitl_broker = bot_api.auth_hitl_broker.clone();
            match selected.as_str() {
                "open_auth_flow" => {
                    // Kick off the provider's auth flow. The sidecar
                    // remains until the next successful probe; the next
                    // `list_bots_auth` poll will fire `HitlResolved`
                    // automatically via the broker once the operator
                    // completes sign-in out-of-band.
                    match bot_runtime
                        .start_auth(&principal, &workspace, &bot_name)
                        .await
                    {
                        Ok(_response) => Ok(HttpResponse::Ok().json(RespondHitlResponse {
                            accepted: true,
                            source: body.source,
                            reason: Some(
                                "auth_flow_started; complete sign-in in the opened browser/QR and the next poll will resolve this request"
                                    .to_string(),
                            ),
                        })),
                        Err(err) => Ok(HttpResponse::BadGateway().json(RespondHitlResponse {
                            accepted: false,
                            source: body.source,
                            reason: Some(format!("bot_auth_start_failed: {err}")),
                        })),
                    }
                },
                "recheck" => {
                    // Re-probe immediately so the operator gets sync
                    // feedback (the 15s poll is too sluggish for "I
                    // just signed in — did it stick?" interactions).
                    match bot_runtime
                        .auth_info(&principal, &workspace, &bot_name)
                        .await
                    {
                        Ok(snapshot) => {
                            // Feed the fresh snapshot through the
                            // broker so it emits HitlResolved on a
                            // successful transition. Then surface the
                            // new status in the response so the
                            // frontend can update its row without
                            // waiting for the next SSE event.
                            if let Some(broker) = auth_hitl_broker.as_ref() {
                                broker.record_snapshot(&principal, &workspace, &snapshot);
                            }
                            let resolved = !matches!(
                                snapshot.status,
                                magician_learning::bots::BotAuthStatus::NeedsAuth
                                    | magician_learning::bots::BotAuthStatus::AccountMismatch
                            );
                            Ok(HttpResponse::Ok().json(RespondHitlResponse {
                                accepted: true,
                                source: body.source,
                                reason: Some(format!(
                                    "recheck_complete; resolved={resolved}; status={:?}",
                                    snapshot.status
                                )),
                            }))
                        },
                        Err(err) => Ok(HttpResponse::BadGateway().json(RespondHitlResponse {
                            accepted: false,
                            source: body.source,
                            reason: Some(format!("bot_auth_recheck_failed: {err}")),
                        })),
                    }
                },
                "dismiss" => {
                    // Explicit dismiss — emit HitlResolved with a
                    // `dismissed` outcome so the frontend drops the
                    // row. The sidecar stays in place; the next poll
                    // will re-emit HitlRequested if the bot still needs
                    // auth (per the transition cache, prev=Ok would be
                    // required to re-emit — but dismiss doesn't change
                    // last-known; the next poll sees same NeedsAuth →
                    // no re-emit). Operator must dismiss + the sidecar
                    // must clear for the row to fully go away.
                    if let Some(broker) = auth_hitl_broker.as_ref() {
                        broker.emit_dismissed(&principal, &workspace, &bot_name);
                    }
                    Ok(HttpResponse::Ok().json(RespondHitlResponse {
                        accepted: true,
                        source: body.source,
                        reason: Some("dismissed".to_string()),
                    }))
                },
                other => Ok(HttpResponse::BadRequest().json(RespondHitlResponse {
                    accepted: false,
                    source: body.source,
                    reason: Some(format!(
                        "bot_auth_unrecognized_selected_id: `{other}` (expected open_auth_flow | recheck | dismiss)"
                    )),
                })),
            }
        },
        "diff_approval" => {
            // The HitlRequested envelope for diff_approval can be
            // backed by either:
            //   - a Magician-native FileEditTransaction, or
            //   - a Pi-backed CodeChangeProposal imported from a
            //     shadow-workspace diff.
            //
            // The URL correlation_id is the backend-specific approval
            // id. Resolve against proposal storage first, then fall
            // back to the native transaction store for existing
            // write_file/edit_file/apply_patch approvals.
            //
            // Operator response:
            //   - selected_id == "apply"  → apply the owning backend,
            //     taking a snapshot and marking the approval Applied.
            //   - selected_id == "reject" → mark the owning backend
            //     Rejected with no disk mutation.
            //   - Aborted              → treat as reject (operator
            //     closed the modal without explicit choice).
            //
            // Per-file partial apply is supported for Pi-backed
            // CodeChangeProposal ids via `selected_paths`. Native
            // FileEditTransaction approvals remain whole-transaction
            // only.
            let request_scope = match resolve_required_scope_from_request(&request) {
                Ok(scope) => scope,
                Err(response) => return Ok(response),
            };
            let Some(artifact_service) = api.orchestrator().artifact_v2_service() else {
                return Ok(missing_hitl_dependency_response(
                    &body.source,
                    "ArtifactV2Service",
                ));
            };
            let scope_root = artifact_service
                .workspace()
                .scope_root(&request_scope.0, &request_scope.1);
            // The coding-agent edits land under `<scope>/workdirs/home`
            // (`capability_home_root`), matching the convention used
            // by capability execution. Tools that stage transactions
            // MUST emit paths relative to this root; otherwise the
            // symlink-containment guard in `apply_transaction` will
            // catch the mismatch.
            let workspace_root = artifact_service
                .workspace()
                .capability_home_root(&request_scope.0, &request_scope.1);
            let transactions =
                magician::magician_v2::execution::file_edit::transaction::TransactionStore::new(
                    &scope_root,
                );
            let proposals =
                magician::magician_v2::execution::file_edit::proposal::CodeChangeProposalStore::new(
                    &scope_root,
                );
            let snapshots =
                magician::magician_v2::execution::file_edit::snapshot::SnapshotStore::new(
                    &scope_root,
                );
            enum DiffApprovalTarget {
                Proposal(
                    magician::magician_v2::execution::file_edit::proposal::CodeChangeProposalId,
                ),
                Transaction(
                    magician::magician_v2::execution::file_edit::transaction::TransactionId,
                ),
            }

            let proposal_id = match magician::magician_v2::execution::file_edit::proposal::CodeChangeProposalId::parse(&correlation_id) {
                Ok(id) => Some(id),
                Err(err) => {
                    if correlation_id.starts_with("ccp-") {
                        return Ok(HttpResponse::BadRequest().json(RespondHitlResponse {
                            accepted: false,
                            source: body.source,
                            reason: Some(format!("diff_approval_invalid_proposal_id: {err}")),
                        }));
                    }
                    None
                },
            };
            let target = if let Some(id) = proposal_id.filter(|id| proposals.exists(id)) {
                DiffApprovalTarget::Proposal(id)
            } else {
                // CRITICAL: validate the operator-supplied
                // correlation_id before treating it as a
                // filesystem-derived transaction id.
                let txn_id = match magician::magician_v2::execution::file_edit::transaction::TransactionId::parse(&correlation_id) {
                    Ok(id) => id,
                    Err(err) => {
                        return Ok(HttpResponse::BadRequest().json(RespondHitlResponse {
                            accepted: false,
                            source: body.source,
                            reason: Some(format!("diff_approval_invalid_correlation_id: {err}")),
                        }));
                    },
                };
                DiffApprovalTarget::Transaction(txn_id)
            };
            // Load the durable record before any mutation and bind the response
            // to its stored origin. This prevents a crafted/stale target from
            // applying proposal A and then draining or terminalizing unrelated
            // execution B supplied in the request body.
            let (owner_task_id, stored_execution_id, authority_key, trusted_entry) = match &target {
                DiffApprovalTarget::Proposal(proposal_id) => {
                    let proposal = match proposals.load(proposal_id) {
                        Ok(proposal) => proposal,
                        Err(err) => {
                            return Ok(HttpResponse::BadRequest().json(RespondHitlResponse {
                                accepted: false,
                                source: body.source,
                                reason: Some(format!("diff_approval_load_failed: {err:#}")),
                            }));
                        },
                    };
                    if proposal.scope.principal != request_scope.0
                        || proposal.scope.workspace != request_scope.1
                    {
                        return Ok(HttpResponse::Forbidden().json(RespondHitlResponse {
                            accepted: false,
                            source: body.source,
                            reason: Some("diff_approval_scope_mismatch".to_string()),
                        }));
                    }
                    let authority_key =
                        magician::magician_v2::execution::trusted_store::TrustedRecordKey {
                            kind: magician::magician_v2::execution::trusted_store::StoreKind::CodeChangeProposal,
                            principal: request_scope.0.clone(),
                            workspace: request_scope.1.clone(),
                            id: proposal_id.as_str().to_string(),
                        };
                    let trusted_entry = match api
                        .agent_api
                        .trust_authority
                        .verify_file_edit_decision(
                            &authority_key,
                            &request_scope.0,
                            &request_scope.1,
                            proposal.task_id.as_deref(),
                            proposal.execution_id.as_deref(),
                            proposal.content_hash(),
                        ) {
                        Ok(entry) => entry,
                        Err(err) => {
                            return Ok(HttpResponse::Conflict().json(RespondHitlResponse {
                                accepted: false,
                                source: body.source,
                                reason: Some(format!("diff_approval_authority_mismatch: {err}")),
                            }));
                        },
                    };
                    (
                        proposal.task_id,
                        proposal.execution_id,
                        authority_key,
                        trusted_entry,
                    )
                },
                DiffApprovalTarget::Transaction(txn_id) => {
                    let transaction = match transactions.load(txn_id) {
                        Ok(transaction) => transaction,
                        Err(err) => {
                            return Ok(HttpResponse::BadRequest().json(RespondHitlResponse {
                                accepted: false,
                                source: body.source,
                                reason: Some(format!("diff_approval_load_failed: {err:#}")),
                            }));
                        },
                    };
                    if transaction.scope.principal != request_scope.0
                        || transaction.scope.workspace != request_scope.1
                    {
                        return Ok(HttpResponse::Forbidden().json(RespondHitlResponse {
                            accepted: false,
                            source: body.source,
                            reason: Some("diff_approval_scope_mismatch".to_string()),
                        }));
                    }
                    let authority_key =
                        magician::magician_v2::execution::trusted_store::TrustedRecordKey {
                            kind:
                                magician::magician_v2::execution::trusted_store::StoreKind::Transaction,
                            principal: request_scope.0.clone(),
                            workspace: request_scope.1.clone(),
                            id: txn_id.as_str().to_string(),
                        };
                    let trusted_entry = match api
                        .agent_api
                        .trust_authority
                        .verify_file_edit_decision(
                            &authority_key,
                            &request_scope.0,
                            &request_scope.1,
                            transaction.task_id.as_deref(),
                            transaction.execution_id.as_deref(),
                            transaction.content_hash(),
                        ) {
                        Ok(entry) => entry,
                        Err(err) => {
                            return Ok(HttpResponse::Conflict().json(RespondHitlResponse {
                                accepted: false,
                                source: body.source,
                                reason: Some(format!("diff_approval_authority_mismatch: {err}")),
                            }));
                        },
                    };
                    (
                        transaction.task_id,
                        transaction.execution_id,
                        authority_key,
                        trusted_entry,
                    )
                },
            };
            let requested_execution_id = body
                .execution_id
                .as_deref()
                .map(str::trim)
                .filter(|value| !value.is_empty());
            let effective_execution_id = match bind_hitl_execution_id(
                requested_execution_id,
                stored_execution_id.as_deref(),
            ) {
                Ok(execution_id) => execution_id,
                Err(HitlExecutionBindingError::Mismatch { requested, owner }) => {
                    return Ok(HttpResponse::Conflict().json(RespondHitlResponse {
                        accepted: false,
                        source: body.source,
                        reason: Some(format!(
                            "diff_approval_execution_mismatch: requested={requested}, owner={owner}"
                        )),
                    }));
                },
            };
            let _execution_lifecycle_exclusion =
                if let Some(execution_id) = effective_execution_id.as_deref() {
                    Some(
                        match acquire_execution_lifecycle_mutation_admission(
                            api.full_pause_store(),
                            execution_id,
                            None,
                            &request_scope.0,
                            &request_scope.1,
                            "resolve_diff_approval",
                        )
                        .await
                        {
                            Ok(exclusion) => exclusion,
                            Err(response) => return Ok(response),
                        },
                    )
                } else {
                    None
                };
            let selected = match &body.value {
                AgenticResumeValue::Choice { selected_id, .. } => selected_id.clone(),
                AgenticResumeValue::Aborted { .. } => "reject".to_string(),
                _ => {
                    return Ok(HttpResponse::BadRequest().json(RespondHitlResponse {
                        accepted: false,
                        source: body.source,
                        reason: Some(
                            "diff_approval_requires_choice_value (apply | reject)".to_string(),
                        ),
                    }));
                },
            };
            let _ = api
                .full_pause_store()
                .schedule_legacy_pending_index_background_repair();
            let pending_pause = match effective_execution_id.as_deref() {
                Some(execution_id) if !execution_id.trim().is_empty() => {
                    let matches: Vec<_> = api
                        .full_pause_store()
                        .get_pending_for_execution(execution_id)
                        .into_iter()
                        .filter(|pending| {
                            diff_approval_input_matches_correlation(
                                &pending.input_type,
                                &correlation_id,
                            )
                        })
                        .collect();
                    if matches.is_empty()
                        && api
                            .full_pause_store()
                            .legacy_pending_index_repair_in_progress()
                    {
                        return Ok(legacy_pause_index_repair_pending_response(execution_id));
                    }
                    match matches.len() {
                        0 => None,
                        1 => Some((execution_id.to_string(), matches[0].key.clone())),
                        count => {
                            return Ok(v2_conflict(
                                "Ambiguous diff approval pause state",
                                Some(serde_json::json!({
                                    "execution_id": execution_id,
                                    "correlation_id": correlation_id,
                                    "count": count,
                                })),
                            ));
                        },
                    }
                },
                _ => None,
            };
            // Legacy records that predate persisted execution ownership can be
            // resolved only while a live pause proves the correlation belongs to
            // the supplied execution. Otherwise fail before applying/rejecting.
            if stored_execution_id.is_none() && pending_pause.is_none() {
                return Ok(HttpResponse::Conflict().json(RespondHitlResponse {
                    accepted: false,
                    source: body.source,
                    reason: Some(
                        "diff_approval_unbound_legacy_record_requires_matching_pause".to_string(),
                    ),
                }));
            }

            let resolution_reason = match selected.as_str() {
                "apply" => {
                    // New scopes may not have executed a capability yet. Create
                    // the apply root only after staged-pause admission succeeds,
                    // so a retryable response has no filesystem side effects.
                    if !workspace_root.exists() {
                        if let Err(err) = std::fs::create_dir_all(&workspace_root) {
                            return Ok(HttpResponse::BadRequest().json(RespondHitlResponse {
                                accepted: false,
                                source: body.source,
                                reason: Some(format!(
                                    "diff_approval_init_home_failed: {err} ({})",
                                    workspace_root.display()
                                )),
                            }));
                        }
                    }
                    match &target {
                    DiffApprovalTarget::Proposal(proposal_id) => {
                        let selected_paths: Vec<String> = body
                            .selected_paths
                            .iter()
                            .map(|path| path.trim().to_string())
                            .filter(|path| !path.is_empty())
                            .collect();
                        // Pre-existing loadability gate: a proposal that cannot be read
                        // from this scope's store fails `diff_approval_load_failed`
                        // before the authority check. The loaded value is bound here as
                        // `loaded_proposal` and reused for the content-hash tamper check
                        // below — it is the SAME on-disk record `apply_proposal` re-loads
                        // and materializes, so hashing it proves what actually gets
                        // applied. The apply-root decision still comes from the authority
                        // (below), not from this record's `apply_root`.
                        let loaded_proposal = match proposals.load(proposal_id) {
                            Ok(loaded) => loaded,
                            Err(err) => {
                                return Ok(HttpResponse::BadRequest().json(RespondHitlResponse {
                                    accepted: false,
                                    source: body.source,
                                    reason: Some(format!("diff_approval_load_failed: {err:#}")),
                                }));
                            },
                        };
                        // TRUSTED-STORE INTEGRITY: resolve the apply root from the
                        // in-process TrustAuthority, NEVER from the shell-writable
                        // on-disk proposal JSON's `apply_root`. The stage site
                        // (`proposal::stage_patch_with_apply_root`, the single choke
                        // point every proposal funnels through) records an authority
                        // entry for every proposal magician itself stages; a record
                        // with no entry is either shell-forged (never staged this
                        // boot) or a pre-restart leftover (authority is empty after a
                        // restart by design). Both fail closed: do NOT apply — the
                        // operator re-stages via a fresh proposal, which mints a fresh
                        // entry.
                        //
                        // An approved out-of-workspace apply carries `apply_root` (an
                        // operator-approved sandbox / real-repo root); a normal apply's
                        // entry has `apply_root: None` → the default scoped workspace
                        // root. The canonicalize + is_dir guard (mirroring
                        // `resolve_code_change_proposal_apply_root`) then runs on the
                        // authority-provided root, and `apply_proposal`'s
                        // symlink-containment guard (`assert_resolved_inside_workspace`)
                        // still rejects any `..`/symlink escape beyond it. The on-disk
                        // JSON is used only for the patch contents (still hunk-checked
                        // per-file by `apply_proposal`), never for the apply-destination
                        // decision.
                        if trusted_entry.content_hash != loaded_proposal.content_hash() {
                            return Ok(HttpResponse::Conflict().json(RespondHitlResponse {
                                accepted: false,
                                source: body.source,
                                reason: Some(
                                    "diff_approval_content_tampered: the proposal changed after review authentication; re-stage to obtain a fresh approval".to_string(),
                                ),
                            }));
                        }
                        let requested_root = trusted_entry
                            .apply_root
                            .clone()
                            .unwrap_or_else(|| workspace_root.clone());
                        // Canonicalize + is_dir guard on the authority-provided root
                        // (mirrors `resolve_code_change_proposal_apply_root`, which
                        // keyed off the now-ignored on-disk `apply_root`).
                        let apply_root = match requested_root.canonicalize() {
                            Ok(canonical) if canonical.is_dir() => requested_root,
                            Ok(canonical) => {
                                return Ok(HttpResponse::BadRequest().json(RespondHitlResponse {
                                    accepted: false,
                                    source: body.source,
                                    reason: Some(format!(
                                        "diff_approval_apply_root_invalid: proposal apply_root `{}` is not a directory",
                                        canonical.display()
                                    )),
                                }));
                            },
                            Err(err) => {
                                return Ok(HttpResponse::BadRequest().json(RespondHitlResponse {
                                    accepted: false,
                                    source: body.source,
                                    reason: Some(format!(
                                        "diff_approval_apply_root_invalid: {}: {err}",
                                        requested_root.display()
                                    )),
                                }));
                            },
                        };
                        let apply_result = if selected_paths.is_empty() {
                            magician::magician_v2::execution::file_edit::proposal::apply_proposal_verified_decision(
                                &proposals,
                                &snapshots,
                                proposal_id,
                                &apply_root,
                                trusted_entry.content_hash,
                            )
                        } else {
                            magician::magician_v2::execution::file_edit::proposal::apply_proposal_selected_paths_verified_decision(
                            &proposals,
                            &snapshots,
                            proposal_id,
                            &apply_root,
                                &selected_paths,
                                trusted_entry.content_hash,
                            )
                        };
                        match apply_result {
                            Ok(magician::magician_v2::execution::file_edit::transaction::DecisionTransition::Transitioned(loaded)) => {
                                // Terminal state reached: drop the authority entry so a
                                // replayed approve for the same id fail-closes.
                                api.agent_api.trust_authority.forget(&authority_key);
                                let snapshot_id = loaded.snapshot_id.clone().unwrap_or_default();
                                if matches!(
                                    loaded.status,
                                    magician::magician_v2::execution::file_edit::proposal::CodeChangeProposalStatus::PartiallyApplied
                                ) {
                                    format!(
                                        "partially applied proposal; applied_files={}; skipped_files={}; snapshot={snapshot_id}",
                                        loaded.applied_paths.len(),
                                        loaded.skipped_paths.len(),
                                    )
                                } else {
                                format!(
                                    "applied proposal; snapshot={snapshot_id} (revert by re-staging or via snapshot api)"
                                )
                                }
                            },
                            Ok(magician::magician_v2::execution::file_edit::transaction::DecisionTransition::AlreadyResolved(_)) => {
                                return Ok(HttpResponse::Conflict().json(RespondHitlResponse {
                                    accepted: false,
                                    source: body.source,
                                    reason: Some("already_resolved".to_string()),
                                }));
                            },
                            Err(err) => {
                                let status = if err.downcast_ref::<magician::magician_v2::execution::file_edit::transaction::ReviewRevisionConflict>().is_some() {
                                    StatusCode::CONFLICT
                                } else {
                                    StatusCode::BAD_REQUEST
                                };
                                return Ok(HttpResponse::build(status).json(RespondHitlResponse {
                                    accepted: false,
                                    source: body.source,
                                    reason: Some(format!("diff_approval_apply_failed: {err:#}")),
                                }));
                            },
                        }
                    },
                    DiffApprovalTarget::Transaction(txn_id) => {
                        if !body.selected_paths.is_empty() {
                            return Ok(HttpResponse::BadRequest().json(RespondHitlResponse {
                                accepted: false,
                                source: body.source,
                                reason: Some(
                                    "diff_approval_partial_apply_not_supported_for_transactions"
                                        .to_string(),
                                ),
                            }));
                        }
                        // TRUSTED-STORE INTEGRITY: resolve the apply root from the
                        // in-process TrustAuthority, NEVER from the shell-writable
                        // on-disk transaction JSON. The stage site
                        // (`staged_file_edit::stage_edits`) records an authority entry
                        // for every transaction magician itself stages; a record with
                        // no entry is either shell-forged (never staged this boot) or a
                        // pre-restart leftover (authority is empty after a restart by
                        // design). Both fail closed: do NOT apply — the operator
                        // re-stages via a fresh approval, which mints a fresh entry.
                        //
                        // An approved out-of-workspace write carries `apply_root` (an
                        // operator-approved sandbox root); a normal write's entry has
                        // `apply_root: None` → the default scoped workspace root. The
                        // canonicalize + is_dir guard (mirroring
                        // `resolve_transaction_apply_root`) then runs on the
                        // authority-provided root, and `apply_transaction`'s
                        // containment guard still rejects any `..`/symlink escape beyond
                        // it. The on-disk JSON is used only for the edit contents (still
                        // hash-checked per-edit by `apply_transaction`), never for the
                        // apply-destination decision.
                        // Load the on-disk record here so the content-hash tamper check
                        // below hashes the SAME record `apply_transaction` re-loads +
                        // applies (both go through `transactions.load(txn_id)` on the same
                        // store). A record that cannot be read fails closed before the
                        // authority check, matching the proposal arm's loadability gate.
                        let loaded_txn = match transactions.load(txn_id) {
                            Ok(loaded) => loaded,
                            Err(err) => {
                                return Ok(HttpResponse::BadRequest().json(RespondHitlResponse {
                                    accepted: false,
                                    source: body.source,
                                    reason: Some(format!("diff_approval_load_failed: {err:#}")),
                                }));
                            },
                        };
                        if trusted_entry.content_hash != loaded_txn.content_hash() {
                            return Ok(HttpResponse::Conflict().json(RespondHitlResponse {
                                accepted: false,
                                source: body.source,
                                reason: Some(
                                    "diff_approval_content_tampered: the transaction changed after review authentication; re-stage to obtain a fresh approval".to_string(),
                                ),
                            }));
                        }
                        let requested_root = trusted_entry
                            .apply_root
                            .clone()
                            .unwrap_or_else(|| workspace_root.clone());
                        // Canonicalize + is_dir guard on the authority-provided root
                        // (mirrors `resolve_transaction_apply_root`, which keyed off the
                        // now-ignored on-disk `apply_root`).
                        let apply_root = match requested_root.canonicalize() {
                            Ok(canonical) if canonical.is_dir() => requested_root,
                            Ok(canonical) => {
                                return Ok(HttpResponse::BadRequest().json(RespondHitlResponse {
                                    accepted: false,
                                    source: body.source,
                                    reason: Some(format!(
                                        "diff_approval_apply_root_invalid: transaction apply_root `{}` is not a directory",
                                        canonical.display()
                                    )),
                                }));
                            },
                            Err(err) => {
                                return Ok(HttpResponse::BadRequest().json(RespondHitlResponse {
                                    accepted: false,
                                    source: body.source,
                                    reason: Some(format!(
                                        "diff_approval_apply_root_invalid: {}: {err}",
                                        requested_root.display()
                                    )),
                                }));
                            },
                        };
                        match magician::magician_v2::execution::file_edit::snapshot::apply_transaction_verified_decision(
                            &transactions,
                            &snapshots,
                            txn_id,
                            &apply_root,
                            trusted_entry.content_hash,
                        ) {
                            Ok(magician::magician_v2::execution::file_edit::transaction::DecisionTransition::Transitioned(loaded)) => {
                                // Terminal state reached: drop the authority entry so a
                                // replayed approve for the same id fail-closes.
                                api.agent_api.trust_authority.forget(&authority_key);
                                let snapshot_id = loaded.snapshot_id.unwrap_or_default();
                                format!(
                                "applied; snapshot={snapshot_id} (revert by re-staging or via snapshot api)"
                            )
                            },
                            Ok(magician::magician_v2::execution::file_edit::transaction::DecisionTransition::AlreadyResolved(_)) => {
                                return Ok(HttpResponse::Conflict().json(RespondHitlResponse {
                                    accepted: false,
                                    source: body.source,
                                    reason: Some("already_resolved".to_string()),
                                }));
                            },
                            Err(err) => {
                                let status = if err.downcast_ref::<magician::magician_v2::execution::file_edit::transaction::ReviewRevisionConflict>().is_some() {
                                    StatusCode::CONFLICT
                                } else {
                                    StatusCode::BAD_REQUEST
                                };
                                return Ok(HttpResponse::build(status).json(RespondHitlResponse {
                                    accepted: false,
                                    source: body.source,
                                    reason: Some(format!("diff_approval_apply_failed: {err:#}")),
                                }));
                            },
                        }
                    },
                    }
                },
                "reject" => match &target {
                    DiffApprovalTarget::Proposal(proposal_id) => {
                        match proposals.reject(proposal_id) {
                            Ok(magician::magician_v2::execution::file_edit::transaction::DecisionTransition::Transitioned(_)) => {
                                // Terminal: drop any authority entry for this record so
                                // a later replayed approve for the same id fail-closes.
                                api.agent_api.trust_authority.forget(&authority_key);
                                "rejected proposal; no disk mutation".to_string()
                            },
                            Ok(magician::magician_v2::execution::file_edit::transaction::DecisionTransition::AlreadyResolved(_)) => {
                                return Ok(HttpResponse::Conflict().json(RespondHitlResponse {
                                    accepted: false,
                                    source: body.source,
                                    reason: Some("already_resolved".to_string()),
                                }));
                            },
                            Err(err) => {
                                return Ok(HttpResponse::BadRequest().json(RespondHitlResponse {
                                    accepted: false,
                                    source: body.source,
                                    reason: Some(format!("diff_approval_reject_failed: {err:#}")),
                                }));
                            },
                        }
                    },
                    DiffApprovalTarget::Transaction(txn_id) => match transactions.reject(txn_id) {
                        Ok(magician::magician_v2::execution::file_edit::transaction::DecisionTransition::Transitioned(_)) => {
                            // Terminal: drop any authority entry for this record so a
                            // later replayed approve for the same id fail-closes.
                            api.agent_api.trust_authority.forget(&authority_key);
                            "rejected; no disk mutation".to_string()
                        },
                        Ok(magician::magician_v2::execution::file_edit::transaction::DecisionTransition::AlreadyResolved(_)) => {
                            return Ok(HttpResponse::Conflict().json(RespondHitlResponse {
                                accepted: false,
                                source: body.source,
                                reason: Some("already_resolved".to_string()),
                            }));
                        },
                        Err(err) => {
                            return Ok(HttpResponse::BadRequest().json(RespondHitlResponse {
                                accepted: false,
                                source: body.source,
                                reason: Some(format!("diff_approval_reject_failed: {err:#}")),
                            }));
                        },
                    },
                },
                other => {
                    return Ok(HttpResponse::BadRequest().json(RespondHitlResponse {
                        accepted: false,
                        source: body.source,
                        reason: Some(format!(
                            "diff_approval_unrecognized_selected_id: `{other}` (expected apply | reject)"
                        )),
                    }));
                },
            };

            // DURABILITY: the canonical `hitl.resolved` must persist to the
            // origin execution's `events.jsonl`, otherwise the attention
            // projection (which reads only per-execution durable events)
            // never sees the resolution and rebuilds the "code apply" card
            // forever — the exact reappearing-HITL-card bug. Persisting via
            // `emit(...)` requires a mappable event, and `map_v2_realtime_event`
            // maps `HitlResolved` only when `execution_id: Some`.
            //
            // The pre-mutation ownership gate above already selected the only
            // execution this decision may affect. Reuse that authoritative
            // binding for durable resolution and terminal reconciliation.
            let resolved_execution_id = effective_execution_id.clone();
            let resolved_task_id = owner_task_id.clone();

            if let Some(broadcaster) = api.orchestrator().event_broadcaster() {
                let resolved_event =
                    magician::magician_v2::realtime_events::RuntimeTransportEvent::HitlResolved {
                        correlation_id: correlation_id.clone(),
                        source: "diff_approval".to_string(),
                        outcome: "responded".to_string(),
                        decision: Some(selected.clone()),
                        task_id: resolved_task_id.clone(),
                        execution_id: resolved_execution_id.clone(),
                        agent_id: None,
                        principal: Some(request_scope.0.clone()),
                        workspace: Some(request_scope.1.clone()),
                        timestamp: chrono::Utc::now().timestamp_millis(),
                    };
                if resolved_execution_id.is_some() {
                    // Durable path: `emit` mirrors the canonical
                    // `hitl.resolved` into the origin execution's
                    // `events.jsonl` (combined with the self-describing-scope
                    // persist fallback, this survives a process restart).
                    if resolved_task_id.is_none() {
                        // execution_id recovered but task_id absent — the
                        // self-describing-scope persist fallback needs task_id
                        // (the events.jsonl directory segment), so on a
                        // registry miss the durable mirror is silently skipped.
                        tracing::warn!(
                            %correlation_id,
                            source = "diff_approval",
                            execution_id = ?resolved_execution_id,
                            "hitl.resolved recovered execution_id but no task_id; self-describing durable persist may be skipped on a registry miss"
                        );
                    }
                    broadcaster.emit(resolved_event);
                } else {
                    // No recoverable execution_id (native transaction with a
                    // blank body.execution_id). The event is unmappable and
                    // cannot persist to any per-execution log, so fall back to
                    // the wire-only broadcast — matching prior behavior — and
                    // record why durability was skipped.
                    tracing::warn!(
                        %correlation_id,
                        source = "diff_approval",
                        "hitl.resolved could not recover an execution_id; persisting durably skipped (wire-only broadcast)"
                    );
                    broadcaster.emit_transport_only(resolved_event);
                }
            }

            if let Some((execution_id, pause_key)) = pending_pause {
                // The diff mutation is durable. Resume re-acquires the exact
                // execution fence around pause consumption and Executing CAS;
                // retaining this instance across that call would self-deadlock.
                drop(_execution_lifecycle_exclusion);
                let resume_req = AgenticResumeRequest {
                    pause_state_id: Some(pause_key),
                    plan_id: None,
                    step_id: None,
                    input_type: "diff_approval".to_string(),
                    value: body.value,
                    agent_id: None,
                    goal_id: None,
                    cycle_id: None,
                };
                return api
                    .resume_agentic_execution_with_scope(
                        web::Path::from(execution_id),
                        web::Json(resume_req),
                        Some(request_scope),
                    )
                    .await;
            } else if let Some(execution_id) = effective_execution_id {
                // No live pause matched this correlation_id, but `body.execution_id`
                // is present. The diff_approval HITL left the runtime execution in
                // WaitingUser (ExecutionPausedForInput), so the operator's decision
                // still has to drive it terminal or the v3 task stays frozen at
                // paused/waiting_for_user (the "perpetually running" orphan).
                //
                // (a) Drain any LINGERING pause for this execution (memory AND disk).
                // Load-bearing: the orphan reconciler refuses to finalize while
                // `resumable_pause_exists` is true, and a stale dead pause (exactly
                // why no live pause matched here) keeps it true.
                let runtime_execution = match api.orchestrator().get_execution(&execution_id).await
                {
                    Ok(execution) => execution,
                    Err(error) => return Ok(v2_execution_load_error(&execution_id, &error)),
                };
                match api
                    .orchestrator()
                    .is_governed_app_execution(&execution_id)
                    .await
                {
                    Ok(false) => {},
                    Ok(true) | Err(_) => {
                        return Ok(governed_app_generic_lifecycle_refused(&execution_id));
                    },
                }
                let _drained = api.full_pause_store().remove_for_execution(&execution_id);

                // (b) Drive the in-memory orchestrator execution terminal — only when
                // it is still NON-terminal (ExecutionStart resurrects a finished run).
                // reject -> ExecutionFailed is a legal one-hop from WaitingUser; apply
                // -> Completed needs ExecutionStart (WaitingUser->Executing) then
                // ExecutionComplete (Executing->Completed), since WaitingUser->
                // ExecutionComplete is not a legal transition.
                match runtime_execution {
                    execution if !execution.waiting_state.is_terminal() => {
                        let events: &[magician::magician_v2::orchestrator::WorkflowEvent] =
                            if selected == "apply" {
                                &[
                                magician::magician_v2::orchestrator::WorkflowEvent::ExecutionStart,
                                magician::magician_v2::orchestrator::WorkflowEvent::ExecutionComplete,
                            ]
                            } else {
                                &[magician::magician_v2::orchestrator::WorkflowEvent::ExecutionFailed]
                            };
                        for event in events {
                            if let Err(error) = api
                                .orchestrator()
                                .transition_status(&execution_id, *event)
                                .await
                            {
                                warn!(
                                    execution_id = %execution_id,
                                    ?event,
                                    error = %error,
                                    "[MAGICIAN-V2-API] diff_approval finalize: terminal transition failed"
                                );
                            }
                        }
                    },
                    _ => {
                        // Already terminal — nothing to transition; the persist below
                        // reconciles the v3 task from the runtime outcome.
                    },
                }

                // (c) Flip the v3 task off paused. transition_status already persists
                // when it actually changed a task-backed execution; this explicit call
                // covers the no-op/idempotent path and mirrors the resume-start route.
                maybe_persist_task_backed_execution_outcome(
                    api.agent_api(),
                    api.orchestrator(),
                    &execution_id,
                    "diff_approval finalize without live pause",
                )
                .await;
            }

            Ok(HttpResponse::Ok().json(RespondHitlResponse {
                accepted: true,
                source: body.source,
                reason: Some(resolution_reason),
            }))
        },
        // Agentic/runtime escalation sources dispatch to
        // `agentic-resume` with the correlation_id as pause_state_id.
        source if is_agentic_runtime_hitl_source(source) => {
            let request_scope = match resolve_required_scope_from_request(&request) {
                Ok(scope) => scope,
                Err(response) => return Ok(response),
            };
            // Canonical envelopes carry the real runtime execution id. Agent-
            // scoped pause keys begin `agent:<agent>:...`, so parsing the first
            // colon-delimited segment yields the literal string `agent` and
            // causes a scope conflict. Prefer the explicit id and retain key
            // parsing only for legacy execution-keyed callers.
            let explicit_execution_id = body.execution_id.clone();
            let resume_req = AgenticResumeRequest {
                pause_state_id: Some(correlation_id),
                plan_id: None,
                step_id: None,
                input_type: canonical_agentic_input_type(body.input_type.as_deref(), &body.value),
                value: body.value,
                agent_id: None,
                goal_id: None,
                cycle_id: None,
            };
            // The legacy resume endpoint takes execution_id in the URL —
            // pull it from the resume_req.pause_state_id parser. The
            // pause_state.storage_key() format is
            // `<execution_id>:<plan_id>:<step_id>` so we extract the prefix.
            let execution_id = canonical_agentic_resume_execution_id(
                explicit_execution_id.as_deref(),
                resume_req.pause_state_id.as_deref(),
            );
            let inner_path = web::Path::from(execution_id);
            let inner = web::Json(resume_req);
            api.resume_agentic_execution_acknowledged_when_admitted(
                inner_path,
                inner,
                Some(request_scope),
                source.to_string(),
            )
            .await
        },
        unsupported => Ok(HttpResponse::BadRequest().json(RespondHitlResponse {
            accepted: false,
            source: unsupported.to_string(),
            reason: Some("unsupported_hitl_source".to_string()),
        })),
    }
}

/// The storage key a `pause_state_id` selector addresses, whether the client
/// sent the bare key or the canonical correlation id built on it.
fn bare_pause_storage_key(selector: &str) -> String {
    magician::magician_v2::execution::agentic::split_hitl_correlation_id(selector)
        .0
        .to_owned()
}

/// Turn a canonical HITL correlation id in `pause_state_id` back into the
/// storage key every pause lookup runs on, keeping the ask it named for the
/// check against the pause taken. A bare key (a legacy client, or a pause
/// from before asks had identities) passes through with nothing to check.
fn split_ask_from_pause_selector(
    req: web::Json<AgenticResumeRequest>,
) -> (web::Json<AgenticResumeRequest>, Option<String>) {
    let mut req = req.into_inner();
    let split = req.pause_state_id.as_deref().and_then(|selector| {
        let (key, ask) =
            magician::magician_v2::execution::agentic::split_hitl_correlation_id(selector);
        ask.map(|ask| (key.to_owned(), ask.to_owned()))
    });
    let expected_ask = split.map(|(key, ask)| {
        req.pause_state_id = Some(key);
        ask
    });
    (web::Json(req), expected_ask)
}

fn canonical_agentic_resume_execution_id(
    explicit_execution_id: Option<&str>,
    pause_state_id: Option<&str>,
) -> String {
    explicit_execution_id
        .map(str::trim)
        .filter(|value| !value.is_empty())
        .map(str::to_string)
        .unwrap_or_else(|| {
            pause_state_id
                .and_then(|key| key.split(':').next())
                .unwrap_or_default()
                .to_string()
        })
}

fn agentic_value_input_type_name(value: &AgenticResumeValue) -> &'static str {
    match value {
        AgenticResumeValue::Text { .. } => "text",
        AgenticResumeValue::Password { .. } => "password",
        AgenticResumeValue::Choice { .. } => "choice",
        AgenticResumeValue::MultiChoice { .. } => "multi_choice",
        AgenticResumeValue::Confirmation { .. } => "confirmation",
        AgenticResumeValue::ExternalActionCompleted { .. } => "external_action",
        AgenticResumeValue::FilePath { .. } => "file_path",
        AgenticResumeValue::Guidance { .. } => "guidance",
        AgenticResumeValue::Aborted { .. } => "aborted",
        AgenticResumeValue::Form { .. } => "form",
    }
}

fn canonical_agentic_input_type(
    requested_input_type: Option<&str>,
    value: &AgenticResumeValue,
) -> String {
    requested_input_type
        .map(str::trim)
        .filter(|value| !value.is_empty())
        .unwrap_or_else(|| agentic_value_input_type_name(value))
        .to_string()
}

fn missing_hitl_dependency_response(source: &str, dependency: &str) -> HttpResponse {
    HttpResponse::ServiceUnavailable().json(RespondHitlResponse {
        accepted: false,
        source: source.to_string(),
        reason: Some(format!("missing_hitl_dependency:{dependency}")),
    })
}

impl std::fmt::Debug for RespondHitlRequest {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        f.debug_struct("RespondHitlRequest")
            .field("source", &self.source)
            .field("value", &"[redacted]")
            .field("input_type", &self.input_type)
            .finish_non_exhaustive()
    }
}

fn agentic_value_decision_label(value: &AgenticResumeValue) -> String {
    match value {
        AgenticResumeValue::Choice { selected_id, .. } => selected_id.clone(),
        AgenticResumeValue::Confirmation { confirmed: true } => "confirm".to_string(),
        AgenticResumeValue::Confirmation { confirmed: false } => "deny".to_string(),
        AgenticResumeValue::Aborted { .. } => "cancel".to_string(),
        AgenticResumeValue::MultiChoice { selected_ids } => selected_ids.join(","),
        _ => "provide_input".to_string(),
    }
}

/// Where a submitted value goes: into service custody as material, or into
/// the ordinary relay/history text. Decided by the pending request's stored
/// sensitivity spec; the legacy browser request types stay secure as a
/// belt-and-braces for entries restored from before the spec existed.
#[derive(Debug, PartialEq)]
enum SensitiveTransport {
    /// `input` carries the material for `UserRequestService::respond_scoped`
    /// to move into custody; nothing is rendered for relays.
    Secure {
        input: Option<String>,
    },
    Ordinary {
        input_text: Option<String>,
    },
}

fn sensitive_transport_for_pending(
    pending: Option<&magician::magician_v2::user_requests::UserRequest>,
    value: &AgenticResumeValue,
) -> SensitiveTransport {
    let spec = pending.and_then(|req| req.sensitive.as_ref());
    let legacy_secure_type = pending.is_some_and(|req| {
        matches!(
            req.request_type.as_str(),
            "secure_browser_input" | "secure_browser_confirm"
        )
    });
    if spec.is_none() && !legacy_secure_type {
        return SensitiveTransport::Ordinary {
            input_text: agentic_value_input_text(value, None),
        };
    }
    let input = match value {
        AgenticResumeValue::Password { value } | AgenticResumeValue::Text { value } => {
            Some(value.clone())
        },
        // A client that submits a masked answer as `guidance` (the operator
        // typed into the advice box, or an older client's only text shape) is
        // still answering THIS ask. Dropping it resolved the ask with no answer
        // while the operator believed they had given one, and the run resumed
        // blind; routing it through custody keeps it off every relay and gives
        // the run the answer it waited for.
        AgenticResumeValue::Guidance { advice } => Some(advice.clone()),
        // A form ships as one JSON object of every answered field; the service
        // deposits the spec-flagged ones into custody and keeps the rest usable
        // as ordinary text. Nothing is rendered here.
        AgenticResumeValue::Form { answers } => spec.map(|_| {
            let object: serde_json::Map<String, serde_json::Value> = answers
                .iter()
                .filter(|answer| !answer.skipped)
                .map(|answer| {
                    let value = if !answer.selected_ids.is_empty() {
                        answer.selected_ids.join(", ")
                    } else {
                        answer.value.clone().unwrap_or_default()
                    };
                    (answer.id.clone(), serde_json::Value::String(value))
                })
                .collect();
            serde_json::Value::Object(object).to_string()
        }),
        _ => None,
    };
    SensitiveTransport::Secure { input }
}

/// Ordinary relay/history text for a value. A `Password` never becomes text;
/// a form withholds every field the spec flags, plus — with or without a
/// spec — any field whose id reads as a secret (compatibility detection that
/// can only withhold more, never less).
fn agentic_value_input_text(
    value: &AgenticResumeValue,
    spec: Option<&magician::magician_v2::user_requests::SensitiveInputSpec>,
) -> Option<String> {
    match value {
        AgenticResumeValue::Choice { other_value, .. } => other_value.clone(),
        AgenticResumeValue::Text { value } => Some(value.clone()),
        AgenticResumeValue::Password { .. } => None,
        AgenticResumeValue::Guidance { advice } => Some(advice.clone()),
        AgenticResumeValue::ExternalActionCompleted { guidance } => guidance.clone(),
        AgenticResumeValue::FilePath { paths } => Some(paths.join(",")),
        AgenticResumeValue::MultiChoice { selected_ids } => Some(selected_ids.join(",")),
        AgenticResumeValue::Aborted { reason } => reason.clone(),
        AgenticResumeValue::Form { answers } => Some(form_answers_response_text(answers, spec)),
        _ => None,
    }
}

fn form_field_is_withheld(
    answer: &magician::magician_v2::execution::agentic::types::FormAnswer,
    spec: Option<&magician::magician_v2::user_requests::SensitiveInputSpec>,
) -> bool {
    spec.is_some_and(|spec| spec.fields.iter().any(|field| field.id == answer.id))
        || magician::magician_v2::secrets::classify::is_secret_param_name(&answer.id)
}

fn form_answers_response_text(
    answers: &[magician::magician_v2::execution::agentic::types::FormAnswer],
    spec: Option<&magician::magician_v2::user_requests::SensitiveInputSpec>,
) -> String {
    answers
        .iter()
        .map(|answer| {
            if answer.skipped {
                format!("{}: skipped", answer.id)
            } else if form_field_is_withheld(answer, spec) {
                format!("{}: [sensitive; withheld]", answer.id)
            } else if !answer.selected_ids.is_empty() {
                format!("{}: {}", answer.id, answer.selected_ids.join(", "))
            } else {
                format!("{}: {}", answer.id, answer.value.as_deref().unwrap_or(""))
            }
        })
        .collect::<Vec<_>>()
        .join("\n")
}

fn form_answer_response_text(
    answer: &magician::magician_v2::execution::agentic::types::FormAnswer,
    spec: Option<&magician::magician_v2::user_requests::SensitiveInputSpec>,
) -> String {
    if answer.skipped {
        "(skipped)".to_string()
    } else if form_field_is_withheld(answer, spec) {
        "[sensitive; withheld]".to_string()
    } else if !answer.selected_ids.is_empty() {
        answer.selected_ids.join(", ")
    } else {
        answer.value.clone().unwrap_or_default()
    }
}

