/// Response for screenshot fetch endpoint
#[derive(Debug, Serialize)]
pub struct ScreenshotResponse {
    pub observation_id: String,
    /// Base64-encoded PNG screenshot
    pub screenshot: String,
    pub captured_at: i64, // Unix timestamp in milliseconds
}

/// Response for storage stats endpoint
#[derive(Debug, Serialize)]
pub struct StorageStatsResponse {
    pub execution_id: String,
    pub total_screenshots: usize,
    pub total_size_bytes: u64,
    pub total_size_human: String,
}

/// Format bytes into human-readable string (e.g., "1.5 MB")
fn format_bytes(bytes: u64) -> String {
    const KB: u64 = 1024;
    const MB: u64 = KB * 1024;
    const GB: u64 = MB * 1024;

    if bytes >= GB {
        format!("{:.2} GB", bytes as f64 / GB as f64)
    } else if bytes >= MB {
        format!("{:.2} MB", bytes as f64 / MB as f64)
    } else if bytes >= KB {
        format!("{:.2} KB", bytes as f64 / KB as f64)
    } else {
        format!("{} B", bytes)
    }
}

/// GET /api/magician/v2/executions/{execution_id}/observations/{observation_id}/screenshot handler
///
/// Fetches a previously captured screenshot from disk by execution_id and observation_id.
/// Screenshots are stored persistently on disk for debugging and inspection.
pub async fn get_observation_screenshot_handler(
    api: web::Data<MagicianV2Api>,
    path: web::Path<(String, String)>,
) -> Result<HttpResponse> {
    let (requested_execution_id, observation_id) = path.into_inner();
    let execution_id = normalize_execution_lookup_id(&api.agent_api, &requested_execution_id).await;

    match api
        .get_observation_screenshot(&observation_id, &execution_id)
        .await
    {
        Ok(Some((png_bytes, metadata))) => {
            // Encode PNG bytes to base64 for JSON response
            let screenshot_base64 = general_purpose::STANDARD.encode(&png_bytes);

            Ok(HttpResponse::Ok().json(ScreenshotResponse {
                observation_id: observation_id.clone(),
                screenshot: screenshot_base64,
                captured_at: metadata.captured_at.timestamp_millis(),
            }))
        },
        Ok(None) => {
            warn!(
                observation_id = %observation_id,
                execution_id = %execution_id,
                "Screenshot not found on disk"
            );
            Ok(v2_not_found(
                "Screenshot not found",
                Some(serde_json::json!({
                    "observation_id": observation_id,
                    "execution_id": execution_id,
                })),
            ))
        },
        Err(e) => {
            error!(
                observation_id = %observation_id,
                execution_id = %execution_id,
                error = %e,
                "Failed to retrieve screenshot"
            );
            Ok(v2_internal_error(
                "Failed to retrieve screenshot",
                Some(serde_json::json!({
                    "observation_id": observation_id,
                    "execution_id": execution_id,
                })),
            ))
        },
    }
}

