/// GET /api/magician/v2/executions/{execution_id}/observations/{observation_id}/json handler
///
/// Returns the raw JSON data for an observation (text-first, SoM, or screenshot metadata).
pub async fn get_observation_json_handler(
    api: web::Data<MagicianV2Api>,
    path: web::Path<(String, String)>,
) -> Result<HttpResponse> {
    let (requested_execution_id, observation_id) = path.into_inner();
    let execution_id = normalize_execution_lookup_id(&api.agent_api, &requested_execution_id).await;
    api.get_observation_json(&execution_id, &observation_id)
        .await
}

/// GET /api/magician/v2/executions/{execution_id}/pause-state handler
///
/// Returns the current pause state for an execution (if any).
pub async fn get_pause_state_handler(
    api: web::Data<MagicianV2Api>,
    request: HttpRequest,
    path: web::Path<String>,
) -> Result<HttpResponse> {
    api.get_pause_state(&request, path).await
}

