    /// The API process owns an independent production wake loop. Keep its
    /// exact-retry fencing behavior aligned with the runtime watcher: failure
    /// to acquire the cross-process claim lock must retain the durable row and
    /// leave without attempting Artifact admission.
    #[test]
    fn web_exact_retry_lock_failure_fails_closed() {
        let source = include_str!("web_api.rs");
        let production = source
            .split("\n#[cfg(test)]\nmod tests {")
            .next()
            .expect("production API source");
        let failure_arm = production
            .split("let _claim_guard = match wake_queue")
            .nth(1)
            .and_then(|tail| tail.split("if !wake_queue").next())
            .expect("web exact-retry lock failure arm");
        assert!(failure_arm.contains("Err(error) => {"));
        assert!(failure_arm.contains("exact retry claim lock unavailable; durable claim retained"));
        assert!(failure_arm.contains("return;"));
        assert!(!failure_arm.contains("retry_exact_sleeping_execution"));
    }

    #[test]
    fn web_exact_retry_releases_preflight_lock_before_lifecycle_reacquires_it() {
        let source = include_str!("web_api.rs");
        let production = source
            .split("\n#[cfg(test)]\nmod tests {")
            .next()
            .expect("production API source");
        let handler = production
            .split("let _claim_guard = match wake_queue")
            .nth(1)
            .and_then(|tail| tail.split("WakeKind::ChildCompleted =>").next())
            .expect("web exact-retry handler");
        let current = handler
            .find(".execution_retry_claim_is_current(")
            .expect("preflight generation read");
        let release = handler
            .find("drop(_claim_guard);")
            .expect("non-reentrant lock release");
        let lifecycle = handler
            .find(".retry_exact_sleeping_execution(")
            .expect("Artifact retry lifecycle");
        assert!(current < release && release < lifecycle);
        let lifecycle_call = handler[lifecycle..]
            .split("execution_retry_started")
            .next()
            .expect("exact retry arguments before started marker");
        assert!(
            lifecycle_call.contains("claimed_until"),
            "the lifecycle must carry the preflight lease token to its locked admission"
        );
    }

    /// A resume that finds no pause (a retried click after the first resume
    /// consumed it) finalizes a possibly-orphaned execution. The finalizer
    /// takes the exact execution fence for itself, and the handler already
    /// holds that fence: the in-process stripe is a plain tokio mutex, so the
    /// handler must release its own before the call. Live, the re-acquire
    /// parked forever and the resumed loop's next pause could never publish
    /// its terminal receipt behind it.
    #[test]
    fn resume_without_a_pause_releases_its_lifecycle_fence_before_finalizing_orphans() {
        let source = include_str!("web_api.rs");
        let production = source
            .split("\n#[cfg(test)]\nmod tests {")
            .next()
            .expect("production API source");
        let handler = production
            .split("async fn resume_agentic_execution_with_scope_inner(")
            .nth(1)
            .expect("resume handler");
        let no_pause_arm = handler
            .split("V2: No pause state found for execution {} (pause_state_id")
            .nth(1)
            .and_then(|tail| tail.split("\"pause_state_gone\"").next())
            .expect("no-pause arm of the resume handler");
        let release = no_pause_arm
            .find("drop(hitl_lifecycle_exclusion);")
            .expect("the handler releases its own fence");
        let finalize = no_pause_arm
            .find(".finalize_orphaned_user_pause_by_execution_id(")
            .expect("orphan finalizer");
        assert!(
            release < finalize,
            "the fence must be released before the finalizer re-acquires it"
        );
    }

    #[test]
    fn web_exact_retry_mutations_keep_the_immutable_generation_fence() {
        let source = include_str!("web_api.rs");
        let production = source
            .split("\n#[cfg(test)]\nmod tests {")
            .next()
            .expect("production API source");
        for method in [
            ".acknowledge_execution_retry_wake(",
            ".mark_execution_retry_started(",
            ".mark_current_execution_retry_started(",
        ] {
            let call = production
                .split(method)
                .nth(1)
                .and_then(|tail| tail.split(".await").next())
                .expect("web exact-retry mutation call");
            for generation_axis in [
                "execution_retry_due_at",
                "stateless_source_segment.as_deref()",
            ] {
                assert_eq!(
                    call.matches(generation_axis).count(),
                    1,
                    "{method} must pass {generation_axis} exactly once"
                );
            }
        }
    }

    #[test]
    fn web_wake_owner_periodically_rediscovers_foreign_rows() {
        let source = include_str!("web_api.rs");
        let production = source
            .split("\n#[cfg(test)]\nmod tests {")
            .next()
            .expect("production API source");
        let wake_loop = production
            .split("// WakeUpQueue watcher: drains due entries")
            .nth(1)
            .and_then(|tail| tail.split("let due = queue").next())
            .expect("web wake owner sleep policy");
        assert!(wake_loop.contains(".min(std::time::Duration::from_secs(30))"));
    }

    #[test]
    fn web_wake_handlers_are_owned_and_drained_by_the_retained_watcher() {
        let source = include_str!("web_api.rs");
        let production = source
            .split("\n#[cfg(test)]\nmod tests {")
            .next()
            .expect("production API source");
        let wake_loop = production
            .split("// WakeUpQueue watcher: drains due entries")
            .nth(1)
            .and_then(|tail| tail.split("// Task-level cron/one-time scheduler").next())
            .expect("web wake watcher body");
        assert!(wake_loop.contains("let mut wake_handlers = tokio::task::JoinSet::new();"));
        assert_eq!(
            wake_loop.matches("wake_handlers.spawn(async move").count(),
            2,
            "both wake-handler branches must remain children of the retained watcher"
        );
        assert!(wake_loop.contains("wakeup_shutdown.cancelled() => break 'wakeup"));
        assert!(!wake_loop.contains("wake_handlers.abort_all();"));
        assert!(wake_loop.contains("while let Some(joined) = wake_handlers.join_next().await"));
        let reserve = wake_loop
            .find("reserve_dispatch_page_permits")
            .expect("handler capacity reservation");
        let claim = wake_loop
            .find(".drain_due_for_limit(")
            .expect("capacity-bounded durable claim");
        assert!(reserve < claim);
        assert!(!wake_loop[claim..].contains("acquire_dispatch_permit().await"));
        assert_eq!(
            wake_loop.matches(".renew_task_addressed_wake(").count(),
            4,
            "scheduled automation and V3 task wakes must validate before dispatch and renew in flight",
        );
        for marker in [
            "V3 task wake was superseded before dispatch",
            "scheduled wake was superseded before dispatch",
        ] {
            assert!(wake_loop.contains(marker));
        }
        assert!(wake_loop.contains(".acknowledge_scheduled_wake("));
        assert!(wake_loop.contains(".acknowledge_task_wake("));
        assert!(
            !wake_loop.contains("tokio::spawn(async move"),
            "claimed wake handlers must not escape the retained supervisor"
        );
    }

    /// `Running` means the resumed owner is still using the queue row as its
    /// durable cross-process admission receipt. Only `Settled` may ACK it.
    #[test]
    fn web_running_exact_retry_retains_its_durable_admission_row() {
        let source = include_str!("web_api.rs");
        let production = source
            .split("\n#[cfg(test)]\nmod tests {")
            .next()
            .expect("production API source");
        let running_arm = production
            .split("ExecutionRetryDisposition::Running) =>")
            .nth(1)
            .and_then(|tail| tail.split("ExecutionRetryDisposition::Started) =>").next())
            .expect("web running exact-retry arm");
        assert!(!running_arm.contains("acknowledge_execution_retry_wake"));
        assert!(running_arm.contains("cross-process admission record"));
    }

    /// Both user-answer and manual-continue flows must offer the exact inner
    /// outcome to the outer fixed-roster reducer before ordinary root
    /// settlement. A reducer error returns from that branch; it never restores
    /// the consumed source pause or falls through to a root terminal.
    #[test]
    fn pipeline_resume_endpoints_fail_closed_before_root_settlement() {
        let source = include_str!("web_api.rs");
        let production = source
            .split("\n#[cfg(test)]\nmod tests {")
            .next()
            .expect("production API source");
        assert_eq!(
            production
                .matches("continue_pipeline_after_exact_stage_outcome")
                .count(),
            2,
            "both exact resume endpoints must invoke the outer pipeline reducer"
        );
        assert!(
            production
                .matches("Ok(false) => {},\n                        Err(error) => {")
                .count()
                >= 2
        );
        assert!(production.contains("exact outer-pipeline recovery retains ownership"));
        assert!(
            production
                .matches("forget_elevation_pause_authority")
                .count()
                >= 6,
            "both success and dead-source error branches must retire protected authority"
        );
        assert!(!production.contains("pipeline outer-cursor rollback"));
        assert!(!production.contains("pipeline continue rollback"));
    }

    #[test]
    fn sleeping_execution_control_projection_is_not_a_user_pause() {
        let execution = ExecutionRun {
            waiting_state: WaitingState::Sleeping,
            ..responsibility_execution_fixture(WaitingState::Sleeping)
        };
        let response = execution_control_state_response(&execution, false, false, None);
        assert_eq!(response.waiting_state, "sleeping");
        assert!(!response.can_pause);
        assert!(!response.can_resume);
        assert!(response.can_cancel);
        assert!(direct_execution_block_reason(&WaitingState::Sleeping).is_some());
        assert!(direct_execution_block_reason(&WaitingState::Runnable)
            .is_some_and(|reason| reason.contains("typed recovery authority")));
        for terminal in [
            WaitingState::Completed,
            WaitingState::Cancelled,
            WaitingState::Failed,
        ] {
            assert!(
                direct_execution_block_reason(&terminal)
                    .is_some_and(|reason| reason.contains("new execution id")),
                "terminal direct rerun must conflict before detached launch"
            );
        }
    }

