    /// A canonical correlation id posted as the pause selector is split into
    /// the storage key every lookup runs on and the ask the answer names; a
    /// bare key passes through and names no ask. The execution id parsed off
    /// the selector is unaffected by the ask suffix.
    #[test]
    fn a_canonical_correlation_id_selects_by_key_and_names_the_ask() {
        let selector = |pause_state_id: &str| {
            web::Json(AgenticResumeRequest {
                pause_state_id: Some(pause_state_id.to_string()),
                plan_id: None,
                step_id: None,
                input_type: "password".to_string(),
                value: AgenticResumeValue::Password {
                    value: "x".to_string(),
                },
                agent_id: None,
                goal_id: None,
                cycle_id: None,
            })
        };
        let (req, ask) =
            split_ask_from_pause_selector(selector("exec-1:direct-abc:direct-step-1~0123456789ab"));
        assert_eq!(
            req.pause_state_id.as_deref(),
            Some("exec-1:direct-abc:direct-step-1")
        );
        assert_eq!(ask.as_deref(), Some("0123456789ab"));
        assert_eq!(
            canonical_agentic_resume_execution_id(
                None,
                Some("exec-1:direct-abc:direct-step-1~0123456789ab")
            ),
            "exec-1"
        );
        assert_eq!(
            bare_pause_storage_key("agent:pa:goal-1:cycle-1~0123456789ab"),
            "agent:pa:goal-1:cycle-1"
        );

        let (req, ask) = split_ask_from_pause_selector(selector("exec-1:direct-abc:direct-step-1"));
        assert_eq!(
            req.pause_state_id.as_deref(),
            Some("exec-1:direct-abc:direct-step-1")
        );
        assert!(ask.is_none());
    }

