    fn execution_control_state_uses_runtime_capabilities_not_task_status() {
        let running = responsibility_execution_fixture(WaitingState::Executing);
        let state = execution_control_state_response(&running, true, false, None);
        assert!(state.can_pause);
        assert!(state.can_steer);
        assert!(state.can_cancel);
        assert!(!state.can_resume);

        let orphaned = execution_control_state_response(&running, false, false, None);
        assert!(!orphaned.can_pause);
        assert!(!orphaned.can_steer);
        assert!(orphaned.can_cancel);

        let waiting = responsibility_execution_fixture(WaitingState::WaitingUser);
        let state = execution_control_state_response(
            &waiting,
            false,
            false,
            Some("user_input".to_string()),
        );
        assert!(!state.can_pause);
        assert!(!state.can_resume);
        assert!(!state.can_steer);
        assert!(state.can_cancel);
    }

    #[test]
    fn execution_control_state_only_resumes_valid_manual_pauses() {
        let mut executing_pause = responsibility_execution_fixture(WaitingState::Paused);
        executing_pause.paused_from_state = Some(WaitingState::Executing);
        let settling = execution_control_state_response(
            &executing_pause,
            false,
            false,
            Some("manual".to_string()),
        );
        assert!(!settling.can_resume);
        assert!(!settling.can_steer);

        let durable = execution_control_state_response(
            &executing_pause,
            false,
            true,
            Some("manual".to_string()),
        );
        assert!(durable.can_resume);
        assert!(!durable.can_pause);

        let mut waiting_pause = responsibility_execution_fixture(WaitingState::Paused);
        waiting_pause.paused_from_state = Some(WaitingState::WaitingUser);
        let state = execution_control_state_response(
            &waiting_pause,
            false,
            false,
            Some("manual".to_string()),
        );
        assert!(state.can_resume);

        let completed = responsibility_execution_fixture(WaitingState::Completed);
        let state = execution_control_state_response(&completed, false, false, None);
        assert!(!state.can_pause);
        assert!(!state.can_resume);
        assert!(!state.can_steer);
        assert!(!state.can_cancel);
    }

    #[tokio::test]
    async fn execution_control_lookup_requires_matching_explicit_scope() {
        let tmp = tempfile::TempDir::new().expect("temporary API root");
        let (api, _receiver) = proposal_api_with_broadcaster(tmp.path());
        let execution_id = "scoped-control-execution";
        ensure_proposal_test_task_workspace(
            &api,
            TEST_PRINCIPAL,
            TEST_WORKSPACE,
            "scoped-control-task",
        )
        .await;
        api.orchestrator()
            .create_execution_with_id(
                TEST_PRINCIPAL,
                TEST_WORKSPACE,
                Some("Scoped control execution".to_string()),
                magician::magician_v2::chat::DEFAULT_AGENT_ID,
                execution_id,
                Some("scoped-control-task".to_string()),
                Some(execution_id.to_string()),
            )
            .await
            .expect("scoped test execution should persist");

        let (_, resolved) = api
            .resolve_scoped_execution_control(&scoped_request(), execution_id)
            .await
            .expect("matching scope should resolve the execution");
        assert_eq!(resolved.id, execution_id);

        let response = api
            .get_execution_control_state(
                &scoped_request(),
                web::Path::from(execution_id.to_string()),
            )
            .await
            .expect("matching scope should load control state");
        assert_eq!(response.status(), StatusCode::OK);
        let body: serde_json::Value = serde_json::from_slice(
            &to_bytes(response.into_body())
                .await
                .expect("control state response body"),
        )
        .expect("control state response JSON");
        assert_eq!(body["execution_id"], execution_id);
        assert_eq!(body["can_pause"], false);
        assert_eq!(body["can_steer"], false);
        assert_eq!(body["can_cancel"], true);

        let wrong_scope = TestRequest::default()
            .insert_header(("X-Principal", "another-principal"))
            .insert_header(("X-Workspace", TEST_WORKSPACE))
            .to_http_request();
        let response = api
            .resolve_scoped_execution_control(&wrong_scope, execution_id)
            .await
            .expect_err("cross-scope control lookup must be concealed");
        assert_eq!(response.status(), StatusCode::NOT_FOUND);

        let response = api
            .resolve_scoped_execution_control(
                &TestRequest::default().to_http_request(),
                execution_id,
            )
            .await
            .expect_err("control lookup must not default a missing scope");
        assert_eq!(response.status(), StatusCode::BAD_REQUEST);
    }

    async fn create_http_control_execution(api: &MagicianV2Api, execution_id: &str) {
        let task_id = format!("task-{execution_id}");
        ensure_proposal_test_task_workspace(api, TEST_PRINCIPAL, TEST_WORKSPACE, &task_id).await;
        // The scope is already sealed by `proposal_api_with_broadcaster`, which
        // every caller of this helper builds its api from. Sealing again here
        // is not idempotent across deployment ids — a second seal under a
        // different one is refused with "legacy writers were already retired by
        // deployment …", which is the guard working as intended.
        api.orchestrator()
            .create_execution_with_id(
                TEST_PRINCIPAL,
                TEST_WORKSPACE,
                Some("HTTP control execution".to_string()),
                magician::magician_v2::chat::DEFAULT_AGENT_ID,
                execution_id,
                Some(task_id),
                Some(execution_id.to_string()),
            )
            .await
            .expect("control execution should persist");
    }

    async fn execution_control_response_json(response: HttpResponse) -> serde_json::Value {
        serde_json::from_slice(
            &to_bytes(response.into_body())
                .await
                .expect("HTTP response body"),
        )
        .expect("HTTP response JSON")
    }

