    #[tokio::test]
    async fn legacy_paused_mutations_require_scope_before_consuming_pause() {
        let tmp = tempfile::TempDir::new().expect("temporary API root");
        let (api, _receiver) = proposal_api_with_broadcaster(tmp.path());
        let execution_id = "legacy-paused-control-scope";
        create_http_control_execution(&api, execution_id).await;

        let prompt_store = magician::magician_v2::prompts::JsonPromptStorage::with_default_config()
            .expect("prompt store");
        let prompt_manager = Arc::new(magician::magician_v2::prompts::PromptManager::new(
            Arc::new(prompt_store),
        ));
        let executors = magician::magician_v2::execution::agentic::ActionExecutors::new(
            test_noop_llm_service(),
            prompt_manager,
        );
        let pause = FullPauseData::new(
            AgenticPauseState::new(
                1,
                "goal",
                "criteria",
                EnvironmentState::Shell(ShellState::default()),
                "history",
                40,
                1,
            )
            .with_observability(execution_id, "plan-1", "step-1")
            .with_scope(TEST_PRINCIPAL, TEST_WORKSPACE),
            UserInputType::Confirmation {
                confirm_label: Some("Resume".to_string()),
                deny_label: Some("Cancel".to_string()),
                destructive: false,
            },
            executors,
            Some("Paused".to_string()),
            Some("Continue".to_string()),
        )
        .with_pause_kind(ExecutionPauseKind::Manual);
        let pause_key = api.full_pause_store().store(pause);
        let wrong_scope = scoped_request_for("another-principal", TEST_WORKSPACE);

        let continue_response = api
            .continue_agentic_execution(
                &wrong_scope,
                web::Path::from(execution_id.to_string()),
                web::Json(AgenticContinueRequest {
                    pause_state_id: Some(pause_key.clone()),
                    plan_id: None,
                    step_id: None,
                    agent_id: None,
                    goal_id: None,
                    cycle_id: None,
                    guidance: None,
                }),
            )
            .await
            .expect("cross-scope continue response");
        assert_eq!(continue_response.status(), StatusCode::NOT_FOUND);
        assert_eq!(
            api.full_pause_store()
                .get_pending_for_execution(execution_id)
                .len(),
            1,
            "authorization must happen before continue takes the pause"
        );

        let cancel_response = api
            .cancel_paused_execution(
                &wrong_scope,
                web::Path::from(execution_id.to_string()),
                Some(web::Json(AgenticCancelRequest {
                    pause_state_id: Some(pause_key),
                    plan_id: None,
                    step_id: None,
                    agent_id: None,
                    goal_id: None,
                    cycle_id: None,
                })),
            )
            .await
            .expect("cross-scope paused cancel response");
        assert_eq!(cancel_response.status(), StatusCode::NOT_FOUND);
        assert_eq!(
            api.full_pause_store()
                .get_pending_for_execution(execution_id)
                .len(),
            1,
            "authorization must happen before cancel takes the pause"
        );
    }

    #[test]
    fn flatten_user_knowledge_preserves_delete_paths_for_supported_shapes() {
        let knowledge = serde_json::json!({
            "preferences": [
                {
                    "key": "pref.tea",
                    "confidence": 0.91,
                    "source_type": "synthesis",
                    "target_tier": "preferences",
                    "rationale": "Repeated preference",
                    "value": { "title": "Tea" }
                }
            ],
            "workflows": {
                "promotions": [
                    {
                        "source_id": "task-1",
                        "confidence": 0.72,
                        "source_type": "manual",
                        "value": { "summary": "Open inbox first" }
                    }
                ],
                "skipped": [
                    {
                        "source_id": "task-2",
                        "reason": "duplicate"
                    }
                ]
            }
        });

        let (promotions, skips) = flatten_user_knowledge(&knowledge);

        assert_eq!(promotions.len(), 2);
        assert_eq!(promotions[0].key, "pref.tea");
        assert_eq!(promotions[0].delete_path, "preferences.0");
        assert_eq!(promotions[1].key, "task-1");
        assert_eq!(promotions[1].target_tier, "workflows");
        assert_eq!(promotions[1].delete_path, "workflows.promotions.0");
        assert_eq!(skips.len(), 1);
        assert_eq!(skips[0].source_id, "task-2");
        assert_eq!(skips[0].delete_path, "workflows.skipped.0");
    }

