    #[test]
    fn a_client_never_names_the_parent_engine() {
        let routing = OperationRoutingOverrides {
            operations: std::collections::BTreeMap::from([(
                "custom_operation".to_string(),
                OperationRoutingEndpoint::new("anthropic", "claude-sonnet-4-6").expect("endpoint"),
            )]),
            ..OperationRoutingOverrides::default()
        }
        .with_parent_engine(Some("grok".to_string()));
        assert_eq!(routing.parent_engine.as_deref(), Some("grok"));

        let admitted = client_llm_routing_overrides(Some(&routing)).expect("endpoints kept");
        assert_eq!(admitted.parent_engine, None);
        assert!(admitted.operations.contains_key("custom_operation"));

        let parent_only =
            OperationRoutingOverrides::default().with_parent_engine(Some("grok".to_string()));
        assert_eq!(
            client_llm_routing_overrides(Some(&parent_only))
                .and_then(OperationRoutingOverrides::normalized),
            None,
            "a parent alone leaves the run with no overrides at all"
        );
        assert_eq!(client_llm_routing_overrides(None), None);
    }

