    #[test]
    fn staged_hitl_admission_precedes_every_mutating_resolution_path() {
        let source = include_str!("web_api.rs");
        let approval_start = source
            .find("pub async fn resolve_approval(")
            .expect("approval endpoint");
        let approval_end = source[approval_start..]
            .find("pub async fn create_proposal(")
            .map(|offset| approval_start + offset)
            .expect("approval endpoint end");
        let approval_source = &source[approval_start..approval_end];
        let approval_guard = approval_source
            .find("acquire_hitl_lifecycle_mutation_admission")
            .expect("approval held lifecycle admission guard");
        let approval_mutation = approval_source
            .find(".resolve_with_outcome(\n                &approval_id")
            .expect("approval resolution mutation");
        assert!(approval_guard < approval_mutation);

        let diff_start = source
            .find("\"diff_approval\" => {")
            .expect("diff-approval dispatch");
        let diff_end = source[diff_start..]
            .find("source if is_agentic_runtime_hitl_source(source)")
            .map(|offset| diff_start + offset)
            .expect("diff-approval dispatch end");
        let diff_source = &source[diff_start..diff_end];
        let diff_guard = diff_source
            .find("acquire_execution_lifecycle_mutation_admission")
            .expect("diff-approval held execution admission guard");
        let diff_mutation = diff_source
            .find("let resolution_reason = match selected.as_str()")
            .expect("diff-approval mutation dispatch");
        let diff_resolution = diff_source
            .find("source: \"diff_approval\".to_string(),\n                        outcome: \"responded\"")
            .expect("diff-approval HitlResolved publication");
        assert!(diff_guard < diff_mutation);
        assert!(diff_guard < diff_resolution);

        let discovery_start = source
            .find("pub async fn get_pause_state(")
            .expect("pause discovery endpoint");
        let discovery_source = &source[discovery_start..];
        let pause_discovery = discovery_source
            .find("Pause-state discovery could not validate durable admission metadata")
            .expect("pause discovery staged-admission guard");
        let public_pause_projection = discovery_source
            .find("let all_pending = self\n            .full_pause_store\n            .get_pending_for_execution")
            .expect("public pause projection");
        assert!(pause_discovery < public_pause_projection);

        for (endpoint, next_endpoint) in [
            ("pub async fn delete_execution(", "pub async fn list_turns("),
            ("pub async fn cancel_processing(", "pub async fn get_mode("),
            (
                "pub async fn cancel_active_execution(",
                "pub async fn get_observation_screenshot(",
            ),
        ] {
            let start = source.find(endpoint).expect("cancellation endpoint");
            let end = source[start..]
                .find(next_endpoint)
                .map(|offset| start + offset)
                .unwrap_or(source.len());
            let endpoint_source = &source[start..end];
            let scope_guard = endpoint_source
                .find("resolve_scoped_execution_control")
                .expect("exact scoped execution authority");
            let cancellation = endpoint_source
                .find(".cancel_execution_tree(&execution_id)")
                .expect("internally fenced execution-tree cancellation");
            assert!(scope_guard < cancellation);
        }

        let delete_start = source
            .find("pub async fn delete_execution(")
            .expect("delete endpoint");
        let delete_end = source[delete_start..]
            .find("pub async fn list_turns(")
            .map(|offset| delete_start + offset)
            .expect("delete endpoint end");
        let delete_source = &source[delete_start..delete_end];
        let delete_cancel = delete_source
            .find(".cancel_execution_tree(&execution_id)")
            .expect("delete cancellation settlement");
        let delete_mutation = delete_source
            .find(".delete_execution(&execution_id)")
            .expect("execution deletion mutation");
        assert!(delete_cancel < delete_mutation);

        let steer_start = source
            .find("pub async fn steer_processing(")
            .expect("steer endpoint");
        let steer_end = source[steer_start..]
            .find("pub async fn cancel_processing(")
            .map(|offset| steer_start + offset)
            .expect("steer endpoint end");
        let steer_source = &source[steer_start..steer_end];
        let steer_guard = steer_source
            .find("acquire_execution_lifecycle_mutation_admission")
            .expect("steer held execution admission guard");
        let steer_mutation = steer_source
            .find(".steer_execution(&execution_id, &body.message)")
            .expect("steer mutation");
        assert!(steer_guard < steer_mutation);

        let delete_agent_start = source
            .find("pub async fn delete_agent_definition(")
            .expect("agent deletion endpoint");
        let delete_agent_end = source[delete_agent_start..]
            .find("pub async fn set_primary_agent(")
            .map(|offset| delete_agent_start + offset)
            .expect("agent deletion endpoint end");
        let delete_agent_source = &source[delete_agent_start..delete_agent_end];
        let delete_agent_guard = delete_agent_source
            .find("acquire_agent_lifecycle_mutation_admission")
            .expect("agent deletion held lifecycle admission guard");
        let delete_agent_mutation = delete_agent_source
            .find("delete_agent_definition_controlled_with_store")
            .expect("agent definition mutation");
        assert!(delete_agent_guard < delete_agent_mutation);

        let generic_agent_cancel = source
            .split("async fn cancel_active_agent_cycles(")
            .nth(1)
            .and_then(|tail| tail.split("struct HarnessRuntimeStopSummary").next())
            .expect("generic active-cycle cancellation helper");
        let generic_cancel_guard = generic_agent_cancel
            .find("admitted_execution_ids")
            .expect("generic cancellation requires a held agent admission snapshot");
        let generic_cancel_mutation = generic_agent_cancel
            .find("cancel_execution_with_retries")
            .expect("generic cancellation mutation");
        assert!(generic_cancel_guard < generic_cancel_mutation);

        let resume_start = source
            .find("async fn resume_agentic_execution_with_scope_inner(")
            .expect("agentic resume implementation");
        let resume_end = source[resume_start..]
            .find("pub async fn get_pause_state(")
            .map(|offset| resume_start + offset)
            .expect("agentic resume implementation end");
        let resume_source = &source[resume_start..resume_end];
        let resume_guard = resume_source
            .find("acquire_execution_lifecycle_mutation_admission")
            .expect("agentic resume held execution admission");
        let resume_take = resume_source
            .find(".take_pause_for_request(")
            .expect("agentic resume destructive pause take");
        let resume_guard_drop = resume_source
            .find("drop(hitl_lifecycle_exclusion)")
            .expect("agentic resume releases admission before running");
        let resume_dispatch = resume_source
            .find("execute_agentically_resume_with_validation(")
            .expect("agentic resume execution dispatch");
        assert!(resume_guard < resume_take);
        assert!(resume_take < resume_guard_drop);
        assert!(resume_guard_drop < resume_dispatch);

        let continue_start = source
            .find("pub async fn continue_agentic_execution(")
            .expect("agentic continue implementation");
        let continue_end = source[continue_start..]
            .find("pub async fn cancel_paused_execution(")
            .map(|offset| continue_start + offset)
            .expect("agentic continue implementation end");
        let continue_source = &source[continue_start..continue_end];
        let continue_guard = continue_source
            .find("acquire_execution_lifecycle_mutation_admission")
            .expect("agentic continue held execution admission");
        let continue_take = continue_source
            .find(".take_pause_for_request(")
            .expect("agentic continue destructive pause take");
        let continue_guard_drop = continue_source
            .rfind("drop(continue_lifecycle_exclusion)")
            .expect("agentic continue releases admission before dispatch");
        let continue_dispatch = continue_source
            .find("spawn_execution_job(move || async move")
            .expect("agentic continue execution dispatch");
        assert!(continue_guard < continue_take);
        assert!(continue_take < continue_guard_drop);
        assert!(continue_guard_drop < continue_dispatch);

        let trigger_start = source
            .find("pub(crate) async fn trigger_agent_controlled(")
            .expect("manual trigger admission");
        let trigger_end = source[trigger_start..]
            .find("pub(crate) async fn manual_trigger_agent_controlled(")
            .map(|offset| trigger_start + offset)
            .expect("manual trigger admission end");
        let trigger_source = &source[trigger_start..trigger_end];
        let trigger_guard = trigger_source
            .find("acquire_agent_dispatch_lifecycle_exclusion")
            .expect("manual trigger durable agent fence");
        let trigger_reservation = trigger_source
            .find("prepare_manual_trigger_with_store")
            .expect("manual trigger reservation");
        let trigger_provision = trigger_source
            .find("ensure_dispatch_task_backed_root")
            .expect("manual trigger execution provisioning");
        assert!(trigger_guard < trigger_reservation);
        assert!(trigger_guard < trigger_provision);

        let scheduled_start = source
            .find("async fn dispatch_scheduled_trigger(")
            .expect("scheduled trigger admission");
        let scheduled_end = source[scheduled_start..]
            .find("async fn resolve_scheduled_wake_target(")
            .map(|offset| scheduled_start + offset)
            .expect("scheduled trigger admission end");
        let scheduled_source = &source[scheduled_start..scheduled_end];
        let scheduled_guard = scheduled_source
            .find("acquire_agent_dispatch_lifecycle_exclusion")
            .expect("scheduled trigger durable agent fence");
        let scheduled_provision = scheduled_source
            .find("ensure_dispatch_task_backed_root")
            .expect("scheduled trigger execution provisioning");
        assert!(scheduled_guard < scheduled_provision);
        assert!(
            scheduled_source
                .matches("drop(_agent_lifecycle_exclusion)")
                .count()
                >= 4,
            "every scheduled promotion re-entry must release its non-reentrant agent fence"
        );

        let promoted_start = source
            .find("async fn launch_manual_trigger_dispatch(")
            .expect("promoted trigger admission");
        let promoted_end = source[promoted_start..]
            .find("async fn cancel_execution_with_retries(")
            .map(|offset| promoted_start + offset)
            .expect("promoted trigger admission end");
        let promoted_source = &source[promoted_start..promoted_end];
        let promoted_guard = promoted_source
            .find("acquire_agent_dispatch_lifecycle_exclusion")
            .expect("promoted trigger durable agent fence");
        let promoted_provision = promoted_source
            .find("ensure_dispatch_task_backed_root")
            .expect("promoted trigger execution provisioning");
        assert!(promoted_guard < promoted_provision);

        let direct_start = source
            .find("pub fn create_execution<'a>(")
            .expect("direct execution admission");
        let direct_end = source[direct_start..]
            .find("pub async fn list_executions(")
            .map(|offset| direct_start + offset)
            .expect("direct execution admission end");
        let direct_source = &source[direct_start..direct_end];
        let direct_guard = direct_source
            .find("acquire_agent_dispatch_lifecycle_exclusion")
            .expect("direct execution durable agent fence");
        let shell_provision = direct_source
            .find("create_task_backed_execution_shell")
            .expect("non-activating execution shell provisioning");
        let durable_accept = direct_source
            .find("accept_and_launch_runtime_request")
            .expect("durable accepted-launch handoff");
        assert!(direct_guard < shell_provision);
        assert!(shell_provision < durable_accept);
        assert!(!direct_source.contains("create_task_backed_direct_root_run_under_work"));
    }

    #[test]
