    fn store_scoped_approval_pause(
        store: &Arc<FullPauseStore>,
        execution_id: &str,
        principal: &str,
        workspace: &str,
    ) {
        let prompt_store =
            magician::magician_v2::prompts::JsonPromptStorage::with_default_config().unwrap();
        let prompt_manager = Arc::new(magician::magician_v2::prompts::PromptManager::new(
            Arc::new(prompt_store),
        ));
        let executors = magician::magician_v2::execution::agentic::ActionExecutors::new(
            test_noop_llm_service(),
            prompt_manager,
        );
        let pause_state = AgenticPauseState::new(
            1,
            "goal",
            "criteria",
            EnvironmentState::Shell(ShellState::default()),
            "history",
            40,
            1,
        )
        .with_observability(execution_id, "plan-1", "step-1")
        .with_agent_routing("agent-a", "goal-a", "cycle-7")
        .with_scope(principal, workspace)
        .with_approval_rules(vec![magician::magician_v2::agents::types::ApprovalRule {
            tool: "orchestrator".to_string(),
            action: magician::magician_v2::agents::types::ActionPattern::Single(
                "delegate_to_agent".to_string(),
            ),
            when: None,
            ttl_secs: None,
        }]);
        store.store(FullPauseData::new(
            pause_state,
            UserInputType::Confirmation {
                confirm_label: None,
                deny_label: None,
                destructive: false,
            },
            executors,
            Some("Continue?".to_string()),
            None,
        ));
    }

