    #[test]
    fn tampered_elevation_pause_is_rejected_before_any_restore_can_remint_authority() {
        // Minimal unit-test boots do not construct AgentApiServices, which is
        // the production installer for the process authority. Install-or-get
        // the canonical instance before staging so this test exercises the
        // real stage/verify boundary instead of depending on test order.
        let _authority = magician::magician_v2::execution::trusted_store::install_process_authority(
            Arc::new(magician::magician_v2::execution::trusted_store::TrustAuthority::new()),
        );
        let store = Arc::new(FullPauseStore::new());
        store_scoped_approval_pause(
            &store,
            "exec-tampered-authority",
            TEST_PRINCIPAL,
            TEST_WORKSPACE,
        );
        let pending = store.get_pending_for_execution("exec-tampered-authority");
        let key = pending.first().expect("pending pause").key.clone();
        let mut pause = store.take(&key).expect("pause data");
        assert!(verify_elevation_pause_authority(&pause).is_ok());

        pause
            .pause_state
            .approval_rules
            .push(magician::magician_v2::agents::types::ApprovalRule {
                tool: "shell".to_string(),
                action: magician::magician_v2::agents::types::ActionPattern::Single(
                    "execute".to_string(),
                ),
                when: None,
                ttl_secs: None,
            });

        assert!(verify_elevation_pause_authority(&pause)
            .expect_err("tampered pause must fail closed")
            .contains("pause_authorization_not_in_authority"));
        if let Some(authority) =
            magician::magician_v2::execution::trusted_store::process_authority()
        {
            authority.forget(&elevation_pause_authority_key(&pause));
        }
    }

    #[tokio::test]
    async fn pause_state_read_requires_and_enforces_scope() {
        let tmp = tempfile::tempdir().unwrap();
        let (api, _receiver) = proposal_api_with_broadcaster(tmp.path());
        store_scoped_approval_pause(
            api.full_pause_store(),
            "exec-scoped-read",
            TEST_PRINCIPAL,
            TEST_WORKSPACE,
        );

        let missing_scope_request = TestRequest::default().to_http_request();
        let missing_scope = api
            .get_pause_state(
                &missing_scope_request,
                web::Path::from("exec-scoped-read".to_string()),
            )
            .await
            .unwrap();
        assert_eq!(missing_scope.status(), StatusCode::BAD_REQUEST);

        let cross_scope_request = TestRequest::default()
            .insert_header(("X-Principal", "other-principal"))
            .insert_header(("X-Workspace", TEST_WORKSPACE))
            .to_http_request();
        let cross_scope = api
            .get_pause_state(
                &cross_scope_request,
                web::Path::from("exec-scoped-read".to_string()),
            )
            .await
            .unwrap();
        assert_eq!(cross_scope.status(), StatusCode::NOT_FOUND);

        let matching_scope_request = TestRequest::default()
            .insert_header(("X-Principal", TEST_PRINCIPAL))
            .insert_header(("X-Workspace", TEST_WORKSPACE))
            .to_http_request();
        let matching_scope = api
            .get_pause_state(
                &matching_scope_request,
                web::Path::from("exec-scoped-read".to_string()),
            )
            .await
            .unwrap();
        assert_eq!(matching_scope.status(), StatusCode::OK);
        let body = to_bytes(matching_scope.into_body()).await.unwrap();
        let json: serde_json::Value = serde_json::from_slice(&body).unwrap();
        assert_eq!(json["has_pause_state"], true);
        assert_eq!(json["question"], "Continue?");
    }

