    #[tokio::test]
    async fn missing_pause_resume_emits_stale_chat_resolution_when_no_pending_pause_remains() {
        let tmp = tempfile::tempdir().unwrap();
        let (api, mut events) = proposal_api_with_broadcaster(tmp.path());
        create_http_control_execution(&api, "exec-missing-pause").await;

        let response = api
            .resume_agentic_execution_with_scope(
                web::Path::from("exec-missing-pause".to_string()),
                web::Json(AgenticResumeRequest {
                    pause_state_id: Some(
                        "exec-missing-pause:plan-missing:step-missing".to_string(),
                    ),
                    plan_id: None,
                    step_id: None,
                    input_type: "external_action".to_string(),
                    value: AgenticResumeValue::ExternalActionCompleted { guidance: None },
                    agent_id: None,
                    goal_id: None,
                    cycle_id: None,
                }),
                None,
            )
            .await
            .expect("resume response");

        assert_eq!(response.status(), StatusCode::GONE);

        let event = tokio::time::timeout(Duration::from_secs(2), async {
            loop {
                match events.recv().await {
                    Ok(magician::magician_v2::realtime_events::RuntimeTransportEvent::AgenticResumed {
                        execution_id,
                        plan_id,
                        step_id,
                        input_type,
                        user_responded,
                        ..
                    }) if execution_id == "exec-missing-pause" => {
                        return (plan_id, step_id, input_type, user_responded);
                    },
                    Ok(_) => continue,
                    Err(tokio::sync::broadcast::error::RecvError::Lagged(_)) => continue,
                    Err(err) => {
                        panic!("event receiver failed while waiting for stale resolution: {err}")
                    },
                }
            }
        })
        .await
        .expect("timed out waiting for stale resolution event");

        assert_eq!(event.0, "plan-missing");
        assert_eq!(event.1, "step-missing");
        assert_eq!(event.2, RESOLVED_ELSEWHERE_INPUT_TYPE);
        assert!(event.3);
    }

    #[tokio::test]
    async fn answered_pause_resume_notice_carries_pause_state_id() {
        let tmp = tempfile::tempdir().unwrap();
        let (api, mut events) = proposal_api_with_broadcaster(tmp.path());

        let prompt_store =
            magician::magician_v2::prompts::JsonPromptStorage::with_default_config().unwrap();
        let prompt_manager = Arc::new(magician::magician_v2::prompts::PromptManager::new(
            Arc::new(prompt_store),
        ));
        let executors = magician::magician_v2::execution::agentic::ActionExecutors::new(
            test_noop_llm_service(),
            prompt_manager,
        );
        let pause_state = AgenticPauseState::new(
            7,
            "goal",
            "criteria",
            EnvironmentState::Shell(ShellState::default()),
            "history",
            40,
            1,
        )
        .with_observability("exec-answer", "plan-1", "step-1")
        .with_scope(TEST_PRINCIPAL, TEST_WORKSPACE);
        let pause_data = FullPauseData::new(
            pause_state,
            UserInputType::ExternalAction {
                instructions: "Done?".to_string(),
                done_label: Some("Mark Done".to_string()),
            },
            executors,
            Some("Done?".to_string()),
            None,
        );
        let req = AgenticResumeRequest {
            pause_state_id: Some("exec-answer:plan-1:step-1".to_string()),
            plan_id: None,
            step_id: None,
            input_type: "external_action".to_string(),
            value: AgenticResumeValue::ExternalActionCompleted { guidance: None },
            agent_id: None,
            goal_id: None,
            cycle_id: None,
        };

        emit_agentic_resumed_notice_for_answered_pause(
            &api.v2_orchestrator,
            "exec-answer",
            &pause_data,
            &req,
            "external_action",
            true,
        );

        let event = tokio::time::timeout(Duration::from_secs(2), async {
            loop {
                match events.recv().await {
                    Ok(magician::magician_v2::realtime_events::RuntimeTransportEvent::AgenticResumed {
                        execution_id,
                        pause_state_id,
                        plan_id,
                        step_id,
                        input_type,
                        resumed_from_iteration,
                        user_responded,
                        ..
                    }) if execution_id == "exec-answer" => {
                        return (
                            pause_state_id,
                            plan_id,
                            step_id,
                            input_type,
                            resumed_from_iteration,
                            user_responded,
                        );
                    },
                    Ok(_) => continue,
                    Err(tokio::sync::broadcast::error::RecvError::Lagged(_)) => continue,
                    Err(err) => panic!("event receiver failed while waiting for resume: {err}"),
                }
            }
        })
        .await
        .expect("timed out waiting for resume event");

        // The notice names the ASK, not the step: `<storage key>~<ask id>` is
        // the correlation every surface and the lifecycle journal address, and
        // a bare key would be the step's *first* question forever.
        assert_eq!(
            event.0.as_deref(),
            Some(pause_data.pause_state.hitl_correlation_id().as_str())
        );
        let (key, ask) = magician::magician_v2::execution::agentic::split_hitl_correlation_id(
            event.0.as_deref().unwrap(),
        );
        assert_eq!(key, "exec-answer:plan-1:step-1");
        assert!(
            ask.is_some_and(|ask| ask.len() == 12),
            "the ask's own id rides the notice"
        );
        assert_eq!(event.1, "plan-1");
        assert_eq!(event.2, "step-1");
        assert_eq!(event.3, "external_action");
        assert_eq!(event.4, 7);
        assert!(event.5);
    }

