    /// Executors rebuilt for a pause read back from disk carry no canonical
    /// event scope, so everything the resumed loop journals routes
    /// transport-only and its next ask never becomes a card. The resume
    /// attaches the run's registered scope, or scopes the executors from the
    /// pause's own identity when the run is not registered.
    #[tokio::test]
    async fn resumed_executors_carry_the_runs_canonical_event_scope() {
        let tmp = tempfile::tempdir().unwrap();
        let (api, _receiver) = proposal_api_with_broadcaster(tmp.path());
        let prompt_store =
            magician::magician_v2::prompts::JsonPromptStorage::with_default_config().unwrap();
        let prompt_manager = Arc::new(magician::magician_v2::prompts::PromptManager::new(
            Arc::new(prompt_store),
        ));
        let bare = || {
            magician::magician_v2::execution::agentic::ActionExecutors::new(
                test_noop_llm_service(),
                prompt_manager.clone(),
            )
        };
        let pause_state = |execution_id: &str| {
            AgenticPauseState::new(
                1,
                "goal",
                "criteria",
                EnvironmentState::Shell(ShellState::default()),
                "history",
                40,
                1,
            )
            .with_observability(execution_id, "plan-1", "step-1")
            .with_scope(TEST_PRINCIPAL, TEST_WORKSPACE)
            .with_task_execution_context(
                Some("task-scoped".to_string()),
                Some(execution_id.to_string()),
                None,
            )
        };

        // Registered run: the registry's scope, ui thread included.
        api.orchestrator().register_runtime_canonical_event_scope(
            magician::magician_v2::artifact_v2::events::CanonicalEventScope {
                principal: TEST_PRINCIPAL.to_string(),
                workspace: TEST_WORKSPACE.to_string(),
                task_id: "task-scoped".to_string(),
                execution_id: "exec-deleg-registered".to_string(),
                ui_thread_id: "thread-1".to_string(),
            },
        );
        let scoped = api
            .with_canonical_event_scope_for_resume(bare(), &pause_state("exec-deleg-registered"));
        let scope = scoped
            .canonical_event_scope
            .as_ref()
            .expect("registered scope attached");
        assert_eq!(scope.execution_id, "exec-deleg-registered");
        assert_eq!(scope.ui_thread_id, "thread-1");

        // Unregistered run (a cold process): scoped from the pause itself.
        let scoped =
            api.with_canonical_event_scope_for_resume(bare(), &pause_state("exec-deleg-cold"));
        let scope = scoped
            .canonical_event_scope
            .as_ref()
            .expect("pause-derived scope attached");
        assert_eq!(scope.execution_id, "exec-deleg-cold");
        assert_eq!(scope.task_id, "task-scoped");
        assert_eq!(scope.principal, TEST_PRINCIPAL);

        // The secret store the answered password is registered in: attached
        // from the scope's resolver when the rebuilt executors have none,
        // kept when they do.
        assert!(bare().secret_store.is_none());
        let with_store =
            api.with_scoped_secret_store_for_resume(bare(), &pause_state("exec-deleg-cold"));
        assert!(
            with_store.secret_store.is_some(),
            "resumed executors must carry the scope's secret store"
        );

        // Executors that already carry a scope keep it.
        let own = bare().with_canonical_event_scope(
            magician::magician_v2::artifact_v2::events::CanonicalEventScope {
                principal: TEST_PRINCIPAL.to_string(),
                workspace: TEST_WORKSPACE.to_string(),
                task_id: "task-own".to_string(),
                execution_id: "exec-deleg-registered".to_string(),
                ui_thread_id: "thread-own".to_string(),
            },
        );
        let kept =
            api.with_canonical_event_scope_for_resume(own, &pause_state("exec-deleg-registered"));
        assert_eq!(
            kept.canonical_event_scope
                .as_ref()
                .map(|s| s.task_id.as_str()),
            Some("task-own")
        );
    }

    #[tokio::test]
    async fn resume_agentic_execution_persists_task_backed_failure_on_confirmation_reject() {
        Box::pin(assert_task_backed_confirmation_reject_is_persisted()).await;
    }

    async fn assert_task_backed_confirmation_reject_is_persisted() {
        let tmp = tempfile::tempdir().unwrap();
        let (api, _receiver) = proposal_api_with_broadcaster(tmp.path());
        let artifact_v2_service = api
            .agent_api
            .runtime
            .artifact_v2_service()
            .expect("test V3 service should be wired");

        let (task_id, execution_id, runtime_execution_id) = create_task_backed_direct_root_run(
            artifact_v2_service.as_ref(),
            &api.v2_orchestrator,
            TEST_PRINCIPAL,
            TEST_WORKSPACE,
            "general",
            Some("Resume reject target"),
            "Pause and reject confirmation",
            magician::magician_v2::chat::DEFAULT_AGENT_ID,
            magician::magician_v2::storage::TaskCreatedBy::User,
            false,
            false,
        )
        .await
        .expect("task-backed root run should bootstrap");

        api.v2_orchestrator
            .set_execution_status_with_side_effects(
                &runtime_execution_id,
                WaitingState::WaitingUser,
                "test setup pause",
            )
            .await
            .expect("execution should enter waiting state");

        let prompt_store =
            magician::magician_v2::prompts::JsonPromptStorage::with_default_config().unwrap();
        let prompt_manager = Arc::new(magician::magician_v2::prompts::PromptManager::new(
            Arc::new(prompt_store),
        ));
        let executors = magician::magician_v2::execution::agentic::ActionExecutors::new(
            test_noop_llm_service(),
            prompt_manager,
        );
        let pause_state = AgenticPauseState::new(
            1,
            "goal",
            "criteria",
            EnvironmentState::Shell(ShellState::default()),
            "history",
            40,
            1,
        )
        .with_observability(&runtime_execution_id, "plan-1", "step-1")
        .with_scope(TEST_PRINCIPAL, TEST_WORKSPACE)
        .with_task_execution_context(
            Some(task_id.clone()),
            Some(runtime_execution_id.clone()),
            None,
        )
        .with_root_execution_id(Some(runtime_execution_id.clone()));
        let pause_data = FullPauseData::new(
            pause_state,
            UserInputType::Confirmation {
                confirm_label: Some("Proceed".to_string()),
                deny_label: Some("Cancel".to_string()),
                destructive: false,
            },
            executors,
            Some("Proceed with the action?".to_string()),
            None,
        );
        let pause_key = api.full_pause_store().store(pause_data);

        let response = api
            .resume_agentic_execution_with_scope(
                web::Path::from(runtime_execution_id.clone()),
                web::Json(AgenticResumeRequest {
                    pause_state_id: Some(pause_key),
                    plan_id: None,
                    step_id: None,
                    input_type: "confirmation".to_string(),
                    value: AgenticResumeValue::Confirmation { confirmed: false },
                    agent_id: None,
                    goal_id: None,
                    cycle_id: None,
                }),
                Some((TEST_PRINCIPAL.to_string(), TEST_WORKSPACE.to_string())),
            )
            .await
            .expect("resume response");

        assert_eq!(response.status(), StatusCode::OK);
        let body = response_json(response).await;
        assert_eq!(body["resumed"], true);
        assert_eq!(body["status"], "failed");

        let task = artifact_v2_service
            .get_task(&scope_ref(TEST_PRINCIPAL, TEST_WORKSPACE), &task_id)
            .await
            .expect("task should reload");
        let execution = artifact_v2_service
            .get_execution(
                &scope_ref(TEST_PRINCIPAL, TEST_WORKSPACE),
                &task_id,
                &execution_id,
            )
            .await
            .expect("execution should reload");

        assert_eq!(task.state.status, "failed");
        assert_eq!(
            task.state.active_root_execution_id.as_deref(),
            Some(execution_id.as_str()),
            "Step-1 terminal persistence keeps active_root until synthesis attaches terminal outputs"
        );
        assert!(
            task.state.synthesis_pending(),
            "confirmation reject should leave task in terminal/synthesis-pending state before async finalization"
        );
        assert_eq!(execution.state.status, "failed");
    }

