    fn proposal_api_with_broadcaster(
        base_path: &std::path::Path,
    ) -> (
        MagicianV2Api,
        tokio::sync::broadcast::Receiver<
            magician::magician_v2::realtime_events::RuntimeTransportEvent,
        >,
    ) {
        static DISABLE_PROXY_ONCE: std::sync::Once = std::sync::Once::new();
        DISABLE_PROXY_ONCE.call_once(|| {
            std::env::set_var("MAGICIAN_DISABLE_SYSTEM_PROXY", "1");
        });

        let runtime_root = base_path.join("proposal_api_runtime");
        std::fs::create_dir_all(&runtime_root).expect("test should create runtime root");

        let broadcaster =
            Arc::new(magician::magician_v2::realtime_events::RuntimeTransportBroadcaster::new(64));
        let receiver = broadcaster.subscribe();

        let conversation_store: Arc<dyn magician::magician_v2::storage::V2ConversationStore> =
            Arc::new(magician::magician_v2::storage::FileV2Store::new(
                &runtime_root,
            ));
        let session_manager: Arc<dyn magician::magician_v2::ask_loop::SessionManager> = Arc::new(
            magician::magician_v2::ask_loop::ClarificationSessionManager::new(
                Arc::clone(&conversation_store),
                Arc::clone(&broadcaster),
            ),
        );

        let prompt_store = magician::magician_v2::prompts::JsonPromptStorage::with_default_config()
            .expect("default prompt storage should load");
        let prompt_manager = Arc::new(magician::magician_v2::prompts::PromptManager::new(
            Arc::new(prompt_store),
        ));

        let tool_discovery: Arc<dyn runtime_core::ToolDiscovery> = Arc::new(NullToolDiscovery);
        let tool_adapter = Arc::new(magician::magician_v2::tooling::ToolDiscoveryAdapter::new(
            tool_discovery,
        ));
        let tool_catalog: Arc<dyn runtime_core::ToolCatalog> = tool_adapter.clone();
        let tool_matching: Arc<dyn runtime_core::ToolMatching> = tool_adapter.clone();

        let runtime_config: Arc<dyn runtime_core::RuntimeConfig> =
            Arc::new(ProposalApiTestRuntimeConfig {
                storage_path: runtime_root.to_string_lossy().to_string(),
            });
        let magicutor_client = Arc::new(
            magician::magician_v2::execution::MagicutorClient::new(
                magician::magician_v2::execution::ExecutionConfig::default(),
            )
            .expect("magicutor client should construct for test"),
        );

        let services = magician::magician_v2::services::MagicianV2Services::new(
            runtime_config,
            conversation_store,
            prompt_manager,
            tool_catalog,
            tool_matching,
            None,
            session_manager,
            magicutor_client,
            Vec::new(),
            std::path::PathBuf::from("."),
            None,
        );
        let llm_service = Arc::new(
            magician::magician_v2::query_analysis::operation_llm_router::MockQueryAnalysisLLM,
        )
            as Arc<
                dyn magician::magician_v2::query_analysis::operation_llm_router::QueryAnalysisLLM,
            >;
        let orchestrator = MagicianV2Orchestrator::new_with_secret_runtime(
            services,
            llm_service,
            magician::magician_v2::secrets::in_memory_secret_runtime_bootstrap(),
        )
        .with_event_broadcaster(Arc::clone(&broadcaster))
        .initialize();

        let api = MagicianV2Api::with_shared_pause_store_and_agent_api(
            orchestrator,
            Arc::new(FullPauseStore::new()),
            test_agent_api_services(base_path),
        );
        let artifact_v2_service = Arc::new(ArtifactV2Service::with_orchestrator(
            runtime_root,
            Arc::clone(&api.v2_orchestrator),
            magician::magician_v2::gaui::MuijStorage::new(base_path.join("proposal_api_muij")),
        ));
        api.v2_orchestrator
            .set_artifact_v2_service(Arc::clone(&artifact_v2_service));
        api.agent_api
            .runtime
            .set_artifact_v2_service(artifact_v2_service);
        // A harness-built service is a cutover-complete deployment, which is the
        // ordinary state. The stateless driver is the default and the only one
        // selected implicitly, and it refuses a scope whose legacy-writer
        // cutover is unsealed — so without this a route answers 503
        // `stateless_scope_not_activated` before reaching the behaviour under
        // test. This is what a real deployment does once per scope via
        // `magician seal-stateless-loop-cutover`; reaching for
        // `MAGICIAN_EXECUTION_DRIVER=inprocess` would also turn those failures
        // green, by no longer exercising the driver production runs.
        //
        // The path is the orchestrator's own pause-state root, which is where
        // the driver looks — not the `proposal_api_runtime` directory above.
        magician::magician_v2::test_support::activate_conventional_test_scopes_sync(
            &api.orchestrator().pause_states_storage_path(),
        );
        (api, receiver)
    }

