    async fn next_agent_event_by_type(
        receiver: &mut tokio::sync::broadcast::Receiver<
            magician::magician_v2::realtime_events::RuntimeTransportEvent,
        >,
        event_type: &str,
    ) -> magician::magician_v2::realtime_events::AgentEventEnvelope {
        tokio::time::timeout(Duration::from_secs(2), async {
            loop {
                match receiver.recv().await {
                    Ok(
                        magician::magician_v2::realtime_events::RuntimeTransportEvent::AgentEvent {
                            event,
                        },
                    ) if event.event_type == event_type => return event,
                    Ok(_) => continue,
                    Err(tokio::sync::broadcast::error::RecvError::Lagged(_)) => continue,
                    Err(err) => {
                        panic!(
                            "event receiver failed while waiting for {event_type}: {}",
                            err
                        );
                    },
                }
            }
        })
        .await
        .unwrap_or_else(|_| panic!("timed out waiting for {event_type}"))
    }

    async fn next_definition_changed_event(
        receiver: &mut tokio::sync::broadcast::Receiver<
            magician::magician_v2::realtime_events::RuntimeTransportEvent,
        >,
    ) -> (String, String, String) {
        tokio::time::timeout(Duration::from_secs(2), async {
            loop {
                match receiver.recv().await {
                    Ok(
                        magician::magician_v2::realtime_events::RuntimeTransportEvent::AgentDefinitionChanged {
                            principal,
                            workspace,
                            agent_id,
                            ..
                        },
                    ) => return (principal, workspace, agent_id),
                    Ok(_) => continue,
                    Err(tokio::sync::broadcast::error::RecvError::Lagged(_)) => continue,
                    Err(err) => {
                        panic!(
                            "event receiver failed while waiting for AgentDefinitionChanged: {}",
                            err
                        );
                    },
                }
            }
        })
        .await
        .unwrap_or_else(|_| panic!("timed out waiting for AgentDefinitionChanged"))
    }

