    #[tokio::test]
    async fn create_task_backed_direct_root_run_bootstraps_task_and_execution_scope() {
        let tmp = tempfile::tempdir().unwrap();
        let (api, _receiver) = proposal_api_with_broadcaster(tmp.path());
        let artifact_v2_service = api
            .agent_api
            .runtime
            .artifact_v2_service()
            .expect("test V3 service should be wired");

        let (task_id, execution_id, runtime_execution_id) = create_task_backed_direct_root_run(
            artifact_v2_service.as_ref(),
            &api.v2_orchestrator,
            "anonymous",
            "default",
            "general",
            Some("Direct Root"),
            "Open https://example.com and report the title",
            magician::magician_v2::chat::DEFAULT_AGENT_ID,
            magician::magician_v2::storage::TaskCreatedBy::User,
            false,
            false,
        )
        .await
        .expect("task-backed root run should bootstrap");

        let task = artifact_v2_service
            .get_task(&scope_ref("anonymous", "default"), &task_id)
            .await
            .expect("task should be persisted");
        assert_eq!(
            task.manifest.lifecycle,
            magician::magician_v2::artifact_v2::models::TaskLifecycle::Persistent,
            "ordinary direct executions should remain user-visible"
        );
        assert_eq!(task.state.status, "running");
        assert_eq!(
            task.state.active_root_execution_id.as_deref(),
            Some(execution_id.as_str())
        );
        assert_eq!(
            task.state.active_root_execution_id.as_deref(),
            Some(runtime_execution_id.as_str())
        );

        let execution = api
            .v2_orchestrator
            .get_execution(&runtime_execution_id)
            .await
            .expect("execution should be persisted");
        assert_eq!(execution.task_id.as_deref(), Some(task_id.as_str()));
        assert_eq!(
            execution.root_execution_id.as_deref(),
            Some(execution_id.as_str())
        );
    }

    async fn response_json(response: HttpResponse) -> serde_json::Value {
        let bytes = to_bytes(response.into_body()).await.unwrap();
        if bytes.is_empty() {
            serde_json::Value::Null
        } else {
            serde_json::from_slice(&bytes).unwrap()
        }
    }

    #[tokio::test]
    async fn create_execution_returns_consistent_envelope_without_initial_message() {
        let tmp = tempfile::tempdir().unwrap();
        let (api, _receiver) = proposal_api_with_broadcaster(tmp.path());
        let request = actix_web::test::TestRequest::default()
            .insert_header(("X-Principal", "test-principal"))
            .insert_header(("X-Workspace", "test-workspace"))
            .to_http_request();

        let response = api
            .create_execution(
                &request,
                web::Json(CreateExecutionRequest {
                    workspace: None,
                    ui_thread_id: "general".to_string(),
                    title: Some("Envelope contract".to_string()),
                    initial_message: None,
                    skip_planning: false,
                    max_iterations: None,
                    debug: false,
                    internal: false,
                    llm_routing_overrides: None,
                    env_mode: None,
                    engagement_id: None,
                }),
            )
            .await
            .expect("create execution response");

        assert_eq!(response.status(), StatusCode::OK);
        let body = response_json(response).await;
        let execution_id = body["execution_id"]
            .as_str()
            .expect("top-level execution_id");
        assert!(
            !execution_id.is_empty(),
            "execution_id should be populated in the response envelope"
        );
        assert_eq!(body["execution"]["id"], execution_id);
        assert_eq!(body["initial_message_enqueued"], false);
        assert_eq!(body["skip_planning"], false);

        let execution = api
            .v2_orchestrator
            .get_execution(execution_id)
            .await
            .expect("execution should be persisted");
        assert!(
            execution.task_id.is_some(),
            "execution should be task-backed"
        );
        assert!(
            execution.root_execution_id.is_some(),
            "execution should carry a root execution id"
        );
    }

