    #[test]
    fn proposal_lifecycle_event_payloads_include_audit_fields() {
        assert_eq!(PROPOSAL_CREATED_EVENT_TYPE, "proposal.created");
        assert_eq!(PROPOSAL_RESOLVED_EVENT_TYPE, "proposal.resolved");

        let created_at = DateTime::parse_from_rfc3339("2026-02-23T12:34:56Z")
            .unwrap()
            .with_timezone(&Utc);
        let resolved_at = DateTime::parse_from_rfc3339("2026-02-23T12:40:00Z")
            .unwrap()
            .with_timezone(&Utc);
        let proposal = magician::magician_v2::agents::DefinitionProposal {
            proposal_id: "8bc2f888-0ef1-4f68-b96f-c7f8d31bc391".to_string(),
            agent_id: "agent-a".to_string(),
            source: "meta_agent".to_string(),
            status: ProposalStatus::Approved,
            payload: serde_json::json!({
                "reasoning": "x",
                "owner_agent_id": "ceo",
            }),
            yaml_before: "version: 1\n".to_string(),
            yaml_after: "version: 2\n".to_string(),
            created_at,
            updated_at: resolved_at,
            resolved_by: Some("reviewer".to_string()),
            resolved_at: Some(resolved_at),
            applied_version: None,
            applied_at: None,
        };

        let created_payload = proposal_created_event_payload(&proposal, "proposal_create_endpoint");
        assert_eq!(created_payload["proposal_id"], proposal.proposal_id);
        // Status is derived from the proposal object, not hardcoded.
        // The test proposal has status Approved to verify this.
        assert_eq!(created_payload["status"], "approved");
        assert_eq!(created_payload["source"], "proposal_create_endpoint");
        assert_eq!(created_payload["created_at"], created_at.to_rfc3339());
        assert_eq!(created_payload["agent_id"], "agent-a");
        assert_eq!(created_payload["proposal_source"], "meta_agent");
        assert_eq!(created_payload["owner_agent_id"], "ceo");

        let resolved_payload = proposal_resolved_event_payload(
            &proposal,
            &ProposalDecision::Approve,
            "reviewer",
            "proposal_resolve_endpoint",
        );
        assert_eq!(resolved_payload["proposal_id"], proposal.proposal_id);
        assert_eq!(resolved_payload["status"], "approved");
        assert_eq!(resolved_payload["decision"], "approved");
        assert_eq!(resolved_payload["resolved_by"], "reviewer");
        assert_eq!(resolved_payload["resolved_at"], resolved_at.to_rfc3339());
        assert_eq!(resolved_payload["source"], "proposal_resolve_endpoint");
        assert_eq!(resolved_payload["agent_id"], "agent-a");
        assert_eq!(resolved_payload["proposal_source"], "meta_agent");
        assert_eq!(resolved_payload["owner_agent_id"], "ceo");
    }

    #[tokio::test]
    async fn proposal_api_endpoints_emit_realtime_lifecycle_events() {
        let tmp = tempfile::tempdir().unwrap();
        let (api, mut events) = proposal_api_with_broadcaster(tmp.path());
        seed_proposal_test_agent(api.agent_api(), "agent-a").await;

        let request = scoped_request();
        let create_response = api
            .create_proposal(
                request,
                web::Json(sample_create_proposal_request("agent-a")),
            )
            .await
            .expect("proposal create should succeed");
        assert_eq!(create_response.status(), StatusCode::CREATED);
        let create_body = response_json(create_response).await;
        let proposal_id = create_body["proposal"]["proposal_id"]
            .as_str()
            .expect("proposal id should be present")
            .to_string();

        let created_event =
            next_agent_event_by_type(&mut events, PROPOSAL_CREATED_EVENT_TYPE).await;
        assert_eq!(created_event.agent_id, "agent-a");
        assert_eq!(created_event.payload["proposal_id"], proposal_id);
        assert_eq!(created_event.payload["status"], "pending");
        assert_eq!(created_event.payload["source"], "proposal_create_endpoint");
        assert!(created_event.payload["created_at"].as_str().is_some());

        let resolve_response = api
            .resolve_proposal(
                scoped_request(),
                web::Path::from(proposal_id.clone()),
                web::Json(ResolveProposalRequest {
                    decision: ProposalDecision::Approve,
                    channel: "reviewer".to_string(),
                }),
            )
            .await
            .expect("proposal resolve should succeed");
        assert_eq!(resolve_response.status(), StatusCode::OK);

        let resolved_event =
            next_agent_event_by_type(&mut events, PROPOSAL_RESOLVED_EVENT_TYPE).await;
        assert_eq!(resolved_event.agent_id, "agent-a");
        assert_eq!(resolved_event.payload["proposal_id"], proposal_id);
        assert_eq!(resolved_event.payload["status"], "approved");
        assert_eq!(resolved_event.payload["decision"], "approved");
        assert_eq!(resolved_event.payload["resolved_by"], "reviewer");
        assert_eq!(
            resolved_event.payload["source"],
            "proposal_resolve_endpoint"
        );
        assert!(resolved_event.payload["resolved_at"].as_str().is_some());
    }

