    #[tokio::test]
    async fn proposal_duplicate_approve_on_applied_skips_event_and_returns_applied_version() {
        // When the resolve handler is called a second time on an already-approved
        // and already-applied proposal, it should:
        // - Return 200 with the proposal including applied_version
        // - NOT re-emit a proposal.applied event (was_already_applied guard)
        let tmp = tempfile::tempdir().unwrap();
        let (api, mut events) = proposal_api_with_broadcaster(tmp.path());
        seed_proposal_test_agent(api.agent_api(), "agent-a").await;

        api.agent_api()
            .runtime()
            .upsert_definition(sample_agent_definition("agent-a", "Proposal Test Agent"))
            .await;

        let request = scoped_request();
        // Create and first-approve through the handler
        let create_response = api
            .create_proposal(
                request,
                web::Json(valid_create_proposal_request("agent-a", "Applied Once")),
            )
            .await
            .expect("create should succeed");
        let create_body = response_json(create_response).await;
        let proposal_id = create_body["proposal"]["proposal_id"]
            .as_str()
            .unwrap()
            .to_string();

        // Consume created event
        next_agent_event_by_type(&mut events, PROPOSAL_CREATED_EVENT_TYPE).await;

        // First resolve (approve + apply)
        let first_resolve = api
            .resolve_proposal(
                scoped_request(),
                web::Path::from(proposal_id.clone()),
                web::Json(ResolveProposalRequest {
                    decision: ProposalDecision::Approve,
                    channel: "reviewer".to_string(),
                }),
            )
            .await
            .expect("first resolve should succeed");
        assert_eq!(first_resolve.status(), StatusCode::OK);
        let first_body = response_json(first_resolve).await;
        assert_eq!(first_body["applied_version"], 2);
        assert!(first_body["application_error"].is_null());

        // Consume resolved + applied events from first resolve
        next_agent_event_by_type(&mut events, PROPOSAL_RESOLVED_EVENT_TYPE).await;
        next_agent_event_by_type(&mut events, PROPOSAL_APPLIED_EVENT_TYPE).await;

        // Second resolve (duplicate approve on already-applied proposal)
        let second_resolve = api
            .resolve_proposal(
                scoped_request(),
                web::Path::from(proposal_id.clone()),
                web::Json(ResolveProposalRequest {
                    decision: ProposalDecision::Approve,
                    channel: "reviewer".to_string(),
                }),
            )
            .await
            .expect("duplicate resolve should succeed");
        assert_eq!(second_resolve.status(), StatusCode::OK);
        let second_body = response_json(second_resolve).await;
        // Proposal was already applied — response should reflect that
        assert_eq!(second_body["proposal"]["applied_version"], 2);
        assert!(!second_body["resolved"].as_bool().unwrap());

        // Verify NO proposal.applied event was emitted for the duplicate
        // (give a short window for any stray events to arrive)
        let no_event = tokio::time::timeout(
            Duration::from_millis(100),
            next_agent_event_by_type(&mut events, PROPOSAL_APPLIED_EVENT_TYPE),
        )
        .await;
        assert!(
            no_event.is_err(),
            "should NOT emit proposal.applied on duplicate resolve of already-applied proposal"
        );
    }

    #[tokio::test]
    async fn proposal_handler_returns_200_with_application_error_on_invalid_yaml() {
        // When proposal application fails (e.g. invalid yaml_after), the handler
        // should still return HTTP 200 (the proposal IS resolved) but include the
        // application_error field so the UI can surface the failure.
        let tmp = tempfile::tempdir().unwrap();
        let (api, mut events) = proposal_api_with_broadcaster(tmp.path());
        seed_proposal_test_agent(api.agent_api(), "agent-a").await;

        api.agent_api()
            .runtime()
            .upsert_definition(sample_agent_definition("agent-a", "Proposal Test Agent"))
            .await;

        let request = scoped_request();
        // Create a proposal with invalid yaml_after (empty name fails validation)
        let create_response = api
            .create_proposal(
                request,
                web::Json(CreateProposalRequest {
                    agent_id: "agent-a".to_string(),
                    source: "meta_agent".to_string(),
                    payload: serde_json::json!({"reasoning": "test"}),
                    yaml_before: valid_agent_yaml("agent-a", "Original", 1),
                    yaml_after: valid_agent_yaml("agent-a", "", 1),
                }),
            )
            .await
            .expect("create should succeed");
        assert_eq!(create_response.status(), StatusCode::CREATED);
        let create_body = response_json(create_response).await;
        let proposal_id = create_body["proposal"]["proposal_id"]
            .as_str()
            .unwrap()
            .to_string();

        // Consume created event
        next_agent_event_by_type(&mut events, PROPOSAL_CREATED_EVENT_TYPE).await;

        // Approve through the handler — resolution succeeds, application fails
        let resolve_response = api
            .resolve_proposal(
                scoped_request(),
                web::Path::from(proposal_id),
                web::Json(ResolveProposalRequest {
                    decision: ProposalDecision::Approve,
                    channel: "reviewer".to_string(),
                }),
            )
            .await
            .expect("resolve should return Ok(HttpResponse)");

        // HTTP 200 — the proposal is resolved even though application failed
        assert_eq!(resolve_response.status(), StatusCode::OK);
        let body = response_json(resolve_response).await;
        assert!(body["resolved"].as_bool().unwrap());
        assert!(body["applied_version"].is_null());
        assert!(
            body["application_error"].as_str().is_some(),
            "application_error should contain the validation error"
        );

        // The resolved event should still fire (proposal WAS resolved)
        next_agent_event_by_type(&mut events, PROPOSAL_RESOLVED_EVENT_TYPE).await;

        // The applied event should NOT fire (application failed)
        let no_applied = tokio::time::timeout(
            Duration::from_millis(100),
            next_agent_event_by_type(&mut events, PROPOSAL_APPLIED_EVENT_TYPE),
        )
        .await;
        assert!(
            no_applied.is_err(),
            "should NOT emit proposal.applied when application fails"
        );

        // Definition should be unchanged at v1
        let record = api
            .agent_api()
            .definition_store
            .get_definition("agent-a")
            .await
            .unwrap()
            .expect("definition should exist");
        assert_eq!(record.version(), 1);
    }

