        let wake_path = services
            .definition_store
            .workspace_layout()
            .expect("workspace layout")
            .base_root()
            .join("wake_up_queue.json");
        let persisted_wakes = vec![magician::magician_v2::agents::wake_up_queue::WakeEntry {
            task_id: String::new(),
            principal: None,
            workspace: None,
            execution_id: Some("parent-exec-1".to_string()),
            stateless_source_segment: None,
            agent_id: None,
            goal_id: None,
            wake_at: Utc::now() + chrono::Duration::minutes(10),
            execution_retry_due_at: None,
            child_completed_generation: None,
            kind: magician::magician_v2::agents::wake_up_queue::WakeKind::ChildCompleted,
            execution_retry_started: false,
            execution_retry_claim_attempt: 0,
        }];
        std::fs::write(
            &wake_path,
            serde_json::to_string_pretty(&persisted_wakes).unwrap(),
        )
        .unwrap();

        ensure_agent_startup_hydrated(&services).await.unwrap();

