    #[tokio::test]
    async fn generic_agent_directory_and_manual_trigger_hide_surface_only_agents() {
        let tmp = tempfile::tempdir().unwrap();
        let services = test_agent_api_services(tmp.path());
        let mut ambient = sample_agent_definition("agent-a", "Alpha");
        ambient.invocation_policy = magician::magician_v2::agents::AgentInvocationPolicy::default();
        let mut loom = sample_agent_definition("brainstorm-facilitator", "Loom");
        loom.invocation_policy.discoverability =
            magician::magician_v2::agents::AgentDiscoverability::SurfaceOnly;
        loom.invocation_policy.delegation =
            magician::magician_v2::agents::AgentDelegationPolicy::None;
        loom.invocation_policy.allowed_direct_surfaces =
            vec![magician::magician_v2::agents::InvocationSurface::ThinkingMap];
        let _ = create_agent_definition_impl(&services, ambient).await;
        let _ = create_agent_definition_impl(&services, loom).await;

        let listed = list_agent_definitions_impl(&services, None).await;
        let body = response_json(listed).await;
        let ids = body["agents"]
            .as_array()
            .expect("agents")
            .iter()
            .filter_map(|entry| entry["definition"]["agent_id"].as_str())
            .collect::<Vec<_>>();
        assert_eq!(ids, vec!["agent-a"]);

        let error = prepare_manual_trigger(
            &services,
            "brainstorm-facilitator",
            ManualAgentTriggerRequest {
                goal_id: Some("generic-trigger".to_string()),
                trigger: Some("manual".to_string()),
            },
        )
        .await
        .expect_err("surface-only agent must fail before scheduler side effects");
        assert_eq!(error.status(), StatusCode::UNPROCESSABLE_ENTITY);
    }

