    #[tokio::test]
    async fn list_agent_definitions_reflects_store_and_api_mutations() {
        let tmp = tempfile::tempdir().unwrap();
        let services = test_agent_api_services(tmp.path());
        let baseline = list_agent_definitions_impl(&services, None).await;
        assert_eq!(baseline.status(), StatusCode::OK);
        let baseline_count = response_json(baseline).await["agents"]
            .as_array()
            .unwrap()
            .len();
        let _ =
            create_agent_definition_impl(&services, sample_agent_definition("agent-a", "Alpha"))
                .await;

        let listed_once = list_agent_definitions_impl(&services, None).await;
        assert_eq!(listed_once.status(), StatusCode::OK);
        let listed_once_body = response_json(listed_once).await;
        assert_eq!(
            listed_once_body["agents"].as_array().unwrap().len(),
            baseline_count + 1
        );

        // Direct store mutation should be visible on the next list call.
        services
            .definition_store
            .create_definition(sample_agent_definition("agent-b", "Bravo"))
            .await
            .unwrap();
        let direct_mutation = list_agent_definitions_impl(&services, None).await;
        assert_eq!(direct_mutation.status(), StatusCode::OK);
        let cached_body = response_json(direct_mutation).await;
        assert_eq!(
            cached_body["agents"].as_array().unwrap().len(),
            baseline_count + 2
        );

        // API mutation should keep the list coherent too.
        let _ =
            create_agent_definition_impl(&services, sample_agent_definition("agent-c", "Charlie"))
                .await;
        let refreshed = list_agent_definitions_impl(&services, None).await;
        assert_eq!(refreshed.status(), StatusCode::OK);
        let refreshed_body = response_json(refreshed).await;
        assert_eq!(
            refreshed_body["agents"].as_array().unwrap().len(),
            baseline_count + 3
        );
    }

