    #[tokio::test]
    async fn set_primary_agent_reloads_previous_primary_and_emits_updates_for_both_agents() {
        let tmp = tempfile::tempdir().unwrap();
        let (api, mut receiver) = proposal_api_with_broadcaster(tmp.path());

        let mut primary = sample_agent_definition("agent-a", "Alpha");
        primary.is_primary = true;
        let secondary = sample_agent_definition("agent-b", "Beta");

        let created_primary = create_agent_definition_impl(&api.agent_api, primary).await;
        assert_eq!(created_primary.status(), StatusCode::CREATED);
        let created_secondary = create_agent_definition_impl(&api.agent_api, secondary).await;
        assert_eq!(created_secondary.status(), StatusCode::CREATED);

        let response = api
            .set_primary_agent(web::Path::from("agent-b".to_string()), scoped_request())
            .await
            .unwrap();
        assert_eq!(response.status(), StatusCode::OK);
        let body = response_json(response).await;
        assert_eq!(body["definition"]["agent_id"], "agent-b");
        assert_eq!(body["definition"]["is_primary"], true);

        let runtime_primary = api
            .agent_api
            .runtime
            .get_definition_in_scope(TEST_PRINCIPAL, TEST_WORKSPACE, "agent-a")
            .await
            .expect("previous primary should remain loaded");
        assert!(!runtime_primary.is_primary);
        let runtime_secondary = api
            .agent_api
            .runtime
            .get_definition_in_scope(TEST_PRINCIPAL, TEST_WORKSPACE, "agent-b")
            .await
            .expect("new primary should remain loaded");
        assert!(runtime_secondary.is_primary);

        let (updated_ids, changed_ids) = tokio::time::timeout(Duration::from_secs(2), async {
            let mut updated_ids = std::collections::BTreeSet::new();
            let mut changed_ids = std::collections::BTreeSet::new();
            while updated_ids.len() < 2 || changed_ids.len() < 2 {
                match receiver.recv().await {
                    Ok(magician::magician_v2::realtime_events::RuntimeTransportEvent::AgentEvent {
                        event,
                    }) if event.event_type == "agent.updated" => {
                        updated_ids.insert(event.agent_id);
                    },
                    Ok(
                        magician::magician_v2::realtime_events::RuntimeTransportEvent::AgentDefinitionChanged {
                            agent_id,
                            ..
                        },
                    ) => {
                        changed_ids.insert(agent_id);
                    },
                    Ok(_) => continue,
                    Err(tokio::sync::broadcast::error::RecvError::Lagged(_)) => continue,
                    Err(err) => panic!("event receiver failed while waiting for set-primary events: {err}"),
                }
            }
            (updated_ids, changed_ids)
        })
        .await
        .unwrap_or_else(|_| panic!("timed out waiting for set-primary events"));

        assert_eq!(
            updated_ids.into_iter().collect::<Vec<_>>(),
            vec!["agent-a".to_string(), "agent-b".to_string()]
        );
        assert_eq!(
            changed_ids.into_iter().collect::<Vec<_>>(),
            vec!["agent-a".to_string(), "agent-b".to_string()]
        );
    }

    #[tokio::test]
    async fn if_match_roundtrip_from_get_etag_supports_success_then_conflict() {
        let tmp = tempfile::tempdir().unwrap();
        let services = test_agent_api_services(tmp.path());
        let _ =
            create_agent_definition_impl(&services, sample_agent_definition("agent-a", "Alpha"))
                .await;

        let get = get_agent_definition_impl(&services, "agent-a", None).await;
        assert_eq!(get.status(), StatusCode::OK);
        let initial_etag = get
            .headers()
            .get(header::ETAG)
            .unwrap()
            .to_str()
            .unwrap()
            .to_string();

        let initial_if_match = TestRequest::default()
            .insert_header((header::IF_MATCH, initial_etag.clone()))
            .to_http_request();
        let parsed_initial = parse_if_match_condition(&initial_if_match).unwrap();
        assert_eq!(parsed_initial, IfMatchCondition::Versions(vec![1]));

        let first_update = update_agent_definition_impl(
            &services,
            "agent-a",
            sample_agent_definition("agent-a", "Alpha v2"),
            1,
        )
        .await;
        assert_eq!(first_update.status(), StatusCode::OK);
        assert_eq!(
            first_update.headers().get(header::ETAG).unwrap(),
            header::HeaderValue::from_static("\"v2\"")
        );

        // Reusing the stale ETag from GET must conflict after the successful update.
        let stale_if_match = TestRequest::default()
            .insert_header((header::IF_MATCH, initial_etag))
            .to_http_request();
        let parsed_stale = parse_if_match_condition(&stale_if_match).unwrap();
        assert_eq!(parsed_stale, IfMatchCondition::Versions(vec![1]));

        let stale_update = update_agent_definition_impl(
            &services,
            "agent-a",
            sample_agent_definition("agent-a", "Alpha v3"),
            1,
        )
        .await;
        assert_eq!(stale_update.status(), StatusCode::PRECONDITION_FAILED);
        assert_eq!(
            stale_update.headers().get(header::ETAG).unwrap(),
            header::HeaderValue::from_static("\"v2\"")
        );
    }

    #[tokio::test]
    async fn create_conflict_reconciles_scheduler_to_persisted_definition() {
        let tmp = tempfile::tempdir().unwrap();
        let services = test_agent_api_services(tmp.path());

        let created =
            create_agent_definition_impl(&services, sample_agent_definition("agent-a", "Alpha"))
                .await;
        assert_eq!(created.status(), StatusCode::CREATED);

        // register_agent is a no-op; register the scheduler entry explicitly.
        let scheduler = services.resolve_default_scheduler().await.unwrap();
        scheduler
            .register_entry("agent-a", "g1", SchedulerTriggerRegistration::Idle)
            .await
            .unwrap();

        let conflict = create_agent_definition_impl(
            &services,
            sample_multi_goal_definition("agent-a", "Alpha duplicate"),
        )
        .await;
        assert_eq!(conflict.status(), StatusCode::CONFLICT);

        // The explicitly registered "g1" entry must survive the conflict
        // reconciliation (reconcile_scheduler_from_store calls register_agent
        // which is a no-op, so existing entries are preserved).
        assert_eq!(
            scheduler
                .allocate_trigger_seq("agent-a", "g1")
                .await
                .unwrap(),
            1
        );
        let stale = scheduler
            .allocate_trigger_seq("agent-a", "g2")
            .await
            .unwrap_err();
        assert!(matches!(stale, SchedulerError::NotRegistered { .. }));
    }

