    #[tokio::test]
    async fn parse_if_match_header_validates_expected_format() {
        let ok_request = TestRequest::default()
            .insert_header((header::IF_MATCH, "v7"))
            .to_http_request();
        assert_eq!(
            parse_if_match_condition(&ok_request).unwrap(),
            IfMatchCondition::Versions(vec![7])
        );

        let quoted_request = TestRequest::default()
            .insert_header((header::IF_MATCH, "\"v8\""))
            .to_http_request();
        assert_eq!(
            parse_if_match_condition(&quoted_request).unwrap(),
            IfMatchCondition::Versions(vec![8])
        );

        let list_request = TestRequest::default()
            .insert_header((header::IF_MATCH, "\"v1\", \"v8\""))
            .to_http_request();
        assert_eq!(
            parse_if_match_condition(&list_request).unwrap(),
            IfMatchCondition::Versions(vec![1, 8])
        );

        let wildcard_request = TestRequest::default()
            .insert_header((header::IF_MATCH, "*"))
            .to_http_request();
        assert_eq!(
            parse_if_match_condition(&wildcard_request).unwrap(),
            IfMatchCondition::Any
        );

        let missing_request = TestRequest::default().to_http_request();
        let missing_response = parse_if_match_condition(&missing_request).unwrap_err();
        assert_eq!(missing_response.status(), StatusCode::PRECONDITION_REQUIRED);

        let invalid_request = TestRequest::default()
            .insert_header((header::IF_MATCH, "abc"))
            .to_http_request();
        let invalid_response = parse_if_match_condition(&invalid_request).unwrap_err();
        assert_eq!(invalid_response.status(), StatusCode::BAD_REQUEST);

        let weak_request = TestRequest::default()
            .insert_header((header::IF_MATCH, "W/\"v7\""))
            .to_http_request();
        let weak_response = parse_if_match_condition(&weak_request).unwrap_err();
        assert_eq!(weak_response.status(), StatusCode::BAD_REQUEST);

        let malformed_quotes_request = TestRequest::default()
            .insert_header((header::IF_MATCH, "\"v7"))
            .to_http_request();
        let malformed_quotes_response =
            parse_if_match_condition(&malformed_quotes_request).unwrap_err();
        assert_eq!(malformed_quotes_response.status(), StatusCode::BAD_REQUEST);
    }

