    #[tokio::test]
    async fn derive_manual_cycle_post_execution_preserves_trust_deny_reason_in_episode_and_event() {
        let tmp = tempfile::tempdir().unwrap();
        let services = test_agent_api_services(tmp.path());
        let definition = sample_agent_definition("agent-a", "Alpha");
        let deny_reason =
            "trust policy denied action (level=reviewed, tool=file, action=write)".to_string();

        let outcome = AgenticOutcome::Failed {
            reason: deny_reason.clone(),
            last_state: default_environment_state_for_mode("file"),
            iterations_used: 1,
        };
        let now = Utc::now();
        let post = derive_manual_cycle_post_execution(
            &services,
            &definition,
            "agent-a",
            "g1",
            "manual",
            1,
            "agent-a-g1-1",
            "thread-a-1",
            now,
            now,
            &outcome,
            None,
        )
        .await
        .expect("cycle post execution should derive");

        match &post.episode_outcome {
            EpisodeOutcome::Failed { error } => assert_eq!(error, &deny_reason),
            other => panic!("expected failed episode outcome, got {other:?}"),
        }
        let failed_event = post
            .events
            .iter()
            .find(|event| event.event_type == "agent.cycle.failed")
            .expect("failed cycle event should be emitted");
        assert_eq!(failed_event.payload["evaluation"]["status"], "failed");
        assert_eq!(failed_event.payload["evaluation"]["reason"], deny_reason);
    }

