    #[tokio::test]
    async fn prepare_scheduled_trigger_dispatch_uses_trigger_scope_for_scoped_agent() {
        let tmp = tempfile::tempdir().unwrap();
        let services = test_root_agent_api_services(tmp.path());
        let agent_id = "scheduled-agent";

        let scheduled_principal = "zz-principal";
        let scheduled_workspace = "zz-workspace";
        let other_principal = "aa-principal";
        let other_workspace = "aa-workspace";

        let mut other_definition = sample_agent_definition(agent_id, "Other Scheduled Agent");
        other_definition.principal = Some(other_principal.to_string());
        other_definition.workspace = Some(other_workspace.to_string());
        services
            .resolve_definition_store(other_principal, other_workspace)
            .create_definition(other_definition)
            .await
            .expect("other scope definition should seed");

        let mut scheduled_definition = sample_agent_definition(agent_id, "Scheduled Scope Agent");
        scheduled_definition.principal = Some(scheduled_principal.to_string());
        scheduled_definition.workspace = Some(scheduled_workspace.to_string());
        services
            .resolve_definition_store(scheduled_principal, scheduled_workspace)
            .create_definition(scheduled_definition)
            .await
            .expect("scheduled scope definition should seed");

        services
            .resolve_definition_store(other_principal, other_workspace)
            .get_definition(agent_id)
            .await
            .expect("other scope definition lookup should succeed")
            .expect("agent should exist in other scope");
        services
            .resolve_definition_store(scheduled_principal, scheduled_workspace)
            .get_definition(agent_id)
            .await
            .expect("scheduled scope definition lookup should succeed")
            .expect("agent should exist in scheduled scope");

        let scheduler = services
            .resolve_scheduler(scheduled_principal, scheduled_workspace)
            .await
            .expect("scoped scheduler should resolve");
        scheduler
            .register_entry(
                agent_id,
                "scope-check",
                SchedulerTriggerRegistration::Cron {
                    schedule: "0 3 * * *".to_string(),
                    timezone: "UTC".to_string(),
                    next_run_at: Some(Utc::now() - chrono::Duration::minutes(1)),
                },
            )
            .await
            .expect("scoped cron should register");

        let scheduled = scheduler
            .collect_due_cron_triggers(Utc::now())
            .await
            .expect("due trigger collection should succeed")
            .into_iter()
            .next()
            .expect("scoped trigger should be due");

        let dispatch = prepare_scheduled_trigger_dispatch(&services, &scheduled)
            .await
            .expect("scheduled prepare should succeed")
            .expect("scheduled dispatch should be prepared");

        assert_eq!(dispatch.principal, scheduled_principal);
        assert_eq!(dispatch.workspace, scheduled_workspace);
        assert_eq!(
            dispatch.definition.principal.as_deref(),
            Some(scheduled_principal)
        );
        assert_eq!(
            dispatch.definition.workspace.as_deref(),
            Some(scheduled_workspace)
        );
    }

