    async fn requeue_scheduled_trigger_for_retry_restores_consumed_trigger_seq() {
        let tmp = tempfile::tempdir().unwrap();
        let services = test_agent_api_services(tmp.path());
        let _ =
            create_agent_definition_impl(&services, sample_agent_definition("agent-a", "Alpha"))
                .await;

        // register_agent is a no-op; register a cron entry explicitly so
        // collect_due_cron_triggers can find and consume it.
        let scheduler = services.resolve_default_scheduler().await.unwrap();
        scheduler
            .register_entry(
                "agent-a",
                "g1",
                SchedulerTriggerRegistration::Cron {
                    schedule: "0 9 * * *".to_string(),
                    timezone: "UTC".to_string(),
                    next_run_at: Some(Utc::now() - chrono::Duration::hours(1)),
                },
            )
            .await
            .unwrap();

        let due = scheduler
            .collect_due_cron_triggers(Utc::now() + chrono::Duration::days(2))
            .await
            .expect("collect_due should succeed");
        let scheduled = due
            .into_iter()
            .next()
            .expect("one trigger should be due for rollback test");
        assert_eq!(scheduled.trigger_seq, 1);

        requeue_scheduled_trigger_for_retry(&services, &scheduled, "test_requeue").await;
        let seq = scheduler
            .allocate_trigger_seq("agent-a", "g1")
            .await
            .expect("allocation should succeed after rollback");
        assert_eq!(seq, 1);
    }

    #[test]
    fn round_robin_covers_all_scopes_without_starvation() {
        // 7 scopes, batch size 3: ceil(7/3) = 3 ticks must cover every scope.
        let scopes: Vec<(String, String)> =
            (0..7).map(|i| (format!("p{i}"), format!("w{i}"))).collect();

        let mut covered = std::collections::HashSet::new();
        let mut cursor = 0usize;
        for _ in 0..3 {
            let (batch, next_cursor) = select_scope_batch(&scopes, cursor, 3);
            for scope in batch {
                covered.insert(scope);
            }
            cursor = next_cursor;
        }

        assert_eq!(
            covered.len(),
            scopes.len(),
            "all 7 scopes must be covered within ceil(7/3)=3 ticks"
        );
        for scope in &scopes {
            assert!(
                covered.contains(scope),
                "scope {scope:?} starved: not covered within 3 ticks"
            );
        }
    }

    #[tokio::test]
    async fn dispatch_budget_requeues_overflow_no_loss() {
        // Register budget+2 due-now cron entries in one scope, then run the
        // budget/requeue loop directly against a real AgentScheduler (invoking the
        // full run_scheduler_tick needs a live orchestrator, which is impractical
        // in a unit test). The assertion that matters: no fire is lost — the
        // overflow reappears on the next collect.
        let tmp = tempfile::tempdir().unwrap();
        let services = test_agent_api_services(tmp.path());
        let _ =
            create_agent_definition_impl(&services, sample_agent_definition("agent-a", "Alpha"))
                .await;

        let scheduler = services.resolve_default_scheduler().await.unwrap();
        let entry_count = SCHEDULER_DISPATCH_BUDGET_PER_TICK + 2;
        for i in 0..entry_count {
            scheduler
                .register_entry(
                    "agent-a",
                    &format!("g{i}"),
                    SchedulerTriggerRegistration::Cron {
                        schedule: "0 9 * * *".to_string(),
                        timezone: "UTC".to_string(),
                        next_run_at: Some(Utc::now() - chrono::Duration::hours(1)),
                    },
                )
                .await
                .expect("cron entry should register");
        }

        let now = Utc::now();
        let due = scheduler
            .collect_due_cron_triggers(now)
            .await
            .expect("collect_due should succeed");
        assert_eq!(
            due.len(),
            entry_count,
            "all registered entries should be due now"
        );

        // Simulate the tick loop: dispatch up to the budget (count only), requeue
        // the rest via the same requeue primitive the tick uses.
        let mut dispatched = 0usize;
        let mut requeued = 0usize;
        for scheduled in &due {
            if dispatched < SCHEDULER_DISPATCH_BUDGET_PER_TICK {
                dispatched += 1;
            } else {
                let rolled = scheduler
                    .requeue_due_cron_trigger(scheduled, now)
                    .await
                    .expect("requeue should succeed");
                assert!(rolled, "requeue should roll the fire back");
                requeued += 1;
            }
        }
        assert_eq!(dispatched, SCHEDULER_DISPATCH_BUDGET_PER_TICK);
        assert_eq!(requeued, 2);

        // The 2 overflow fires must reappear on the next collect (not lost);
        // the dispatched ones must NOT (their next_run_at advanced past `now`).
        let redue = scheduler
            .collect_due_cron_triggers(now)
            .await
            .expect("second collect_due should succeed");
        assert_eq!(
            redue.len(),
            2,
            "exactly the 2 requeued overflow fires must reappear; none lost, none double-fired"
        );

        // Each reappearing fire is genuinely due again (next_run_at <= now).
        for scheduled in &redue {
            assert!(
                scheduled.trigger_seq >= 1,
                "requeued fire should carry a valid rolled-back trigger_seq"
            );
        }
    }

