    #[tokio::test]
    async fn complete_cycle_and_take_next_dispatch_controlled_waits_on_control_gate() {
        let tmp = tempfile::tempdir().unwrap();
        let services = test_agent_api_services(tmp.path());
        let _ =
            create_agent_definition_impl(&services, sample_agent_definition("agent-a", "Alpha"))
                .await;

        let request = ManualAgentTriggerRequest {
            goal_id: Some("g1".to_string()),
            trigger: Some("manual".to_string()),
        };
        let (active_dispatch, active_schedule) =
            prepare_manual_trigger(&services, "agent-a", request.clone())
                .await
                .expect("first trigger should start now");
        assert!(matches!(active_schedule, ManualDispatchSchedule::StartNow));
        let (queued_dispatch, queued_schedule) =
            prepare_manual_trigger(&services, "agent-a", request)
                .await
                .expect("second trigger should queue");
        assert!(matches!(
            queued_schedule,
            ManualDispatchSchedule::Queued { queue_position: 1 }
        ));

        let control_guard = services.control_gate.lock().await;
        let services_clone = services.clone();
        let cycle_id = active_dispatch.cycle_id.clone();
        let join = tokio::spawn(async move {
            complete_cycle_and_take_next_dispatch_controlled(
                &services_clone,
                TEST_PRINCIPAL,
                TEST_WORKSPACE,
                "agent-a",
                "g1",
                &cycle_id,
                true,
            )
            .await
        });
        tokio::time::sleep(Duration::from_millis(100)).await;
        assert!(
            !join.is_finished(),
            "completion handoff should wait on control_gate"
        );
        drop(control_guard);

        let promoted = tokio::time::timeout(Duration::from_secs(1), join)
            .await
            .expect("completion handoff should unblock after releasing control_gate")
            .expect("join should succeed")
            .expect("queued dispatch should be promoted");
        assert_eq!(promoted.cycle_id, queued_dispatch.cycle_id);
    }

    #[tokio::test]
    async fn abandon_cycle_and_take_next_dispatch_controlled_promotes_queue_without_completion_mark(
    ) {
        let tmp = tempfile::tempdir().unwrap();
        let services = test_agent_api_services(tmp.path());
        let _ =
            create_agent_definition_impl(&services, sample_agent_definition("agent-a", "Alpha"))
                .await;

        let request = ManualAgentTriggerRequest {
            goal_id: Some("g1".to_string()),
            trigger: Some("manual".to_string()),
        };
        let (active_dispatch, active_schedule) =
            prepare_manual_trigger(&services, "agent-a", request.clone())
                .await
                .expect("first trigger should start now");
        assert!(matches!(active_schedule, ManualDispatchSchedule::StartNow));
        let (queued_dispatch, queued_schedule) =
            prepare_manual_trigger(&services, "agent-a", request)
                .await
                .expect("second trigger should queue");
        assert!(matches!(
            queued_schedule,
            ManualDispatchSchedule::Queued { queue_position: 1 }
        ));

        let promoted = abandon_cycle_and_take_next_dispatch_controlled(
            &services,
            TEST_PRINCIPAL,
            TEST_WORKSPACE,
            "agent-a",
            "g1",
            &active_dispatch.cycle_id,
            true,
        )
        .await
        .expect("queued dispatch should be promoted");
        assert_eq!(promoted.cycle_id, queued_dispatch.cycle_id);

        let active = services
            .runtime
            .active_cycle_in_scope(Some(TEST_PRINCIPAL), Some(TEST_WORKSPACE), "agent-a", "g1")
            .await
            .expect("promoted dispatch should become active");
        assert_eq!(active.cycle_id, queued_dispatch.cycle_id);

        // Abandoning without completion mark keeps the original tuple retryable.
        let retry = services
            .runtime
            .admit_trigger_in_scope(
                Some(TEST_PRINCIPAL),
                Some(TEST_WORKSPACE),
                "agent-a",
                "g1",
                "manual",
                active_dispatch.trigger_seq,
            )
            .await;
        assert!(matches!(
            retry,
            TriggerAdmission::Queued {
                queue_position: 1,
                ..
            }
        ));
    }

