    #[tokio::test]
    async fn concurrent_prepare_manual_trigger_starts_one_and_queues_one() {
        let tmp = tempfile::tempdir().unwrap();
        let services = test_agent_api_services(tmp.path());
        let _ =
            create_agent_definition_impl(&services, sample_agent_definition("agent-a", "Alpha"))
                .await;

        let request = ManualAgentTriggerRequest {
            goal_id: Some("g1".to_string()),
            trigger: Some("manual".to_string()),
        };

        let services_a = services.clone();
        let services_b = services.clone();
        let (left, right) = tokio::join!(
            prepare_manual_trigger(&services_a, "agent-a", request.clone()),
            prepare_manual_trigger(&services_b, "agent-a", request),
        );

        let mut started: Option<ManualTriggerDispatch> = None;
        let mut queued: Option<ManualTriggerDispatch> = None;
        for result in [left, right] {
            let (dispatch, schedule) = result.expect("concurrent trigger should be admitted");
            match schedule {
                ManualDispatchSchedule::StartNow => started = Some(dispatch),
                ManualDispatchSchedule::Queued { queue_position } => {
                    assert_eq!(queue_position, 1);
                    queued = Some(dispatch);
                },
            }
        }

        let started = started.expect("one concurrent request should start immediately");
        let queued = queued.expect("one concurrent request should be queued");
        let active = services
            .runtime
            .active_cycle_in_scope(Some(TEST_PRINCIPAL), Some(TEST_WORKSPACE), "agent-a", "g1")
            .await
            .expect("active cycle should be tracked");
        assert_eq!(active.cycle_id, started.cycle_id);
        assert_eq!(
            services
                .runtime
                .pending_trigger_count_in_scope(
                    Some(TEST_PRINCIPAL),
                    Some(TEST_WORKSPACE),
                    "agent-a",
                    "g1",
                )
                .await,
            1
        );
        assert!(services
            .pending_cycle_dispatches
            .read()
            .await
            .contains_key(&queued.cycle_id));
    }

