    #[cfg(unix)]
    #[tokio::test]
    async fn delete_failure_preserves_scheduler_registration() {
        let tmp = tempfile::tempdir().unwrap();
        let services = test_agent_api_services(tmp.path());
        let created =
            create_agent_definition_impl(&services, sample_agent_definition("agent-a", "Alpha"))
                .await;
        assert_eq!(created.status(), StatusCode::CREATED);

        // register_agent is a no-op; register the scheduler entry explicitly.
        let scheduler = services.resolve_default_scheduler().await.unwrap();
        scheduler
            .register_entry("agent-a", "g1", SchedulerTriggerRegistration::Idle)
            .await
            .unwrap();

        let agent_dir = services
            .definition_store
            .storage()
            .agent_dir("agent-a")
            .unwrap();
        let mut readonly_permissions = std::fs::metadata(&agent_dir).unwrap().permissions();
        readonly_permissions.set_mode(0o555);
        tokio::fs::set_permissions(&agent_dir, readonly_permissions)
            .await
            .unwrap();

        let response = delete_agent_definition_impl(&services, "agent-a").await;

        let mut writable_permissions = std::fs::metadata(&agent_dir).unwrap().permissions();
        writable_permissions.set_mode(0o755);
        tokio::fs::set_permissions(&agent_dir, writable_permissions)
            .await
            .unwrap();

        assert_eq!(response.status(), StatusCode::INTERNAL_SERVER_ERROR);
        let body = response_json(response).await;
        assert_eq!(body["code"], "definition_storage_failure");

        let retained_seq = scheduler
            .allocate_trigger_seq("agent-a", "g1")
            .await
            .unwrap();
        assert_eq!(retained_seq, 1);
    }

