    async fn hydrate_agent_runtime_state_marks_paused_task_backed_active_cycles_as_paused() {
        let tmp = tempfile::tempdir().unwrap();
        let services = test_agent_api_services(tmp.path());
        services
            .definition_store
            .create_definition(sample_agent_definition("agent-a", "Alpha"))
            .await
            .unwrap();

        let admission = services
            .runtime
            .admit_trigger_in_scope(
                Some(TEST_PRINCIPAL),
                Some(TEST_WORKSPACE),
                "agent-a",
                "goal-a",
                "manual",
                1,
            )
            .await;
        let cycle_id = match admission {
            TriggerAdmission::StartNow { reservation } => reservation.cycle_id,
            other => panic!("expected immediate trigger admission, got {other:?}"),
        };
        assert!(
            services
                .runtime
                .bind_active_cycle_execution_id_in_scope(
                    Some(TEST_PRINCIPAL),
                    Some(TEST_WORKSPACE),
                    "agent-a",
                    "goal-a",
                    &cycle_id,
                    "exec-paused",
                )
                .await
        );

        let record = services
            .definition_store
            .get_definition("agent-a")
            .await
            .unwrap()
            .unwrap();
        let mut response = AgentDefinitionRecordResponse::from(record);
        let tasks = vec![sample_active_task_list_item(
            "agent-a",
            "task-paused",
            "paused",
            "exec-paused",
            "2026-04-13T12:00:00Z",
        )];

        hydrate_agent_runtime_state(&services, &mut response, Some(&tasks), None).await;

        assert_eq!(response.status.as_deref(), Some("paused"));
        assert_eq!(response.current_goal_id.as_deref(), Some("goal-a"));
        assert_eq!(
            response.current_cycle_id.as_deref(),
            Some(cycle_id.as_str())
        );
        assert_eq!(
            response.current_execution_id.as_deref(),
            Some("exec-paused")
        );
    }

