    fn sample_episode_record(
        agent_id: &str,
        goal_id: &str,
        trigger_seq: u64,
        started_at: DateTime<Utc>,
    ) -> magician::magician_v2::artifact_v2::memory::V3EpisodeRecord {
        magician::magician_v2::artifact_v2::memory::V3EpisodeRecord::new_memory_episode(
            None,
            agent_id.to_string(),
            format!("{agent_id}-{goal_id}-{trigger_seq}"),
            goal_id.to_string(),
            "manual".to_string(),
            trigger_seq,
            started_at,
            None,
            started_at,
            started_at + chrono::Duration::seconds(15),
            &EpisodeOutcome::GoalAchieved {
                summary: "ok".to_string(),
            },
            Vec::new(),
            Vec::new(),
            Vec::new(),
            None,
            None,
            None,
        )
    }

    fn sample_native_episode_record(
        scope: Option<(&str, &str)>,
        agent_id: &str,
        goal_id: &str,
        trigger_seq: u64,
        started_at: DateTime<Utc>,
    ) -> magician::magician_v2::artifact_v2::memory::V3EpisodeRecord {
        let mut episode = sample_episode_record(agent_id, goal_id, trigger_seq, started_at);
        episode.principal = scope.map(|(principal, _)| principal.to_string());
        episode.workspace = scope.map(|(_, workspace)| workspace.to_string());
        episode
    }

