    #[tokio::test]
    async fn get_agent_memory_tier_requires_goal_for_ambiguous_agent_goal_scope() {
        let tmp = tempfile::tempdir().unwrap();
        let services = test_agent_api_services(tmp.path());
        let mut definition = sample_multi_goal_definition("agent-a", "Alpha");
        let available_goal_ids = goal_ids_for_definition(&definition);
        assert_eq!(available_goal_ids.len(), 2);
        definition.memory_tiers = vec![magician::magician_v2::agents::MemoryTierDefinition {
            name: "task_progress".to_string(),
            scope: magician::magician_v2::agents::TierScope::AgentGoal,
            description: "Task progress".to_string(),
            schema: std::collections::BTreeMap::new(),
            render: magician::magician_v2::agents::RenderConfig {
                format: "key_value".to_string(),
                template: "{items}".to_string(),
            },
            retention: magician::magician_v2::agents::RetentionMode::GoalLifetime,
        }];
        // Clear default consolidation rules that reference tiers we removed.
        definition.memory_consolidation = vec![];
        let _ = create_agent_definition_impl(&services, definition).await;

        let missing_goal_response = get_agent_memory_tier_impl(
            &services,
            "agent-a",
            "task_progress",
            &AgentMemoryQuery { goal_id: None },
        )
        .await;
        assert_eq!(missing_goal_response.status(), StatusCode::BAD_REQUEST);
        let missing_goal_body = response_json(missing_goal_response).await;
        assert_eq!(missing_goal_body["code"], "memory_goal_id_required");

        let explicit_goal_response = get_agent_memory_tier_impl(
            &services,
            "agent-a",
            "task_progress",
            &AgentMemoryQuery {
                goal_id: Some("g1".to_string()),
            },
        )
        .await;
        assert_eq!(explicit_goal_response.status(), StatusCode::BAD_REQUEST);
        let explicit_goal_body = response_json(explicit_goal_response).await;
        assert_eq!(explicit_goal_body["code"], "invalid_goal_id");

        let valid_goal_response = get_agent_memory_tier_impl(
            &services,
            "agent-a",
            "task_progress",
            &AgentMemoryQuery {
                goal_id: Some(available_goal_ids[0].clone()),
            },
        )
        .await;
        assert_eq!(valid_goal_response.status(), StatusCode::OK);
        let valid_goal_body = response_json(valid_goal_response).await;
        assert_eq!(valid_goal_body["goal_id"], available_goal_ids[0]);
    }

    #[test]
    fn infer_memory_tier_renderer_is_deterministic_for_non_canonical_formats() {
        let mut tier = magician::magician_v2::agents::MemoryTierDefinition {
            name: "timeline".to_string(),
            scope: magician::magician_v2::agents::TierScope::Agent,
            description: "test tier".to_string(),
            schema: std::collections::BTreeMap::new(),
            render: magician::magician_v2::agents::RenderConfig {
                format: "timeline_log_v2".to_string(),
                template: "{items}".to_string(),
            },
            retention: magician::magician_v2::agents::RetentionMode::Forever,
        };

        assert!(matches!(
            infer_memory_tier_renderer(&tier),
            MemoryTierRenderer::AppendLog
        ));

        tier.render.format = "priority_scorecard".to_string();
        assert!(matches!(
            infer_memory_tier_renderer(&tier),
            MemoryTierRenderer::ScoredList
        ));

        tier.render.format = "summary_blob".to_string();
        assert!(matches!(
            infer_memory_tier_renderer(&tier),
            MemoryTierRenderer::Archive
        ));

        tier.render.format = "custom_renderer".to_string();
        assert!(matches!(
            infer_memory_tier_renderer(&tier),
            MemoryTierRenderer::KeyValue
        ));
    }

    #[tokio::test]
    async fn list_triggers_exposes_next_fire_and_agent_filter() {
        let tmp = tempfile::tempdir().unwrap();
        let services = test_agent_api_services(tmp.path());
        let _ =
            create_agent_definition_impl(&services, sample_agent_definition("agent-a", "Alpha"))
                .await;
        let _ = create_agent_definition_impl(&services, sample_agent_definition("agent-b", "Beta"))
            .await;
        // register_agent is a no-op in the unified architecture; register
        // scheduler entries explicitly so the listing endpoint has data.
        let scheduler = services.resolve_default_scheduler().await.unwrap();
        scheduler
            .register_entry(
                "agent-a",
                "g1",
                SchedulerTriggerRegistration::Cron {
                    schedule: "0 9 * * *".to_string(),
                    timezone: "UTC".to_string(),
                    next_run_at: Some(Utc::now() + chrono::Duration::hours(1)),
                },
            )
            .await
            .unwrap();
        scheduler
            .register_entry(
                "agent-b",
                "g1",
                SchedulerTriggerRegistration::Cron {
                    schedule: "0 12 * * *".to_string(),
                    timezone: "UTC".to_string(),
                    next_run_at: Some(Utc::now() + chrono::Duration::hours(4)),
                },
            )
            .await
            .unwrap();

        let response = list_triggers_impl(&services, &ListTriggersQuery { agent_id: None }).await;
        assert_eq!(response.status(), StatusCode::OK);
        let body = response_json(response).await;
        let triggers = body["triggers"].as_array().unwrap();
        assert!(triggers
            .iter()
            .any(|entry| { entry["trigger_kind"] == "cron" && !entry["next_fire_at"].is_null() }));

        let filtered = list_triggers_impl(
            &services,
            &ListTriggersQuery {
                agent_id: Some("agent-a".to_string()),
            },
        )
        .await;
        assert_eq!(filtered.status(), StatusCode::OK);
        let filtered_body = response_json(filtered).await;
        let filtered_triggers = filtered_body["triggers"].as_array().unwrap();
        assert!(!filtered_triggers.is_empty());
        assert!(filtered_triggers
            .iter()
            .all(|entry| entry["agent_id"] == "agent-a"));
    }

