    // ── PATCH (JSON Merge Patch) tests ──────────────────────────────────

    #[test]
    fn json_merge_patch_changes_only_specified_keys() {
        let mut base = serde_json::json!({
            "name": "Old",
            "persona": "Helper",
            "tools": ["a", "b"]
        });
        let patch = serde_json::json!({ "name": "New" });
        json_merge_patch(&mut base, &patch);
        assert_eq!(base["name"], "New");
        assert_eq!(base["persona"], "Helper");
        assert_eq!(base["tools"], serde_json::json!(["a", "b"]));
    }

    #[test]
    fn json_merge_patch_null_removes_key() {
        let mut base = serde_json::json!({
            "name": "Agent",
            "autonomous_config": { "schedule": "* * * * *" }
        });
        let patch = serde_json::json!({ "autonomous_config": null });
        json_merge_patch(&mut base, &patch);
        assert!(!base.as_object().unwrap().contains_key("autonomous_config"));
        assert_eq!(base["name"], "Agent");
    }

    #[test]
    fn json_merge_patch_recursively_merges_nested_objects() {
        let mut base = serde_json::json!({
            "constraints": { "max_steps": 10, "timeout": 60 }
        });
        let patch = serde_json::json!({ "constraints": { "max_steps": 20 } });
        json_merge_patch(&mut base, &patch);
        // RFC 7386: nested objects are recursively merged
        assert_eq!(base["constraints"]["max_steps"], 20);
        assert_eq!(base["constraints"]["timeout"], 60);
    }

    #[test]
    fn json_merge_patch_null_removes_nested_key() {
        let mut base = serde_json::json!({
            "observation": { "default_mode": "screenshot", "escalation": "full" }
        });
        let patch = serde_json::json!({ "observation": { "escalation": null } });
        json_merge_patch(&mut base, &patch);
        assert_eq!(base["observation"]["default_mode"], "screenshot");
        assert!(!base["observation"]
            .as_object()
            .unwrap()
            .contains_key("escalation"));
    }

